fn display_status(value: &str) -> String {
    if active_console_locale() == Locale::En {
        return value.to_owned();
    }
    match value.trim().to_ascii_lowercase().as_str() {
        "active" => "ใช้งานอยู่",
        "inactive" => "ไม่ได้ใช้งาน",
        "enabled" => "เปิดใช้งาน",
        "disabled" => "ปิดใช้งาน",
        "draft" => "ฉบับร่าง",
        "pending" => "รอดำเนินการ",
        "claimed" => "รับงานแล้ว",
        "retryable" => "ลองใหม่ได้",
        "completed" | "complete" => "เสร็จสมบูรณ์",
        "failed" => "ล้มเหลว",
        "dead_letter" => "คิวรายการล้มเหลว",
        "open" => "เปิดอยู่",
        "closed" => "ปิดแล้ว",
        "approved" => "อนุมัติแล้ว",
        "rejected" => "ปฏิเสธแล้ว",
        "resolved" => "แก้ไขแล้ว",
        "healthy" => "ปกติ",
        "degraded" => "ประสิทธิภาพลดลง",
        "stale" => "ล้าสมัย",
        "fresh" => "เป็นปัจจุบัน",
        "running" | "in_progress" => "กำลังดำเนินการ",
        "cancelled" | "canceled" => "ยกเลิกแล้ว",
        "posted" => "ลงบัญชีแล้ว",
        "paid" => "ชำระแล้ว",
        "unpaid" => "ยังไม่ชำระ",
        _ => return value.to_owned(),
    }
    .to_owned()
}

fn display_error_message(value: &str) -> String {
    let is_machine_code = !value.is_empty()
        && value
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_');
    if !is_machine_code {
        return value.to_owned();
    }
    match value {
        "authentication_required" => localized_copy(
            "Sign in with an authenticated session to continue.",
            "เข้าสู่ระบบด้วยเซสชันที่ยืนยันตัวตนแล้วเพื่อดำเนินการต่อ",
        ),
        "authorization_denied" => localized_copy(
            "The server denied this action for the current identity or scope.",
            "เซิร์ฟเวอร์ปฏิเสธการดำเนินการนี้สำหรับตัวตนหรือขอบเขตปัจจุบัน",
        ),
        "offline" => localized_copy(
            "The service is unavailable. No command was issued.",
            "บริการไม่พร้อมใช้งาน และไม่มีการส่งคำสั่ง",
        ),
        code if code.ends_with("_conflict") => localized_copy(
            "A concurrent change requires a fresh authorized read.",
            "มีการเปลี่ยนแปลงพร้อมกัน จึงต้องอ่านข้อมูลที่ได้รับอนุญาตใหม่",
        ),
        code if code.ends_with("_rejected") => localized_copy(
            "The server rejected the request. Review the bounded inputs and try again.",
            "เซิร์ฟเวอร์ปฏิเสธคำขอ โปรดตรวจสอบข้อมูลที่กรอกแล้วลองอีกครั้ง",
        ),
        _ => localized_copy(
            "The authorized service could not complete this request.",
            "บริการที่ได้รับอนุญาตไม่สามารถดำเนินการคำขอนี้ให้เสร็จได้",
        ),
    }
    .to_owned()
}

#[derive(Clone)]
struct AuthHttpResponse {
    status: u16,
    body: String,
}

fn typed_http_method(method: &str) -> Result<crate::platform::http::HttpMethod, String> {
    use crate::platform::http::HttpMethod;
    match method {
        "GET" => Ok(HttpMethod::Get),
        "POST" => Ok(HttpMethod::Post),
        "PUT" => Ok(HttpMethod::Put),
        "PATCH" => Ok(HttpMethod::Patch),
        "DELETE" => Ok(HttpMethod::Delete),
        _ => Err("identity_validation_failed".to_owned()),
    }
}

fn decode_typed_http_response(
    response: crate::platform::http::HttpResponse,
) -> Result<AuthHttpResponse, String> {
    let body =
        String::from_utf8(response.body).map_err(|_| "identity_invalid_response".to_owned())?;
    Ok(AuthHttpResponse {
        status: response.status,
        body,
    })
}

#[cfg(target_arch = "wasm32")]
async fn execute_web_http(
    endpoint: crate::platform::http::HttpEndpoint,
    method: &str,
    path: &str,
    body: String,
    headers: Vec<crate::platform::http::HttpHeader>,
) -> Result<AuthHttpResponse, String> {
    use crate::platform::http::{HttpHost, HttpRequest, WebFetchHttpHost};

    let host: std::rc::Rc<dyn HttpHost> = if Runtime::try_current().is_some() {
        try_consume_context::<crate::platform::ConsolePlatform>()
            .map(|platform| platform.http)
            .unwrap_or_else(|| std::rc::Rc::new(WebFetchHttpHost::default()))
    } else {
        std::rc::Rc::new(WebFetchHttpHost::default())
    };
    let mut request = HttpRequest::new(endpoint, typed_http_method(method)?, path);
    request.headers = headers;
    if !body.is_empty() {
        request = request.json(body.into_bytes());
    }
    host.execute(request)
        .await
        .map_err(|_| "identity_offline".to_owned())
        .and_then(decode_typed_http_response)
}

#[cfg(not(target_arch = "wasm32"))]
async fn execute_native_http(
    endpoint: crate::platform::http::HttpEndpoint,
    method: &str,
    path: &str,
    body: String,
    headers: Vec<crate::platform::http::HttpHeader>,
) -> Result<AuthHttpResponse, String> {
    use crate::platform::http::{HttpHost, HttpRequest};

    let host: std::rc::Rc<dyn HttpHost> = if Runtime::try_current().is_some() {
        if let Some(platform) = try_consume_context::<crate::platform::ConsolePlatform>() {
            platform.http
        } else {
            native_http_host()?
        }
    } else {
        native_http_host()?
    };
    let mut request = HttpRequest::new(endpoint, typed_http_method(method)?, path);
    request.headers = headers;
    if !body.is_empty() {
        request = request.json(body.into_bytes());
    }
    host.execute(request)
        .await
        .map_err(|_| "identity_offline".to_owned())
        .and_then(decode_typed_http_response)
}

#[cfg(not(target_arch = "wasm32"))]
fn native_http_host() -> Result<std::rc::Rc<dyn crate::platform::http::HttpHost>, String> {
    let config = crate::platform::NativeEndpointConfig {
        auth_http: auth_http_origin(),
        public_http: auth_http_origin(),
        grpc: GRPC_ENDPOINT.to_owned(),
    };
    crate::platform::http::ReqwestHttpHost::new(&config)
        .map(|host| std::rc::Rc::new(host) as std::rc::Rc<dyn crate::platform::http::HttpHost>)
        .map_err(|_| "identity_validation_failed".to_owned())
}

impl std::fmt::Debug for AuthHttpResponse {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("AuthHttpResponse")
            .field("status", &self.status)
            .field("body_len", &self.body.len())
            .finish()
    }
}

