fn entitlement_expected_version(value: &str) -> Result<Option<u64>, String> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(None);
    }
    let version = value
        .parse::<u64>()
        .map_err(|_| "expected entitlement version must be a positive integer".to_string())?;
    if version == 0 {
        return Err("expected entitlement version must be a positive integer".to_string());
    }
    Ok(Some(version))
}

fn entitlement_command_receipt(
    receipt: Option<EntitlementCommandReceipt>,
    correlation_id: String,
) -> Result<EntitlementCommandReceiptModel, String> {
    let receipt = receipt.ok_or_else(|| "entitlement command returned no receipt".to_string())?;
    if receipt.aggregate_type.is_empty()
        || receipt.aggregate_id.is_empty()
        || receipt.command_id.is_empty()
        || receipt.version == 0
    {
        return Err("entitlement command returned an incomplete receipt".to_string());
    }
    Ok(EntitlementCommandReceiptModel {
        aggregate_type: receipt.aggregate_type,
        aggregate_id: receipt.aggregate_id,
        version: receipt.version,
        replayed: receipt.replayed,
        command_id: receipt.command_id,
        correlation_id,
    })
}

fn entitlement_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "entitlement_command_rejected".into()
        }
        _ => "entitlement_service_failed".into(),
    }
}

