fn billing_response_text(
    value: &str,
    label: &str,
    allow_empty: bool,
    max_bytes: usize,
) -> Result<String, String> {
    let value = value.trim();
    if (!allow_empty && value.is_empty())
        || value.len() > max_bytes
        || value.chars().any(char::is_control)
    {
        return Err(format!("billing response contained an invalid {label}"));
    }
    Ok(value.to_owned())
}

fn safe_billing_hosted_url(value: &str) -> Result<String, String> {
    let value = value.trim();
    if value.len() > 2_048
        || !value.starts_with("https://")
        || value
            .chars()
            .any(|character| character.is_whitespace() || character.is_control())
    {
        return Err("billing provider returned an unsafe destination".into());
    }
    let authority = value
        .trim_start_matches("https://")
        .split('/')
        .next()
        .unwrap_or_default();
    if authority.is_empty() || authority.contains('@') || authority.starts_with('.') {
        return Err("billing provider returned an unsafe destination".into());
    }
    Ok(value.to_owned())
}

