fn activity_record_candidate(path: &str) -> Option<(Uuid, &'static str)> {
    let path = path.split(['?', '#']).next()?.trim_matches('/');
    let segments = path.split('/').collect::<Vec<_>>();
    let [module, record, raw_id] = segments.as_slice() else {
        return None;
    };
    let descriptor = RECORD_TYPES
        .iter()
        .find(|descriptor| descriptor.module == *module && descriptor.record == *record)?;
    let id = Uuid::parse_str(raw_id).ok()?;
    (id.get_version_num() == 4).then_some((id, descriptor.id))
}

fn reference_authority_scope(scope_key: &str) -> Result<AuthorityScope, ()> {
    let mut scope = AuthorityScope {
        // The server derives the tenant from its authoritative root-holding
        // binding. A successful descriptor returns that tenant UUID.
        tenant_id: String::new(),
        level: AuthorityScopeLevel::Unspecified as i32,
        holding_id: None,
        company_id: None,
        branch_id: None,
    };
    if let Some(holding_id) = scope_key.strip_prefix("holding:") {
        scope.level = AuthorityScopeLevel::Holding as i32;
        scope.holding_id = Some(canonical_scope_uuid(holding_id, "holding ID").map_err(|_| ())?);
    } else if let Some(value) = scope_key.strip_prefix("company:") {
        let mut values = value.split(':');
        let (Some(holding_id), Some(company_id), None) =
            (values.next(), values.next(), values.next())
        else {
            return Err(());
        };
        scope.level = AuthorityScopeLevel::Company as i32;
        scope.holding_id = Some(canonical_scope_uuid(holding_id, "holding ID").map_err(|_| ())?);
        scope.company_id = Some(canonical_scope_uuid(company_id, "company ID").map_err(|_| ())?);
    } else if let Some(value) = scope_key.strip_prefix("branch:") {
        let mut values = value.split(':');
        let (Some(holding_id), Some(company_id), Some(branch_id), None) =
            (values.next(), values.next(), values.next(), values.next())
        else {
            return Err(());
        };
        scope.level = AuthorityScopeLevel::Branch as i32;
        scope.holding_id = Some(canonical_scope_uuid(holding_id, "holding ID").map_err(|_| ())?);
        scope.company_id = Some(canonical_scope_uuid(company_id, "company ID").map_err(|_| ())?);
        scope.branch_id = Some(canonical_scope_uuid(branch_id, "branch ID").map_err(|_| ())?);
    } else {
        // Platform and subtree roles cannot be represented as one exact
        // tenant detail scope by the current Reference contract.
        return Err(());
    }
    Ok(scope)
}

fn same_reference_hierarchy(expected: &AuthorityScope, actual: &AuthorityScope) -> bool {
    expected.level == actual.level
        && expected.holding_id == actual.holding_id
        && expected.company_id == actual.company_id
        && expected.branch_id == actual.branch_id
}

#[derive(Clone)]
struct ActivityResolution {
    gate: ActivityReferenceGate,
    state: ActivityRailState,
}

async fn resolve_activity_reference(
    path: String,
    scope_key: String,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> ActivityReferenceGate {
    let Some((candidate_id, record_type)) = activity_record_candidate(&path) else {
        return ActivityReferenceGate::NotRecordRoute;
    };
    if access_token.is_empty() || principal_ref.is_empty() || session_id.is_empty() {
        return ActivityReferenceGate::Neutral;
    }
    let Ok(authority_scope) = reference_authority_scope(&scope_key) else {
        return ActivityReferenceGate::Neutral;
    };
    let Ok(channel) = reference_grpc_channel().await else {
        return ActivityReferenceGate::Offline;
    };
    let mut client = ReferenceQueryServiceClient::new(channel);
    let mut request = tonic::Request::new(ResolveReferenceRequest {
        record_id: candidate_id.to_string(),
        authority_scope: Some(authority_scope.clone()),
        purpose: "authorized_record_activity".into(),
    });
    if add_crm_transport_metadata(&mut request, &access_token, &principal_ref, &session_id).is_err()
    {
        return ActivityReferenceGate::Neutral;
    }
    let response = match client.resolve(request).await {
        Ok(response) => response.into_inner(),
        Err(status)
            if matches!(
                status.code(),
                tonic::Code::Unavailable | tonic::Code::DeadlineExceeded
            ) =>
        {
            return ActivityReferenceGate::Offline;
        }
        Err(status)
            if matches!(
                status.code(),
                tonic::Code::PermissionDenied
                    | tonic::Code::Unauthenticated
                    | tonic::Code::NotFound
            ) =>
        {
            return ActivityReferenceGate::Neutral;
        }
        Err(_) => return ActivityReferenceGate::Degraded,
    };
    let freshness =
        DirectoryFreshness::try_from(response.freshness).unwrap_or(DirectoryFreshness::Unspecified);
    if freshness == DirectoryFreshness::Stale {
        return ActivityReferenceGate::Stale;
    }
    if freshness == DirectoryFreshness::Unavailable {
        return ActivityReferenceGate::Degraded;
    }
    if freshness != DirectoryFreshness::Fresh || !response.found {
        return ActivityReferenceGate::Neutral;
    }
    let Some(descriptor) = response.descriptor else {
        return ActivityReferenceGate::Degraded;
    };
    let (Some(record), Some(resolved_scope)) = (descriptor.record, descriptor.scope) else {
        return ActivityReferenceGate::Degraded;
    };
    let Ok(resolved_tenant_uuid) = Uuid::parse_str(&resolved_scope.tenant_id) else {
        return ActivityReferenceGate::Degraded;
    };
    let Ok(resolved_tenant_id) = TenantId::try_from_uuid(resolved_tenant_uuid) else {
        return ActivityReferenceGate::Degraded;
    };
    if descriptor.canonical_route != path
        || descriptor.descriptor_version == 0
        || descriptor.source_event_position == 0
        || record.id != candidate_id.to_string()
        || record.record_type != record_type
        || !same_reference_hierarchy(&authority_scope, &resolved_scope)
    {
        return ActivityReferenceGate::Degraded;
    }
    let Some(owner_context) = ContextId::ALL
        .into_iter()
        .find(|context| context.slug() == record.owner_context)
    else {
        return ActivityReferenceGate::Degraded;
    };
    let Ok(record_type) = RecordTypeId::try_new(record.record_type) else {
        return ActivityReferenceGate::Degraded;
    };
    let Ok(record_id) = RecordId::try_from_uuid(candidate_id) else {
        return ActivityReferenceGate::Degraded;
    };
    let Ok(record) = StableRecordRef::try_new(record_id, owner_context, record_type) else {
        return ActivityReferenceGate::Degraded;
    };
    if record.canonical_detail_route() != path {
        return ActivityReferenceGate::Degraded;
    }
    ActivityReferenceGate::Authorized {
        tenant_id: resolved_tenant_id,
        record,
        canonical_route: path,
    }
}

async fn load_activity_threads(
    gate: &ActivityReferenceGate,
    scope_key: &str,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> ActivityRailState {
    let ActivityReferenceGate::Authorized {
        tenant_id, record, ..
    } = gate
    else {
        return match gate {
            ActivityReferenceGate::Stale => ActivityRailState::Stale {
                threads: Vec::new(),
                reason: "The record directory projection is stale".into(),
            },
            ActivityReferenceGate::Degraded => ActivityRailState::Degraded {
                threads: Vec::new(),
                reason: "Record discussions are temporarily unavailable".into(),
                retryable: true,
            },
            ActivityReferenceGate::Offline => ActivityRailState::Offline {
                cached_threads: Vec::new(),
            },
            ActivityReferenceGate::NotRecordRoute
            | ActivityReferenceGate::Resolving
            | ActivityReferenceGate::Neutral
            | ActivityReferenceGate::Authorized { .. } => ActivityRailState::Denied,
        };
    };
    let Ok(mut authority_scope) = reference_authority_scope(scope_key) else {
        return ActivityRailState::Denied;
    };
    // The tenant identity comes only from the already-authorized descriptor;
    // it is never accepted from the route or browser input.
    authority_scope.tenant_id = tenant_id.to_string();
    let Ok(channel) = reference_grpc_channel().await else {
        return ActivityRailState::Offline {
            cached_threads: Vec::new(),
        };
    };
    let mut client = CollaborationQueryServiceClient::new(channel);
    let mut request = tonic::Request::new(ListThreadsByRecordRequest {
        tenant_id: tenant_id.to_string(),
        authority_scope: Some(authority_scope),
        actor_principal_id: principal_ref.to_owned(),
        record: Some(ProtoStableRecordRef {
            id: record.id().to_string(),
            owner_context: record.owner_context().slug().into(),
            record_type: record.record_type().as_str().into(),
        }),
        page_size: 50,
        cursor: None,
    });
    if add_crm_transport_metadata(&mut request, access_token, principal_ref, session_id).is_err() {
        return ActivityRailState::Denied;
    }
    let response = match client.list_threads_by_record(request).await {
        Ok(response) => response.into_inner(),
        Err(status)
            if matches!(
                status.code(),
                tonic::Code::PermissionDenied
                    | tonic::Code::Unauthenticated
                    | tonic::Code::NotFound
            ) =>
        {
            return ActivityRailState::Denied;
        }
        Err(status)
            if matches!(
                status.code(),
                tonic::Code::Unavailable | tonic::Code::DeadlineExceeded
            ) =>
        {
            return ActivityRailState::Offline {
                cached_threads: Vec::new(),
            };
        }
        Err(_) => {
            return ActivityRailState::Degraded {
                threads: Vec::new(),
                reason: "Record discussions could not be loaded".into(),
                retryable: true,
            };
        }
    };
    if response.authorized_count < response.authorized_projection_json_utf8.len() as u64 {
        return ActivityRailState::Degraded {
            threads: Vec::new(),
            reason: "Record discussion pagination is inconsistent".into(),
            retryable: true,
        };
    }
    let freshness =
        DirectoryFreshness::try_from(response.freshness).unwrap_or(DirectoryFreshness::Unspecified);
    match freshness {
        DirectoryFreshness::Unspecified => ActivityRailState::Denied,
        DirectoryFreshness::Unavailable => ActivityRailState::Degraded {
            threads: Vec::new(),
            reason: "Record discussion projection is unavailable".into(),
            retryable: true,
        },
        DirectoryFreshness::Fresh | DirectoryFreshness::Stale => present_authorized_thread_page(
            &response.authorized_projection_json_utf8,
            record,
            freshness == DirectoryFreshness::Stale,
        )
        .unwrap_or_else(erpx_console_feature_ai_collaboration::activity_error),
    }
}

async fn fetch_billing_workspace(
    scope: BillingScope,
    invoice_cursor: String,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<BillingWorkspaceModel, String> {
    let channel = billing_grpc_channel().await?;
    let mut client = CommercialQueryServiceClient::new(channel);

    let mut catalog_request = tonic::Request::new(ListSaasCatalogRequest {
        currency: scope.currency.clone(),
        context: Some(billing_query_context(&scope, &principal_ref, &session_id)?),
    });
    add_platform_metadata(
        &mut catalog_request,
        &access_token,
        &principal_ref,
        &session_id,
    )?;
    let catalog_response = client
        .list_saas_catalog(catalog_request)
        .await
        .map_err(billing_rpc_error)?
        .into_inner();
    let catalog = catalog_response
        .prices
        .into_iter()
        .take(256)
        .map(|price| {
            Ok(BillingCatalogPriceModel {
                item_key: billing_response_text(&price.item_key, "catalog item key", false, 128)?,
                display_name: billing_response_text(
                    &price.display_name,
                    "catalog display name",
                    false,
                    255,
                )?,
                kind: billing_response_text(&price.kind, "catalog kind", false, 64)?,
                pricing_unit: billing_response_text(
                    &price.pricing_unit,
                    "catalog pricing unit",
                    false,
                    64,
                )?,
                interval: billing_response_text(&price.interval, "catalog interval", false, 64)?,
                amount_minor: price.amount_minor,
                currency: billing_response_text(&price.currency, "catalog currency", false, 3)?,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;

    let mut subscription_request = tonic::Request::new(GetTenantSubscriptionRequest {
        tenant_id: scope.tenant_id.clone(),
        context: Some(billing_query_context(&scope, &principal_ref, &session_id)?),
    });
    add_platform_metadata(
        &mut subscription_request,
        &access_token,
        &principal_ref,
        &session_id,
    )?;
    let subscription_response = client
        .get_tenant_subscription(subscription_request)
        .await
        .map_err(billing_rpc_error)?
        .into_inner();
    let subscription = subscription_response
        .subscription
        .ok_or_else(|| "billing response omitted the subscription state".to_string())?;
    if subscription.tenant_id != scope.tenant_id {
        return Err("billing response crossed the requested tenant boundary".into());
    }
    let subscription = BillingSubscriptionModel {
        state: billing_response_text(&subscription.state, "subscription state", false, 64)?,
        currency: billing_response_text(&subscription.currency, "subscription currency", false, 3)?,
        grace_until: billing_response_text(
            &subscription.grace_until,
            "subscription grace timestamp",
            true,
            64,
        )?,
        business_modules_read_only: subscription.business_modules_read_only,
        items: subscription
            .items
            .into_iter()
            .take(256)
            .map(|item| {
                Ok(BillingSubscriptionItemModel {
                    item_key: billing_response_text(
                        &item.item_key,
                        "subscription item key",
                        false,
                        128,
                    )?,
                    quantity: item.quantity,
                })
            })
            .collect::<Result<Vec<_>, String>>()?,
    };

    let mut invoices_request = tonic::Request::new(ListTenantInvoicesRequest {
        tenant_id: scope.tenant_id.clone(),
        page_size: 25,
        after_invoice_id: invoice_cursor,
        context: Some(billing_query_context(&scope, &principal_ref, &session_id)?),
    });
    add_platform_metadata(
        &mut invoices_request,
        &access_token,
        &principal_ref,
        &session_id,
    )?;
    let invoices_response = client
        .list_tenant_invoices(invoices_request)
        .await
        .map_err(billing_rpc_error)?
        .into_inner();
    if !invoices_response.has_more && !invoices_response.next_after_invoice_id.is_empty() {
        return Err("billing response returned an invoice cursor without another page".into());
    }
    let invoices = invoices_response
        .invoices
        .into_iter()
        .take(25)
        .map(|invoice| {
            Ok(BillingInvoiceModel {
                invoice_id: billing_response_text(&invoice.invoice_id, "invoice ID", false, 128)?,
                state: billing_response_text(&invoice.state, "invoice state", false, 64)?,
                currency: billing_response_text(&invoice.currency, "invoice currency", false, 3)?,
                amount_due_minor: invoice.amount_due_minor,
                amount_paid_minor: invoice.amount_paid_minor,
                due_at: billing_response_text(&invoice.due_at, "invoice due timestamp", true, 64)?,
                hosted_invoice_available: invoice.hosted_invoice_available,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(BillingWorkspaceModel {
        catalog_revision: catalog_response.revision,
        catalog,
        subscription,
        invoices,
        invoices_has_more: invoices_response.has_more,
        next_invoice_cursor: billing_response_text(
            &invoices_response.next_after_invoice_id,
            "invoice cursor",
            true,
            128,
        )?,
        correlation_id: billing_response_text(
            &invoices_response.correlation_id,
            "billing correlation ID",
            false,
            128,
        )?,
    })
}

async fn execute_billing_command(
    scope: BillingScope,
    input: BillingCommandInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<BillingCommandResult, String> {
    let channel = billing_grpc_channel().await?;
    let mut client = CommercialCommandServiceClient::new(channel);
    match input {
        BillingCommandInput::Checkout { item_key, quantity } => {
            let item_key = billing_response_text(&item_key, "checkout item key", false, 128)?;
            let quantity = quantity
                .trim()
                .parse::<u32>()
                .map_err(|_| "checkout quantity must be a positive integer".to_string())?;
            if quantity == 0 {
                return Err("checkout quantity must be a positive integer".into());
            }
            let mut request = tonic::Request::new(CreateCheckoutSessionRequest {
                tenant_id: scope.tenant_id.clone(),
                items: vec![SubscriptionItemSelection { item_key, quantity }],
                return_path: "/billing/checkout/success".into(),
                context: Some(billing_command_context(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "tenant_billing_checkout",
                    false,
                )?),
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .create_checkout_session(request)
                .await
                .map_err(billing_rpc_error)?
                .into_inner();
            let hosted_url = safe_billing_hosted_url(&response.hosted_url)?;
            let expires_at =
                billing_response_text(&response.expires_at, "checkout expiry timestamp", true, 64)?;
            let correlation_id = billing_response_text(
                &response.correlation_id,
                "billing correlation ID",
                false,
                128,
            )?;
            Ok(BillingCommandResult {
                message: format!(
                    "Checkout session is ready{} · correlation {correlation_id}.",
                    if expires_at.is_empty() {
                        String::new()
                    } else {
                        format!(" until {expires_at}")
                    }
                ),
                hosted_url: Some(hosted_url),
            })
        }
        BillingCommandInput::CustomerPortal => {
            let mut request = tonic::Request::new(CreateCustomerPortalSessionRequest {
                tenant_id: scope.tenant_id.clone(),
                return_path: "/billing".into(),
                context: Some(billing_command_context(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "tenant_billing_customer_portal",
                    false,
                )?),
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .create_customer_portal_session(request)
                .await
                .map_err(billing_rpc_error)?
                .into_inner();
            let hosted_url = safe_billing_hosted_url(&response.hosted_url)?;
            let correlation_id = billing_response_text(
                &response.correlation_id,
                "billing correlation ID",
                false,
                128,
            )?;
            Ok(BillingCommandResult {
                message: format!(
                    "Customer portal session is ready · correlation {correlation_id}."
                ),
                hosted_url: Some(hosted_url),
            })
        }
        BillingCommandInput::GrantGrace {
            delinquency_cycle_id,
            extension_days,
            reason,
            mfa_code,
        } => {
            let delinquency_cycle_id = Uuid::parse_str(delinquency_cycle_id.trim())
                .map_err(|_| "delinquency cycle ID must be a UUID".to_string())?
                .to_string();
            let extension_days = extension_days
                .trim()
                .parse::<u32>()
                .map_err(|_| "grace extension must be from one to seven days".to_string())?;
            if !(1..=7).contains(&extension_days) {
                return Err("grace extension must be from one to seven days".into());
            }
            let reason = billing_response_text(&reason, "grace extension reason", false, 512)?;
            if mfa_code.trim().is_empty() || mfa_code.len() > 128 {
                return Err("a fresh MFA code is required".into());
            }
            let mut request = tonic::Request::new(GrantBillingGraceExtensionRequest {
                tenant_id: scope.tenant_id.clone(),
                delinquency_cycle_id,
                extension_days,
                reason,
                mfa_code,
                context: Some(billing_command_context(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "platform_billing_grace_extension",
                    true,
                )?),
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .grant_grace_extension(request)
                .await
                .map_err(billing_rpc_error)?
                .into_inner();
            let extension_id =
                billing_response_text(&response.extension_id, "billing extension ID", false, 128)?;
            let extended_until = billing_response_text(
                &response.extended_until,
                "billing extension timestamp",
                false,
                64,
            )?;
            let correlation_id = billing_response_text(
                &response.correlation_id,
                "billing correlation ID",
                false,
                128,
            )?;
            Ok(BillingCommandResult {
                message: format!(
                    "Grace extension {extension_id} committed through {extended_until} · correlation {correlation_id}."
                ),
                hosted_url: None,
            })
        }
    }
}

#[cfg(target_arch = "wasm32")]
async fn fetch_entitlement_probe(
    scope: EntitlementScope,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<EntitlementProbeModel, String> {
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    let mut client = CommercialQueryServiceClient::new(channel);
    let mut request = tonic::Request::new(CheckEntitlementRequest {
        billing_state: String::new(),
        module_key: scope.module_key.clone(),
        module_active: false,
        rbac_allows: false,
        mutation: false,
        context: Some(entitlement_query_context(
            &scope,
            &principal_ref,
            &session_id,
        )?),
        customer_id: scope.customer_id,
        subscription_id: scope.subscription_id,
        required_permission: "commercial.entitlement.activate".into(),
        approval_amount_minor: 0,
        support_capability_id: String::new(),
        support_device_ref: String::new(),
        support_session_id: String::new(),
        support_ticket_id: String::new(),
        support_mode: String::new(),
        support_scope: String::new(),
    });
    add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
    let response = client
        .check_entitlement(request)
        .await
        .map_err(entitlement_rpc_error)?
        .into_inner();
    Ok(EntitlementProbeModel {
        allowed: response.allowed,
        reason: response.reason,
    })
}

