const MAX_PLATFORM_READ_TEXT_BYTES: usize = 512;

/// Apply the final display boundary to scalar values that arrive from a platform read model.
///
/// Protobuf strings are not trusted merely because they came from an authenticated RPC.  Keep
/// the client model bounded and redact credential-looking values before they can enter Debug,
/// cached state, or RSX.  Required fields are rejected by the record validators below when the
/// redaction marker would otherwise be mistaken for an identifier or status.
fn safe_platform_read_text(value: &str) -> String {
    if value.trim().is_empty() {
        String::new()
    } else {
        SafeUiText::new(value).as_str().to_owned()
    }
}

fn validate_platform_read_text(
    value: &str,
    field: &str,
    allow_empty: bool,
    max_bytes: usize,
) -> Result<(), String> {
    let value = value.trim();
    if (!allow_empty && value.is_empty())
        || value.len() > max_bytes
        || value.chars().any(char::is_control)
        || value == "[redacted]"
    {
        return Err(format!("platform {field} was malformed"));
    }
    Ok(())
}

fn validate_platform_identifier(value: &str, field: &str, allow_empty: bool) -> Result<(), String> {
    validate_platform_read_text(value, field, allow_empty, 128)?;
    let value = value.trim();
    if !value.is_empty()
        && (value.chars().any(char::is_whitespace) || value.contains(['/', '\\', '?', '#']))
    {
        return Err(format!("platform {field} was not a safe opaque identifier"));
    }
    Ok(())
}

