fn validate_tenant_registration_reference(value: &str, label: &str) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty()
        || value.len() > 255
        || value
            .chars()
            .any(|character| character.is_control() || matches!(character, '/' | '\\' | ':' | ' '))
    {
        return Err(format!(
            "{label} must be an opaque reference without spaces, slashes, or colons."
        ));
    }
    Ok(value.to_owned())
}

impl PlatformTenantLifecycleReceipt {
    fn validate(self) -> Result<Self, String> {
        validate_platform_identifier(&self.tenant_id, "tenant lifecycle tenant ID", false)?;
        validate_platform_read_text(&self.state, "tenant lifecycle state", false, 64)?;
        validate_platform_read_text(
            &self.correlation_id,
            "tenant lifecycle correlation ID",
            false,
            128,
        )?;
        Ok(self)
    }
}

