impl TenantOrganizationNodeRecord {
    fn from_target(
        scope: &TenantGovernanceScope,
        wire: organization_target::OrganizationNodeRecord,
    ) -> Result<Self, String> {
        use organization_target::organization_placement_v1::Placement;

        Uuid::parse_str(&wire.node_id)
            .map_err(|_| "The organization node ID was invalid.".to_owned())?;
        if wire.source_version == 0 {
            return Err("The organization aggregate version was invalid.".to_owned());
        }
        let kind = match organization_target::OrganizationNodeKindV1::try_from(wire.kind).ok() {
            Some(organization_target::OrganizationNodeKindV1::Holding) => "holding",
            Some(organization_target::OrganizationNodeKindV1::Company) => "company",
            Some(organization_target::OrganizationNodeKindV1::Headquarters) => "headquarters",
            Some(organization_target::OrganizationNodeKindV1::Branch) => "branch",
            Some(organization_target::OrganizationNodeKindV1::Department) => "department",
            Some(organization_target::OrganizationNodeKindV1::Team) => "team",
            _ => return Err("The organization node kind was unsupported.".to_owned()),
        };
        let status = match organization_target::OrganizationNodeStatusV1::try_from(wire.status).ok()
        {
            Some(organization_target::OrganizationNodeStatusV1::Active) => "active",
            Some(organization_target::OrganizationNodeStatusV1::Suspended) => "suspended",
            Some(organization_target::OrganizationNodeStatusV1::Archived) => "archived",
            _ => return Err("The organization node status was unsupported.".to_owned()),
        };
        let placement = wire
            .placement
            .and_then(|placement| placement.placement)
            .ok_or_else(|| "The organization placement was absent.".to_owned())?;
        let (placement_kind, holding_id, company_id, branch_id, department_id) = match placement {
            Placement::Holding(_) => (
                "holding",
                scope.holding_id.clone(),
                String::new(),
                String::new(),
                String::new(),
            ),
            Placement::Company(value) => (
                "company",
                value.holding_id,
                String::new(),
                String::new(),
                String::new(),
            ),
            Placement::Headquarters(value) => (
                "headquarters",
                value.holding_id,
                value.company_id,
                String::new(),
                String::new(),
            ),
            Placement::Branch(value) => (
                "branch",
                value.holding_id,
                value.company_id,
                wire.node_id.clone(),
                String::new(),
            ),
            Placement::Department(value) => (
                "department",
                value.holding_id,
                value.company_id,
                value.branch_id.unwrap_or_default(),
                wire.node_id.clone(),
            ),
            Placement::Team(value) => (
                "team",
                value.holding_id,
                value.company_id,
                value.branch_id.unwrap_or_default(),
                value.department_id,
            ),
        };
        if placement_kind != kind || holding_id != scope.holding_id {
            return Err("The organization node was outside the selected holding.".to_owned());
        }
        for value in [&holding_id, &company_id, &branch_id, &department_id] {
            if !value.is_empty() {
                Uuid::parse_str(value)
                    .map_err(|_| "An organization scope identifier was invalid.".to_owned())?;
            }
        }
        for (value, field, allow_empty, limit) in [
            (wire.code.as_str(), "organization code", false, 64),
            (wire.display_name.as_str(), "organization name", false, 160),
            (status, "organization status", false, 64),
            (
                wire.updated_at.as_str(),
                "organization update timestamp",
                false,
                64,
            ),
        ] {
            validate_platform_read_text(value, field, allow_empty, limit)?;
        }
        Ok(Self {
            kind: kind.to_owned(),
            node_id: wire.node_id,
            company_id,
            branch_id,
            department_id,
            code: safe_platform_read_text(&wire.code),
            name: safe_platform_read_text(&wire.display_name),
            registration_number: String::new(),
            status: status.to_owned(),
            aggregate_version: wire.source_version,
            updated_at: wire.updated_at,
        })
    }
}

impl BranchProvisioningRecord {
    fn from_wire(
        wire: platform_admin_target::TenantBranchProvisioningRecord,
    ) -> Result<Self, String> {
        validate_platform_identifier(&wire.job_id, "branch provisioning job ID", false)?;
        validate_platform_identifier(&wire.branch_id, "branch ID", false)?;
        validate_platform_read_text(&wire.branch_code, "branch code", false, 64)?;
        validate_platform_read_text(&wire.branch_name, "branch name", false, 160)?;
        validate_platform_read_text(&wire.state, "branch provisioning state", false, 64)?;
        validate_platform_read_text(&wire.failure_category, "branch failure category", true, 96)?;
        validate_platform_read_text(&wire.updated_at, "branch update timestamp", false, 64)?;
        validate_platform_read_text(
            &wire.correlation_id,
            "branch provisioning correlation ID",
            false,
            128,
        )?;
        for unit in &wire.enabled_business_units {
            erpx_domain::data_plane::BusinessUnitId::parse(unit)
                .map_err(|_| "branch provisioning returned an unsupported business unit")?;
        }
        Ok(Self {
            job_id: wire.job_id,
            branch_id: wire.branch_id,
            branch_code: wire.branch_code,
            branch_name: wire.branch_name,
            enabled_business_units: wire.enabled_business_units,
            state: wire.state,
            attempt_count: wire.attempt_count,
            failure_category: wire.failure_category,
            updated_at: wire.updated_at,
            route_version: wire.route_version,
            correlation_id: wire.correlation_id,
        })
    }

    fn retryable(&self) -> bool {
        matches!(self.state.as_str(), "failed" | "retry_pending")
    }

    fn active(&self) -> bool {
        matches!(self.state.as_str(), "active" | "completed") && self.route_version > 0
    }
}

