fn business_unit_scope_label(scope: Option<TenantScope>) -> Result<String, String> {
    match scope.and_then(|scope| scope.scope) {
        Some(tenant_scope::Scope::Holding(scope)) => {
            Uuid::parse_str(&scope.holding_id)
                .map_err(|_| "business-unit holding scope was invalid")?;
            Ok(format!("holding:{}", scope.holding_id))
        }
        Some(tenant_scope::Scope::Company(scope)) => {
            Uuid::parse_str(&scope.holding_id)
                .map_err(|_| "business-unit holding scope was invalid")?;
            Uuid::parse_str(&scope.company_id)
                .map_err(|_| "business-unit company scope was invalid")?;
            Ok(format!("company:{}", scope.company_id))
        }
        Some(tenant_scope::Scope::Branch(scope)) => {
            Uuid::parse_str(&scope.holding_id)
                .map_err(|_| "business-unit holding scope was invalid")?;
            Uuid::parse_str(&scope.company_id)
                .map_err(|_| "business-unit company scope was invalid")?;
            Uuid::parse_str(&scope.branch_id)
                .map_err(|_| "business-unit branch scope was invalid")?;
            Ok(format!("branch:{}", scope.branch_id))
        }
        Some(tenant_scope::Scope::Subtree(scope)) => {
            Uuid::parse_str(&scope.holding_id)
                .map_err(|_| "business-unit holding scope was invalid")?;
            for value in scope.company_ids.iter().chain(scope.branch_ids.iter()) {
                Uuid::parse_str(value).map_err(|_| "business-unit subtree scope was invalid")?;
            }
            Ok(format!(
                "subtree:{} companies/{} branches",
                scope.company_ids.len(),
                scope.branch_ids.len()
            ))
        }
        _ => Err("business-unit configuration scope was absent".to_owned()),
    }
}

fn bounded_policy_field_count(bytes: &[u8], field: &str) -> Result<usize, String> {
    if bytes.is_empty() || bytes.len() > 64 * 1024 {
        return Err(format!("{field} was absent or oversized"));
    }
    serde_json::from_slice::<serde_json::Value>(bytes)
        .ok()
        .and_then(|value| value.as_object().map(serde_json::Map::len))
        .ok_or_else(|| format!("{field} was not a JSON object"))
}

impl BusinessUnitConfigurationRecord {
    fn from_wire(
        expected_tenant_id: &str,
        expected_business_unit: &str,
        wire: platform_admin_target::BusinessUnitConfigurationMessage,
        correlation_id: String,
    ) -> Result<Self, String> {
        if wire.tenant_id != expected_tenant_id || wire.business_unit != expected_business_unit {
            return Err("business-unit configuration identity mismatch".to_owned());
        }
        validate_platform_identifier(&wire.tenant_id, "business-unit tenant ID", false)?;
        Uuid::parse_str(&wire.root_holding_id)
            .map_err(|_| "business-unit holding ID was invalid".to_owned())?;
        let unit = erpx_domain::data_plane::BusinessUnitId::parse(&wire.business_unit)
            .map_err(|_| "business-unit configuration catalog value was invalid".to_owned())?;
        if wire.configuration_version == 0 {
            return Err("business-unit configuration version was invalid".to_owned());
        }
        let organization_scope = business_unit_scope_label(wire.organization_scope)?;
        let mut role_mappings = Vec::with_capacity(wire.directory_role_mappings.len().min(100));
        if wire.directory_role_mappings.len() > 100 {
            return Err("business-unit role mappings were oversized".to_owned());
        }
        for mapping in wire.directory_role_mappings {
            validate_platform_read_text(
                &mapping.group_ref,
                "business-unit directory group",
                false,
                255,
            )?;
            let template =
                erpx_domain::data_plane::BusinessUnitRoleTemplate::parse(&mapping.role_key)
                    .map_err(|_| "business-unit role template was invalid".to_owned())?;
            if template.business_unit != unit {
                return Err("business-unit role template did not match its unit".to_owned());
            }
            if !(1..=2_160).contains(&mapping.assignment_duration_hours) {
                return Err("business-unit assignment duration was invalid".to_owned());
            }
            role_mappings.push(BusinessUnitRoleMappingRecord {
                group_ref: safe_platform_read_text(&mapping.group_ref),
                role_key: mapping.role_key,
                target_scope: business_unit_scope_label(mapping.target_scope)?,
                requires_mfa: mapping.requires_mfa,
                assignment_duration_hours: mapping.assignment_duration_hours,
                approval_limit_minor: mapping.approval_limit_minor,
                active: mapping.active,
            });
        }
        if wire.integration_references.len() > 100 {
            return Err("business-unit integrations were oversized".to_owned());
        }
        for reference in &wire.integration_references {
            validate_platform_read_text(reference, "business-unit integration", false, 255)?;
        }
        validate_platform_read_text(&wire.updated_by, "business-unit updater", false, 255)?;
        validate_platform_read_text(
            &wire.updated_at,
            "business-unit update timestamp",
            false,
            64,
        )?;
        validate_platform_read_text(&correlation_id, "business-unit correlation ID", false, 128)?;
        Ok(Self {
            tenant_id: wire.tenant_id,
            business_unit: wire.business_unit,
            configuration_version: wire.configuration_version,
            active: wire.active,
            organization_scope,
            role_mappings,
            integration_count: wire.integration_references.len(),
            retention_policy_fields: bounded_policy_field_count(
                &wire.retention_policy_json,
                "retention policy",
            )?,
            projection_policy_fields: bounded_policy_field_count(
                &wire.projection_policy_json,
                "projection policy",
            )?,
            workflow_policy_fields: bounded_policy_field_count(
                &wire.workflow_policy_json,
                "workflow policy",
            )?,
            updated_by: safe_platform_read_text(&wire.updated_by),
            updated_at: wire.updated_at,
            correlation_id,
        })
    }
}

impl RootAccessQueueRecord {
    fn from_wire(wire: platform_admin_target::RootAccessQueueEntry) -> Result<Self, String> {
        let request = wire
            .access_request
            .ok_or_else(|| "root access request detail was absent".to_owned())?;
        validate_platform_identifier(&request.request_id, "root access request ID", false)?;
        validate_platform_read_text(&wire.state, "root access state", false, 64)?;
        validate_platform_read_text(&request.reason, "root access reason", false, 512)?;
        validate_platform_read_text(
            &request.ticket_reference,
            "root access ticket reference",
            false,
            128,
        )?;
        validate_platform_read_text(
            &request.requested_until,
            "root access expiry timestamp",
            false,
            64,
        )?;
        let mode = platform_admin_target::RootAccessMode::try_from(request.mode)
            .map_err(|_| "root access mode was invalid".to_owned())?
            .as_str_name()
            .to_owned();
        for action in &request.allowed_actions {
            validate_platform_read_text(action, "root access action", false, 128)?;
        }
        for unit in &request.business_units {
            validate_platform_read_text(unit, "root access business unit", false, 64)?;
        }
        Ok(Self {
            request_id: request.request_id,
            state: wire.state,
            mode,
            allowed_actions: request.allowed_actions,
            business_units: request.business_units,
            reason: request.reason,
            ticket_reference: request.ticket_reference,
            requested_until: request.requested_until,
        })
    }
}

fn validate_infrastructure_reference(value: &str, expected_prefix: &str) -> Result<(), String> {
    let value = value.trim();
    if value.len() < expected_prefix.len() + 1
        || value.len() > 255
        || !value.starts_with(expected_prefix)
        || value.contains("://")
        || value.contains('@')
        || value.contains('=')
    {
        return Err(format!(
            "Enter an opaque secret-manager reference beginning with {expected_prefix}"
        ));
    }
    Ok(())
}

fn validate_infrastructure_reason(value: &str) -> Result<(), String> {
    let length = value.trim().chars().count();
    if !(8..=512).contains(&length) {
        return Err("Enter an audited reason between 8 and 512 characters.".to_owned());
    }
    Ok(())
}

fn root_access_mode(
    value: &str,
) -> Result<(platform_admin_target::RootAccessMode, i64, Vec<String>), String> {
    match value {
        "health_diagnostic" => Ok((
            platform_admin_target::RootAccessMode::HealthDiagnostic,
            8,
            vec!["infrastructure.health.read".to_owned()],
        )),
        "infrastructure_maintenance" => Ok((
            platform_admin_target::RootAccessMode::InfrastructureMaintenance,
            2,
            vec![
                "infrastructure.health.read".to_owned(),
                "infrastructure.configuration.apply".to_owned(),
            ],
        )),
        "business_diagnostic" => Ok((
            platform_admin_target::RootAccessMode::BusinessDiagnostic,
            8,
            vec!["business.diagnostic.read".to_owned()],
        )),
        "business_mutation" => Ok((
            platform_admin_target::RootAccessMode::BusinessMutation,
            2,
            vec!["business.recovery.apply".to_owned()],
        )),
        "emergency_recovery" => Ok((
            platform_admin_target::RootAccessMode::EmergencyRecovery,
            1,
            vec!["infrastructure.recovery.apply".to_owned()],
        )),
        _ => Err("Select a bounded Root access mode.".to_owned()),
    }
}

fn safe_infrastructure_status(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "Your session expired. Sign in and retry.".to_owned(),
        tonic::Code::PermissionDenied => {
            "This action is not authorized for the current persona and scope.".to_owned()
        }
        tonic::Code::InvalidArgument => {
            "The server rejected one or more typed fields. Review the form and retry.".to_owned()
        }
        tonic::Code::Aborted | tonic::Code::FailedPrecondition => {
            "The infrastructure state changed or a required approval is missing. Refresh before retrying."
                .to_owned()
        }
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => {
            "The control plane is temporarily unavailable. This request was not silently retried."
                .to_owned()
        }
        _ => "The infrastructure command failed without exposing backend details.".to_owned(),
    }
}

