/// An explicitly selected tenant/holding scope for the Operations read service.
///
/// The console never infers this scope from platform data. A user must enter both opaque tenant
/// reference and UUID holding scope, after which the server performs the authoritative scope and
/// role checks.
#[derive(Debug, Clone, PartialEq, Eq)]
struct OperationsScope {
    tenant_id: String,
    holding_id: String,
}

impl OperationsScope {
    fn new(tenant_id: &str, holding_id: &str) -> Result<Self, &'static str> {
        let tenant_id = tenant_id.trim();
        if tenant_id.is_empty()
            || tenant_id.len() > 128
            || !tenant_id
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "_-.:".contains(character))
        {
            return Err("Enter a valid opaque tenant reference.");
        }
        let holding_id = Uuid::parse_str(holding_id.trim())
            .map_err(|_| "Enter a valid UUID holding scope.")?
            .to_string();
        Ok(Self {
            tenant_id: tenant_id.to_owned(),
            holding_id,
        })
    }
}

fn validate_operations_record_scope(
    requested: &OperationsScope,
    returned: Option<&TenantScope>,
) -> Result<(), String> {
    match returned.and_then(|scope| scope.scope.as_ref()) {
        Some(tenant_scope::Scope::Holding(holding))
            if holding.holding_id == requested.holding_id =>
        {
            Ok(())
        }
        _ => Err("Operations record scope did not match the authorized holding".to_owned()),
    }
}

fn operations_source_label(value: i32) -> Result<&'static str, String> {
    use operations_target::OperationsSourceContext as Source;
    match Source::try_from(value) {
        Ok(Source::Commercial) => Ok("commercial"),
        Ok(Source::Customer) => Ok("customer"),
        Ok(Source::Marketing) => Ok("marketing"),
        Ok(Source::Crm) => Ok("crm"),
        Ok(Source::Procurement) => Ok("procurement"),
        Ok(Source::Inventory) => Ok("inventory"),
        Ok(Source::Assets) => Ok("assets"),
        Ok(Source::Maintenance) => Ok("maintenance"),
        Ok(Source::Quality) => Ok("quality"),
        Ok(Source::Sales) => Ok("sales"),
        Ok(Source::PeoplePayroll) => Ok("people_payroll"),
        Ok(Source::Pos) => Ok("pos"),
        Ok(Source::Finance) => Ok("finance"),
        Ok(Source::Support) => Ok("support"),
        Ok(Source::Unspecified) | Err(_) => Err("Operations source context was invalid".to_owned()),
    }
}

fn operations_source_value(value: &str) -> Result<i32, String> {
    use operations_target::OperationsSourceContext as Source;
    let source = match value.trim().to_ascii_lowercase().as_str() {
        "commercial" => Source::Commercial,
        "customer" => Source::Customer,
        "marketing" => Source::Marketing,
        "crm" => Source::Crm,
        "procurement" => Source::Procurement,
        "inventory" => Source::Inventory,
        "assets" => Source::Assets,
        "maintenance" => Source::Maintenance,
        "quality" => Source::Quality,
        "sales" => Source::Sales,
        "people_payroll" | "people-payroll" => Source::PeoplePayroll,
        "pos" => Source::Pos,
        "finance" => Source::Finance,
        "support" => Source::Support,
        _ => return Err("Operations policy included an unsupported source context".to_owned()),
    };
    Ok(source as i32)
}

fn operations_exception_status_label(value: i32) -> Result<&'static str, String> {
    use operations_target::OperationsExceptionStatus as Status;
    match Status::try_from(value) {
        Ok(Status::Assigned) => Ok("assigned"),
        Ok(Status::Acknowledged) => Ok("acknowledged"),
        Ok(Status::Escalated) => Ok("escalated"),
        Ok(Status::Resolved) => Ok("resolved"),
        Ok(Status::Closed) => Ok("closed"),
        Ok(Status::Unspecified) | Err(_) => {
            Err("Operations exception status was invalid".to_owned())
        }
    }
}

fn operations_policy_status_label(value: i32) -> Result<&'static str, String> {
    use operations_target::OperationsWorkQueuePolicyStatus as Status;
    match Status::try_from(value) {
        Ok(Status::Active) => Ok("active"),
        Ok(Status::Paused) => Ok("paused"),
        Ok(Status::Retired) => Ok("retired"),
        Ok(Status::Unspecified) | Err(_) => Err("Operations policy status was invalid".to_owned()),
    }
}

