impl OperationsReadModel {
    fn from_wire(
        scope: &OperationsScope,
        summary: operations_target::GetOperationsSummaryCqrsResponse,
        exceptions: operations_target::ListOperationsExceptionQueueResponse,
        policies: operations_target::ListOperationsWorkQueuePoliciesCqrsResponse,
    ) -> Result<Self, String> {
        let summary_metadata = summary
            .metadata
            .ok_or_else(|| "Operations summary metadata was empty".to_string())?;
        let summary_correlation_id = bounded_operations_value(
            &summary_metadata.correlation_id,
            "summary correlation ID",
            false,
            128,
        )?;
        let projection_checkpoint_count = u64::from(
            summary_metadata
                .projection
                .as_ref()
                .and_then(|projection| projection.checkpoint.as_ref())
                .is_some(),
        );
        let summary = summary
            .summary
            .ok_or_else(|| "Operations summary response was empty".to_string())?;
        let source_counts = summary
            .source_counts
            .into_iter()
            .take(100)
            .map(|source| {
                Ok(OperationsSourceCountRecord {
                    source_domain: bounded_operations_value(
                        operations_source_label(source.source_context)?,
                        "source domain",
                        false,
                        128,
                    )?,
                    reference_count: source.reference_count,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        let summary = OperationsSummaryRecord {
            tenant_id: scope.tenant_id.clone(),
            holding_id: scope.holding_id.clone(),
            projection_name: "operations".to_owned(),
            read_row_count: summary.read_row_count,
            exception_count: summary.exception_count,
            projection_checkpoint_count,
            event_count: summary.event_count,
            source_reference_count: summary.source_reference_count,
            source_counts,
            latest_event_at: bounded_operations_value(
                summary.latest_event_at.as_deref().unwrap_or_default(),
                "latest event timestamp",
                true,
                64,
            )?,
        };
        let exception_metadata = exceptions
            .metadata
            .ok_or_else(|| "Operations exception metadata was empty".to_string())?;
        let exception_correlation_id = bounded_operations_value(
            &exception_metadata.correlation_id,
            "exception correlation ID",
            false,
            128,
        )?;
        let raw_next_cursor = exceptions.next_cursor.unwrap_or_default();
        let exception_rows = exceptions.exceptions;
        if exception_rows.len() > 100 {
            return Err("Operations exception page exceeded its display bound".to_string());
        }
        let exceptions = exception_rows
            .into_iter()
            .map(|exception| {
                validate_operations_record_scope(scope, exception.scope.as_ref())?;
                Ok(OperationsExceptionRecord {
                    exception_id: bounded_operations_value(
                        &exception.exception_id,
                        "exception ID",
                        false,
                        128,
                    )?,
                    category: bounded_operations_value(
                        &exception.category,
                        "exception category",
                        false,
                        128,
                    )?,
                    severity: bounded_operations_value(
                        &exception.severity,
                        "exception severity",
                        false,
                        64,
                    )?,
                    status: bounded_operations_value(
                        operations_exception_status_label(exception.status)?,
                        "exception status",
                        false,
                        64,
                    )?,
                    assigned_to: bounded_operations_value(
                        &exception.assignee_id,
                        "exception assignee",
                        true,
                        128,
                    )?,
                    manager_ref: bounded_operations_value(
                        &exception.manager_id,
                        "exception manager",
                        true,
                        128,
                    )?,
                    due_at: bounded_operations_value(
                        &exception.due_at,
                        "exception due timestamp",
                        true,
                        64,
                    )?,
                    aggregate_version: exception.aggregate_version,
                    updated_at: bounded_operations_value(
                        &exception.updated_at,
                        "exception updated timestamp",
                        false,
                        64,
                    )?,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        let next_cursor =
            bounded_operations_value(&raw_next_cursor, "Operations pagination cursor", true, 512)?;
        let has_more = !next_cursor.is_empty();
        let policy_metadata = policies
            .metadata
            .ok_or_else(|| "Operations policy metadata was empty".to_string())?;
        let _policy_correlation_id = bounded_operations_value(
            &policy_metadata.correlation_id,
            "policy correlation ID",
            false,
            128,
        )?;
        let policy_rows = policies.policies;
        if policy_rows.len() > 100 {
            return Err("Operations policy page exceeded its display bound".to_string());
        }
        let policies = policy_rows
            .into_iter()
            .map(|policy| {
                validate_operations_record_scope(scope, policy.scope.as_ref())?;
                Ok(OperationsPolicyRecord {
                    policy_id: bounded_operations_value(
                        &policy.policy_id,
                        "policy ID",
                        false,
                        128,
                    )?,
                    name: bounded_operations_value(&policy.name, "policy name", false, 255)?,
                    allowed_domains: policy
                        .allowed_sources
                        .into_iter()
                        .take(16)
                        .map(|source| {
                            bounded_operations_value(
                                operations_source_label(source)?,
                                "policy domain",
                                false,
                                128,
                            )
                        })
                        .collect::<Result<Vec<_>, _>>()?,
                    escalation_after_minutes: policy.escalation_after_minutes,
                    status: bounded_operations_value(
                        operations_policy_status_label(policy.status)?,
                        "policy status",
                        false,
                        64,
                    )?,
                    aggregate_version: policy.aggregate_version,
                    updated_at: bounded_operations_value(
                        &policy.updated_at,
                        "policy updated timestamp",
                        false,
                        64,
                    )?,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            summary,
            exceptions,
            policies,
            has_more,
            next_cursor,
            summary_correlation_id,
            exception_correlation_id,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FinanceScope {
    tenant_id: String,
    holding_ref: String,
    holding_id: String,
}

impl FinanceScope {
    fn new(tenant_id: &str, holding_ref: &str, holding_id: &str) -> Result<Self, &'static str> {
        let tenant = OperationsScope::new(tenant_id, holding_id)
            .map_err(|_| "Enter a valid opaque tenant reference and holding UUID.")?;
        let holding_ref = holding_ref.trim();
        if holding_ref.is_empty()
            || holding_ref.len() > 128
            || !holding_ref
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "_-".contains(character))
        {
            return Err("Enter a valid opaque Finance holding reference.");
        }
        Ok(Self {
            tenant_id: tenant.tenant_id,
            holding_ref: holding_ref.to_owned(),
            holding_id: tenant.holding_id,
        })
    }

    fn tenant_scope(&self) -> TenantScope {
        TenantScope {
            scope: Some(tenant_scope::Scope::Holding(HoldingScope {
                holding_id: self.holding_id.clone(),
            })),
        }
    }

    fn tenant_route(&self) -> ProtoTenantRoute {
        ProtoTenantRoute {
            tenant_id: self.tenant_id.clone(),
            holding_ref: self.holding_ref.clone(),
        }
    }
}

