#[derive(Debug, Clone, PartialEq, Eq)]
struct BillingScope {
    tenant_id: String,
    holding_id: String,
    currency: String,
}

impl BillingScope {
    fn new(tenant_id: &str, holding_id: &str, currency: &str) -> Result<Self, &'static str> {
        let tenant_id = tenant_id.trim();
        if tenant_id.is_empty()
            || tenant_id.len() > 128
            || !tenant_id
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "_-.:".contains(character))
        {
            return Err("Enter a valid opaque tenant reference.");
        }
        let holding_id = holding_id.trim();
        let holding_id = if holding_id.is_empty() {
            String::new()
        } else {
            Uuid::parse_str(holding_id)
                .map_err(|_| "Enter a valid holding UUID, or leave it empty for a platform read.")?
                .to_string()
        };
        let currency = currency.trim().to_ascii_uppercase();
        if currency.len() != 3
            || !currency
                .chars()
                .all(|character| character.is_ascii_uppercase())
        {
            return Err("Enter a three-letter billing currency.");
        }
        Ok(Self {
            tenant_id: tenant_id.to_owned(),
            holding_id,
            currency,
        })
    }
}

