#[derive(Debug, Clone, PartialEq, Eq)]
struct QualityCommandReceiptModel {
    inspection_id: String,
    version: u64,
    replayed: bool,
    correlation_id: String,
}

impl QualityReadModel {
    fn from_wire(
        scope: &QualityScope,
        response: ListQualityInspectionsResponse,
    ) -> Result<Self, String> {
        if response.inspections.len() > 100 {
            return Err("Quality read response exceeded its display bound".into());
        }
        let metadata = response
            .metadata
            .ok_or_else(|| "Quality read response omitted query metadata".to_string())?;
        let correlation_id = bounded_finance_value(
            &metadata.correlation_id,
            "Quality correlation ID",
            false,
            128,
        )?;
        let next_cursor = response
            .next_cursor
            .map(|value| bounded_finance_value(&value, "Quality next cursor", false, 512))
            .transpose()?;
        let rows = response
            .inspections
            .into_iter()
            .map(|row| {
                let branch_id = row.branch_id.unwrap_or_default();
                if row.holding_id != scope.finance.holding_id
                    || row.company_id != scope.company_id
                    || branch_id != scope.branch_id
                    || Uuid::parse_str(&row.inspection_id).is_err()
                    || Uuid::parse_str(&row.holding_id).is_err()
                    || Uuid::parse_str(&row.company_id).is_err()
                    || (!branch_id.is_empty() && Uuid::parse_str(&branch_id).is_err())
                    || row.source_version == 0
                    || row.quantity == 0
                {
                    return Err("Quality read row identity or version was invalid".into());
                }
                let reference =
                    bounded_finance_value(&row.reference, "Quality reference", false, 128)?;
                let kind = quality_kind_label(row.kind)?.to_owned();
                let status = quality_status_label(row.status)?.to_owned();
                let projected_at =
                    bounded_finance_value(&row.projected_at, "Quality projected_at", false, 64)?;
                Ok(QualityInspectionRowModel {
                    inspection_id: row.inspection_id,
                    holding_id: row.holding_id,
                    company_id: row.company_id,
                    branch_id,
                    reference,
                    kind,
                    status,
                    quantity: row.quantity,
                    source_version: row.source_version,
                    projected_at,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            scope: scope.clone(),
            rows,
            has_more: next_cursor.is_some(),
            next_cursor,
            correlation_id,
        })
    }
}

fn quality_kind_label(value: i32) -> Result<&'static str, String> {
    match QualityInspectionKind::try_from(value) {
        Ok(QualityInspectionKind::Incoming) => Ok("incoming"),
        Ok(QualityInspectionKind::InProcess) => Ok("in_process"),
        Ok(QualityInspectionKind::Final) => Ok("final"),
        Ok(QualityInspectionKind::Unspecified) | Err(_) => {
            Err("Quality read row kind was invalid".into())
        }
    }
}

fn quality_status_label(value: i32) -> Result<&'static str, String> {
    match QualityInspectionStatus::try_from(value) {
        Ok(QualityInspectionStatus::Draft) => Ok("draft"),
        Ok(QualityInspectionStatus::InProgress) => Ok("in_progress"),
        Ok(QualityInspectionStatus::Passed) => Ok("passed"),
        Ok(QualityInspectionStatus::Failed) => Ok("failed"),
        Ok(QualityInspectionStatus::Released) => Ok("released"),
        Ok(QualityInspectionStatus::Cancelled) => Ok("cancelled"),
        Ok(QualityInspectionStatus::Unspecified) | Err(_) => {
            Err("Quality read row status was invalid".into())
        }
    }
}

fn quality_command_context(
    principal_ref: &str,
    session_id: &str,
    scope: &QualityScope,
    purpose: &str,
    idempotency_key: &str,
    expected_version: Option<u64>,
) -> Result<CommandRequestMetadata, String> {
    let session_id = Uuid::parse_str(session_id)
        .map_err(|_| "the authenticated Quality session must be a UUID".to_string())?;
    let correlation_id = Uuid::new_v4().to_string();
    Ok(CommandRequestMetadata {
        contract_version: u32::from(CONTRACT_VERSION),
        command_id: Uuid::new_v4().to_string(),
        idempotency_key: idempotency_key.to_owned(),
        correlation_id: correlation_id.clone(),
        causation_id: None,
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_string(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(scope.tenant_scope()),
        audit: Some(AuditContext {
            purpose: purpose.to_owned(),
            customer_visible: false,
            module: "quality".into(),
            correlation_id,
        }),
        expected_aggregate_version: expected_version,
        subscription_id: None,
        mfa_code: None,
        tenant_route: Some(ProtoTenantRoute {
            tenant_id: scope.finance.tenant_id.clone(),
            holding_ref: scope.finance.holding_ref.clone(),
        }),
    })
}

fn quality_uuid(value: &str, field: &str) -> Result<String, String> {
    let value = value.trim();
    Uuid::parse_str(value).map_err(|_| format!("{field} must be a UUID"))?;
    Ok(value.to_owned())
}

fn quality_quantity(value: &str, field: &str, allow_zero: bool) -> Result<u64, String> {
    let quantity = value
        .trim()
        .parse::<u64>()
        .map_err(|_| format!("{field} must be a whole number"))?;
    if !allow_zero && quantity == 0 {
        return Err(format!("{field} must be greater than zero"));
    }
    Ok(quantity)
}

fn quality_note(value: &str, field: &str) -> Result<String, String> {
    let value = value.trim();
    if value.len() > 2_048 || value.chars().any(char::is_control) {
        return Err(format!(
            "{field} must be at most 2,048 printable characters"
        ));
    }
    Ok(value.to_owned())
}

fn quality_receipt_model(
    receipt: Option<ProtoCommandReceipt>,
    inspection: Option<QualityInspection>,
) -> Result<QualityCommandReceiptModel, String> {
    let receipt = receipt.ok_or_else(|| "Quality command receipt was absent".to_string())?;
    let inspection = inspection.ok_or_else(|| "Quality command result was absent".to_string())?;
    let inspection_id = quality_uuid(&inspection.inspection_id, "inspection ID")?;
    if inspection.source_version == 0 {
        return Err("Quality command receipt version was invalid".into());
    }
    let aggregate = receipt
        .aggregate
        .ok_or_else(|| "Quality command receipt omitted aggregate metadata".to_string())?;
    if aggregate.aggregate_id != inspection_id || aggregate.version != inspection.source_version {
        return Err("Quality command receipt did not match its inspection".into());
    }
    let correlation_id = bounded_finance_value(
        &receipt.correlation_id,
        "Quality correlation ID",
        false,
        128,
    )?;
    Ok(QualityCommandReceiptModel {
        inspection_id,
        version: inspection.source_version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

