fn finance_command_text(value: &str, field: &str, max_len: usize) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty() || value.len() > max_len || value.chars().any(char::is_control) {
        return Err(format!(
            "{field} is required and must be at most {max_len} bytes"
        ));
    }
    Ok(value.to_owned())
}

fn finance_command_uuid(value: &str, field: &str) -> Result<String, String> {
    let value = finance_command_text(value, field, 64)?;
    Uuid::parse_str(&value).map_err(|_| format!("{field} must be a UUID"))?;
    Ok(value)
}

fn finance_command_date(value: &str, field: &str) -> Result<String, String> {
    let value = finance_command_text(value, field, 10)?;
    if value.len() != 10
        || value.as_bytes().get(4) != Some(&b'-')
        || value.as_bytes().get(7) != Some(&b'-')
        || !value
            .chars()
            .enumerate()
            .all(|(index, character)| index == 4 || index == 7 || character.is_ascii_digit())
    {
        return Err(format!("{field} must be YYYY-MM-DD"));
    }
    Ok(value)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FinanceJournalRecord {
    journal_id: String,
    company_id: String,
    period_id: String,
    source_version: u64,
    posted_at: String,
}

fn bounded_finance_uuid(value: &str, label: &str) -> Result<String, &'static str> {
    let value = value.trim();
    if Uuid::parse_str(value).is_err() {
        return Err(match label {
            "period" => "Enter a valid Finance period UUID.",
            "company" => "Enter a valid Finance company UUID.",
            _ => "Enter a valid Finance UUID.",
        });
    }
    Ok(value.to_owned())
}

fn bounded_finance_value(
    value: &str,
    field: &str,
    allow_empty: bool,
    max_len: usize,
) -> Result<String, String> {
    let value = value.trim();
    if (!allow_empty && value.is_empty())
        || value.len() > max_len
        || value.chars().any(char::is_control)
    {
        return Err(format!("{field} was malformed"));
    }
    Ok(value.to_owned())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SalesScope {
    finance: FinanceScope,
    aggregate_type: String,
    aggregate_id: String,
}

impl SalesScope {
    fn new(
        tenant_id: &str,
        holding_ref: &str,
        holding_id: &str,
        aggregate_type: &str,
        aggregate_id: &str,
    ) -> Result<Self, &'static str> {
        let finance = FinanceScope::new(tenant_id, holding_ref, holding_id)
            .map_err(|_| "Enter a valid Sales tenant, holding reference, and holding UUID.")?;
        let aggregate_type = aggregate_type.trim();
        if !matches!(aggregate_type, "quote" | "sales_order") {
            return Err("Choose the Sales-owned quote or sales_order record type.");
        }
        let aggregate_id = bounded_finance_uuid(aggregate_id, "aggregate")
            .map_err(|_| "Enter a valid Sales aggregate UUID.")?;
        Ok(Self {
            finance,
            aggregate_type: aggregate_type.to_owned(),
            aggregate_id,
        })
    }
}

