#[derive(Debug, Clone, PartialEq, Eq)]
struct SalesTransitionResult {
    aggregate_type: String,
    aggregate_id: String,
    version: u64,
    replayed: bool,
    correlation_id: String,
}

impl SalesTransitionResult {
    fn from_target(
        scope: &SalesScope,
        response: erpx_cqrs::CommandReceipt<erpx_sales::SalesMutationResult>,
    ) -> Result<Self, String> {
        let aggregate_type = response.aggregate.aggregate_type;
        let aggregate_id = response.aggregate.aggregate_id.to_string();
        if aggregate_type != scope.aggregate_type
            || aggregate_id != scope.aggregate_id
            || response.aggregate.version == 0
        {
            return Err("Sales transition receipt identity was invalid".into());
        }
        Ok(Self {
            aggregate_type,
            aggregate_id,
            version: response.aggregate.version,
            replayed: response.replayed,
            correlation_id: response.correlation_id.to_string(),
        })
    }
}

impl SalesReadModel {
    fn from_target(
        scope: &SalesScope,
        response: erpx_cqrs::QueryResult<erpx_sales::SalesQueryResponse>,
    ) -> Result<Self, String> {
        let (present, source_version, identity) = match response.value {
            erpx_sales::SalesQueryResponse::Quote(value) if scope.aggregate_type == "quote" => {
                let identity = value
                    .as_ref()
                    .map(|quote| quote.quote_id.as_uuid().to_string());
                (
                    value.is_some(),
                    value.map_or(0, |quote| quote.version),
                    identity,
                )
            }
            erpx_sales::SalesQueryResponse::SalesOrder(value)
                if scope.aggregate_type == "sales_order" =>
            {
                let identity = value
                    .as_ref()
                    .map(|order| order.sales_order_id.as_uuid().to_string());
                (
                    value.is_some(),
                    value.map_or(0, |order| order.version),
                    identity,
                )
            }
            _ => return Err("Sales query response type did not match the requested record".into()),
        };
        if identity
            .as_deref()
            .is_some_and(|value| value != scope.aggregate_id)
            || (present && source_version == 0)
        {
            return Err("Sales response identity or source version was invalid".into());
        }
        Ok(Self {
            scope: scope.clone(),
            present,
            source_version,
            correlation_id: response.metadata.correlation_id.to_string(),
        })
    }
}

