#[derive(Debug, Clone, PartialEq, Eq)]
struct ScmListReadModel {
    scope: ScmListScope,
    rows: Vec<ScmListRowModel>,
    has_more: bool,
    next_cursor: Option<String>,
    correlation_id: String,
}

impl ScmListReadModel {
    fn correlation_id(
        metadata: Option<erpx_proto::common::v2::QueryMetadata>,
    ) -> Result<String, String> {
        let correlation_id = metadata
            .ok_or_else(|| "SCM read response omitted query metadata".to_owned())?
            .correlation_id;
        Uuid::parse_str(&correlation_id)
            .map_err(|_| "SCM read correlation ID was invalid".to_owned())?;
        Ok(correlation_id)
    }

    fn from_procurement(
        scope: &ScmListScope,
        response: procurement_target::ListPurchaseOrdersResponse,
    ) -> Result<Self, String> {
        if scope.context != ProductContext::Procurement || response.orders.len() > 100 {
            return Err("SCM read response exceeded its display bound".into());
        }
        let correlation_id = Self::correlation_id(response.metadata)?;
        let rows = response
            .orders
            .into_iter()
            .map(|order| {
                let aggregate_id = bounded_finance_uuid(&order.purchase_order_id, "purchase order")
                    .map_err(|_| "SCM read aggregate identity was invalid".to_owned())?;
                validate_scm_target_scope(scope, order.scope.as_ref())?;
                if order.source_version == 0 {
                    return Err("SCM read source version was invalid".to_owned());
                }
                let projected_at =
                    bounded_finance_value(&order.projected_at, "SCM projected_at", false, 64)?;
                Ok(ScmListRowModel {
                    aggregate_type: "purchase_order".to_owned(),
                    aggregate_id,
                    reference: bounded_finance_value(
                        &order.order_code,
                        "purchase order code",
                        false,
                        128,
                    )?,
                    source_version: order.source_version,
                    projected_at,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        let next_cursor = response.next_cursor;
        Ok(Self {
            scope: scope.clone(),
            rows,
            has_more: next_cursor.is_some(),
            next_cursor,
            correlation_id,
        })
    }

    fn from_inventory(
        scope: &ScmListScope,
        response: inventory_target::ListStockItemsResponse,
    ) -> Result<Self, String> {
        if scope.context != ProductContext::Inventory || response.items.len() > 100 {
            return Err("SCM read response exceeded its display bound".into());
        }
        let correlation_id = Self::correlation_id(response.metadata)?;
        let rows = response
            .items
            .into_iter()
            .map(|item| {
                let aggregate_id = bounded_finance_uuid(&item.stock_item_id, "stock item")
                    .map_err(|_| "SCM read aggregate identity was invalid".to_owned())?;
                validate_scm_target_scope(scope, item.scope.as_ref())?;
                if item.source_version == 0 {
                    return Err("SCM read source version was invalid".to_owned());
                }
                Ok(ScmListRowModel {
                    aggregate_type: "stock_item".to_owned(),
                    aggregate_id,
                    reference: bounded_finance_value(
                        &item.item_code,
                        "stock item code",
                        false,
                        128,
                    )?,
                    source_version: item.source_version,
                    projected_at: bounded_finance_value(
                        &item.projected_at,
                        "SCM projected_at",
                        false,
                        64,
                    )?,
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        let next_cursor = response.next_cursor;
        Ok(Self {
            scope: scope.clone(),
            rows,
            has_more: next_cursor.is_some(),
            next_cursor,
            correlation_id,
        })
    }
}

fn validate_scm_target_scope(
    expected: &ScmListScope,
    actual: Option<&TenantScope>,
) -> Result<(), String> {
    let matches = match actual.and_then(|scope| scope.scope.as_ref()) {
        Some(tenant_scope::Scope::Company(scope)) => {
            expected.branch_id.is_empty()
                && scope.holding_id == expected.finance.holding_id
                && scope.company_id == expected.company_id
        }
        Some(tenant_scope::Scope::Branch(scope)) => {
            scope.holding_id == expected.finance.holding_id
                && scope.company_id == expected.company_id
                && scope.branch_id == expected.branch_id
        }
        _ => false,
    };
    if matches {
        Ok(())
    } else {
        Err("SCM read row was outside the authorized organization scope".to_owned())
    }
}

