impl ScmTransitionResult {
    fn from_target(
        scope: &ProductAggregateScope,
        response: ProtoCommandReceipt,
    ) -> Result<Self, String> {
        let receipt = response
            .aggregate
            .ok_or_else(|| "SCM transition response omitted its aggregate receipt".to_owned())?;
        if receipt.aggregate_type != scope.aggregate_type
            || receipt.aggregate_id != scope.aggregate_id
            || receipt.version == 0
        {
            return Err("SCM transition receipt identity was invalid".into());
        }
        Uuid::parse_str(&response.correlation_id)
            .map_err(|_| "SCM transition correlation ID was invalid".to_owned())?;
        Ok(Self {
            version: receipt.version,
            replayed: response.replayed,
            correlation_id: response.correlation_id,
        })
    }
}

