fn hr_employee_status(value: erpx_people_payroll::EmployeeStatus) -> &'static str {
    match value {
        erpx_people_payroll::EmployeeStatus::Draft => "draft",
        erpx_people_payroll::EmployeeStatus::Active => "active",
        erpx_people_payroll::EmployeeStatus::OnLeave => "on_leave",
        erpx_people_payroll::EmployeeStatus::Suspended => "suspended",
        erpx_people_payroll::EmployeeStatus::Terminated => "terminated",
    }
}

fn hr_leave_status(value: erpx_people_payroll::LeaveStatus) -> &'static str {
    match value {
        erpx_people_payroll::LeaveStatus::Draft => "draft",
        erpx_people_payroll::LeaveStatus::Submitted => "submitted",
        erpx_people_payroll::LeaveStatus::Approved => "approved",
        erpx_people_payroll::LeaveStatus::Rejected => "rejected",
        erpx_people_payroll::LeaveStatus::Cancelled => "cancelled",
        erpx_people_payroll::LeaveStatus::Taken => "taken",
    }
}

fn hr_expense_status(value: erpx_people_payroll::ExpenseStatus) -> &'static str {
    match value {
        erpx_people_payroll::ExpenseStatus::Draft => "draft",
        erpx_people_payroll::ExpenseStatus::Submitted => "submitted",
        erpx_people_payroll::ExpenseStatus::Approved => "approved",
        erpx_people_payroll::ExpenseStatus::Rejected => "rejected",
        erpx_people_payroll::ExpenseStatus::Reimbursed => "reimbursed",
    }
}

fn hr_payroll_status(value: erpx_people_payroll::PayrollStatus) -> &'static str {
    match value {
        erpx_people_payroll::PayrollStatus::Draft => "draft",
        erpx_people_payroll::PayrollStatus::Review => "review",
        erpx_people_payroll::PayrollStatus::Approved => "approved",
        erpx_people_payroll::PayrollStatus::Posted => "posted",
        erpx_people_payroll::PayrollStatus::Cancelled => "cancelled",
    }
}

fn hr_cqrs_scope_parts(
    requested: &HrEmployeeScope,
    actual: &erpx_kernel::TenantScope,
) -> Result<(String, String), String> {
    if actual != &hr_cqrs_scope(requested)? {
        return Err("People & Payroll row escaped its requested typed scope.".to_owned());
    }
    match actual {
        erpx_kernel::TenantScope::Company { company_id, .. } => {
            Ok((company_id.to_string(), String::new()))
        }
        erpx_kernel::TenantScope::Branch {
            company_id,
            branch_id,
            ..
        } => Ok((company_id.to_string(), branch_id.to_string())),
        _ => Err("People & Payroll returned a non-exact scope.".to_owned()),
    }
}

async fn fetch_hr_bundle_cqrs(
    scope: HrEmployeeScope,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<HrReadBundle, String> {
    use erpx_ui_foundation::QueryGateway;

    let gateway = crate::features::people_payroll::PeoplePayrollGateway::new(
        hr_cqrs_transport(&scope, &access_token).await?,
    );
    let employees = gateway
        .execute(hr_cqrs_query(
            &scope,
            &principal_ref,
            &session_id,
            erpx_people_payroll::PeoplePayrollQuery::ListEmployees(
                erpx_people_payroll::ListEmployees {
                    filter: erpx_people_payroll::ports::EmployeeListFilter {
                        status: None,
                        page_size: 25,
                        cursor: None,
                    },
                },
            ),
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    let leaves = gateway
        .execute(hr_cqrs_query(
            &scope,
            &principal_ref,
            &session_id,
            erpx_people_payroll::PeoplePayrollQuery::ListLeaveRequests(
                erpx_people_payroll::ListLeaveRequests {
                    filter: erpx_people_payroll::ports::LeaveRequestListFilter {
                        employee_id: None,
                        status: None,
                        page_size: 25,
                        cursor: None,
                    },
                },
            ),
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    let expenses = gateway
        .execute(hr_cqrs_query(
            &scope,
            &principal_ref,
            &session_id,
            erpx_people_payroll::PeoplePayrollQuery::ListExpenseClaims(
                erpx_people_payroll::ListExpenseClaims {
                    filter: erpx_people_payroll::ports::ExpenseClaimListFilter {
                        employee_id: None,
                        status: None,
                        page_size: 25,
                        cursor: None,
                    },
                },
            ),
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    let payroll = gateway
        .execute(hr_cqrs_query(
            &scope,
            &principal_ref,
            &session_id,
            erpx_people_payroll::PeoplePayrollQuery::ListPayrollRuns(
                erpx_people_payroll::ListPayrollRuns {
                    filter: erpx_people_payroll::ports::PayrollRunListFilter {
                        status: None,
                        starts_on_or_after: None,
                        ends_on_or_before: None,
                        page_size: 25,
                        cursor: None,
                    },
                },
            ),
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;

    let employee_metadata = employees.metadata;
    let employees = match employees.value {
        erpx_people_payroll::PeoplePayrollQueryResponse::Employees(value) => value,
        _ => return Err("People & Payroll employee query returned the wrong response.".to_owned()),
    };
    let leave_metadata = leaves.metadata;
    let leaves = match leaves.value {
        erpx_people_payroll::PeoplePayrollQueryResponse::LeaveRequests(value) => value,
        _ => return Err("People & Payroll leave query returned the wrong response.".to_owned()),
    };
    let expense_metadata = expenses.metadata;
    let expenses = match expenses.value {
        erpx_people_payroll::PeoplePayrollQueryResponse::ExpenseClaims(value) => value,
        _ => return Err("People & Payroll expense query returned the wrong response.".to_owned()),
    };
    let payroll_metadata = payroll.metadata;
    let payroll = match payroll.value {
        erpx_people_payroll::PeoplePayrollQueryResponse::PayrollRuns(value) => value,
        _ => return Err("People & Payroll payroll query returned the wrong response.".to_owned()),
    };

    let employee_has_more = employees.next_cursor.is_some();
    let leave_has_more = leaves.next_cursor.is_some();
    let expense_has_more = expenses.next_cursor.is_some();
    let payroll_has_more = payroll.next_cursor.is_some();
    let correlation_id = employee_metadata.correlation_id.to_string();
    let employees = employees
        .employees
        .into_iter()
        .map(|value| {
            let (company_id, branch_id) = hr_cqrs_scope_parts(&scope, &value.scope)?;
            Ok(HrEmployeeRecord {
                employee_id: value.employee_id.as_uuid().to_string(),
                employee_ref: value.employee_code,
                display_name: value.display_name,
                company_id,
                branch_id,
                status: hr_employee_status(value.status).to_owned(),
                hired_on: value.hired_on.to_string(),
                terminated_on: value
                    .terminated_on
                    .map(|date| date.to_string())
                    .unwrap_or_default(),
                source_version: value.version,
                projected_at: pos_projected_at(&employee_metadata, value.updated_at),
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    let leave_requests = leaves
        .leave_requests
        .into_iter()
        .map(|value| {
            hr_cqrs_scope_parts(&scope, &value.scope)?;
            Ok(HrLeaveRecord {
                leave_id: value.leave_request_id.as_uuid().to_string(),
                employee_id: value.employee_id.as_uuid().to_string(),
                starts_on: value.starts_on.to_string(),
                ends_on: value.ends_on.to_string(),
                reason: value.reason,
                status: hr_leave_status(value.status).to_owned(),
                requested_by: value.requested_by,
                approved_by: value.approved_by.unwrap_or_default(),
                source_version: value.version,
                projected_at: pos_projected_at(&leave_metadata, value.updated_at),
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    let expenses = expenses
        .expense_claims
        .into_iter()
        .map(|value| {
            hr_cqrs_scope_parts(&scope, &value.scope)?;
            Ok(HrExpenseRecord {
                expense_id: value.expense_claim_id.as_uuid().to_string(),
                employee_id: value.employee_id.as_uuid().to_string(),
                currency: value.currency.as_str().to_owned(),
                amount_minor: value.amount_minor,
                status: hr_expense_status(value.status).to_owned(),
                submitted_by: value.claimed_by,
                approved_by: value.approved_by.unwrap_or_default(),
                source_version: value.version,
                projected_at: pos_projected_at(&expense_metadata, value.updated_at),
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    let payroll_runs = payroll
        .payroll_runs
        .into_iter()
        .map(|value| {
            hr_cqrs_scope_parts(&scope, &value.scope)?;
            Ok(HrPayrollRecord {
                payroll_id: value.payroll_run_id.as_uuid().to_string(),
                starts_on: value.starts_on.to_string(),
                ends_on: value.ends_on.to_string(),
                status: hr_payroll_status(value.status).to_owned(),
                prepared_by: value.prepared_by,
                reviewed_by: value.reviewed_by.unwrap_or_default(),
                approved_by: value.approved_by.unwrap_or_default(),
                total_gross_minor: value.total_gross_minor,
                total_deductions_minor: value.total_deductions_minor,
                total_net_minor: value.total_net_minor,
                lines: value
                    .lines
                    .into_iter()
                    .enumerate()
                    .map(|(index, line)| HrPayrollLineRecord {
                        line_no: u32::try_from(index + 1).unwrap_or(u32::MAX),
                        employee_id: line.employee_id.as_uuid().to_string(),
                        gross_minor: line.gross_minor,
                        deductions_minor: line.deductions_minor,
                        net_minor: line.net_minor,
                    })
                    .collect(),
                lines_truncated: false,
                source_version: value.version,
                projected_at: pos_projected_at(&payroll_metadata, value.updated_at),
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(HrReadBundle {
        scope,
        employees,
        employee_has_more,
        leave_requests,
        leave_has_more,
        expenses,
        expense_has_more,
        payroll_runs,
        payroll_has_more,
        reassignments: Vec::new(),
        reassignment_has_more: false,
        correlation_id,
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LegalContractScope {
    finance: FinanceScope,
    company_id: String,
    branch_id: String,
}

impl LegalContractScope {
    fn new(
        tenant_id: &str,
        holding_ref: &str,
        holding_id: &str,
        company_id: &str,
        branch_id: &str,
    ) -> Result<Self, &'static str> {
        let finance = FinanceScope::new(tenant_id, holding_ref, holding_id)
            .map_err(|_| "Enter a valid Legal tenant, holding reference, and holding UUID.")?;
        let company_id = bounded_finance_uuid(company_id, "company")
            .map_err(|_| "Enter a valid Legal company UUID.")?;
        let branch_id = branch_id.trim();
        if !branch_id.is_empty() && Uuid::parse_str(branch_id).is_err() {
            return Err("Enter a valid Legal branch UUID or leave the branch filter empty.");
        }
        Ok(Self {
            finance,
            company_id,
            branch_id: branch_id.to_owned(),
        })
    }

    fn tenant_scope(&self) -> TenantScope {
        let scope = if self.branch_id.is_empty() {
            tenant_scope::Scope::Company(CompanyScope {
                holding_id: self.finance.holding_id.clone(),
                company_id: self.company_id.clone(),
            })
        } else {
            tenant_scope::Scope::Branch(BranchScope {
                holding_id: self.finance.holding_id.clone(),
                company_id: self.company_id.clone(),
                branch_id: self.branch_id.clone(),
            })
        };
        TenantScope { scope: Some(scope) }
    }

    fn tenant_route(&self) -> ProtoTenantRoute {
        ProtoTenantRoute {
            tenant_id: self.finance.tenant_id.clone(),
            holding_ref: self.finance.holding_ref.clone(),
        }
    }
}

fn legal_contract_status_label(value: i32) -> Result<&'static str, String> {
    use legal_target::LegalContractStatus as Status;
    match Status::try_from(value) {
        Ok(Status::Draft) => Ok("draft"),
        Ok(Status::Review) => Ok("review"),
        Ok(Status::Approved) => Ok("approved"),
        Ok(Status::Active) => Ok("active"),
        Ok(Status::Expired) => Ok("expired"),
        Ok(Status::Terminated) => Ok("terminated"),
        Ok(Status::Archived) => Ok("archived"),
        Ok(Status::Unspecified) | Err(_) => Err("Legal contract status was invalid".to_owned()),
    }
}

fn legal_target_query_metadata(
    scope: &LegalContractScope,
    principal_ref: &str,
    session_id: &str,
) -> Result<QueryRequestMetadata, String> {
    Uuid::parse_str(session_id)
        .map_err(|_| "the authenticated Legal session must be a UUID".to_owned())?;
    let correlation_id = Uuid::new_v4().to_string();
    Ok(QueryRequestMetadata {
        contract_version: u32::from(CONTRACT_VERSION),
        query_id: Uuid::new_v4().to_string(),
        correlation_id: correlation_id.clone(),
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_owned(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(scope.tenant_scope()),
        audit: Some(AuditContext {
            purpose: "legal_contract_console_read".to_owned(),
            customer_visible: false,
            module: "legal".to_owned(),
            correlation_id,
        }),
        consistency: Some(QueryConsistency {
            requirement: Some(query_consistency::Requirement::Eventual(
                EventualConsistency {},
            )),
        }),
        tenant_route: Some(scope.tenant_route()),
    })
}

