impl PosSaleScope {
    fn new(
        tenant_id: &str,
        holding_ref: &str,
        holding_id: &str,
        company_id: &str,
        branch_id: &str,
    ) -> Result<Self, &'static str> {
        let finance = FinanceScope::new(tenant_id, holding_ref, holding_id)
            .map_err(|_| "Enter a valid POS tenant, holding reference, and holding UUID.")?;
        let company_id = bounded_finance_uuid(company_id, "company")
            .map_err(|_| "Enter a valid POS company UUID.")?;
        let branch_id = branch_id.trim();
        if !branch_id.is_empty() && Uuid::parse_str(branch_id).is_err() {
            return Err("Enter a valid POS branch UUID or leave the branch filter empty.");
        }
        Ok(Self {
            finance,
            company_id,
            branch_id: branch_id.to_owned(),
        })
    }
}

