fn bounded_operations_value(
    value: &str,
    field: &str,
    allow_empty: bool,
    max_len: usize,
) -> Result<String, String> {
    let value = value.trim();
    if (!allow_empty && value.is_empty())
        || value.len() > max_len
        || value.chars().any(char::is_control)
    {
        return Err(format!("Operations {field} was malformed"));
    }
    Ok(value.to_owned())
}

