/// Display-safe Platform audit data. The payload and customer identifier from the storage model
/// are intentionally absent from this client model.
impl From<platform_admin_target::PlatformAuditEntry> for PlatformAuditRecord {
    fn from(value: platform_admin_target::PlatformAuditEntry) -> Self {
        Self {
            audit_id: safe_platform_read_text(&value.audit_id),
            actor_ref: safe_platform_read_text(&value.actor_ref),
            action: safe_platform_read_text(&value.action),
            purpose: safe_platform_read_text(&value.purpose),
            correlation_id: safe_platform_read_text(&value.correlation_id),
            recorded_at: safe_platform_read_text(&value.recorded_at),
            customer_scoped: value.customer_scoped,
        }
    }
}

impl PlatformAuditRecord {
    fn validate(&self) -> Result<(), String> {
        for (value, field, max_bytes) in [
            (&self.audit_id, "audit ID", 128),
            (&self.actor_ref, "audit actor", 256),
            (&self.correlation_id, "audit correlation ID", 128),
            (&self.recorded_at, "audit timestamp", 64),
        ] {
            validate_platform_read_text(value, field, false, max_bytes)?;
        }
        // Historical audit action/purpose labels may legitimately mention a
        // credential operation. `SafeUiText` redacts those labels; retain the
        // redacted row instead of rejecting the complete authorized page.
        for (value, field, max_bytes) in [
            (&self.action, "audit action", 256),
            (&self.purpose, "audit purpose", 512),
        ] {
            let value = value.trim();
            if value.is_empty() || value.len() > max_bytes || value.chars().any(char::is_control) {
                return Err(format!("platform {field} was malformed"));
            }
        }
        Ok(())
    }

    fn from_wire(value: platform_admin_target::PlatformAuditEntry) -> Result<Self, String> {
        let record = Self::from(value);
        record.validate()?;
        Ok(record)
    }
}

const PLATFORM_AUDIT_PAGE_SIZE: u32 = 100;

fn platform_audit_page_from_wire(
    response: platform_admin_target::ListPlatformAuditResponse,
) -> Result<Vec<PlatformAuditRecord>, String> {
    if response.entries.len() > PLATFORM_AUDIT_PAGE_SIZE as usize {
        return Err("platform audit page exceeded its display bound".into());
    }
    let has_complete_cursor =
        !response.next_before_recorded_at.is_empty() && !response.next_before_audit_id.is_empty();
    if response.has_more != has_complete_cursor {
        return Err("platform audit pagination metadata was inconsistent".into());
    }
    response
        .entries
        .into_iter()
        .map(PlatformAuditRecord::from_wire)
        .collect()
}

