impl PlatformRoleReviewRecord {
    fn from_wire(value: RoleReviewItem) -> Result<Self, String> {
        let assignment = value
            .assignment
            .ok_or_else(|| "role-review item omitted its assignment".to_string())?;
        let record = Self {
            assignment_id: safe_platform_read_text(&value.assignment_id),
            principal_ref: safe_platform_read_text(&value.principal_ref),
            valid_from: safe_platform_read_text(&value.valid_from),
            valid_until: safe_platform_read_text(&value.valid_until),
            classifications: value
                .classifications
                .iter()
                .map(|value| safe_platform_read_text(value))
                .collect(),
            notification_kind: safe_platform_read_text(&value.notification_kind),
            notification_key: safe_platform_read_text(&value.notification_key),
            role_key: safe_platform_read_text(&assignment.role_key),
            scope: safe_platform_read_text(&assignment.scope),
            risk_tier: safe_platform_read_text(&assignment.risk_tier),
            assignment_version: assignment.assignment_version,
            effective: assignment.effective,
        };
        record.validate()?;
        Ok(record)
    }

    fn validate(&self) -> Result<(), String> {
        for (value, field, max_bytes) in [
            (&self.assignment_id, "role-review assignment ID", 128),
            (&self.principal_ref, "role-review principal", 256),
            (&self.valid_from, "role-review valid-from timestamp", 64),
            (&self.valid_until, "role-review valid-until timestamp", 64),
            (&self.role_key, "role-review role key", 128),
            (&self.scope, "role-review scope", 512),
            (&self.risk_tier, "role-review risk tier", 64),
        ] {
            validate_platform_read_text(value, field, false, max_bytes)?;
        }
        validate_platform_read_text(
            &self.notification_kind,
            "role-review notification kind",
            true,
            64,
        )?;
        validate_platform_read_text(
            &self.notification_key,
            "role-review notification key",
            true,
            256,
        )?;
        if self.assignment_version == 0 {
            return Err("role-review assignment version must be positive".into());
        }
        for classification in &self.classifications {
            validate_platform_read_text(classification, "role-review classification", false, 64)?;
        }
        Ok(())
    }
}

