struct Customer360SectionFactView {
    section: String,
    key: String,
    value: String,
}

fn customer_360_fact_key_allowed(section: &str, key: &str) -> bool {
    match section {
        "account" => matches!(
            key,
            "account_code"
                | "trading_name"
                | "country"
                | "account_state"
                | "subscription_state"
                | "responsibility_contact_count"
                | "customer_success_owner_present"
        ),
        "organization" => matches!(
            key,
            "holding_count"
                | "company_count"
                | "branch_count"
                | "department_count"
                | "active_user_count"
                | "expiring_role_count"
                | "open_ticket_count"
                | "module_count"
        ),
        "contacts" => matches!(key, "contact_count" | "customer_success_owner_present"),
        "commercial" => matches!(
            key,
            "payment_state"
                | "invoice_count"
                | "quote_count"
                | "discount_count"
                | "lifetime_value_minor"
                | "module_allocation_count"
        ),
        "entitlements" => matches!(
            key,
            "active_module_count"
                | "subscription_allocation_count"
                | "organization_allocation_count"
        ),
        "onboarding" => matches!(
            key,
            "state" | "imports_completed" | "training_completed" | "go_live_at" | "owner_present"
        ),
        "health" => matches!(
            key,
            "state"
                | "projection_lag_seconds"
                | "worker_failures"
                | "storage_status"
                | "backup_status"
                | "point_in_time_recovery_status"
                | "integration_failure_count"
                | "api_usage_count"
                | "last_activity_at"
        ),
        "support" => key == "open_ticket_count",
        "access_audit" => matches!(key, "read_count" | "last_access_at" | "customer_visible"),
        "notes" => matches!(key, "note_count" | "has_next_page"),
        _ => false,
    }
}

