#[derive(Debug, Clone, PartialEq, Eq)]
struct CustomerAccessAuditPage {
    entries: Vec<CustomerAccessAuditEntryView>,
    projection_updated_at: String,
    freshness: String,
    read_only: bool,
    correlation_id: String,
    present: bool,
    has_next_page: bool,
    next_before_occurred_at: String,
    next_before_audit_id: String,
}

impl CustomerAccessAuditPage {
    fn from_response(response: GetCustomerAccessAuditResponse) -> Result<Self, String> {
        if response.entries.len() > CUSTOMER_ACCESS_AUDIT_PAGE_SIZE as usize {
            return Err("customer access-audit response exceeded its page bound".into());
        }
        let next_before_occurred_at = bounded_customer360_value(
            &response.next_before_occurred_at,
            "customer access-audit cursor timestamp",
            true,
            64,
        )?;
        let next_before_audit_id = bounded_customer360_value(
            &response.next_before_audit_id,
            "customer access-audit cursor ID",
            true,
            128,
        )?;
        if next_before_occurred_at.is_empty() != next_before_audit_id.is_empty() {
            return Err("customer access-audit cursor was incomplete".into());
        }
        if !next_before_audit_id.is_empty() && Uuid::parse_str(&next_before_audit_id).is_err() {
            return Err("customer access-audit cursor ID was not a UUID".into());
        }
        let entries = response
            .entries
            .into_iter()
            .map(CustomerAccessAuditEntryView::from)
            .collect::<Vec<_>>();
        for entry in &entries {
            bounded_customer360_value(&entry.audit_id, "customer access-audit ID", false, 128)?;
            bounded_customer360_value(&entry.actor, "customer access-audit actor", false, 256)?;
            bounded_customer360_value(&entry.module, "customer access-audit module", false, 128)?;
            bounded_customer360_value(&entry.scope, "customer access-audit scope", false, 4096)?;
            bounded_customer360_value(&entry.purpose, "customer access-audit purpose", false, 256)?;
            bounded_customer360_value(
                &entry.occurred_at,
                "customer access-audit timestamp",
                false,
                64,
            )?;
            bounded_customer360_value(
                &entry.correlation_id,
                "customer access-audit correlation ID",
                false,
                128,
            )?;
        }
        Ok(Self {
            entries,
            projection_updated_at: response.projection_updated_at,
            freshness: response.freshness,
            read_only: response.read_only,
            correlation_id: response.correlation_id,
            present: response.present,
            has_next_page: !next_before_occurred_at.is_empty(),
            next_before_occurred_at,
            next_before_audit_id,
        })
    }
}

const INCIDENT_LIST_PAGE_SIZE: u32 = 100;
const SUPPORT_TICKET_LIST_PAGE_SIZE: u32 = 100;

#[derive(Debug, Clone, PartialEq, Eq)]
struct IncidentReadPage {
    model: IncidentListDisplayModel,
    has_more: bool,
    correlation_id: String,
}

impl IncidentReadPage {
    fn from_target_wire(
        response: support_target::ListSupportIncidentRecordsResponse,
    ) -> Result<Self, String> {
        if response.incidents.len() > INCIDENT_LIST_PAGE_SIZE as usize {
            return Err("incident response exceeded its page bound".into());
        }
        let metadata = response
            .metadata
            .ok_or_else(|| "incident response omitted query metadata".to_owned())?;
        let correlation_id = bounded_incident_value(
            &metadata.correlation_id,
            "incident correlation ID",
            false,
            128,
        )?;
        let inputs = response.incidents.into_iter().map(|incident| {
            IncidentDtoInput::new(
                incident.incident_id,
                support_incident_status_label(incident.status).unwrap_or("invalid"),
                incident.commander_ref,
                Vec::<String>::new(),
                incident.affected_services,
                incident.affected_customer_accounts,
                incident.source_version,
            )
        });
        let model =
            IncidentListDisplayModel::from_safe_dtos(IncidentProjectionMetadata::unknown(), inputs);
        if model.dropped_record_count() != 0 {
            return Err("incident response contained invalid display fields".into());
        }
        Ok(Self {
            model,
            has_more: response.next_cursor.is_some(),
            correlation_id,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SupportTicketReadPage {
    model: SupportTicketListDisplayModel,
    has_more: bool,
    next_cursor: String,
    correlation_id: String,
}

impl SupportTicketReadPage {
    fn from_target_wire(
        response: support_target::ListSupportInternalTicketRecordsResponse,
    ) -> Result<Self, String> {
        if response.tickets.len() > SUPPORT_TICKET_LIST_PAGE_SIZE as usize {
            return Err("support ticket response exceeded its page bound".into());
        }
        let metadata = response
            .metadata
            .ok_or_else(|| "support ticket response omitted query metadata".to_owned())?;
        let correlation_id = bounded_incident_value(
            &metadata.correlation_id,
            "support ticket correlation ID",
            false,
            128,
        )?;
        let next_cursor = bounded_incident_value(
            response.next_cursor.as_deref().unwrap_or_default(),
            "support ticket cursor",
            true,
            512,
        )?;
        let inputs = response.tickets.into_iter().map(|ticket| {
            SupportTicketDtoInput::new(
                ticket.ticket_id,
                ticket.customer_id,
                support_ticket_status_label(ticket.status).unwrap_or("invalid"),
                ticket.severity,
            )
        });
        let model = SupportTicketListDisplayModel::from_safe_dtos(
            SupportProjectionMetadata::unknown(),
            inputs,
        );
        if model.dropped_record_count() != 0 {
            return Err("support ticket response contained invalid display fields".into());
        }
        Ok(Self {
            model,
            has_more: !next_cursor.is_empty(),
            next_cursor,
            correlation_id,
        })
    }
}

fn support_ticket_status_label(value: i32) -> Option<&'static str> {
    match support_target::SupportTicketStatus::try_from(value).ok()? {
        support_target::SupportTicketStatus::New => Some("new"),
        support_target::SupportTicketStatus::Triaged => Some("triaged"),
        support_target::SupportTicketStatus::WaitingForCustomer => Some("waiting_for_customer"),
        support_target::SupportTicketStatus::AccessRequested => Some("access_requested"),
        support_target::SupportTicketStatus::Approved => Some("approved"),
        support_target::SupportTicketStatus::InProgress => Some("in_progress"),
        support_target::SupportTicketStatus::Resolved => Some("resolved"),
        support_target::SupportTicketStatus::CustomerConfirmed => Some("customer_confirmed"),
        support_target::SupportTicketStatus::Closed => Some("closed"),
        support_target::SupportTicketStatus::Unspecified => None,
    }
}

fn support_incident_status_label(value: i32) -> Option<&'static str> {
    match support_target::SupportIncidentStatus::try_from(value).ok()? {
        support_target::SupportIncidentStatus::Investigating => Some("investigating"),
        support_target::SupportIncidentStatus::Identified => Some("identified"),
        support_target::SupportIncidentStatus::Monitoring => Some("monitoring"),
        support_target::SupportIncidentStatus::Resolved => Some("resolved"),
        support_target::SupportIncidentStatus::PostmortemComplete => Some("postmortem_complete"),
        support_target::SupportIncidentStatus::Unspecified => None,
    }
}

