struct SupportCommandReceipt {
    resource: String,
    resource_id: String,
    status: String,
    version: u64,
    correlation_id: String,
}

fn support_csv_values(
    value: &str,
    field: &str,
    max_items: usize,
    max_item_bytes: usize,
) -> Result<Vec<String>, String> {
    let values = value
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| bounded_incident_value(value, field, false, max_item_bytes))
        .collect::<Result<Vec<_>, _>>()?;
    if values.len() > max_items {
        return Err(format!("{field} has too many entries"));
    }
    Ok(values)
}

fn support_expected_version(value: &str, field: &str) -> Result<u64, String> {
    let version = value
        .trim()
        .parse::<u64>()
        .map_err(|_| format!("{field} must be a positive integer"))?;
    if version == 0 {
        return Err(format!("{field} must be positive"));
    }
    Ok(version)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SupportTargetScope {
    tenant_id: String,
    holding_ref: String,
    holding_id: String,
    company_id: Option<String>,
    branch_id: Option<String>,
}

impl SupportTargetScope {
    fn try_new(
        tenant: &PlatformTenantRecord,
        holding_id: &str,
        company_id: Option<&str>,
        branch_id: Option<&str>,
    ) -> Result<Self, String> {
        let holding_id = Uuid::parse_str(holding_id.trim())
            .map_err(|_| "support holding ID must be a UUID".to_owned())?
            .to_string();
        if tenant.root_holding_id != holding_id || !tenant.enterable {
            return Err("additional authorized Support scope input is required".into());
        }
        let company_id = company_id
            .filter(|value| !value.trim().is_empty())
            .map(|value| {
                Uuid::parse_str(value.trim())
                    .map(|id| id.to_string())
                    .map_err(|_| "support company ID must be a UUID".to_owned())
            })
            .transpose()?;
        let branch_id = branch_id
            .filter(|value| !value.trim().is_empty())
            .map(|value| {
                Uuid::parse_str(value.trim())
                    .map(|id| id.to_string())
                    .map_err(|_| "support branch ID must be a UUID".to_owned())
            })
            .transpose()?;
        if branch_id.is_some() && company_id.is_none() {
            return Err("support branch scope requires an authorized company".into());
        }
        Ok(Self {
            tenant_id: tenant.tenant_id.clone(),
            holding_ref: tenant.root_holding_id.clone(),
            holding_id,
            company_id,
            branch_id,
        })
    }

    fn tenant_scope(&self) -> TenantScope {
        let scope = match (&self.company_id, &self.branch_id) {
            (Some(company_id), Some(branch_id)) => tenant_scope::Scope::Branch(BranchScope {
                holding_id: self.holding_id.clone(),
                company_id: company_id.clone(),
                branch_id: branch_id.clone(),
            }),
            (Some(company_id), None) => tenant_scope::Scope::Company(CompanyScope {
                holding_id: self.holding_id.clone(),
                company_id: company_id.clone(),
            }),
            (None, None) => tenant_scope::Scope::Holding(HoldingScope {
                holding_id: self.holding_id.clone(),
            }),
            (None, Some(_)) => unreachable!("branch scope construction requires a company"),
        };
        TenantScope { scope: Some(scope) }
    }

    fn tenant_route(&self) -> ProtoTenantRoute {
        ProtoTenantRoute {
            tenant_id: self.tenant_id.clone(),
            holding_ref: self.holding_ref.clone(),
        }
    }

    fn domain_scope(&self) -> Result<erpx_kernel::TenantScope, String> {
        let holding_id =
            Uuid::parse_str(&self.holding_id).map_err(|_| "invalid support holding")?;
        let scope = match (&self.company_id, &self.branch_id) {
            (Some(company_id), Some(branch_id)) => erpx_kernel::TenantScope::Branch {
                holding_id,
                company_id: Uuid::parse_str(company_id).map_err(|_| "invalid support company")?,
                branch_id: Uuid::parse_str(branch_id).map_err(|_| "invalid support branch")?,
            },
            (Some(company_id), None) => erpx_kernel::TenantScope::Company {
                holding_id,
                company_id: Uuid::parse_str(company_id).map_err(|_| "invalid support company")?,
            },
            (None, None) => erpx_kernel::TenantScope::Holding { holding_id },
            (None, Some(_)) => unreachable!("branch scope construction requires a company"),
        };
        scope
            .validate()
            .map_err(|_| "support scope was invalid".to_owned())?;
        Ok(scope)
    }
}

async fn resolve_support_target_scope(
    holding_id: &str,
    company_id: Option<&str>,
    branch_id: Option<&str>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<SupportTargetScope, String> {
    let holding_id = Uuid::parse_str(holding_id.trim())
        .map_err(|_| "support holding ID must be a UUID".to_owned())?
        .to_string();
    let matches = fetch_platform_tenants(
        access_token.to_owned(),
        principal_ref.to_owned(),
        session_id.to_owned(),
    )
    .await?
    .into_iter()
    .filter(|tenant| tenant.enterable && tenant.root_holding_id == holding_id)
    .collect::<Vec<_>>();
    let [tenant] = matches.as_slice() else {
        return Err("additional authorized Support tenant input is required".into());
    };
    SupportTargetScope::try_new(tenant, &holding_id, company_id, branch_id)
}

