const MARKETING_CONTENT_READ_PAGE_SIZE: u32 = 25;
const MARKETING_CONTENT_MAX_LABEL_BYTES: usize = 255;

#[derive(Debug, Clone, PartialEq, Eq)]
struct MarketingContentReadModel {
    aggregate_type: String,
    aggregate_id: String,
    holding_id: String,
    company_id: String,
    branch_id: String,
    label: String,
    status: String,
    source_version: u64,
    source_event_id: String,
    projected_at: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MarketingContentReadPage {
    rows: Vec<MarketingContentReadModel>,
    has_more: bool,
    next_cursor: Option<String>,
}

impl MarketingContentReadPage {
    fn is_empty(&self) -> bool {
        self.rows.is_empty()
    }
}

fn marketing_content_aggregate_type(route: RouteId) -> Option<&'static str> {
    match route {
        RouteId::MarketingTemplates => Some("template"),
        RouteId::MarketingForms => Some("form"),
        RouteId::MarketingDomains => Some("domain"),
        RouteId::MarketingContent => None,
        _ => None,
    }
}

fn marketing_content_read_request(
    scope: &CrmReadScope,
    aggregate_type: Option<&str>,
    after_cursor: Option<&str>,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<ListMarketingContentReadRowsRequest>, CrmReadError> {
    let scope = CrmReadScope::new(
        scope.tenant_id.clone(),
        scope.holding_ref.clone(),
        scope.scope.clone(),
    )?;
    let after_id = after_cursor.unwrap_or_default();
    if !after_id.is_empty() && after_id.len() > 512 {
        return Err(CrmReadError::MalformedProjection);
    }
    let context = crm_query_context(&scope, principal_ref, session_id);
    Ok(tonic::Request::new(ListMarketingContentReadRowsRequest {
        tenant_id: scope.tenant_id,
        holding_ref: scope.holding_ref,
        aggregate_type: aggregate_type.unwrap_or_default().to_owned(),
        page_size: MARKETING_CONTENT_READ_PAGE_SIZE,
        after_id: after_id.to_owned(),
        context: Some(context),
    }))
}

fn bounded_marketing_content_text(value: &str, max_bytes: usize) -> Option<String> {
    let value = value.trim();
    if value.is_empty()
        || value.len() > max_bytes
        || value.chars().any(char::is_control)
        || crm_sensitive_marker(value)
    {
        None
    } else {
        Some(value.to_owned())
    }
}

fn decode_marketing_content_rows(
    route: RouteId,
    response: ListMarketingContentReadRowsResponse,
    after_cursor: Option<&str>,
) -> Result<MarketingContentReadPage, CrmReadError> {
    let expected_type = marketing_content_aggregate_type(route);
    let mut rows = Vec::with_capacity(response.rows.len());
    for row in response.rows {
        if !matches!(
            row.aggregate_type.as_str(),
            "asset" | "template" | "form" | "domain"
        ) || expected_type.is_some_and(|value| value != row.aggregate_type)
            || !row.read_only
            || !row.present
            || Uuid::parse_str(row.aggregate_id.trim()).is_err()
            || Uuid::parse_str(row.holding_id.trim()).is_err()
            || row.source_version == 0
        {
            return Err(CrmReadError::MalformedProjection);
        }
        if !row.company_id.is_empty() && Uuid::parse_str(row.company_id.trim()).is_err()
            || !row.branch_id.is_empty() && Uuid::parse_str(row.branch_id.trim()).is_err()
            || Uuid::parse_str(row.source_event_id.trim()).is_err()
        {
            return Err(CrmReadError::MalformedProjection);
        }
        let label = if row.label.trim().is_empty() {
            "(unnamed)".into()
        } else {
            bounded_marketing_content_text(&row.label, MARKETING_CONTENT_MAX_LABEL_BYTES)
                .ok_or(CrmReadError::MalformedProjection)?
        };
        let status = bounded_marketing_content_text(&row.status, 64)
            .ok_or(CrmReadError::MalformedProjection)?;
        let projected_at = bounded_marketing_content_text(&row.projected_at, 64)
            .ok_or(CrmReadError::MalformedProjection)?;
        rows.push(MarketingContentReadModel {
            aggregate_type: row.aggregate_type,
            aggregate_id: Uuid::parse_str(row.aggregate_id.trim())
                .map_err(|_| CrmReadError::MalformedProjection)?
                .to_string(),
            holding_id: Uuid::parse_str(row.holding_id.trim())
                .map_err(|_| CrmReadError::MalformedProjection)?
                .to_string(),
            company_id: row.company_id,
            branch_id: row.branch_id,
            label,
            status,
            source_version: row.source_version,
            source_event_id: Uuid::parse_str(row.source_event_id.trim())
                .map_err(|_| CrmReadError::MalformedProjection)?
                .to_string(),
            projected_at,
        });
    }
    if response.has_more == response.next_after_id.is_empty() {
        return Err(CrmReadError::MalformedProjection);
    }
    if response.has_more && response.next_after_id.is_empty() {
        return Err(CrmReadError::MalformedProjection);
    }
    if after_cursor.is_some() && rows.is_empty() && response.has_more {
        return Err(CrmReadError::MalformedProjection);
    }
    Ok(MarketingContentReadPage {
        rows,
        has_more: response.has_more,
        next_cursor: (!response.next_after_id.is_empty()).then_some(response.next_after_id),
    })
}

#[cfg(target_arch = "wasm32")]
async fn fetch_marketing_content_rows(
    scope: CrmReadScope,
    route: RouteId,
    access_token: String,
    principal_ref: String,
    session_id: String,
    after_cursor: Option<String>,
) -> Result<MarketingContentReadPage, CrmReadError> {
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    let mut client = MarketingQueryServiceClient::new(channel);
    let mut request = marketing_content_read_request(
        &scope,
        marketing_content_aggregate_type(route),
        after_cursor.as_deref(),
        &principal_ref,
        &session_id,
    )?;
    add_crm_transport_metadata(&mut request, &access_token, &principal_ref, &session_id)
        .map_err(|_| CrmReadError::MalformedProjection)?;
    let response = client
        .list_marketing_content_read_rows(request)
        .await
        .map_err(|error| CrmReadError::from_status(&error))?
        .into_inner();
    decode_marketing_content_rows(route, response, after_cursor.as_deref())
}

#[cfg(not(target_arch = "wasm32"))]
async fn fetch_marketing_content_rows(
    scope: CrmReadScope,
    route: RouteId,
    access_token: String,
    principal_ref: String,
    session_id: String,
    after_cursor: Option<String>,
) -> Result<MarketingContentReadPage, CrmReadError> {
    let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
        .connect()
        .await
        .map_err(|_| CrmReadError::Offline)?;
    let mut client = MarketingQueryServiceClient::new(channel);
    let mut request = marketing_content_read_request(
        &scope,
        marketing_content_aggregate_type(route),
        after_cursor.as_deref(),
        &principal_ref,
        &session_id,
    )?;
    add_crm_transport_metadata(&mut request, &access_token, &principal_ref, &session_id)
        .map_err(|_| CrmReadError::MalformedProjection)?;
    let response = client
        .list_marketing_content_read_rows(request)
        .await
        .map_err(|error| CrmReadError::from_status(&error))?
        .into_inner();
    decode_marketing_content_rows(route, response, after_cursor.as_deref())
}

fn validate_crm_reference(value: &str, _field: &'static str) -> Result<String, CrmReadError> {
    let value = value.trim();
    if value.is_empty()
        || value.len() > CRM_MAX_REFERENCE_BYTES
        || value.chars().any(char::is_control)
        || crm_sensitive_marker(value)
    {
        return Err(CrmReadError::MalformedProjection);
    }
    Ok(value.to_owned())
}

fn crm_sensitive_marker(value: &str) -> bool {
    let value = value.to_ascii_lowercase();
    [
        "access_token",
        "refresh_token",
        "authorization",
        "password",
        "secret",
        "api_key",
        "private_key",
        "credential",
    ]
    .iter()
    .any(|marker| value.contains(marker))
}

fn marketing_crm_definition(route: RouteId) -> Option<RouteDefinition> {
    RouteRegistry::marketing_crm()
        .definitions()
        .iter()
        .copied()
        .find(|definition| definition.id == route)
}

fn crm_surface_for_route(route: RouteId) -> Option<CrmSurface> {
    match route {
        RouteId::CrmLeads => Some(CrmSurface::AcceptedLeadHandoffs),
        RouteId::CrmOpportunities => Some(CrmSurface::Opportunities),
        RouteId::MarketingAttribution => Some(CrmSurface::Attribution),
        _ => None,
    }
}

fn crm_aggregate_type(surface: CrmSurface) -> &'static str {
    match surface {
        CrmSurface::AcceptedLeadHandoffs => "marketing_crm_accepted_lead_handoff",
        CrmSurface::Opportunities => "marketing_crm_opportunity",
        CrmSurface::Attribution => "marketing_crm_attribution",
    }
}

