fn crm_state_for_error(error: CrmReadError) -> CrmState<CrmRows> {
    match error {
        CrmReadError::Denied => CrmViewState::Denied {
            metadata: None,
            reason: "The server denied the CRM read.".into(),
        },
        CrmReadError::Offline => CrmViewState::Offline {
            data: None,
            metadata: None,
            reason: "The CRM read service is unavailable.".into(),
        },
        CrmReadError::ScopeUnavailable | CrmReadError::RouteUnavailable => CrmViewState::Error {
            reason: "No safe CRM data adapter is available for this route and scope.".into(),
        },
        CrmReadError::MalformedProjection => CrmViewState::Error {
            reason: "The CRM projection did not satisfy the typed display contract.".into(),
        },
    }
}

fn crm_query_context(scope: &CrmReadScope, principal_ref: &str, session_id: &str) -> QueryContext {
    let correlation_id = Uuid::new_v4().to_string();
    QueryContext {
        contract_version: u32::from(CONTRACT_VERSION),
        request_id: Uuid::new_v4().to_string(),
        correlation_id: correlation_id.clone(),
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_owned(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(TenantScope {
            scope: Some(scope.scope.clone()),
        }),
        consistency: Some(QueryConsistency {
            requirement: Some(query_consistency::Requirement::Eventual(
                EventualConsistency {},
            )),
        }),
        audit: Some(AuditContext {
            purpose: "crm_console_read".into(),
            customer_visible: true,
            module: "crm".into(),
            correlation_id,
        }),
    }
}

