fn marketing_content_receipt(
    receipt: Option<erpx_proto::erpx::marketing::v2::MarketingContentWriteReceipt>,
    correlation_id: &str,
) -> Result<MarketingContentReceipt, String> {
    let correlation_id = bounded_finance_value(
        correlation_id,
        "Marketing command correlation ID",
        false,
        128,
    )?;
    let receipt = receipt.ok_or_else(|| "Marketing command omitted its receipt".to_string())?;
    let aggregate_type =
        finance_command_text(&receipt.aggregate_type, "Marketing aggregate type", 128)?;
    let aggregate_id = finance_command_uuid(&receipt.aggregate_id, "Marketing aggregate ID")?;
    if receipt.version == 0 {
        return Err("Marketing receipt version must be positive".into());
    }
    Ok(MarketingContentReceipt {
        aggregate_type,
        aggregate_id,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

fn crm_write_receipt(response: SaveCrmHandoffResponse) -> Result<CrmWriteReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "CRM command correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "CRM handoff command omitted its receipt".to_string())?;
    crm_write_receipt_fields(receipt, correlation_id)
}

fn crm_opportunity_receipt(
    response: SaveCrmOpportunityResponse,
) -> Result<CrmWriteReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "CRM command correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "CRM opportunity command omitted its receipt".to_string())?;
    crm_write_receipt_fields(receipt, correlation_id)
}

fn crm_write_receipt_fields(
    receipt: CrmWriteReceiptMessage,
    correlation_id: String,
) -> Result<CrmWriteReceipt, String> {
    let aggregate_type = finance_command_text(&receipt.aggregate_type, "CRM aggregate type", 128)?;
    let aggregate_id = finance_command_uuid(&receipt.aggregate_id, "CRM aggregate ID")?;
    let reference = finance_command_text(&receipt.reference, "CRM aggregate reference", 128)?;
    if receipt.version == 0 {
        return Err("CRM receipt version must be positive".into());
    }
    Ok(CrmWriteReceipt {
        aggregate_type,
        aggregate_id,
        reference,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

fn crm_attribution_receipt(
    response: RecordCrmAttributionResponse,
) -> Result<CrmAttributionReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "CRM attribution correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "CRM attribution command omitted its receipt".to_string())?;
    let record_id = finance_command_uuid(&receipt.record_id, "CRM attribution record ID")?;
    let reference = finance_command_text(&receipt.reference, "CRM attribution reference", 128)?;
    let model = finance_command_text(&receipt.model, "CRM attribution model", 32)?;
    if receipt.source_opportunity_version == 0 || receipt.version == 0 {
        return Err("CRM attribution receipt versions must be positive".into());
    }
    Ok(CrmAttributionReceipt {
        record_id,
        reference,
        model,
        source_opportunity_version: receipt.source_opportunity_version,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id,
    })
}

fn marketing_erasure_receipt(
    response: EraseMarketingProfileResponse,
) -> Result<MarketingErasureReceipt, String> {
    let correlation_id = bounded_finance_value(
        &response.correlation_id,
        "Marketing erasure correlation ID",
        false,
        128,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "Marketing erasure command omitted its receipt".to_string())?;
    let profile_id = finance_command_uuid(&receipt.profile_id, "Marketing erased profile ID")?;
    let _idempotency_key = finance_command_text(
        &receipt.idempotency_key,
        "Marketing erasure idempotency key",
        512,
    )?;
    Ok(MarketingErasureReceipt {
        profile_id,
        replayed: receipt.replayed,
        correlation_id,
    })
}

async fn save_crm_handoff(
    scope: CrmReadScope,
    input: CrmHandoffTypedInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<CrmWriteReceipt, String> {
    #[cfg(target_arch = "wasm32")]
    {
        let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
        let mut client = CrmCommandServiceClient::new(channel);
        let mut request = crm_handoff_typed_request(&scope, &input, &principal_ref, &session_id)?;
        add_crm_transport_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
        let response = client
            .save_crm_handoff(request)
            .await
            .map_err(crm_command_rpc_error)?
            .into_inner();
        return crm_write_receipt(response);
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
            .connect()
            .await
            .map_err(|_| "offline".to_string())?;
        let mut client = CrmCommandServiceClient::new(channel);
        let mut request = crm_handoff_typed_request(&scope, &input, &principal_ref, &session_id)?;
        add_crm_transport_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
        let response = client
            .save_crm_handoff(request)
            .await
            .map_err(crm_command_rpc_error)?
            .into_inner();
        crm_write_receipt(response)
    }
}

