fn marketing_provider_context(
    scope: &CrmReadScope,
    principal_ref: &str,
    session_id: &str,
    purpose: &str,
    idempotency_prefix: &str,
) -> Result<CommandContext, String> {
    if !matches!(scope.scope, tenant_scope::Scope::Holding(_)) {
        return Err("Marketing provider commands require an explicit holding scope".into());
    }
    marketing_content_command_context(
        scope,
        principal_ref,
        session_id,
        purpose,
        &format!("{idempotency_prefix}-{}", Uuid::new_v4()),
    )
}

fn marketing_provider_channels(value: &str) -> Result<Vec<String>, String> {
    let value = value.trim();
    if value.is_empty() {
        return Err("Marketing provider channels are required".into());
    }
    let mut channels = Vec::new();
    for channel in value.split(',') {
        let channel = finance_command_text(channel, "Marketing provider channel", 32)?;
        if channels.iter().any(|existing| existing == &channel) {
            return Err("Marketing provider channels must be unique".into());
        }
        channels.push(channel);
        if channels.len() > 5 {
            return Err("Marketing provider supports at most five channels".into());
        }
    }
    Ok(channels)
}

fn marketing_provider_typed_routes(
    input: &MarketingProviderConfigureInput,
) -> Result<Vec<MarketingProviderChannelRoute>, String> {
    let channel =
        finance_command_text(&input.route_channel, "Marketing provider route channel", 32)?;
    let enabled_channels = marketing_provider_channels(&input.channels)?;
    if !enabled_channels.iter().any(|enabled| enabled == &channel) {
        return Err("Marketing provider route channel must be enabled".into());
    }
    let endpoint = finance_command_text(
        &input.route_endpoint,
        "Marketing provider route endpoint",
        2048,
    )?;
    let reconciliation_endpoint = if input.reconciliation_endpoint.trim().is_empty() {
        String::new()
    } else {
        finance_command_text(
            &input.reconciliation_endpoint,
            "Marketing provider reconciliation endpoint",
            2048,
        )?
    };
    Ok(vec![MarketingProviderChannelRoute {
        channel,
        endpoint,
        reconciliation_endpoint,
    }])
}

fn marketing_provider_configure_request(
    scope: &CrmReadScope,
    input: &MarketingProviderConfigureInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<tonic::Request<ConfigureMarketingProviderAccountRequest>, String> {
    let provider_account_id =
        finance_command_uuid(&input.provider_account_id, "Marketing provider account ID")?;
    let provider_priority = if input.provider_priority.trim().is_empty() {
        0
    } else {
        input
            .provider_priority
            .trim()
            .parse::<u32>()
            .map_err(|_| "Marketing provider priority must be a positive integer".to_string())?
    };
    let context = marketing_provider_context(
        scope,
        principal_ref,
        session_id,
        "marketing_provider_configure",
        "marketing-provider-configure",
    )?;
    Ok(tonic::Request::new(
        ConfigureMarketingProviderAccountRequest {
            tenant_id: finance_command_text(&scope.tenant_id, "Marketing tenant ID", 128)?,
            holding_ref: finance_command_text(
                &scope.holding_ref,
                "Marketing holding reference",
                128,
            )?,
            provider_account_id,
            provider_account_ref: finance_command_text(
                &input.provider_account_ref,
                "Marketing provider account reference",
                128,
            )?,
            provider_key: finance_command_text(&input.provider_key, "Marketing provider key", 128)?,
            verifier_key_ref: finance_command_text(
                &input.verifier_key_ref,
                "Marketing verifier secret reference",
                512,
            )?,
            outbound_credential_ref: finance_command_text(
                &input.outbound_credential_ref,
                "Marketing outbound secret reference",
                512,
            )?,
            channels: marketing_provider_channels(&input.channels)?,
            context: Some(context),
            channel_routes: marketing_provider_typed_routes(input)?,
            provider_priority,
        },
    ))
}

