fn marketing_provider_receipt(
    receipt: Option<erpx_proto::erpx::marketing::v2::MarketingProviderAccountWriteReceipt>,
    correlation_id: &str,
) -> Result<MarketingProviderReceipt, String> {
    let receipt =
        receipt.ok_or_else(|| "Marketing provider command omitted its receipt".to_string())?;
    Ok(MarketingProviderReceipt {
        provider_account_id: finance_command_uuid(
            &receipt.provider_account_id,
            "Marketing provider account ID",
        )?,
        provider_account_ref: finance_command_text(
            &receipt.provider_account_ref,
            "Marketing provider account reference",
            128,
        )?,
        state: finance_command_text(&receipt.state, "Marketing provider state", 32)?,
        onboarding_state: finance_command_text(
            &receipt.onboarding_state,
            "Marketing provider onboarding state",
            32,
        )?,
        version: receipt.version,
        replayed: receipt.replayed,
        correlation_id: bounded_finance_value(
            correlation_id,
            "Marketing provider correlation ID",
            false,
            128,
        )?,
    })
}

