fn crm_read_request(
    scope: &CrmReadScope,
    surface: CrmSurface,
    principal_ref: &str,
    session_id: &str,
    after_id: Option<&str>,
) -> Result<tonic::Request<ListCrmReadRowsRequest>, CrmReadError> {
    let scope = CrmReadScope::new(
        scope.tenant_id.clone(),
        scope.holding_ref.clone(),
        scope.scope.clone(),
    )?;
    let after_id = after_id.unwrap_or_default();
    if !after_id.is_empty() {
        validate_crm_reference(after_id, "after_id")?;
    }
    let context = crm_query_context(&scope, principal_ref, session_id);
    Ok(tonic::Request::new(ListCrmReadRowsRequest {
        tenant_id: scope.tenant_id,
        holding_ref: scope.holding_ref,
        aggregate_type: crm_aggregate_type(surface).into(),
        page_size: CRM_READ_PAGE_SIZE,
        after_id: after_id.into(),
        context: Some(context),
    }))
}

fn add_crm_transport_metadata<T>(
    request: &mut tonic::Request<T>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<(), String> {
    request.metadata_mut().insert(
        "x-erpx-access-token",
        MetadataValue::try_from(access_token)
            .map_err(|_| "CRM access token is not valid transport metadata".to_string())?,
    );
    request.metadata_mut().insert(
        "x-erpx-actor",
        MetadataValue::try_from(principal_ref)
            .map_err(|_| "CRM principal is not valid transport metadata".to_string())?,
    );
    request.metadata_mut().insert(
        "x-erpx-session",
        MetadataValue::try_from(session_id)
            .map_err(|_| "CRM session is not valid transport metadata".to_string())?,
    );
    Ok(())
}

#[cfg(target_arch = "wasm32")]
async fn fetch_crm_rows(
    scope: CrmReadScope,
    surface: CrmSurface,
    access_token: String,
    principal_ref: String,
    session_id: String,
    after_id: Option<String>,
) -> Result<CrmRows, CrmReadError> {
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    let mut client = CrmQueryServiceClient::new(channel);
    let mut request = crm_read_request(
        &scope,
        surface,
        &principal_ref,
        &session_id,
        after_id.as_deref(),
    )?;
    add_crm_transport_metadata(&mut request, &access_token, &principal_ref, &session_id)
        .map_err(|_| CrmReadError::MalformedProjection)?;
    let response = client
        .list_crm_read_rows(request)
        .await
        .map_err(|error| CrmReadError::from_status(&error))?
        .into_inner();
    decode_crm_rows(surface, response, after_id.as_deref())
}

#[cfg(not(target_arch = "wasm32"))]
async fn fetch_crm_rows(
    scope: CrmReadScope,
    surface: CrmSurface,
    access_token: String,
    principal_ref: String,
    session_id: String,
    after_id: Option<String>,
) -> Result<CrmRows, CrmReadError> {
    let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
        .connect()
        .await
        .map_err(|_| CrmReadError::Offline)?;
    let mut client = CrmQueryServiceClient::new(channel);
    let mut request = crm_read_request(
        &scope,
        surface,
        &principal_ref,
        &session_id,
        after_id.as_deref(),
    )?;
    add_crm_transport_metadata(&mut request, &access_token, &principal_ref, &session_id)
        .map_err(|_| CrmReadError::MalformedProjection)?;
    let response = client
        .list_crm_read_rows(request)
        .await
        .map_err(|error| CrmReadError::from_status(&error))?
        .into_inner();
    decode_crm_rows(surface, response, after_id.as_deref())
}

fn decode_crm_rows(
    surface: CrmSurface,
    response: ListCrmReadRowsResponse,
    after_id: Option<&str>,
) -> Result<CrmRows, CrmReadError> {
    let metadata = CrmPageMetadata::new(
        CRM_READ_PAGE_SIZE as usize,
        after_id,
        (!response.next_after_id.is_empty()).then_some(response.next_after_id.as_str()),
        response.has_more,
    )
    .map_err(|_| CrmReadError::MalformedProjection)?;
    let mut handoffs = Vec::new();
    let mut opportunities = Vec::new();
    let mut attribution = Vec::new();
    for row in response.rows {
        if row.aggregate_type != crm_aggregate_type(surface)
            || row.aggregate_id.is_empty()
            || row.source_version == 0
        {
            return Err(CrmReadError::MalformedProjection);
        }
        let fields = crm_payload_fields(&row);
        match surface {
            CrmSurface::AcceptedLeadHandoffs => {
                let inputs = fields
                    .iter()
                    .map(|(key, value)| CrmFieldInput::new(key, value));
                handoffs.push(
                    CrmHandoffDisplayModel::from_untrusted_fields(row.aggregate_id, inputs)
                        .ok_or(CrmReadError::MalformedProjection)?,
                );
            }
            CrmSurface::Opportunities => {
                let status = bounded_json_string_field(&row.payload_json, "status")
                    .ok_or(CrmReadError::MalformedProjection)?;
                let inputs = fields
                    .iter()
                    .map(|(key, value)| CrmFieldInput::new(key, value));
                opportunities.push(
                    CrmOpportunityDisplayModel::from_untrusted_fields(
                        row.aggregate_id,
                        &status,
                        inputs,
                    )
                    .ok_or(CrmReadError::MalformedProjection)?,
                );
            }
            CrmSurface::Attribution => {
                let model = bounded_json_string_field(&row.payload_json, "model")
                    .ok_or(CrmReadError::MalformedProjection)?;
                let inputs = fields
                    .iter()
                    .map(|(key, value)| CrmFieldInput::new(key, value));
                attribution.push(
                    CrmAttributionDisplayModel::from_untrusted_fields(
                        row.aggregate_id,
                        &model,
                        inputs,
                    )
                    .ok_or(CrmReadError::MalformedProjection)?,
                );
            }
        }
    }
    match surface {
        CrmSurface::AcceptedLeadHandoffs => Ok(CrmRows::Handoffs(
            CrmReadPage::new(handoffs, metadata).map_err(|_| CrmReadError::MalformedProjection)?,
        )),
        CrmSurface::Opportunities => Ok(CrmRows::Opportunities(
            CrmReadPage::new(opportunities, metadata)
                .map_err(|_| CrmReadError::MalformedProjection)?,
        )),
        CrmSurface::Attribution => Ok(CrmRows::Attribution(
            CrmReadPage::new(attribution, metadata)
                .map_err(|_| CrmReadError::MalformedProjection)?,
        )),
    }
}

fn crm_payload_fields(row: &CrmReadRow) -> Vec<(String, String)> {
    [
        "reference",
        "lead_label",
        "account_label",
        "contact_label",
        "accepted_at",
        "source_label",
        "scope_label",
        "name",
        "currency",
        "expected_revenue_minor",
        "created_at",
        "updated_at",
        "accepted_lead_reference",
        "opportunity_reference",
        "model",
        "revenue_minor",
        "cost_minor",
        "campaign_label",
        "attributed_at",
    ]
    .into_iter()
    .filter_map(|key| {
        bounded_json_string_field(&row.payload_json, key).map(|value| (key.to_owned(), value))
    })
    .collect()
}

fn bounded_json_string_field(payload: &[u8], key: &str) -> Option<String> {
    let payload = std::str::from_utf8(payload).ok()?;
    let marker = format!("\"{key}\"");
    let start = payload.find(&marker)? + marker.len();
    let colon = payload[start..].find(':')? + start + 1;
    let remainder = payload[colon..].trim_start();
    let remainder = remainder.strip_prefix('"')?;
    let end = remainder.find('"')?;
    let value = &remainder[..end];
    if value.contains('\\') {
        return None;
    }
    let value = value.trim();
    if value.is_empty() || value.len() > 256 || value.chars().any(char::is_control) {
        None
    } else {
        Some(value.to_owned())
    }
}

#[cfg(target_arch = "wasm32")]
async fn fetch_platform_tenants(
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<Vec<PlatformTenantRecord>, String> {
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    let mut client = platform_admin_target::platform_administration_query_service_client::PlatformAdministrationQueryServiceClient::new(channel);
    let mut after_tenant_id = String::new();
    let mut tenants = Vec::new();
    for _ in 0..100 {
        let context = platform_query_context(&principal_ref, &session_id);
        let mut request = tonic::Request::new(platform_admin_target::ListPlatformTenantsRequest {
            page_size: 100,
            after_tenant_id,
            context: Some(context),
            search: String::new(),
            lifecycle: String::new(),
            billing_state: String::new(),
            plan: String::new(),
            module: String::new(),
            health: String::new(),
        });
        request.metadata_mut().insert(
            "x-erpx-access-token",
            MetadataValue::try_from(access_token.as_str())
                .map_err(|_| "access token is not valid transport metadata".to_string())?,
        );
        request.metadata_mut().insert(
            "x-erpx-actor",
            MetadataValue::try_from(principal_ref.as_str())
                .map_err(|_| "principal reference is not valid transport metadata".to_string())?,
        );
        request.metadata_mut().insert(
            "x-erpx-session",
            MetadataValue::try_from(session_id.as_str())
                .map_err(|_| "session reference is not valid transport metadata".to_string())?,
        );
        let page = client
            .list_operational_tenants(request)
            .await
            .map_err(platform_operations_rpc_error)?
            .into_inner();
        if page.tenants.len() > 100 {
            return Err("platform tenant page exceeded its bound".to_string());
        }
        let page_tenants = page
            .tenants
            .into_iter()
            .map(PlatformTenantRecord::from_wire)
            .collect::<Result<Vec<_>, _>>()?;
        tenants.extend(page_tenants);
        if !page.has_more {
            return Ok(tenants);
        }
        if page.next_after_tenant_id.is_empty() {
            return Err("platform tenant pagination cursor was empty".to_string());
        }
        after_tenant_id = page.next_after_tenant_id;
    }
    Err("platform tenant pagination exceeded its bound".to_string())
}

