fn tenant_admin_context_model(
    context: platform_admin_target::TenantAdminContext,
    correlation_id: String,
) -> Result<TenantAdminContextModel, String> {
    for (value, field, allow_empty) in [
        (
            context.administrative_context_id.as_str(),
            "administrative context ID",
            false,
        ),
        (context.tenant_id.as_str(), "tenant ID", false),
        (context.customer_id.as_str(), "customer ID", false),
        (context.root_holding_id.as_str(), "root holding ID", false),
    ] {
        validate_platform_identifier(value, field, allow_empty)?;
    }
    validate_platform_read_text(&context.issued_at, "context issue timestamp", false, 64)?;
    validate_platform_read_text(&context.expires_at, "context expiry timestamp", false, 64)?;
    validate_platform_identifier(&correlation_id, "context correlation ID", false)?;
    Ok(TenantAdminContextModel {
        administrative_context_id: context.administrative_context_id,
        tenant_id: context.tenant_id,
        customer_id: context.customer_id,
        root_holding_id: context.root_holding_id,
        issued_at: context.issued_at,
        expires_at: context.expires_at,
        active: context.active,
        correlation_id,
    })
}

fn tenant_admin_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::NotFound => "tenant_context_not_found".into(),
        tonic::Code::Aborted | tonic::Code::AlreadyExists => "conflict".into(),
        tonic::Code::FailedPrecondition => "tenant_configuration_incomplete".into(),
        tonic::Code::InvalidArgument => "tenant_context_validation_failed".into(),
        _ => "tenant_context_failed".into(),
    }
}

fn platform_operations_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        _ => "platform_operations_read_failed".into(),
    }
}

fn tenant_admin_error_message(category: &str) -> &'static str {
    match category {
        "authentication_required" => "Sign in again before entering a tenant workspace.",
        "authorization_denied" => {
            "The current platform role, session, device, scope, or MFA proof does not authorize this tenant context."
        }
        "offline" => "Tenant administration is temporarily unreachable. No context was issued.",
        "tenant_context_not_found" => "The administrative context no longer exists.",
        "conflict" => "Tenant administration changed concurrently. Refresh before retrying.",
        "tenant_configuration_incomplete" => {
            "Tenant entry is unavailable until its customer and root-holding configuration is complete."
        }
        "tenant_context_validation_failed" => "Review the reason and MFA fields before retrying.",
        _ => "Tenant administration could not complete this action. No backend detail was exposed.",
    }
}

fn tenant_admin_error_state(category: &str) -> UiStateKind {
    match category {
        "authentication_required"
        | "authorization_denied"
        | "Your session expired. Sign in and retry."
        | "This action is not authorized for the current persona and scope." => UiStateKind::Denied,
        "offline"
        | "The control plane is temporarily unavailable. This request was not silently retried." => {
            UiStateKind::Offline
        }
        "tenant_context_not_found" | "tenant_configuration_incomplete" => UiStateKind::Unavailable,
        "conflict"
        | "The infrastructure state changed or a required approval is missing. Refresh before retrying." => {
            UiStateKind::Conflict
        }
        category if category.contains("stale") => UiStateKind::Stale,
        category if category.contains("unavailable") || category.contains("not_applicable") => {
            UiStateKind::Unavailable
        }
        _ => UiStateKind::Error,
    }
}

