async fn fetch_tenant_business_unit_configuration_with_client<T>(
    client: &mut platform_admin_target::platform_administration_query_service_client::PlatformAdministrationQueryServiceClient<T>,
    scope: &TenantGovernanceScope,
    business_unit: &str,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<Option<BusinessUnitConfigurationRecord>, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    erpx_domain::data_plane::BusinessUnitId::parse(business_unit)
        .map_err(|_| "Select a canonical business unit.".to_owned())?;
    let response = client
        .get_business_unit_configuration(authenticated_rpc_request(
            platform_admin_target::GetBusinessUnitConfigurationRequest {
                tenant_id: scope.tenant_id.clone(),
                business_unit: business_unit.to_owned(),
                context: Some(tenant_holding_query_context(
                    principal_ref,
                    session_id,
                    &scope.holding_id,
                    "tenant_business_unit_configuration_read",
                )?),
            },
            access_token,
            principal_ref,
            session_id,
        )?)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner();
    if !response.exists {
        return Ok(None);
    }
    response
        .configuration
        .ok_or_else(|| "The tenant business-unit configuration was absent.".to_owned())
        .and_then(|configuration| {
            if configuration.root_holding_id != scope.holding_id {
                return Err(
                    "The tenant business-unit configuration was outside the selected holding."
                        .to_owned(),
                );
            }
            BusinessUnitConfigurationRecord::from_wire(
                &scope.tenant_id,
                business_unit,
                configuration,
                response.correlation_id,
            )
        })
        .map(Some)
}

fn tenant_business_unit_role_level(
    value: &str,
) -> Result<erpx_domain::data_plane::BusinessUnitRoleLevel, String> {
    use erpx_domain::data_plane::BusinessUnitRoleLevel;
    match value {
        "viewer" => Ok(BusinessUnitRoleLevel::Viewer),
        "operator" => Ok(BusinessUnitRoleLevel::Operator),
        "approver" => Ok(BusinessUnitRoleLevel::Approver),
        "admin" => Ok(BusinessUnitRoleLevel::Administrator),
        "auditor" => Ok(BusinessUnitRoleLevel::Auditor),
        _ => Err("Select a canonical directory role level.".to_owned()),
    }
}

fn validate_directory_group_reference(value: &str) -> Result<String, String> {
    let value = value.trim();
    if value.len() < 17
        || value.len() > 255
        || !value.starts_with("directory-group-")
        || value.chars().any(|character| {
            !character.is_ascii_alphanumeric() && !matches!(character, '-' | '_' | '.')
        })
    {
        return Err(
            "Enter an opaque directory group reference beginning with directory-group-.".to_owned(),
        );
    }
    Ok(value.to_owned())
}

#[derive(Clone, Copy)]
struct TenantRpcAuthorization<'a> {
    administrative_context_id: Option<&'a str>,
    access_token: &'a str,
    principal_ref: &'a str,
    session_id: &'a str,
}

impl<'a> TenantRpcAuthorization<'a> {
    fn request<T>(self, message: T) -> Result<tonic::Request<T>, String> {
        tenant_admin_rpc_request(
            authenticated_rpc_request(
                message,
                self.access_token,
                self.principal_ref,
                self.session_id,
            )?,
            self.administrative_context_id,
        )
    }
}

