async fn save_tenant_business_unit_configuration_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    scope: &TenantGovernanceScope,
    current: Option<&BusinessUnitConfigurationRecord>,
    input: TenantBusinessUnitConfigurationInput,
    authorization: TenantRpcAuthorization<'_>,
) -> Result<TenantBusinessUnitConfigurationReceipt, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let unit = erpx_domain::data_plane::BusinessUnitId::parse(&input.business_unit)
        .map_err(|_| "Select a canonical business unit.".to_owned())?;
    if current.is_some_and(|record| record.business_unit != input.business_unit) {
        return Err("Reload the selected business unit before saving.".to_owned());
    }
    let group_ref = validate_directory_group_reference(&input.directory_group_ref)?;
    let role_level = tenant_business_unit_role_level(&input.role_level)?;
    if !(1..=2_160).contains(&input.assignment_duration_hours) {
        return Err("Assignment duration must be between 1 and 2160 hours.".to_owned());
    }
    if !(1..=3_650).contains(&input.retention_days) {
        return Err("Retention must be between 1 and 3650 days.".to_owned());
    }
    if !(30..=86_400).contains(&input.projection_stale_after_seconds) {
        return Err("Projection freshness must be between 30 and 86400 seconds.".to_owned());
    }
    let expected_version = current.map_or(0, |record| record.configuration_version);
    let configuration_version = expected_version
        .checked_add(1)
        .ok_or_else(|| "The business-unit configuration version cannot advance.".to_owned())?;
    let role_key = unit.role_key(role_level);
    let organization_scope = TenantScope {
        scope: Some(tenant_scope::Scope::Holding(HoldingScope {
            holding_id: scope.holding_id.clone(),
        })),
    };
    let mut context = tenant_holding_command_context(
        authorization.principal_ref,
        authorization.session_id,
        &scope.holding_id,
        "tenant_business_unit_configuration_save",
        &format!(
            "tenant-business-unit-{}-{configuration_version}",
            input.business_unit
        ),
        &input.mfa_code,
    )?;
    context.expected_aggregate_version = expected_version;
    let request = authorization.request(
        platform_admin_target::SaveBusinessUnitConfigurationRequest {
            configuration: Some(platform_admin_target::BusinessUnitConfigurationMessage {
                tenant_id: scope.tenant_id.clone(),
                root_holding_id: scope.holding_id.clone(),
                business_unit: input.business_unit.clone(),
                configuration_version,
                active: input.active,
                organization_scope: Some(organization_scope.clone()),
                directory_role_mappings: vec![
                    platform_admin_target::BusinessUnitDirectoryRoleMappingMessage {
                        group_ref,
                        role_key,
                        target_scope: Some(organization_scope),
                        requires_mfa: input.requires_mfa,
                        assignment_duration_hours: input.assignment_duration_hours,
                        approval_limit_minor: input.approval_limit_minor,
                        active: true,
                    },
                ],
                integration_references: Vec::new(),
                retention_policy_json: serde_json::to_vec(&serde_json::json!({
                    "retention_days": input.retention_days,
                }))
                .map_err(|_| "The retention policy could not be encoded.".to_owned())?,
                projection_policy_json: serde_json::to_vec(&serde_json::json!({
                    "stale_after_seconds": input.projection_stale_after_seconds,
                }))
                .map_err(|_| "The projection policy could not be encoded.".to_owned())?,
                workflow_policy_json: serde_json::to_vec(&serde_json::json!({
                    "approval_required": input.approval_required,
                }))
                .map_err(|_| "The workflow policy could not be encoded.".to_owned())?,
                updated_by: authorization.principal_ref.to_owned(),
                updated_at: Utc::now().to_rfc3339(),
            }),
            expected_configuration_version: expected_version,
            context: Some(context),
        },
    )?;
    let response = client
        .save_business_unit_configuration(request)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner();
    if response.configuration_version != configuration_version {
        return Err("The business-unit configuration receipt version was stale.".to_owned());
    }
    Uuid::parse_str(&response.correlation_id)
        .map_err(|_| "The business-unit receipt correlation ID was invalid.".to_owned())?;
    Ok(TenantBusinessUnitConfigurationReceipt {
        business_unit: input.business_unit,
        configuration_version: response.configuration_version,
        correlation_id: response.correlation_id,
    })
}

