async fn begin_platform_tenant_provisioning_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    input: BeginTenantProvisioningInput,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<PlatformTenantLifecycleReceipt, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let tenant_id = validate_tenant_registration_reference(&input.tenant_id, "Tenant ID")?;
    let holding_ref =
        validate_tenant_registration_reference(&input.holding_ref, "Holding reference")?;
    let write_database_key =
        validate_tenant_registration_reference(&input.write_database_key, "Write database key")?;
    let read_database_key =
        validate_tenant_registration_reference(&input.read_database_key, "Read database key")?;
    if write_database_key == read_database_key {
        return Err("Write and read database keys must differ.".to_owned());
    }
    let storage_namespace =
        validate_tenant_registration_reference(&input.storage_namespace, "Storage namespace")?;
    let credential_key_ref = validate_tenant_registration_reference(
        &input.credential_key_ref,
        "Credential key reference",
    )?;
    let backup_chain_ref =
        validate_tenant_registration_reference(&input.backup_chain_ref, "Backup chain reference")?;
    let owner_principal_ref = validate_tenant_registration_reference(
        &input.owner_principal_ref,
        "Owner principal reference",
    )?;
    let owner_approver_ref = validate_tenant_registration_reference(
        &input.owner_approver_ref,
        "Independent approver reference",
    )?;
    if owner_approver_ref == principal_ref {
        return Err("The independent approver must differ from the current operator.".to_owned());
    }
    if input.mfa_code.trim().is_empty() || input.mfa_code.len() > 128 {
        return Err("Enter fresh MFA evidence before beginning provisioning.".to_owned());
    }
    let mut context = platform_command_context(
        principal_ref,
        session_id,
        "platform_tenant_provisioning_begin",
        &format!("console-tenant-provisioning-{tenant_id}"),
    );
    context.mfa_code = input.mfa_code;
    let response = client
        .begin_tenant_provisioning(authenticated_rpc_request(
            platform_admin_target::BeginTenantProvisioningRequest {
                tenant_id,
                holding_ref,
                write_database_key,
                read_database_key,
                storage_namespace,
                credential_key_ref,
                backup_chain_ref,
                context: Some(context),
                owner_principal_ref,
                owner_approver_ref,
            },
            access_token,
            principal_ref,
            session_id,
        )?)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner();
    if !response.accepted {
        return Err("The server did not accept the tenant provisioning request.".to_owned());
    }
    PlatformTenantLifecycleReceipt {
        tenant_id: response.tenant_id,
        state: response.state,
        registry_version: Some(response.registry_version),
        databases_ready: None,
        storage_ready: None,
        owner_seeded: None,
        correlation_id: response.correlation_id,
    }
    .validate()
}

