async fn mutate_platform_tenant_lifecycle_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    tenant_id: String,
    action: PlatformTenantLifecycleAction,
    mfa_code: String,
    authorization: TenantRpcAuthorization<'_>,
) -> Result<PlatformTenantLifecycleReceipt, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    validate_platform_identifier(&tenant_id, "tenant lifecycle tenant ID", false)?;
    if mfa_code.trim().is_empty() || mfa_code.len() > 128 {
        return Err("Enter fresh MFA evidence for this tenant lifecycle command.".to_owned());
    }
    let mut context = platform_command_context(
        authorization.principal_ref,
        authorization.session_id,
        action.purpose(),
        &format!("console-tenant-lifecycle-{}", Uuid::new_v4()),
    );
    context.mfa_code = mfa_code;
    let receipt = match action {
        PlatformTenantLifecycleAction::ProvisionResources => {
            let request =
                authorization.request(platform_admin_target::ProvisionTenantResourcesRequest {
                    tenant_id,
                    context: Some(context),
                })?;
            let response = client
                .provision_tenant_resources(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            // The one-time owner recovery code is deliberately not copied into
            // client state, receipts, logs, URLs, or rendered output.
            PlatformTenantLifecycleReceipt {
                tenant_id: response.tenant_id,
                state: response.state,
                registry_version: None,
                databases_ready: Some(response.databases_ready),
                storage_ready: Some(response.storage_ready),
                owner_seeded: Some(response.owner_seeded),
                correlation_id: response.correlation_id,
            }
        }
        PlatformTenantLifecycleAction::Activate | PlatformTenantLifecycleAction::Suspend => {
            let request = platform_admin_target::TransitionTenantStateRequest {
                tenant_id,
                context: Some(context),
            };
            let request = authorization.request(request)?;
            let response = if matches!(action, PlatformTenantLifecycleAction::Activate) {
                client.activate_tenant(request).await
            } else {
                client.suspend_tenant(request).await
            }
            .map_err(safe_infrastructure_status)?
            .into_inner();
            PlatformTenantLifecycleReceipt {
                tenant_id: response.tenant_id,
                state: response.state,
                registry_version: Some(response.registry_version),
                databases_ready: None,
                storage_ready: None,
                owner_seeded: None,
                correlation_id: response.correlation_id,
            }
        }
    };
    receipt.validate()
}

