async fn mutate_tenant_infrastructure_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
    administrative_context_id: Option<&str>,
    infrastructure: TenantInfrastructureRecord,
    action: TenantInfrastructureAction,
) -> Result<String, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    match action {
        TenantInfrastructureAction::SaveProfile(input) => {
            if infrastructure.is_customer_hosted() {
                return Err(
                    "Customer-hosted profile changes must be proposed and approved in the customer holding workspace."
                        .to_owned(),
                );
            }
            validate_infrastructure_reason(&input.reason)?;
            if input.mfa_code.trim().is_empty() || input.mfa_code.len() > 128 {
                return Err("Enter fresh MFA evidence for this profile change.".to_owned());
            }
            let prefix = "erpx-managed:";
            for reference in [
                &input.write_database_ref,
                &input.read_database_ref,
                &input.storage_ref,
                &input.backup_profile_ref,
            ] {
                validate_infrastructure_reference(reference, prefix)?;
            }
            if !input.directory_credential_ref.trim().is_empty() {
                validate_infrastructure_reference(&input.directory_credential_ref, prefix)?;
            }
            if input.write_database_ref.trim() == input.read_database_ref.trim() {
                return Err("Write and read database references must differ.".to_owned());
            }
            let profile_version = infrastructure
                .profile_version
                .checked_add(1)
                .ok_or_else(|| "The profile version cannot advance safely.".to_owned())?;
            let mut context = platform_command_context(
                principal_ref,
                session_id,
                "tenant_infrastructure_profile_update",
                &format!("console-infrastructure-profile-{}", Uuid::new_v4()),
            );
            context.mfa_code = input.mfa_code;
            let request = tenant_admin_rpc_request(
                authenticated_rpc_request(
                    platform_admin_target::SaveTenantInfrastructureProfileRequest {
                        profile: Some(platform_admin_target::TenantInfrastructureProfileMessage {
                            tenant_id: infrastructure.tenant_id,
                            root_holding_id: infrastructure.root_holding_id,
                            deployment_mode:
                                platform_admin_target::TenantDeploymentMode::ErpxManaged as i32,
                            write_database_ref: input.write_database_ref.trim().to_owned(),
                            read_database_ref: input.read_database_ref.trim().to_owned(),
                            storage_ref: input.storage_ref.trim().to_owned(),
                            directory_credential_ref: input
                                .directory_credential_ref
                                .trim()
                                .to_owned(),
                            backup_profile_ref: input.backup_profile_ref.trim().to_owned(),
                            profile_version,
                        }),
                        expected_profile_version: infrastructure.profile_version,
                        reason: input.reason.trim().to_owned(),
                        context: Some(context),
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?,
                administrative_context_id,
            )?;
            let response = client
                .save_tenant_infrastructure_profile(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            Ok(format!(
                "Infrastructure profile v{} saved · correlation {}.",
                response.profile_version, response.correlation_id
            ))
        }
        TenantInfrastructureAction::ProposeConfiguration(input) => {
            validate_infrastructure_reason(&input.reason)?;
            let customer_hosted = infrastructure.is_customer_hosted();
            let base_version = if customer_hosted {
                infrastructure.observed_version
            } else {
                infrastructure.desired_version
            };
            let desired_version = base_version.checked_add(1).ok_or_else(|| {
                "The desired configuration version cannot advance safely.".to_owned()
            })?;
            let desired_state = serde_json::json!({
                "profile_version": infrastructure.profile_version,
                "directory_ready_required": input.require_directory,
                "projections_healthy_required": input.require_projections,
                "backup_verified_required": input.require_backup,
            });
            let desired_state_json = serde_json::to_vec(&desired_state)
                .map_err(|_| "The typed desired configuration could not be encoded.".to_owned())?;
            let configuration_hash = Sha256::digest(&desired_state_json).to_vec();
            let target_agent_id = if customer_hosted {
                if Uuid::parse_str(&infrastructure.agent_id).is_err() {
                    return Err(
                        "Enroll a tenant-bound data-plane agent before proposing this configuration."
                            .to_owned(),
                    );
                }
                infrastructure.agent_id.clone()
            } else {
                String::new()
            };
            let mut required_capabilities = vec![
                "configuration_reconciliation".to_owned(),
                "health_telemetry".to_owned(),
            ];
            if input.require_directory {
                required_capabilities.push("directory_sync".to_owned());
            }
            if input.require_projections {
                required_capabilities.push("projection_worker".to_owned());
            }
            if input.require_backup {
                required_capabilities.push("backup".to_owned());
            }
            let configuration_id = Uuid::new_v4();
            let request = tenant_admin_rpc_request(
                authenticated_rpc_request(
                    platform_admin_target::ProposeDesiredConfigurationRequest {
                        desired: Some(platform_admin_target::DesiredConfigurationMessage {
                            contract_version: u32::from(CONTRACT_VERSION),
                            configuration_id: configuration_id.to_string(),
                            tenant_id: infrastructure.tenant_id,
                            root_holding_id: infrastructure.root_holding_id,
                            target_agent_id,
                            deployment_mode: if customer_hosted {
                                platform_admin_target::TenantDeploymentMode::CustomerDataPlane
                                    as i32
                            } else {
                                platform_admin_target::TenantDeploymentMode::ErpxManaged as i32
                            },
                            configuration_layer: "tenant".to_owned(),
                            business_unit: String::new(),
                            expected_observed_version: base_version,
                            desired_version,
                            lifecycle: if customer_hosted {
                                platform_admin_target::ConfigurationLifecycle::AwaitingApproval
                                    as i32
                            } else {
                                platform_admin_target::ConfigurationLifecycle::Draft as i32
                            },
                            configuration_hash,
                            desired_state_json,
                            secret_references: Vec::new(),
                            required_capabilities,
                            requester_ref: principal_ref.to_owned(),
                            reason: input.reason.trim().to_owned(),
                            expires_at: (Utc::now() + Duration::hours(24)).to_rfc3339(),
                            correlation_id: String::new(),
                            control_plane_signature: Vec::new(),
                            signing_key_id: String::new(),
                        }),
                        context: Some(platform_command_context(
                            principal_ref,
                            session_id,
                            "tenant_desired_configuration_proposal",
                            &format!("console-desired-configuration-{configuration_id}"),
                        )),
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?,
                administrative_context_id,
            )?;
            let response = client
                .propose_desired_configuration(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            Ok(format!(
                "Desired configuration v{} proposed as {} · correlation {}.",
                response.desired_version, response.configuration_id, response.correlation_id
            ))
        }
        TenantInfrastructureAction::RequestRootAccess(input) => {
            if Uuid::parse_str(&infrastructure.agent_id).is_err() {
                return Err("Root access requires an enrolled tenant agent.".to_owned());
            }
            if Uuid::parse_str(input.device_ref.trim()).is_err() {
                return Err("Enter the UUID of the device bound to this session.".to_owned());
            }
            validate_infrastructure_reason(&input.reason)?;
            if input.ticket_reference.trim().is_empty()
                || input.ticket_reference.trim().chars().count() > 128
            {
                return Err("Enter a ticket reference of at most 128 characters.".to_owned());
            }
            let (mode, maximum_hours, allowed_actions) = root_access_mode(&input.mode)?;
            if input.duration_hours < 1 || input.duration_hours > maximum_hours {
                return Err(format!(
                    "This access mode allows a window from 1 to {maximum_hours} hours."
                ));
            }
            let requires_business_unit = matches!(
                mode,
                platform_admin_target::RootAccessMode::BusinessDiagnostic
                    | platform_admin_target::RootAccessMode::BusinessMutation
            );
            let business_units = if input.business_unit.trim().is_empty() {
                if requires_business_unit {
                    return Err("Select an exact business unit for business access.".to_owned());
                }
                Vec::new()
            } else {
                let unit =
                    erpx_domain::data_plane::BusinessUnitId::parse(input.business_unit.trim())
                        .map_err(|_| "Select a canonical business unit.".to_owned())?;
                vec![unit.as_str().to_owned()]
            };
            let holding_id = Uuid::parse_str(&infrastructure.root_holding_id)
                .map_err(|_| "The tenant holding binding is invalid.".to_owned())?;
            let requested_at = Utc::now();
            let request_id = Uuid::new_v4();
            let request = tenant_admin_rpc_request(
                authenticated_rpc_request(
                    platform_admin_target::RequestRootAccessRequest {
                        access_request: Some(platform_admin_target::RootAccessRequestMessage {
                            request_id: request_id.to_string(),
                            requester_ref: principal_ref.to_owned(),
                            device_ref: input.device_ref.trim().to_owned(),
                            tenant_id: infrastructure.tenant_id,
                            agent_id: infrastructure.agent_id,
                            tenant_scope: Some(TenantScope {
                                scope: Some(tenant_scope::Scope::Holding(HoldingScope {
                                    holding_id: holding_id.to_string(),
                                })),
                            }),
                            mode: mode as i32,
                            allowed_actions,
                            business_units,
                            reason: input.reason.trim().to_owned(),
                            ticket_reference: input.ticket_reference.trim().to_owned(),
                            requested_at: requested_at.to_rfc3339(),
                            requested_until: (requested_at + Duration::hours(input.duration_hours))
                                .to_rfc3339(),
                        }),
                        context: Some(platform_command_context(
                            principal_ref,
                            session_id,
                            "tenant_root_access_request",
                            &format!("console-root-access-{request_id}"),
                        )),
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?,
                administrative_context_id,
            )?;
            let response = client
                .request_root_access(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            Ok(format!(
                "Root access request {} is {} · correlation {}.",
                response.request_id, response.state, response.correlation_id
            ))
        }
    }
}

