async fn fetch_tenant_governance_infrastructure_with_client<T>(
    client: &mut platform_admin_target::platform_administration_query_service_client::PlatformAdministrationQueryServiceClient<T>,
    scope: &TenantGovernanceScope,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<TenantInfrastructureRecord, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let response = client
        .get_tenant_infrastructure(authenticated_rpc_request(
            platform_admin_target::GetTenantInfrastructureRequest {
                tenant_id: scope.tenant_id.clone(),
                context: Some(tenant_holding_query_context(
                    principal_ref,
                    session_id,
                    &scope.holding_id,
                    "tenant_infrastructure_read",
                )?),
            },
            access_token,
            principal_ref,
            session_id,
        )?)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner();
    let infrastructure = response
        .infrastructure
        .ok_or_else(|| "The tenant infrastructure detail was absent.".to_owned())
        .and_then(TenantInfrastructureRecord::from_wire)?;
    if infrastructure.tenant_id != scope.tenant_id
        || infrastructure.root_holding_id != scope.holding_id
    {
        return Err(
            "The tenant infrastructure response was outside the selected scope.".to_owned(),
        );
    }
    Ok(infrastructure)
}

