fn organization_target_placement(
    scope: &TenantGovernanceScope,
    input: &TenantOrganizationNodeInput,
    node_id: &str,
) -> Result<organization_target::OrganizationPlacementV1, String> {
    use organization_target::organization_placement_v1::Placement;

    let required_uuid = |value: &str, label: &str| {
        Uuid::parse_str(value.trim())
            .map(|value| value.to_string())
            .map_err(|_| format!("The {label} must be a UUID."))
    };
    let optional_uuid = |value: &str, label: &str| {
        if value.trim().is_empty() {
            Ok(None)
        } else {
            required_uuid(value, label).map(Some)
        }
    };
    let placement = match input.kind.as_str() {
        "holding" if node_id == scope.holding_id => {
            Placement::Holding(organization_target::OrganizationHoldingPlacement {})
        }
        "holding" => {
            return Err("A holding node ID must equal the selected holding UUID.".to_owned());
        }
        "company" => Placement::Company(organization_target::OrganizationCompanyPlacement {
            holding_id: scope.holding_id.clone(),
        }),
        "headquarters" => {
            Placement::Headquarters(organization_target::OrganizationHeadquartersPlacement {
                holding_id: scope.holding_id.clone(),
                company_id: required_uuid(&input.company_id, "company ID")?,
            })
        }
        "branch" => {
            return Err("Create new branches through the typed provisioning workflow.".to_owned());
        }
        "department" => {
            Placement::Department(organization_target::OrganizationDepartmentPlacement {
                holding_id: scope.holding_id.clone(),
                company_id: required_uuid(&input.company_id, "company ID")?,
                branch_id: optional_uuid(&input.branch_id, "branch ID")?,
            })
        }
        "team" => Placement::Team(organization_target::OrganizationTeamPlacement {
            holding_id: scope.holding_id.clone(),
            company_id: required_uuid(&input.company_id, "company ID")?,
            branch_id: optional_uuid(&input.branch_id, "branch ID")?,
            department_id: required_uuid(&input.department_id, "department ID")?,
            team_id: node_id.to_owned(),
        }),
        _ => return Err("Select a canonical organization node kind.".to_owned()),
    };
    Ok(organization_target::OrganizationPlacementV1 {
        placement: Some(placement),
    })
}

