async fn fetch_tenant_organization_nodes_with_client<T>(
    client: &mut organization_target::organization_query_service_client::OrganizationQueryServiceClient<T>,
    scope: &TenantGovernanceScope,
    after_cursor: &str,
    administrative_context_id: Option<&str>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<TenantOrganizationPage, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    if after_cursor.len() > 512 || after_cursor.chars().any(char::is_control) {
        return Err("The organization cursor was invalid.".to_owned());
    }
    let request = tenant_admin_rpc_request(
        authenticated_rpc_request(
            organization_target::ListOrganizationNodeRecordsRequest {
                metadata: Some(organization_target_query_metadata(
                    scope,
                    principal_ref,
                    session_id,
                )?),
                kind: None,
                status: None,
                parent_node_id: None,
                page_size: 50,
                cursor: (!after_cursor.is_empty()).then(|| after_cursor.to_owned()),
            },
            access_token,
            principal_ref,
            session_id,
        )?,
        administrative_context_id,
    )?;
    let response = client
        .list_nodes(request)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner();
    if response.nodes.len() > 50
        || response
            .next_cursor
            .as_ref()
            .is_some_and(|cursor| cursor.len() > 512 || cursor.chars().any(char::is_control))
    {
        return Err("The organization page metadata was invalid.".to_owned());
    }
    let correlation_id = response
        .metadata
        .ok_or_else(|| "The organization query metadata was absent.".to_owned())?
        .correlation_id;
    Uuid::parse_str(&correlation_id)
        .map_err(|_| "The organization correlation ID was invalid.".to_owned())?;
    let next_cursor = response.next_cursor.unwrap_or_default();
    Ok(TenantOrganizationPage {
        nodes: response
            .nodes
            .into_iter()
            .map(|node| TenantOrganizationNodeRecord::from_target(scope, node))
            .collect::<Result<Vec<_>, _>>()?,
        has_more: !next_cursor.is_empty(),
        next_cursor,
        correlation_id,
    })
}

