async fn save_tenant_organization_node_with_client<T>(
    client: &mut organization_target::organization_command_service_client::OrganizationCommandServiceClient<T>,
    scope: &TenantGovernanceScope,
    input: TenantOrganizationNodeInput,
    administrative_context_id: Option<&str>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<TenantOrganizationWriteReceipt, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let node_id = Uuid::parse_str(input.node_id.trim())
        .map_err(|_| "The organization node ID must be a UUID.".to_owned())?
        .to_string();
    validate_platform_read_text(&input.code, "organization code", false, 64)?;
    validate_platform_read_text(&input.name, "organization name", false, 160)?;
    let placement = organization_target_placement(scope, &input, &node_id)?;
    let request = tenant_admin_rpc_request(
        authenticated_rpc_request(
            organization_target::CreateOrganizationNodeCommandRequest {
                metadata: Some(organization_target_command_metadata(
                    scope,
                    principal_ref,
                    session_id,
                )?),
                node_id: node_id.clone(),
                placement: Some(placement),
                code: input.code.trim().to_owned(),
                display_name: input.name.trim().to_owned(),
            },
            access_token,
            principal_ref,
            session_id,
        )?,
        administrative_context_id,
    )?;
    let response = client
        .create_node(request)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner();
    let node = TenantOrganizationNodeRecord::from_target(
        scope,
        response
            .node
            .ok_or_else(|| "The organization write response omitted the node.".to_owned())?,
    )?;
    let receipt = response
        .receipt
        .ok_or_else(|| "The organization write response omitted the receipt.".to_owned())?;
    let aggregate = receipt
        .aggregate
        .ok_or_else(|| "The organization write receipt omitted aggregate identity.".to_owned())?;
    if node.node_id != node_id
        || aggregate.context != "organization"
        || aggregate.aggregate_id != node_id
        || aggregate.version != node.aggregate_version
    {
        return Err("The organization write receipt did not match the request.".to_owned());
    }
    Uuid::parse_str(&receipt.correlation_id)
        .map_err(|_| "The organization correlation receipt was invalid.".to_owned())?;
    Ok(TenantOrganizationWriteReceipt {
        kind: node.kind,
        node_id,
        aggregate_version: node.aggregate_version,
        applied: !receipt.replayed,
        correlation_id: receipt.correlation_id,
    })
}

