async fn mutate_tenant_branch_infrastructure_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    scope: &TenantGovernanceScope,
    action: BranchInfrastructureAction,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<String, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    match action {
        BranchInfrastructureAction::Provision(input) => {
            let company_id = Uuid::parse_str(input.company_id.trim())
                .map_err(|_| "Enter a valid company UUID.".to_owned())?
                .to_string();
            let branch_id = Uuid::parse_str(input.branch_id.trim())
                .map_err(|_| "Enter a valid new branch UUID.".to_owned())?
                .to_string();
            validate_platform_read_text(&input.branch_code, "branch code", false, 64)?;
            validate_platform_read_text(&input.branch_name, "branch name", false, 160)?;
            validate_platform_read_text(
                &input.registration_number,
                "branch registration number",
                false,
                96,
            )?;
            let database_profile_key = validate_tenant_registration_reference(
                &input.database_profile_key,
                "Database profile key",
            )?;
            if input.enabled_business_units.is_empty()
                || input.enabled_business_units.len()
                    > erpx_domain::data_plane::BusinessUnitId::ALL.len()
            {
                return Err("Select at least one canonical business unit.".to_owned());
            }
            for unit in &input.enabled_business_units {
                erpx_domain::data_plane::BusinessUnitId::parse(unit)
                    .map_err(|_| "Select only canonical business units.".to_owned())?;
            }
            let context = tenant_holding_command_context(
                principal_ref,
                session_id,
                &scope.holding_id,
                "tenant_branch_provisioning",
                &format!("tenant-branch-provision-{branch_id}"),
                &input.mfa_code,
            )?;
            let response = client
                .provision_tenant_branch(authenticated_rpc_request(
                    platform_admin_target::ProvisionTenantBranchRequest {
                        tenant_id: scope.tenant_id.clone(),
                        company_id,
                        branch_id,
                        branch_code: input.branch_code.trim().to_owned(),
                        branch_name: input.branch_name.trim().to_owned(),
                        registration_number: input.registration_number.trim().to_owned(),
                        database_profile_key,
                        enabled_business_units: input.enabled_business_units,
                        context: Some(context),
                        mfa_code: input.mfa_code,
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            let record = response
                .provisioning
                .ok_or_else(|| "The tenant branch receipt was absent.".to_owned())
                .and_then(BranchProvisioningRecord::from_wire)?;
            Ok(format!(
                "Branch {} queued as job {} · correlation {}.",
                record.branch_code, record.job_id, response.correlation_id
            ))
        }
        BranchInfrastructureAction::Retry { job_id, mfa_code } => {
            let job_id = Uuid::parse_str(job_id.trim())
                .map_err(|_| "The branch job ID is invalid.".to_owned())?
                .to_string();
            let context = tenant_holding_command_context(
                principal_ref,
                session_id,
                &scope.holding_id,
                "tenant_branch_provisioning_retry",
                &format!("tenant-branch-retry-{job_id}"),
                &mfa_code,
            )?;
            let response = client
                .retry_tenant_branch_provisioning(authenticated_rpc_request(
                    platform_admin_target::RetryTenantBranchProvisioningRequest {
                        tenant_id: scope.tenant_id.clone(),
                        job_id,
                        context: Some(context),
                        mfa_code,
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            let record = response
                .provisioning
                .ok_or_else(|| "The tenant branch retry receipt was absent.".to_owned())
                .and_then(BranchProvisioningRecord::from_wire)?;
            Ok(format!(
                "Branch job {} is {} · correlation {}.",
                record.job_id, record.state, response.correlation_id
            ))
        }
        BranchInfrastructureAction::Suspend {
            branch_id,
            mfa_code,
        } => {
            let branch_id = Uuid::parse_str(branch_id.trim())
                .map_err(|_| "The branch ID is invalid.".to_owned())?
                .to_string();
            let context = tenant_holding_command_context(
                principal_ref,
                session_id,
                &scope.holding_id,
                "tenant_branch_route_suspension",
                &format!("tenant-branch-suspend-{branch_id}"),
                &mfa_code,
            )?;
            let response = client
                .suspend_tenant_branch_route(authenticated_rpc_request(
                    platform_admin_target::SuspendTenantBranchRouteRequest {
                        tenant_id: scope.tenant_id.clone(),
                        branch_id: branch_id.clone(),
                        context: Some(context),
                        mfa_code,
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            if response.branch_id != branch_id {
                return Err("The branch suspension receipt did not match the request.".to_owned());
            }
            validate_platform_read_text(&response.state, "branch suspension state", false, 64)?;
            Ok(format!(
                "Branch route {} is {} at v{} · correlation {}.",
                response.branch_id, response.state, response.route_version, response.correlation_id
            ))
        }
    }
}

