async fn mutate_tenant_governance_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    scope: &TenantGovernanceScope,
    action: TenantGovernanceAction,
    administrative_context_id: Option<&str>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<TenantGovernanceReceipt, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let receipt = match action {
        TenantGovernanceAction::DecideDesiredConfiguration {
            configuration_id,
            approve,
            reason,
            mfa_code,
        } => {
            let configuration_id = Uuid::parse_str(configuration_id.trim())
                .map_err(|_| "The desired configuration ID must be a UUID.".to_owned())?
                .to_string();
            validate_infrastructure_reason(&reason)?;
            let context = tenant_holding_command_context(
                principal_ref,
                session_id,
                &scope.holding_id,
                if approve {
                    "tenant_desired_configuration_approval"
                } else {
                    "tenant_desired_configuration_rejection"
                },
                &format!("tenant-desired-decision-{configuration_id}-{approve}"),
                &mfa_code,
            )?;
            let request = tenant_admin_rpc_request(
                authenticated_rpc_request(
                    platform_admin_target::DecideDesiredConfigurationRequest {
                        configuration_id,
                        approve,
                        reason: reason.trim().to_owned(),
                        context: Some(context),
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?,
                administrative_context_id,
            )?;
            let response = client
                .decide_desired_configuration(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            let state = platform_admin_target::ConfigurationLifecycle::try_from(response.lifecycle)
                .map_err(|_| "The desired configuration receipt state was invalid.".to_owned())?
                .as_str_name()
                .to_owned();
            TenantGovernanceReceipt {
                subject_id: response.configuration_id,
                state,
                correlation_id: response.correlation_id,
            }
        }
        TenantGovernanceAction::DecideRootAccess {
            request_id,
            approve,
            reason,
            mfa_code,
        } => {
            let request_id = Uuid::parse_str(request_id.trim())
                .map_err(|_| "The Root access request ID must be a UUID.".to_owned())?
                .to_string();
            validate_infrastructure_reason(&reason)?;
            let context = tenant_holding_command_context(
                principal_ref,
                session_id,
                &scope.holding_id,
                if approve {
                    "tenant_root_access_approval"
                } else {
                    "tenant_root_access_rejection"
                },
                &format!("tenant-root-decision-{request_id}-{approve}"),
                &mfa_code,
            )?;
            let request = tenant_admin_rpc_request(
                authenticated_rpc_request(
                    platform_admin_target::DecideRootAccessRequest {
                        request_id,
                        approve,
                        reason: reason.trim().to_owned(),
                        context: Some(context),
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?,
                administrative_context_id,
            )?;
            let response = client
                .decide_root_access(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            TenantGovernanceReceipt {
                subject_id: response.request_id,
                state: response.state,
                correlation_id: response.correlation_id,
            }
        }
        TenantGovernanceAction::RevokeRootAccess {
            request_id,
            reason,
            mfa_code,
        } => {
            let request_id = Uuid::parse_str(request_id.trim())
                .map_err(|_| "The Root access request ID must be a UUID.".to_owned())?
                .to_string();
            validate_infrastructure_reason(&reason)?;
            let context = tenant_holding_command_context(
                principal_ref,
                session_id,
                &scope.holding_id,
                "tenant_root_access_revocation",
                &format!("tenant-root-revocation-{request_id}"),
                &mfa_code,
            )?;
            let request = tenant_admin_rpc_request(
                authenticated_rpc_request(
                    platform_admin_target::RevokeRootAccessRequest {
                        request_id: request_id.clone(),
                        reason: reason.trim().to_owned(),
                        context: Some(context),
                    },
                    access_token,
                    principal_ref,
                    session_id,
                )?,
                administrative_context_id,
            )?;
            let response = client
                .revoke_root_access(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            if !response.revoked {
                return Err("The Root access revocation was not applied.".to_owned());
            }
            TenantGovernanceReceipt {
                subject_id: request_id,
                state: "revoked".to_owned(),
                correlation_id: response.correlation_id,
            }
        }
    };
    receipt.validate()
}

fn add_tenant_admin_context_metadata<T>(
    request: &mut tonic::Request<T>,
    administrative_context_id: &str,
) -> Result<(), String> {
    Uuid::parse_str(administrative_context_id)
        .map_err(|_| "The tenant administrative context is invalid.".to_owned())?;
    request.metadata_mut().insert(
        "x-erpx-tenant-admin-context",
        MetadataValue::try_from(administrative_context_id)
            .map_err(|_| "The tenant administrative context cannot be transported.".to_owned())?,
    );
    Ok(())
}

fn tenant_admin_rpc_request<T>(
    mut request: tonic::Request<T>,
    administrative_context_id: Option<&str>,
) -> Result<tonic::Request<T>, String> {
    if let Some(administrative_context_id) = administrative_context_id {
        add_tenant_admin_context_metadata(&mut request, administrative_context_id)?;
    }
    Ok(request)
}

