async fn mutate_branch_infrastructure_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    tenant_id: String,
    administrative_context_id: &str,
    action: BranchInfrastructureAction,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<String, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    validate_platform_identifier(&tenant_id, "branch tenant ID", false)?;
    match action {
        BranchInfrastructureAction::Provision(input) => {
            Uuid::parse_str(input.company_id.trim())
                .map_err(|_| "Enter a valid company UUID.".to_owned())?;
            Uuid::parse_str(input.branch_id.trim())
                .map_err(|_| "Enter a valid new branch UUID.".to_owned())?;
            validate_platform_read_text(&input.branch_code, "branch code", false, 64)?;
            validate_platform_read_text(&input.branch_name, "branch name", false, 160)?;
            validate_platform_read_text(
                &input.registration_number,
                "branch registration number",
                false,
                96,
            )?;
            let profile_key = validate_tenant_registration_reference(
                &input.database_profile_key,
                "Database profile key",
            )?;
            if input.enabled_business_units.is_empty()
                || input.enabled_business_units.len()
                    > erpx_domain::data_plane::BusinessUnitId::ALL.len()
            {
                return Err("Select at least one canonical business unit.".to_owned());
            }
            for unit in &input.enabled_business_units {
                erpx_domain::data_plane::BusinessUnitId::parse(unit)
                    .map_err(|_| "Select only canonical business units.".to_owned())?;
            }
            if input.mfa_code.trim().is_empty() || input.mfa_code.len() > 128 {
                return Err("Enter fresh MFA evidence for branch provisioning.".to_owned());
            }
            let mut context = platform_command_context(
                principal_ref,
                session_id,
                "tenant_branch_provisioning",
                &format!("console-branch-provision-{}", input.branch_id.trim()),
            );
            context.mfa_code = input.mfa_code.clone();
            let mut request = authenticated_rpc_request(
                platform_admin_target::ProvisionTenantBranchRequest {
                    tenant_id,
                    company_id: input.company_id.trim().to_owned(),
                    branch_id: input.branch_id.trim().to_owned(),
                    branch_code: input.branch_code.trim().to_owned(),
                    branch_name: input.branch_name.trim().to_owned(),
                    registration_number: input.registration_number.trim().to_owned(),
                    database_profile_key: profile_key,
                    enabled_business_units: input.enabled_business_units,
                    context: Some(context),
                    mfa_code: input.mfa_code,
                },
                access_token,
                principal_ref,
                session_id,
            )?;
            add_tenant_admin_context_metadata(&mut request, administrative_context_id)?;
            let response = client
                .provision_tenant_branch(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            let record = response
                .provisioning
                .ok_or_else(|| "The branch provisioning receipt was absent.".to_owned())
                .and_then(BranchProvisioningRecord::from_wire)?;
            Ok(format!(
                "Branch {} queued as job {} · correlation {}.",
                record.branch_code, record.job_id, response.correlation_id
            ))
        }
        BranchInfrastructureAction::Retry { job_id, mfa_code } => {
            Uuid::parse_str(job_id.trim())
                .map_err(|_| "The branch job ID is invalid.".to_owned())?;
            if mfa_code.trim().is_empty() || mfa_code.len() > 128 {
                return Err("Enter fresh MFA evidence before retrying.".to_owned());
            }
            let mut context = platform_command_context(
                principal_ref,
                session_id,
                "tenant_branch_provisioning_retry",
                &format!("console-branch-retry-{}", Uuid::new_v4()),
            );
            context.mfa_code = mfa_code.clone();
            let mut request = authenticated_rpc_request(
                platform_admin_target::RetryTenantBranchProvisioningRequest {
                    tenant_id,
                    job_id,
                    context: Some(context),
                    mfa_code,
                },
                access_token,
                principal_ref,
                session_id,
            )?;
            add_tenant_admin_context_metadata(&mut request, administrative_context_id)?;
            let response = client
                .retry_tenant_branch_provisioning(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            let record = response
                .provisioning
                .ok_or_else(|| "The branch retry receipt was absent.".to_owned())
                .and_then(BranchProvisioningRecord::from_wire)?;
            Ok(format!(
                "Branch job {} is {} · correlation {}.",
                record.job_id, record.state, response.correlation_id
            ))
        }
        BranchInfrastructureAction::Suspend {
            branch_id,
            mfa_code,
        } => {
            Uuid::parse_str(branch_id.trim())
                .map_err(|_| "The branch ID is invalid.".to_owned())?;
            if mfa_code.trim().is_empty() || mfa_code.len() > 128 {
                return Err("Enter fresh MFA evidence before suspension.".to_owned());
            }
            let mut context = platform_command_context(
                principal_ref,
                session_id,
                "tenant_branch_route_suspension",
                &format!("console-branch-suspend-{}", Uuid::new_v4()),
            );
            context.mfa_code = mfa_code.clone();
            let mut request = authenticated_rpc_request(
                platform_admin_target::SuspendTenantBranchRouteRequest {
                    tenant_id,
                    branch_id,
                    context: Some(context),
                    mfa_code,
                },
                access_token,
                principal_ref,
                session_id,
            )?;
            add_tenant_admin_context_metadata(&mut request, administrative_context_id)?;
            let response = client
                .suspend_tenant_branch_route(request)
                .await
                .map_err(safe_infrastructure_status)?
                .into_inner();
            validate_platform_identifier(&response.branch_id, "suspended branch ID", false)?;
            validate_platform_read_text(&response.state, "suspended branch state", false, 64)?;
            Ok(format!(
                "Branch route {} is {} at v{} · correlation {}.",
                response.branch_id, response.state, response.route_version, response.correlation_id
            ))
        }
    }
}

#[cfg(target_arch = "wasm32")]
async fn fetch_platform_projection_statuses_once(
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<Vec<PlatformProjectionStatusRecord>, String> {
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    let mut client = platform_admin_target::platform_administration_query_service_client::PlatformAdministrationQueryServiceClient::new(channel);
    let mut after_cursor = String::new();
    let mut statuses = Vec::new();
    for _ in 0..100 {
        let mut request =
            tonic::Request::new(platform_admin_target::ListProjectionStatusesRequest {
                tenant_id: String::new(),
                holding_ref: String::new(),
                projection_name: String::new(),
                page_size: 100,
                after_cursor,
                context: Some(platform_query_context(&principal_ref, &session_id)),
            });
        request.metadata_mut().insert(
            "x-erpx-access-token",
            MetadataValue::try_from(access_token.as_str())
                .map_err(|_| "access token is not valid transport metadata".to_string())?,
        );
        request.metadata_mut().insert(
            "x-erpx-actor",
            MetadataValue::try_from(principal_ref.as_str())
                .map_err(|_| "principal reference is not valid transport metadata".to_string())?,
        );
        request.metadata_mut().insert(
            "x-erpx-session",
            MetadataValue::try_from(session_id.as_str())
                .map_err(|_| "session reference is not valid transport metadata".to_string())?,
        );
        let page = client
            .list_projection_statuses(request)
            .await
            .map_err(platform_projection_status_rpc_error)?
            .into_inner();
        if page.statuses.len() > 100 {
            return Err("platform projection-status page exceeded its bound".to_string());
        }
        let page_statuses = page
            .statuses
            .into_iter()
            .map(PlatformProjectionStatusRecord::from_wire)
            .collect::<Result<Vec<_>, _>>()?;
        statuses.extend(page_statuses);
        if !page.has_more {
            return Ok(statuses);
        }
        if page.next_cursor.is_empty() {
            return Err("projection status pagination cursor was empty".to_string());
        }
        after_cursor = page.next_cursor;
    }
    Err("projection status pagination exceeded its bound".to_string())
}

