async fn fetch_tenant_brand_editor_with_client<T>(
    client: &mut platform_admin_target::platform_administration_query_service_client::PlatformAdministrationQueryServiceClient<T>,
    scope: &TenantGovernanceScope,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<PlatformBrandEditorRecord, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let brand_scope = platform_admin_target::BrandScopeMessage {
        scope_kind: "holding".to_owned(),
        tenant_id: scope.tenant_id.clone(),
        root_holding_id: scope.holding_id.clone(),
        business_unit: String::new(),
    };
    let query_context = || {
        tenant_holding_query_context(
            principal_ref,
            session_id,
            &scope.holding_id,
            "tenant_corporate_identity_read",
        )
    };
    let resolved = client
        .get_resolved_corporate_identity(authenticated_rpc_request(
            platform_admin_target::GetResolvedCorporateIdentityRequest {
                scope: Some(brand_scope.clone()),
                context: Some(query_context()?),
            },
            access_token,
            principal_ref,
            session_id,
        )?)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner()
        .identity
        .ok_or_else(|| "The tenant corporate identity was absent.".to_owned())?;
    let draft_response = client
        .get_corporate_identity_draft(authenticated_rpc_request(
            platform_admin_target::GetCorporateIdentityDraftRequest {
                scope: Some(brand_scope),
                context: Some(query_context()?),
            },
            access_token,
            principal_ref,
            session_id,
        )?)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner();
    decode_platform_brand_editor_record(
        resolved,
        draft_response
            .exists
            .then_some(draft_response.draft)
            .flatten(),
    )
}

