async fn mutate_tenant_brand_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    scope: &TenantGovernanceScope,
    authorization: TenantRpcAuthorization<'_>,
    record: PlatformBrandEditorRecord,
    action: CorporateIdentityEditorAction,
) -> Result<String, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    validate_infrastructure_reason(&action.submission.reason)?;
    if matches!(action.kind, CorporateIdentityEditorActionKind::Rollback) {
        let source_version = action
            .submission
            .rollback_source_version
            .ok_or_else(|| "Select an immutable tenant identity history version.".to_owned())?;
        let context = tenant_holding_command_context(
            authorization.principal_ref,
            authorization.session_id,
            &scope.holding_id,
            "tenant_corporate_identity_rollback",
            &format!(
                "tenant-brand-rollback-{}-{source_version}",
                record.profile_id
            ),
            &action.submission.mfa_code,
        )?;
        let request =
            authorization.request(platform_admin_target::RollbackCorporateIdentityRequest {
                profile_id: record.profile_id,
                source_version,
                expected_published_version: record.published_version,
                reason: action.submission.reason,
                context: Some(context),
            })?;
        let published = client
            .rollback_corporate_identity(request)
            .await
            .map_err(safe_infrastructure_status)?
            .into_inner()
            .published
            .ok_or_else(|| "The tenant identity rollback receipt was absent.".to_owned())?;
        return Ok(format!(
            "Tenant corporate identity rolled back from v{} as v{}.",
            source_version, published.version
        ));
    }
    let save_context = tenant_holding_command_context(
        authorization.principal_ref,
        authorization.session_id,
        &scope.holding_id,
        "tenant_corporate_identity_draft",
        &format!("tenant-brand-draft-{}", record.profile_id),
        &action.submission.mfa_code,
    )?;
    let draft = tenant_brand_draft_message(scope, &record, &action, authorization.principal_ref);
    let request =
        authorization.request(platform_admin_target::SaveCorporateIdentityDraftRequest {
            draft: Some(draft),
            expected_version: record.base_version,
            reason: action.submission.reason.clone(),
            context: Some(save_context),
        })?;
    let saved = client
        .save_corporate_identity_draft(request)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner()
        .draft
        .ok_or_else(|| "The tenant identity draft receipt was absent.".to_owned())?;
    if matches!(action.kind, CorporateIdentityEditorActionKind::SaveDraft) {
        return Ok(format!("Tenant identity draft v{} saved.", saved.version));
    }
    let publish_context = tenant_holding_command_context(
        authorization.principal_ref,
        authorization.session_id,
        &scope.holding_id,
        "tenant_corporate_identity_publish",
        &format!(
            "tenant-brand-publish-{}-{}",
            saved.profile_id, saved.version
        ),
        &action.submission.mfa_code,
    )?;
    let request = authorization.request(
        platform_admin_target::PublishCorporateIdentityDraftRequest {
            profile_id: saved.profile_id,
            expected_draft_version: saved.version,
            reason: action.submission.reason,
            context: Some(publish_context),
        },
    )?;
    let published = client
        .publish_corporate_identity_draft(request)
        .await
        .map_err(safe_infrastructure_status)?
        .into_inner()
        .published
        .ok_or_else(|| "The tenant identity publication receipt was absent.".to_owned())?;
    Ok(format!(
        "Tenant corporate identity v{} published.",
        published.version
    ))
}

