async fn mutate_platform_brand_with_client<T>(
    client: &mut platform_admin_target::platform_administration_command_service_client::PlatformAdministrationCommandServiceClient<T>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
    record: PlatformBrandEditorRecord,
    action: CorporateIdentityEditorAction,
) -> Result<String, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    validate_infrastructure_reason(&action.submission.reason)?;
    if matches!(action.kind, CorporateIdentityEditorActionKind::Rollback) {
        let source_version = action
            .submission
            .rollback_source_version
            .ok_or_else(|| "Select an immutable identity history version.".to_owned())?;
        let mut context = platform_command_context(
            principal_ref,
            session_id,
            "platform_corporate_identity_rollback",
            &format!("platform-brand-rollback-{source_version}"),
        );
        context.mfa_code = action.submission.mfa_code;
        let published = client
            .rollback_corporate_identity(authenticated_rpc_request(
                platform_admin_target::RollbackCorporateIdentityRequest {
                    profile_id: record.profile_id,
                    source_version,
                    expected_published_version: record.published_version,
                    reason: action.submission.reason,
                    context: Some(context),
                },
                access_token,
                principal_ref,
                session_id,
            )?)
            .await
            .map_err(safe_infrastructure_status)?
            .into_inner()
            .published
            .ok_or_else(|| "Corporate identity rollback receipt was absent.".to_owned())?;
        return Ok(format!(
            "Corporate identity rolled back from v{} as v{}.",
            source_version, published.version
        ));
    }
    let mut save_context = platform_command_context(
        principal_ref,
        session_id,
        "platform_corporate_identity_draft",
        &Uuid::new_v4().to_string(),
    );
    save_context.mfa_code = action.submission.mfa_code.clone();
    let draft = platform_brand_draft_message(&record, &action, principal_ref);
    let saved = client
        .save_corporate_identity_draft(authenticated_rpc_request(
            platform_admin_target::SaveCorporateIdentityDraftRequest {
                draft: Some(draft),
                expected_version: record.base_version,
                reason: action.submission.reason.clone(),
                context: Some(save_context),
            },
            access_token,
            principal_ref,
            session_id,
        )?)
        .await
        .map_err(|status| {
            format!(
                "Corporate identity draft was not saved: {}",
                status.message()
            )
        })?
        .into_inner()
        .draft
        .ok_or_else(|| "corporate identity draft receipt was absent".to_owned())?;
    if matches!(action.kind, CorporateIdentityEditorActionKind::SaveDraft) {
        return Ok(format!("Draft v{} saved.", saved.version));
    }

    let mut publish_context = platform_command_context(
        principal_ref,
        session_id,
        "platform_corporate_identity_publish",
        &Uuid::new_v4().to_string(),
    );
    publish_context.mfa_code = action.submission.mfa_code;
    let published = client
        .publish_corporate_identity_draft(authenticated_rpc_request(
            platform_admin_target::PublishCorporateIdentityDraftRequest {
                profile_id: saved.profile_id,
                expected_draft_version: saved.version,
                reason: action.submission.reason,
                context: Some(publish_context),
            },
            access_token,
            principal_ref,
            session_id,
        )?)
        .await
        .map_err(|status| format!("Corporate identity was not published: {}", status.message()))?
        .into_inner()
        .published
        .ok_or_else(|| "corporate identity publication receipt was absent".to_owned())?;
    Ok(format!(
        "Corporate identity v{} published.",
        published.version
    ))
}

fn decode_navigation_manifest(
    groups: Vec<platform_admin_target::NavigationManifestGroup>,
) -> Result<Vec<NavGroup>, String> {
    let mut decoded = Vec::with_capacity(groups.len().min(8));
    for group in groups.into_iter().take(8) {
        validate_platform_read_text(&group.label, "navigation group", false, 80)?;
        validate_platform_read_text(&group.group_id, "navigation group id", false, 96)?;
        validate_platform_read_text(&group.label_key, "navigation group label key", false, 128)?;
        let mut items = Vec::with_capacity(group.items.len().min(32));
        for item in group.items.into_iter().take(32) {
            validate_platform_read_text(&item.label, "navigation label", false, 96)?;
            validate_platform_read_text(&item.route_id, "navigation route id", false, 96)?;
            validate_platform_read_text(&item.label_key, "navigation label key", false, 128)?;
            if !item.path.starts_with('/') || item.path.len() > 256 {
                return Err("navigation path is invalid".to_owned());
            }
            let access_state =
                platform_admin_target::NavigationAccessState::try_from(item.access_state)
                    .map_err(|_| "navigation access state is invalid".to_owned())?;
            let access = match access_state {
                platform_admin_target::NavigationAccessState::Locked => {
                    NavAccess::locked(item.required_role_keys)
                }
                platform_admin_target::NavigationAccessState::Unspecified
                | platform_admin_target::NavigationAccessState::Authorized => NavAccess::Authorized,
            };
            items.push(
                NavItem::new(item.label, item.path, item.icon)
                    .with_manifest_metadata(item.route_id, item.label_key)
                    .with_action_capabilities(item.action_capabilities)
                    .with_access(access),
            );
        }
        if !items.is_empty() {
            decoded.push(
                NavGroup::new(group.label, items)
                    .with_manifest_metadata(group.group_id, group.label_key),
            );
        }
    }
    if decoded.is_empty() {
        return Err("authorized navigation manifest is empty".to_owned());
    }
    Ok(decoded)
}

#[cfg(any(target_arch = "wasm32", feature = "server"))]
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub(crate) struct NavigationHttpItem {
    route_id: String,
    label: String,
    label_key: String,
    path: String,
    icon: String,
    action_capabilities: Vec<String>,
    #[serde(default)]
    access_state: i32,
    #[serde(default)]
    required_role_keys: Vec<String>,
}

#[cfg(any(target_arch = "wasm32", feature = "server"))]
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub(crate) struct NavigationHttpGroup {
    group_id: String,
    label: String,
    label_key: String,
    items: Vec<NavigationHttpItem>,
}

#[cfg(feature = "server")]
pub(crate) fn navigation_http_groups(groups: &[NavGroup]) -> Vec<NavigationHttpGroup> {
    groups
        .iter()
        .map(|group| NavigationHttpGroup {
            group_id: group.group_id.clone(),
            label: group.label.clone(),
            label_key: group.label_key.clone(),
            items: group
                .items
                .iter()
                .map(|item| NavigationHttpItem {
                    route_id: item.route_id.clone(),
                    label: item.label.clone(),
                    label_key: item.label_key.clone(),
                    path: item.path.clone(),
                    icon: item.icon.clone(),
                    action_capabilities: item.action_capabilities.clone(),
                    access_state: match &item.access {
                        NavAccess::Authorized => {
                            platform_admin_target::NavigationAccessState::Authorized as i32
                        }
                        NavAccess::Locked { .. } => {
                            platform_admin_target::NavigationAccessState::Locked as i32
                        }
                    },
                    required_role_keys: item.required_role_keys().to_vec(),
                })
                .collect(),
        })
        .collect()
}

#[cfg(target_arch = "wasm32")]
fn decode_navigation_http_groups(
    groups: Vec<NavigationHttpGroup>,
) -> Result<Vec<NavGroup>, String> {
    decode_navigation_manifest(
        groups
            .into_iter()
            .map(|group| platform_admin_target::NavigationManifestGroup {
                group_id: group.group_id,
                label: group.label,
                label_key: group.label_key,
                items: group
                    .items
                    .into_iter()
                    .map(|item| platform_admin_target::NavigationManifestItem {
                        route_id: item.route_id,
                        label: item.label,
                        label_key: item.label_key,
                        path: item.path,
                        icon: item.icon,
                        badge_count: 0,
                        action_capabilities: item.action_capabilities,
                        access_state: item.access_state,
                        required_role_keys: item.required_role_keys,
                    })
                    .collect(),
            })
            .collect(),
    )
}

#[cfg(target_arch = "wasm32")]
pub(crate) async fn fetch_navigation_manifest(
    _access_token: String,
    _principal_ref: String,
    _session_id: String,
    scope_key: String,
    _development_context_token: Option<String>,
    include_inaccessible: bool,
) -> Result<Vec<NavGroup>, String> {
    navigation_query_context("browser-bff", "browser-bff", &scope_key)?;
    let response = execute_web_http(
        crate::platform::http::HttpEndpoint::Auth,
        "POST",
        "/api/v2/navigation",
        serde_json::json!({
            "scope_key": scope_key,
            "include_inaccessible": include_inaccessible,
        })
        .to_string(),
        Vec::new(),
    )
    .await
    .map_err(|_| "authorized navigation read failed: Unavailable".to_owned())?;
    match response.status {
        200 => serde_json::from_str::<Vec<NavigationHttpGroup>>(&response.body)
            .map_err(|_| "authorized navigation response was invalid".to_owned())
            .and_then(decode_navigation_http_groups),
        400 => Err("authorized navigation read failed: InvalidArgument".to_owned()),
        401 => Err("authorized navigation read failed: Unauthenticated".to_owned()),
        403 => Err("authorized navigation read failed: PermissionDenied".to_owned()),
        _ => Err("authorized navigation read failed: Unavailable".to_owned()),
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub(crate) async fn fetch_navigation_manifest(
    access_token: String,
    principal_ref: String,
    session_id: String,
    scope_key: String,
    development_context_token: Option<String>,
    include_inaccessible: bool,
) -> Result<Vec<NavGroup>, String> {
    let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
        .connect()
        .await
        .map_err(|_| "authorized navigation connection failed".to_string())?;
    let mut client = platform_admin_target::platform_administration_query_service_client::PlatformAdministrationQueryServiceClient::new(channel);
    let mut request = tonic::Request::new(platform_admin_target::GetNavigationManifestRequest {
        context: Some(navigation_query_context(
            &principal_ref,
            &session_id,
            &scope_key,
        )?),
        include_inaccessible,
    });
    request.metadata_mut().insert(
        "x-erpx-access-token",
        MetadataValue::try_from(access_token.as_str())
            .map_err(|_| "access token is not valid transport metadata".to_string())?,
    );
    request.metadata_mut().insert(
        "x-erpx-actor",
        MetadataValue::try_from(principal_ref.as_str())
            .map_err(|_| "principal reference is not valid transport metadata".to_string())?,
    );
    request.metadata_mut().insert(
        "x-erpx-session",
        MetadataValue::try_from(session_id.as_str())
            .map_err(|_| "session reference is not valid transport metadata".to_string())?,
    );
    if let Some(context_token) = development_context_token {
        request.metadata_mut().insert(
            "x-erpx-dev-persona-context",
            MetadataValue::try_from(context_token.as_str())
                .map_err(|_| "development context is not valid transport metadata".to_string())?,
        );
    }
    let response = client
        .get_navigation_manifest(request)
        .await
        .map_err(|status| format!("authorized navigation read failed: {:?}", status.code()))?
        .into_inner();
    decode_navigation_manifest(response.groups)
}

