const fn work_severity_query_value(severity: WorkItemSeverity) -> &'static str {
    match severity {
        WorkItemSeverity::Critical => "critical",
        WorkItemSeverity::High => "high",
        WorkItemSeverity::Medium => "medium",
        WorkItemSeverity::Low => "low",
        WorkItemSeverity::Informational => "informational",
    }
}

#[cfg(target_arch = "wasm32")]
async fn fetch_work_queue_read_model(
    view: WorkQueueView,
    domain: Option<WorkDomain>,
    severity: Option<WorkItemSeverity>,
    cursor: Option<String>,
) -> Result<WorkQueueReadModel, String> {
    let mut path = format!(
        "/api/v2/work-items?view={}&page_size=24",
        view.query_value()
    );
    if let Some(domain) = domain {
        path.push_str("&domain=");
        path.push_str(domain.as_str());
    }
    if let Some(severity) = severity {
        path.push_str("&severity=");
        path.push_str(work_severity_query_value(severity));
    }
    if let Some(cursor) = cursor.filter(|value| erpx_ui_core::valid_work_cursor(value)) {
        path.push_str("&cursor=");
        path.push_str(&cursor);
    }
    let response = bff_http("GET", &path, String::new()).await?;
    if response.status != 200 {
        return Err(identity_response_error(response.status));
    }
    let model = serde_json::from_str::<WorkQueueReadModel>(&response.body)
        .map_err(|_| "work_queue_invalid_response".to_owned())?;
    if !model.is_bounded() {
        return Err("work_queue_invalid_response".to_owned());
    }
    Ok(model)
}

