fn decode_platform_role_review(
    evaluated_at: String,
    expiry_horizon_until: String,
    items: Vec<RoleReviewItem>,
) -> Result<PlatformRoleReviewPage, String> {
    validate_platform_read_text(&evaluated_at, "role-review evaluated timestamp", false, 64)?;
    validate_platform_read_text(
        &expiry_horizon_until,
        "role-review expiry horizon",
        false,
        64,
    )?;
    if items.len() > 1_000 {
        return Err("role-review response exceeded its bound".to_string());
    }
    let items = items
        .into_iter()
        .map(PlatformRoleReviewRecord::from_wire)
        .collect::<Result<Vec<_>, _>>()?;
    Ok(PlatformRoleReviewPage {
        evaluated_at: safe_platform_read_text(&evaluated_at),
        expiry_horizon_until: safe_platform_read_text(&expiry_horizon_until),
        items,
    })
}

