struct MigrationWorkRequestFields<'a> {
    run_id: &'a str,
    work_kind: &'a str,
    scope_key: &'a str,
    source_fence: &'a str,
    max_attempts: &'a str,
    mfa_code: &'a str,
    principal_ref: &'a str,
    session_id: &'a str,
}

fn migration_work_request(
    fields: MigrationWorkRequestFields<'_>,
) -> Result<platform_admin_target::QueueMigrationWorkRequest, String> {
    let run_id = Uuid::parse_str(fields.run_id.trim())
        .map_err(|_| "Enter a valid migration run UUID.".to_string())?;
    let work_kind = bounded_operations_value(fields.work_kind, "migration work kind", false, 32)?;
    if !matches!(
        work_kind.as_str(),
        "backfill" | "project" | "shadow_replay" | "final_delta" | "reconcile" | "rollback"
    ) {
        return Err("Choose a supported migration work kind.".into());
    }
    let scope_key = bounded_operations_value(fields.scope_key, "migration scope", false, 200)?;
    let source_fence =
        bounded_operations_value(fields.source_fence, "migration source fence", false, 200)?;
    let max_attempts = fields
        .max_attempts
        .trim()
        .parse::<u32>()
        .map_err(|_| "Max attempts must be a number from 1 to 25.".to_string())?;
    if !(1..=25).contains(&max_attempts) {
        return Err("Max attempts must be a number from 1 to 25.".into());
    }
    let mfa_code = bounded_operations_value(fields.mfa_code, "MFA code", false, 128)?;
    let idempotency_key = format!("console-g13-work-{}", Uuid::new_v4());
    Ok(platform_admin_target::QueueMigrationWorkRequest {
        run_id: run_id.to_string(),
        work_kind,
        scope_key,
        source_fence,
        max_attempts,
        mfa_code,
        context: Some(platform_command_context(
            fields.principal_ref,
            fields.session_id,
            "queue G13 migration execution work",
            &idempotency_key,
        )),
    })
}

struct BeginMigrationRunRequestFields<'a> {
    run_id: &'a str,
    cohort: &'a str,
    source_contract_hash: &'a str,
    id_namespace: &'a str,
    mfa_code: &'a str,
    principal_ref: &'a str,
    session_id: &'a str,
}

fn begin_migration_run_request(
    fields: BeginMigrationRunRequestFields<'_>,
) -> Result<platform_admin_target::BeginMigrationRunRequest, String> {
    let run_id = Uuid::parse_str(fields.run_id.trim())
        .map_err(|_| "Enter a valid migration run UUID.".to_string())?;
    let bounded = |value: &str, label: &str| bounded_operations_value(value, label, false, 128);
    let cohort = bounded(fields.cohort, "migration cohort")?;
    let source_contract_hash = fields.source_contract_hash.trim().to_owned();
    if source_contract_hash.len() != 64
        || !source_contract_hash
            .chars()
            .all(|character| character.is_ascii_digit() || ('a'..='f').contains(&character))
    {
        return Err("Source contract hash must be 64 lowercase hexadecimal characters.".into());
    }
    let id_namespace = bounded(fields.id_namespace, "migration ID namespace")?;
    let mfa_code = bounded_operations_value(fields.mfa_code, "MFA code", false, 128)?;
    let idempotency_key = format!("console-g13-begin-{}", Uuid::new_v4());
    Ok(platform_admin_target::BeginMigrationRunRequest {
        run_id: run_id.to_string(),
        cohort,
        source_contract_hash,
        id_namespace,
        mfa_code,
        context: Some(platform_command_context(
            fields.principal_ref,
            fields.session_id,
            "begin G13 migration run",
            &idempotency_key,
        )),
    })
}

struct AdvanceMigrationPhaseRequestFields<'a> {
    run_id: &'a str,
    expected_version: &'a str,
    expected_phase: &'a str,
    mfa_code: &'a str,
    principal_ref: &'a str,
    session_id: &'a str,
}

fn advance_migration_phase_request(
    fields: AdvanceMigrationPhaseRequestFields<'_>,
) -> Result<platform_admin_target::AdvanceMigrationPhaseRequest, String> {
    let run_id = Uuid::parse_str(fields.run_id.trim())
        .map_err(|_| "Enter a valid migration run UUID.".to_string())?;
    let expected_version = fields
        .expected_version
        .trim()
        .parse::<u64>()
        .map_err(|_| "Expected version must be a positive number.".to_string())?;
    if expected_version == 0 {
        return Err("Expected version must be a positive number.".into());
    }
    let expected_phase =
        bounded_operations_value(fields.expected_phase, "expected migration phase", false, 64)?;
    if !matches!(
        expected_phase.as_str(),
        "source_frozen"
            | "ids_mapped"
            | "write_backfilled"
            | "read_projected"
            | "shadow_replaying"
            | "reconciled"
            | "read_only_pilot"
            | "workflow_accepted"
            | "rollback_rehearsed"
            | "mutation_frozen"
    ) {
        return Err(
            "Choose a phase before final-delta completion; command-owner approval is external."
                .into(),
        );
    }
    let mfa_code = bounded_operations_value(fields.mfa_code, "MFA code", false, 128)?;
    let idempotency_key = format!("console-g13-advance-{}", Uuid::new_v4());
    Ok(platform_admin_target::AdvanceMigrationPhaseRequest {
        run_id: run_id.to_string(),
        expected_version,
        expected_phase,
        mfa_code,
        context: Some(platform_command_context(
            fields.principal_ref,
            fields.session_id,
            "advance G13 migration phase",
            &idempotency_key,
        )),
    })
}

