async fn fetch_incidents(
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<IncidentReadPage, String> {
    let tenants = fetch_platform_tenants(
        access_token.clone(),
        principal_ref.clone(),
        session_id.clone(),
    )
    .await?;
    let channel = support_grpc_channel().await?;
    let mut client =
        support_target::support_query_service_client::SupportQueryServiceClient::new(channel);
    let mut incidents = Vec::new();
    let mut metadata = None;
    for tenant in tenants.into_iter().filter(|tenant| tenant.enterable) {
        let scope = SupportTargetScope::try_new(&tenant, &tenant.root_holding_id, None, None)?;
        let remaining = INCIDENT_LIST_PAGE_SIZE as usize - incidents.len();
        if remaining == 0 {
            return Err("additional authorized incident scope input is required".into());
        }
        let mut request = tonic::Request::new(support_target::ListSupportIncidentRecordsRequest {
            metadata: Some(support_target_query_metadata(
                &scope,
                &principal_ref,
                &session_id,
                "support_incident_console_read",
            )?),
            status: None,
            page_size: u32::try_from(remaining).unwrap_or(INCIDENT_LIST_PAGE_SIZE),
            cursor: None,
        });
        add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
        let response = client
            .list_incidents(request)
            .await
            .map_err(incidents_rpc_error)?
            .into_inner();
        if response.next_cursor.is_some() {
            return Err("additional authorized incident scope input is required".into());
        }
        metadata = response.metadata;
        incidents.extend(response.incidents);
    }
    IncidentReadPage::from_target_wire(support_target::ListSupportIncidentRecordsResponse {
        incidents,
        next_cursor: None,
        metadata,
    })
}

