fn support_command_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::Aborted => "conflict".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "support_command_rejected".into()
        }
        _ => "support_command_failed".into(),
    }
}

#[cfg(target_arch = "wasm32")]
type SupportGrpcChannel = tonic_web_wasm_client::Client;
#[cfg(not(target_arch = "wasm32"))]
type SupportGrpcChannel = tonic::transport::Channel;

#[cfg(target_arch = "wasm32")]
async fn support_grpc_channel() -> Result<SupportGrpcChannel, String> {
    Ok(tonic_web_wasm_client::Client::new(grpc_endpoint()))
}

#[cfg(not(target_arch = "wasm32"))]
async fn support_grpc_channel() -> Result<SupportGrpcChannel, String> {
    tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
        .connect()
        .await
        .map_err(|_| "offline".to_string())
}

fn support_ticket_status(value: &str) -> Result<i32, String> {
    let status = match value.trim() {
        "new" => support_target::SupportTicketStatus::New,
        "triaged" => support_target::SupportTicketStatus::Triaged,
        "waiting_for_customer" => support_target::SupportTicketStatus::WaitingForCustomer,
        "access_requested" => support_target::SupportTicketStatus::AccessRequested,
        "approved" => support_target::SupportTicketStatus::Approved,
        "in_progress" => support_target::SupportTicketStatus::InProgress,
        "resolved" => support_target::SupportTicketStatus::Resolved,
        "customer_confirmed" => support_target::SupportTicketStatus::CustomerConfirmed,
        "closed" => support_target::SupportTicketStatus::Closed,
        _ => return Err("select a supported ticket status".into()),
    };
    Ok(status as i32)
}

fn support_incident_status(value: &str) -> Result<i32, String> {
    let status = match value.trim() {
        "investigating" => support_target::SupportIncidentStatus::Investigating,
        "identified" => support_target::SupportIncidentStatus::Identified,
        "monitoring" => support_target::SupportIncidentStatus::Monitoring,
        "resolved" => support_target::SupportIncidentStatus::Resolved,
        "postmortem_complete" => support_target::SupportIncidentStatus::PostmortemComplete,
        _ => return Err("select a supported incident status".into()),
    };
    Ok(status as i32)
}

fn support_mode(value: &str) -> Result<i32, String> {
    let mode = match value.trim() {
        "diagnostic_read" => support_target::SupportMode::DiagnosticRead,
        "tenant_mutation" => support_target::SupportMode::TenantMutation,
        "impersonation" => support_target::SupportMode::Impersonation,
        _ => return Err("select a supported support-session mode".into()),
    };
    Ok(mode as i32)
}

fn support_command_correlation(receipt: Option<&ProtoCommandReceipt>) -> Result<String, String> {
    bounded_incident_value(
        receipt
            .map(|receipt| receipt.correlation_id.as_str())
            .unwrap_or_default(),
        "support command correlation ID",
        false,
        128,
    )
}

fn support_target_ticket_receipt(
    ticket: Option<support_target::SupportInternalTicketRecord>,
    receipt: Option<ProtoCommandReceipt>,
) -> Result<SupportCommandReceipt, String> {
    let ticket = ticket.ok_or_else(|| "support command omitted its ticket".to_owned())?;
    Ok(SupportCommandReceipt {
        resource: "ticket".into(),
        resource_id: bounded_incident_value(&ticket.ticket_id, "ticket ID", false, 128)?,
        status: support_ticket_status_label(ticket.status)
            .ok_or_else(|| "support command returned an invalid ticket status".to_owned())?
            .to_owned(),
        version: ticket.source_version,
        correlation_id: support_command_correlation(receipt.as_ref())?,
    })
}

fn support_target_incident_receipt(
    incident: Option<support_target::SupportIncidentRecord>,
    receipt: Option<ProtoCommandReceipt>,
) -> Result<SupportCommandReceipt, String> {
    let incident = incident.ok_or_else(|| "support command omitted its incident".to_owned())?;
    Ok(SupportCommandReceipt {
        resource: "incident".into(),
        resource_id: bounded_incident_value(&incident.incident_id, "incident ID", false, 128)?,
        status: support_incident_status_label(incident.status)
            .ok_or_else(|| "support command returned an invalid incident status".to_owned())?
            .to_owned(),
        version: incident.source_version,
        correlation_id: support_command_correlation(receipt.as_ref())?,
    })
}

fn support_session_status_label(value: i32) -> Option<&'static str> {
    match support_target::SupportSessionStatus::try_from(value).ok()? {
        support_target::SupportSessionStatus::Requested => Some("requested"),
        support_target::SupportSessionStatus::Approved => Some("approved"),
        support_target::SupportSessionStatus::Revoked => Some("revoked"),
        support_target::SupportSessionStatus::Unspecified => None,
    }
}

fn support_target_session_receipt(
    session: Option<support_target::SupportSessionRecord>,
    receipt: Option<ProtoCommandReceipt>,
) -> Result<SupportCommandReceipt, String> {
    let session = session.ok_or_else(|| "support command omitted its session".to_owned())?;
    Ok(SupportCommandReceipt {
        resource: "support session".into(),
        resource_id: bounded_incident_value(&session.session_id, "support session ID", false, 128)?,
        status: support_session_status_label(session.status)
            .ok_or_else(|| "support command returned an invalid session status".to_owned())?
            .to_owned(),
        version: session.source_version,
        correlation_id: support_command_correlation(receipt.as_ref())?,
    })
}

async fn authorize_support_customer_selection(
    scope: &SupportTargetScope,
    customer_id: &str,
    customer_account_id: &str,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<(), String> {
    use erpx_ui_foundation::QueryGateway;

    let customer_id =
        Uuid::parse_str(customer_id.trim()).map_err(|_| "customer ID must be a UUID".to_owned())?;
    let customer_account_id = Uuid::parse_str(customer_account_id.trim())
        .map_err(|_| "customer account ID must be a UUID".to_owned())?;
    if customer_id != customer_account_id {
        return Err(
            "the selected customer account is not an accepted Customer profile fact".into(),
        );
    }
    let Some(company_id) = scope.company_id.as_deref() else {
        return Err("an explicit authorized customer owning company is required".into());
    };
    let transport = {
        #[cfg(target_arch = "wasm32")]
        let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
        #[cfg(not(target_arch = "wasm32"))]
        let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
            .connect()
            .await
            .map_err(|_| "offline".to_owned())?;
        crate::transport::wave4_5::CustomerAuthorityGrpcTransport::try_new(
            channel,
            access_token,
            &scope.tenant_id,
            &scope.holding_ref,
        )
        .map_err(|error| error.message().to_owned())?
    };
    let gateway =
        crate::features::customer_authority::gateway::CustomerAuthorityGateway::new(transport);
    let mut query = customer_authority_query(
        principal_ref,
        session_id,
        erpx_customer_authority::GetCustomer {
            customer_id: erpx_customer_authority::CustomerId::try_from_uuid(customer_id)
                .map_err(|_| "customer ID was invalid".to_owned())?,
        },
    )?;
    query.tenant_scope = scope.domain_scope()?;
    let result = QueryGateway::<erpx_customer_authority::GetCustomer>::execute(&gateway, query)
        .await
        .map_err(|_| "the authorized Customer profile fact is unavailable".to_owned())?;
    let customer = result
        .value
        .customer
        .ok_or_else(|| "the authorized Customer profile fact is unavailable".to_owned())?;
    let company_scope = erpx_kernel::TenantScope::Company {
        holding_id: Uuid::parse_str(&scope.holding_id)
            .map_err(|_| "support holding was invalid".to_owned())?,
        company_id: Uuid::parse_str(company_id)
            .map_err(|_| "support company was invalid".to_owned())?,
    };
    let selected_scope = scope.domain_scope()?;
    if customer.customer_id.as_uuid() != customer_id
        || customer.merged_into.is_some()
        || customer.primary_authority != company_scope
        || !customer.visible_under(&selected_scope)
    {
        return Err("the selected Customer profile is outside the authorized Support scope".into());
    }
    Ok(())
}

async fn execute_support_command(
    input: SupportCommandInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<SupportCommandReceipt, String> {
    let (holding_id, company_id, branch_id) = match &input {
        SupportCommandInput::CreateTicket {
            holding_id,
            company_id,
            branch_id,
            ..
        }
        | SupportCommandInput::CreateIncident {
            holding_id,
            company_id,
            branch_id,
            ..
        }
        | SupportCommandInput::RequestSession {
            holding_id,
            company_id,
            branch_id,
            ..
        } => (
            holding_id.as_str(),
            Some(company_id.as_str()),
            Some(branch_id.as_str()),
        ),
        SupportCommandInput::TransitionTicket { holding_id, .. }
        | SupportCommandInput::RecurTicket { holding_id, .. }
        | SupportCommandInput::AddTicketReply { holding_id, .. }
        | SupportCommandInput::AddTicketInternalNote { holding_id, .. }
        | SupportCommandInput::TransitionIncident { holding_id, .. }
        | SupportCommandInput::ApproveSession { holding_id, .. }
        | SupportCommandInput::RevokeSession { holding_id, .. } => {
            (holding_id.as_str(), None, None)
        }
    };
    let scope = resolve_support_target_scope(
        holding_id,
        company_id,
        branch_id.filter(|value| !value.trim().is_empty()),
        &access_token,
        &principal_ref,
        &session_id,
    )
    .await?;
    let channel = support_grpc_channel().await?;
    let mut client =
        support_target::support_command_service_client::SupportCommandServiceClient::new(channel);
    match input {
        SupportCommandInput::CreateTicket {
            customer_id,
            customer_account_id,
            case_code,
            category,
            severity,
            description,
            ..
        } => {
            authorize_support_customer_selection(
                &scope,
                &customer_id,
                &customer_account_id,
                &access_token,
                &principal_ref,
                &session_id,
            )
            .await?;
            let mut request = tonic::Request::new(support_target::OpenSupportTicketCommandRequest {
                metadata: Some(support_target_command_metadata(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "support_ticket_open",
                    None,
                    None,
                )?),
                ticket_id: Uuid::new_v4().to_string(),
                customer_id: Uuid::parse_str(customer_id.trim())
                    .map_err(|_| "customer ID must be a UUID".to_owned())?
                    .to_string(),
                customer_account_id: Uuid::parse_str(customer_account_id.trim())
                    .map_err(|_| "customer account ID must be a UUID".to_owned())?
                    .to_string(),
                case_code: bounded_incident_value(&case_code, "ticket case code", false, 128)?,
                category: bounded_incident_value(&category, "ticket category", false, 64)?,
                severity: bounded_incident_value(&severity, "ticket severity", false, 32)?,
                description: bounded_incident_value(
                    &description,
                    "ticket description",
                    false,
                    4_096,
                )?,
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .open_ticket(request)
                .await
                .map_err(support_command_rpc_error)?
                .into_inner();
            support_target_ticket_receipt(response.ticket, response.receipt)
        }
        SupportCommandInput::TransitionTicket {
            ticket_id,
            next_status,
            expected_version,
            ..
        } => {
            let mut request = tonic::Request::new(
                support_target::TransitionSupportTicketCommandRequest {
                    metadata: Some(support_target_command_metadata(
                        &scope,
                        &principal_ref,
                        &session_id,
                        "support_ticket_transition",
                        Some(support_expected_version(&expected_version, "ticket version")?),
                        None,
                    )?),
                    ticket_id: Uuid::parse_str(ticket_id.trim())
                        .map_err(|_| "ticket ID must be a UUID".to_owned())?
                        .to_string(),
                    next: support_ticket_status(&next_status)?,
                },
            );
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client
                .transition_ticket(request)
                .await
                .map_err(support_command_rpc_error)?
                .into_inner();
            support_target_ticket_receipt(response.ticket, response.receipt)
        }
        SupportCommandInput::RecurTicket { .. } => Err(
            "additional authorized customer and source-ticket facts are required to open a follow-up ticket"
                .into(),
        ),
        input @ (SupportCommandInput::AddTicketReply { .. }
        | SupportCommandInput::AddTicketInternalNote { .. }) => {
            let internal = matches!(&input, SupportCommandInput::AddTicketInternalNote { .. });
            let (ticket_id, body) = match input {
                SupportCommandInput::AddTicketReply {
                    ticket_id, body, ..
                }
                | SupportCommandInput::AddTicketInternalNote {
                    ticket_id, body, ..
                } => (ticket_id, body),
                _ => unreachable!(),
            };
            let mut request = tonic::Request::new(
                support_target::AddSupportTicketMessageCommandRequest {
                    metadata: Some(support_target_command_metadata(
                        &scope,
                        &principal_ref,
                        &session_id,
                        if internal { "support_ticket_internal_note" } else { "support_ticket_customer_reply" },
                        None,
                        None,
                    )?),
                    ticket_id: Uuid::parse_str(ticket_id.trim())
                        .map_err(|_| "ticket ID must be a UUID".to_owned())?
                        .to_string(),
                    message_id: Uuid::new_v4().to_string(),
                    body: bounded_incident_value(&body, "ticket message", false, 4_096)?,
                },
            );
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            if internal {
                let response = client
                    .add_internal_note(request)
                    .await
                    .map_err(support_command_rpc_error)?
                    .into_inner();
                support_target_ticket_receipt(response.ticket, response.receipt)
            } else {
                let response = client
                    .add_customer_reply(request)
                    .await
                    .map_err(support_command_rpc_error)?
                    .into_inner();
                let ticket = response.ticket.ok_or_else(|| "support command omitted its ticket".to_owned())?;
                Ok(SupportCommandReceipt {
                    resource: "ticket".into(),
                    resource_id: ticket.ticket_id,
                    status: support_ticket_status_label(ticket.status)
                        .ok_or_else(|| "support command returned an invalid ticket status".to_owned())?
                        .to_owned(),
                    version: ticket.source_version,
                    correlation_id: support_command_correlation(response.receipt.as_ref())?,
                })
            }
        }
        SupportCommandInput::CreateIncident {
            incident_code,
            severity,
            leads,
            affected_services,
            affected_customer_accounts,
            ..
        } => {
            if !leads.trim().is_empty() {
                return Err("incident lead assignment requires an authorized Identity principal selector".into());
            }
            let affected_customer_account_ids = support_csv_values(
                &affected_customer_accounts,
                "affected customer accounts",
                256,
                64,
            )?
            .into_iter()
            .map(|value| Uuid::parse_str(&value).map(|id| id.to_string()).map_err(|_| "affected customer accounts must be UUIDs".to_owned()))
            .collect::<Result<Vec<_>, _>>()?;
            let mut request = tonic::Request::new(support_target::OpenSupportIncidentCommandRequest {
                metadata: Some(support_target_command_metadata(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "support_incident_open",
                    None,
                    None,
                )?),
                incident_id: Uuid::new_v4().to_string(),
                incident_code: bounded_incident_value(&incident_code, "incident code", false, 128)?,
                severity: bounded_incident_value(&severity, "incident severity", false, 32)?,
                affected_services: support_csv_values(&affected_services, "affected services", 64, 128)?,
                affected_customer_account_ids,
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client.open_incident(request).await.map_err(support_command_rpc_error)?.into_inner();
            support_target_incident_receipt(response.incident, response.receipt)
        }
        SupportCommandInput::TransitionIncident { incident_id, next_status, expected_version, .. } => {
            let mut request = tonic::Request::new(support_target::TransitionSupportIncidentCommandRequest {
                metadata: Some(support_target_command_metadata(
                    &scope,
                    &principal_ref,
                    &session_id,
                    "support_incident_transition",
                    Some(support_expected_version(&expected_version, "incident version")?),
                    None,
                )?),
                incident_id: Uuid::parse_str(incident_id.trim()).map_err(|_| "incident ID must be a UUID".to_owned())?.to_string(),
                next: support_incident_status(&next_status)?,
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client.transition_incident(request).await.map_err(support_command_rpc_error)?.into_inner();
            support_target_incident_receipt(response.incident, response.receipt)
        }
        SupportCommandInput::RequestSession {
            ticket_id,
            customer_id,
            mode,
            permissions,
            reason,
            duration_minutes,
            represented_tenant_user,
            module,
            ..
        } => {
            Uuid::parse_str(customer_id.trim()).map_err(|_| "customer ID must be a UUID".to_owned())?;
            let permissions = support_csv_values(&permissions, "support permissions", 64, 128)?;
            if permissions.is_empty() { return Err("select at least one support permission".into()); }
            let duration_minutes = duration_minutes.trim().parse::<u32>().map_err(|_| "support duration must be a positive number of minutes".to_owned())?;
            if !(1..=480).contains(&duration_minutes) { return Err("support duration must be between 1 and 480 minutes".into()); }
            let represented_principal_id = (!represented_tenant_user.trim().is_empty())
                .then(|| Uuid::parse_str(represented_tenant_user.trim()).map(|id| id.to_string()).map_err(|_| "represented tenant user must be a UUID".to_owned()))
                .transpose()?;
            let mut request = tonic::Request::new(support_target::RequestTypedSupportSessionCommandRequest {
                metadata: Some(support_target_command_metadata(&scope, &principal_ref, &session_id, "support_session_request", None, None)?),
                session_id: Uuid::new_v4().to_string(),
                ticket_id: Uuid::parse_str(ticket_id.trim()).map_err(|_| "ticket ID must be a UUID".to_owned())?.to_string(),
                represented_principal_id,
                mode: support_mode(&mode)?,
                permissions,
                approved_scope: Some(scope.tenant_scope()),
                module: bounded_incident_value(&module, "support module", false, 128)?,
                reason: bounded_incident_value(&reason, "support session reason", false, 1_024)?,
                duration_seconds: i64::from(duration_minutes) * 60,
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client.request_session(request).await.map_err(support_command_rpc_error)?.into_inner();
            support_target_session_receipt(response.session, response.receipt)
        }
        SupportCommandInput::ApproveSession { session_id: support_session_id, mfa_code, .. } => {
            let mfa_code = bounded_incident_value(&mfa_code, "current MFA code", false, 256)?;
            let mut request = tonic::Request::new(support_target::SupportSessionIdentityCommandRequest {
                metadata: Some(support_target_command_metadata(&scope, &principal_ref, &session_id, "support_session_approve", None, Some(&mfa_code))?),
                session_id: Uuid::parse_str(support_session_id.trim()).map_err(|_| "support session ID must be a UUID".to_owned())?.to_string(),
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client.approve_session(request).await.map_err(support_command_rpc_error)?.into_inner();
            support_target_session_receipt(response.session, response.receipt)
        }
        SupportCommandInput::RevokeSession { session_id: support_session_id, .. } => {
            let mut request = tonic::Request::new(support_target::RevokeTypedSupportSessionCommandRequest {
                metadata: Some(support_target_command_metadata(&scope, &principal_ref, &session_id, "support_session_revoke", None, None)?),
                session_id: Uuid::parse_str(support_session_id.trim()).map_err(|_| "support session ID must be a UUID".to_owned())?.to_string(),
                reason: "customer_requested_from_console".to_owned(),
            });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            let response = client.revoke_session(request).await.map_err(support_command_rpc_error)?.into_inner();
            support_target_session_receipt(response.session, response.receipt)
        }
    }
}

fn customer_authority_actor(
    principal_ref: &str,
    session_id: &str,
) -> Result<erpx_kernel::ActorAttribution, String> {
    let session_id = Uuid::parse_str(session_id)
        .map_err(|_| "The authenticated session identifier is invalid.".to_owned())?;
    Ok(erpx_kernel::ActorAttribution {
        principal_ref: principal_ref.to_owned(),
        kind: erpx_kernel::ActorKind::PlatformUser,
        session_id: Some(
            erpx_kernel::SessionId::try_from_uuid(session_id)
                .map_err(|_| "The authenticated session identifier is invalid.".to_owned())?,
        ),
        represented_principal_ref: None,
        support_capability_id: None,
    })
}

fn customer_authority_query<Q>(
    principal_ref: &str,
    session_id: &str,
    query: Q,
) -> Result<erpx_cqrs::QueryEnvelope<Q>, String> {
    Ok(erpx_cqrs::QueryEnvelope {
        contract_version: erpx_cqrs::CONTRACT_VERSION,
        query_id: erpx_kernel::QueryId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a query identifier.".to_owned())?,
        correlation_id: erpx_kernel::CorrelationId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a correlation identifier.".to_owned())?,
        actor: customer_authority_actor(principal_ref, session_id)?,
        tenant_scope: erpx_kernel::TenantScope::Platform,
        audit: erpx_kernel::AuditContext {
            purpose: "platform_customer_360_console_read".to_owned(),
            customer_visible: false,
            module: Some("customer_authority".to_owned()),
        },
        consistency: erpx_cqrs::QueryConsistency::Eventual,
        query,
    })
}

async fn customer_authority_transport(
    tenant: &PlatformTenantRecord,
    access_token: &str,
) -> Result<crate::transport::wave4_5::CustomerAuthorityGrpcTransport, String> {
    #[cfg(target_arch = "wasm32")]
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    #[cfg(not(target_arch = "wasm32"))]
    let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
        .connect()
        .await
        .map_err(|_| "offline".to_owned())?;
    crate::transport::wave4_5::CustomerAuthorityGrpcTransport::try_new(
        channel,
        access_token,
        &tenant.tenant_id,
        &tenant.root_holding_id,
    )
    .map_err(|error| error.message().to_owned())
}

fn customer_authority_status_label(status: erpx_customer_authority::CustomerStatus) -> String {
    match status {
        erpx_customer_authority::CustomerStatus::Prospect => "prospect",
        erpx_customer_authority::CustomerStatus::Onboarding => "onboarding",
        erpx_customer_authority::CustomerStatus::Active => "active",
        erpx_customer_authority::CustomerStatus::Suspended => "suspended",
        erpx_customer_authority::CustomerStatus::Churned => "churned",
    }
    .to_owned()
}

fn customer_record_from_authority(
    value: erpx_customer_authority::CustomerAuthorityView,
    tenants: &[PlatformTenantRecord],
) -> Result<CustomerRecord, String> {
    let customer_id = value.customer_id.as_uuid().to_string();
    let tenant = tenants
        .iter()
        .find(|tenant| tenant.customer_id == customer_id);
    let trading_name = safe_platform_read_text(&value.trading_name);
    let legal_name = safe_platform_read_text(value.legal_name.as_deref().unwrap_or(&trading_name));
    let record = CustomerRecord {
        id: safe_platform_read_text(&customer_id),
        account_code: safe_platform_read_text(value.code.as_str()),
        trading_name,
        legal_name,
        country: safe_platform_read_text(&value.country),
        status: customer_authority_status_label(value.status),
        billing_state: tenant
            .map(|tenant| tenant.subscription_state.clone())
            .unwrap_or_else(|| "not_projected".to_owned()),
        health: tenant
            .map(|tenant| tenant.health.clone())
            .unwrap_or_else(|| "not_projected".to_owned()),
        companies: tenant.map_or(0, |tenant| tenant.company_count),
        branches: tenant.map_or(0, |tenant| tenant.branch_count),
        users: tenant.map_or(0, |tenant| tenant.used_seats),
        expiring_roles: 0,
        tickets: 0,
        modules: tenant.map_or(0, |tenant| {
            u32::try_from(tenant.enabled_modules.len()).unwrap_or(u32::MAX)
        }),
        lag_seconds: 0,
    };
    record.validate()?;
    Ok(record)
}

fn customer_record_from_tenant(tenant: &PlatformTenantRecord) -> Result<CustomerRecord, String> {
    let customer_name = if tenant.customer_name.is_empty() {
        tenant.customer_id.clone()
    } else {
        tenant.customer_name.clone()
    };
    let record = CustomerRecord {
        id: tenant.customer_id.clone(),
        account_code: tenant.customer_id.clone(),
        trading_name: customer_name.clone(),
        legal_name: customer_name,
        // Country belongs to Customer Authority and is intentionally absent from the
        // platform tenant summary. Keep the authorized registry row usable while the
        // richer projection catches up without presenting a service failure as data.
        country: "—".to_owned(),
        status: tenant.state.clone(),
        billing_state: tenant.subscription_state.clone(),
        health: tenant.health.clone(),
        companies: tenant.company_count,
        branches: tenant.branch_count,
        users: tenant.used_seats,
        expiring_roles: 0,
        tickets: 0,
        modules: u32::try_from(tenant.enabled_modules.len()).unwrap_or(u32::MAX),
        lag_seconds: 0,
    };
    record.validate()?;
    Ok(record)
}

fn append_tenant_customer_fallbacks(
    customers: &mut Vec<CustomerRecord>,
    tenants: &[PlatformTenantRecord],
    search: Option<&str>,
) -> Result<(), String> {
    let search = search.map(str::to_ascii_lowercase);
    for tenant in tenants {
        if tenant.customer_id.is_empty()
            || customers
                .iter()
                .any(|customer| customer.id == tenant.customer_id)
        {
            continue;
        }
        let customer = customer_record_from_tenant(tenant)?;
        let matches_search = search.as_ref().is_none_or(|search| {
            customer.trading_name.to_ascii_lowercase().contains(search)
                || customer.account_code.to_ascii_lowercase().contains(search)
        });
        if matches_search {
            customers.push(customer);
        }
    }
    customers.sort_by(|left, right| {
        left.trading_name
            .to_ascii_lowercase()
            .cmp(&right.trading_name.to_ascii_lowercase())
            .then_with(|| left.id.cmp(&right.id))
    });
    Ok(())
}

fn tenant_customer_fallbacks(
    tenants: &[PlatformTenantRecord],
    search: Option<&str>,
) -> Result<Vec<CustomerRecord>, String> {
    let mut customers = Vec::new();
    append_tenant_customer_fallbacks(&mut customers, tenants, search)?;
    Ok(customers)
}

