#[cfg(target_arch = "wasm32")]
async fn transition_operations_exception(
    input: OperationsTransitionInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<OperationsTransitionResult, String> {
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    let mut client =
        operations_target::operations_command_service_client::OperationsCommandServiceClient::new(
            channel,
        );
    let metadata = operations_target_command_metadata(
        &principal_ref,
        &session_id,
        &input.scope,
        "operations_exception_lifecycle",
        input.expected_version,
        &input.mfa_code,
    )?;
    let response = match input.action.as_str() {
        "reassign" => {
            let mut request =
                tonic::Request::new(operations_target::ReassignOperationsExceptionRequest {
                    metadata: Some(metadata),
                    exception_id: input.exception_id,
                    assignee_id: input.assignee,
                    manager_id: input.manager,
                });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            client.reassign_exception(request).await
        }
        "acknowledge" => {
            let mut request =
                tonic::Request::new(operations_target::AcknowledgeOperationsExceptionRequest {
                    metadata: Some(metadata),
                    exception_id: input.exception_id,
                });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            client.acknowledge_exception(request).await
        }
        "escalate" => {
            let mut request =
                tonic::Request::new(operations_target::EscalateOperationsExceptionRequest {
                    metadata: Some(metadata),
                    exception_id: input.exception_id,
                    manager_id: input.manager,
                });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            client.escalate_exception(request).await
        }
        "resolve" => {
            let mut request =
                tonic::Request::new(operations_target::ResolveOperationsExceptionRequest {
                    metadata: Some(metadata),
                    exception_id: input.exception_id,
                });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            client.resolve_exception(request).await
        }
        "close" => {
            let mut request =
                tonic::Request::new(operations_target::CloseOperationsExceptionRequest {
                    metadata: Some(metadata),
                    exception_id: input.exception_id,
                });
            add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
            client.close_exception(request).await
        }
        _ => return Err("operations_scope_unavailable".to_owned()),
    }
    .map_err(operations_rpc_error)?
    .into_inner();
    OperationsTransitionResult::from_wire(response)
}

