fn finance_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "finance_scope_unavailable".into()
        }
        tonic::Code::NotFound => "finance_route_unavailable".into(),
        _ => "finance_read_failed".into(),
    }
}

fn finance_command_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "finance_command_rejected".into()
        }
        tonic::Code::NotFound => "finance_route_unavailable".into(),
        _ => "finance_command_failed".into(),
    }
}

fn finance_target_period_request(
    scope: &FinanceScope,
    input: &FinancePeriodCommandInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<finance_target::CreateFinancePeriodRequest, String> {
    if finance_expected_version(&input.expected_version, "expected period version")?.is_some() {
        return Err(
            "an existing period cannot be overwritten; use an explicit close transition".into(),
        );
    }
    let company_id = finance_command_uuid(&input.company_id, "period company ID")?;
    Ok(finance_target::CreateFinancePeriodRequest {
        metadata: Some(finance_target_command_metadata(
            scope,
            principal_ref,
            session_id,
            "finance_period_create",
            None,
        )?),
        period_id: finance_command_uuid(&input.period_id, "period ID")?,
        target_scope: Some(TenantScope {
            scope: Some(tenant_scope::Scope::Company(CompanyScope {
                holding_id: scope.holding_id.clone(),
                company_id,
            })),
        }),
        code: finance_command_text(&input.label, "period code", 64)?.to_ascii_uppercase(),
        starts_on: finance_command_date(&input.starts_on, "period start")?,
        ends_on: finance_command_date(&input.ends_on, "period end")?,
    })
}

fn finance_target_period_receipt(
    response: finance_target::FinancePeriodMutationResponse,
) -> Result<FinancePeriodCommandReceipt, String> {
    let receipt = response
        .receipt
        .ok_or_else(|| "Finance period command omitted its receipt".to_owned())?;
    let aggregate = receipt
        .aggregate
        .ok_or_else(|| "Finance period command omitted aggregate metadata".to_owned())?;
    let period = response
        .period
        .ok_or_else(|| "Finance period command omitted its result".to_owned())?;
    if aggregate.aggregate_id != period.period_id
        || aggregate.version != period.source_version
        || aggregate.version == 0
    {
        return Err("Finance period receipt did not match its result".into());
    }
    Ok(FinancePeriodCommandReceipt {
        period_id: finance_command_uuid(&period.period_id, "Finance period receipt ID")?,
        version: aggregate.version,
        replayed: receipt.replayed,
        correlation_id: bounded_finance_value(
            &receipt.correlation_id,
            "Finance period correlation ID",
            false,
            128,
        )?,
    })
}

enum FinanceTargetChartRequest {
    Create(finance_target::CreateFinanceChartRequest),
    Add(finance_target::AddFinanceAccountRequest),
}

fn finance_target_account(
    input: &FinanceChartTypedInput,
) -> Result<finance_target::FinanceAccountRecord, String> {
    let category = match input.account_category.trim() {
        "asset" => finance_target::FinanceAccountCategory::Asset,
        "liability" => finance_target::FinanceAccountCategory::Liability,
        "equity" => finance_target::FinanceAccountCategory::Equity,
        "revenue" => finance_target::FinanceAccountCategory::Revenue,
        "expense" => finance_target::FinanceAccountCategory::Expense,
        _ => return Err("account category is not supported".into()),
    };
    let normal_balance = if matches!(
        category,
        finance_target::FinanceAccountCategory::Asset
            | finance_target::FinanceAccountCategory::Expense
    ) {
        finance_target::FinanceNormalBalance::Debit
    } else {
        finance_target::FinanceNormalBalance::Credit
    };
    Ok(finance_target::FinanceAccountRecord {
        account_id: finance_command_uuid(&input.account_id, "account ID")?,
        code: finance_command_text(&input.account_code, "account code", 64)?.to_ascii_uppercase(),
        name: finance_command_text(&input.account_name, "account name", 255)?,
        category: category as i32,
        normal_balance: normal_balance as i32,
        parent_account_id: None,
        status: finance_target::FinanceAccountStatus::Active as i32,
    })
}

fn finance_target_chart_request(
    scope: &FinanceScope,
    input: &FinanceChartTypedInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<FinanceTargetChartRequest, String> {
    let chart_id = finance_command_uuid(&input.chart_id, "chart ID")?;
    let company_id = finance_command_uuid(&input.company_id, "chart company ID")?;
    let account = finance_target_account(input)?;
    let expected = finance_expected_version(&input.expected_version, "expected chart version")?;
    let metadata = finance_target_command_metadata(
        scope,
        principal_ref,
        session_id,
        if expected.is_some() {
            "finance_chart_add_account"
        } else {
            "finance_chart_create"
        },
        expected,
    )?;
    Ok(match expected {
        Some(_) => FinanceTargetChartRequest::Add(finance_target::AddFinanceAccountRequest {
            metadata: Some(metadata),
            chart_id,
            account: Some(account),
        }),
        None => FinanceTargetChartRequest::Create(finance_target::CreateFinanceChartRequest {
            metadata: Some(metadata),
            chart_id,
            target_scope: Some(TenantScope {
                scope: Some(tenant_scope::Scope::Company(CompanyScope {
                    holding_id: scope.holding_id.clone(),
                    company_id,
                })),
            }),
            code: finance_command_text(&input.code, "chart code", 64)?.to_ascii_uppercase(),
            name: finance_command_text(&input.name, "chart name", 255)?,
            currency: finance_command_text(&input.currency, "chart currency", 3)?
                .to_ascii_uppercase(),
            accounts: vec![account],
        }),
    })
}

fn finance_target_chart_receipt(
    response: finance_target::FinanceChartMutationResponse,
) -> Result<FinanceChartCommandReceipt, String> {
    let receipt = response
        .receipt
        .ok_or_else(|| "Finance chart command omitted its receipt".to_owned())?;
    let aggregate = receipt
        .aggregate
        .ok_or_else(|| "Finance chart command omitted aggregate metadata".to_owned())?;
    let chart = response
        .chart
        .ok_or_else(|| "Finance chart command omitted its result".to_owned())?;
    if aggregate.aggregate_id != chart.chart_id
        || aggregate.version != chart.source_version
        || aggregate.version == 0
    {
        return Err("Finance chart receipt did not match its result".into());
    }
    let event_id = receipt
        .committed_events
        .first()
        .map(|event| event.event_id.clone())
        .ok_or_else(|| "Finance chart command omitted committed event evidence".to_owned())?;
    Ok(FinanceChartCommandReceipt {
        chart_id: finance_command_uuid(&chart.chart_id, "Finance chart receipt ID")?,
        version: aggregate.version,
        event_id: finance_command_uuid(&event_id, "Finance chart event ID")?,
        replayed: receipt.replayed,
        correlation_id: bounded_finance_value(
            &receipt.correlation_id,
            "Finance chart correlation ID",
            false,
            128,
        )?,
    })
}

struct FinanceTargetJournalPlan {
    create: finance_target::CreateTypedFinanceJournalRequest,
    chart_id: String,
    period_id: String,
    company_id: String,
}

fn finance_target_journal_plan(
    scope: &FinanceScope,
    input: &FinanceJournalTypedInput,
    principal_ref: &str,
    session_id: &str,
) -> Result<FinanceTargetJournalPlan, String> {
    let chart_id = finance_command_uuid(&input.chart_id, "journal chart ID")?;
    let period_id = finance_command_uuid(&input.period.period_id, "journal period ID")?;
    let company_id = finance_command_uuid(&input.period.company_id, "journal company ID")?;
    let debit_account_id = finance_command_uuid(&input.debit_account_id, "debit account ID")?;
    let credit_account_id = finance_command_uuid(&input.credit_account_id, "credit account ID")?;
    if debit_account_id == credit_account_id {
        return Err("debit and credit account IDs must be different".into());
    }
    let amount_minor = input
        .amount_minor
        .trim()
        .parse::<i64>()
        .map_err(|_| "journal amount must be a positive integer in minor units".to_owned())?;
    if amount_minor <= 0 {
        return Err("journal amount must be a positive integer in minor units".into());
    }
    let currency =
        finance_command_text(&input.currency, "journal currency", 3)?.to_ascii_uppercase();
    Ok(FinanceTargetJournalPlan {
        create: finance_target::CreateTypedFinanceJournalRequest {
            metadata: Some(finance_target_command_metadata(
                scope,
                principal_ref,
                session_id,
                "finance_journal_create",
                None,
            )?),
            journal_id: finance_command_uuid(&input.journal_id, "journal ID")?,
            target_scope: Some(TenantScope {
                scope: Some(tenant_scope::Scope::Company(CompanyScope {
                    holding_id: scope.holding_id.clone(),
                    company_id: company_id.clone(),
                })),
            }),
            chart_id: chart_id.clone(),
            period_id: period_id.clone(),
            journal_code: finance_command_text(&input.journal_code, "journal code", 64)?,
            entry_date: finance_command_date(&input.entry_date, "journal entry date")?,
            currency: currency.clone(),
            source: Some(finance_target::FinanceJournalSource {
                source: Some(finance_target::finance_journal_source::Source::Manual(
                    finance_target::FinanceManualJournalSource {
                        reference: finance_command_text(
                            &input.source_reference,
                            "journal source reference",
                            128,
                        )?,
                    },
                )),
            }),
            description: finance_command_text(&input.description, "journal description", 1_024)?,
            lines: vec![
                finance_target::FinanceJournalLineRecord {
                    line_id: Uuid::new_v4().to_string(),
                    account_id: debit_account_id,
                    debit_minor: amount_minor,
                    credit_minor: 0,
                    currency: currency.clone(),
                    memo: String::new(),
                },
                finance_target::FinanceJournalLineRecord {
                    line_id: Uuid::new_v4().to_string(),
                    account_id: credit_account_id,
                    debit_minor: 0,
                    credit_minor: amount_minor,
                    currency,
                    memo: String::new(),
                },
            ],
        },
        chart_id,
        period_id,
        company_id,
    })
}

fn finance_target_journal_receipt(
    response: finance_target::FinanceJournalMutationResponse,
) -> Result<FinanceJournalCommandReceipt, String> {
    let receipt = response
        .receipt
        .ok_or_else(|| "Finance journal command omitted its receipt".to_owned())?;
    let journal = response
        .journal
        .ok_or_else(|| "Finance journal command omitted its result".to_owned())?;
    let aggregate = receipt
        .aggregate
        .ok_or_else(|| "Finance journal command omitted aggregate metadata".to_owned())?;
    if aggregate.aggregate_id != journal.journal_id
        || aggregate.version != journal.source_version
        || aggregate.version == 0
    {
        return Err("Finance journal receipt did not match its result".into());
    }
    let company_id = match journal.scope.and_then(|scope| scope.scope) {
        Some(tenant_scope::Scope::Company(scope)) => scope.company_id,
        Some(tenant_scope::Scope::Branch(scope)) => scope.company_id,
        _ => return Err("Finance journal result was not company-bound".into()),
    };
    Ok(FinanceJournalCommandReceipt {
        journal_id: finance_command_uuid(&journal.journal_id, "Finance journal receipt ID")?,
        company_id: finance_command_uuid(&company_id, "Finance journal company ID")?,
        period_id: finance_command_uuid(&journal.period_id, "Finance journal period ID")?,
        posted_at: journal
            .posted_at
            .filter(|value| !value.is_empty())
            .ok_or_else(|| "Finance journal was not posted".to_owned())?,
        replayed: receipt.replayed,
        correlation_id: bounded_finance_value(
            &receipt.correlation_id,
            "Finance journal correlation ID",
            false,
            128,
        )?,
    })
}

fn finance_target_record_company_matches(
    scope: Option<TenantScope>,
    holding_id: &str,
    company_id: &str,
) -> bool {
    matches!(
        scope.and_then(|scope| scope.scope),
        Some(tenant_scope::Scope::Company(scope))
            if scope.holding_id == holding_id && scope.company_id == company_id
    )
}

macro_rules! define_finance_journal_reference_lookup {
    ($cfg:meta, $client:ty) => {
        #[$cfg]
        async fn finance_target_journal_reference_versions(
            client: &mut finance_target::finance_query_service_client::FinanceQueryServiceClient<
                $client,
            >,
            scope: &FinanceScope,
            plan: &FinanceTargetJournalPlan,
            access_token: &str,
            principal_ref: &str,
            session_id: &str,
        ) -> Result<(u64, u64), String> {
            let metadata = finance_target_company_query_metadata(
                scope,
                &plan.company_id,
                principal_ref,
                session_id,
                "finance_journal_reference_read",
            )?;
            let mut chart_request =
                tonic::Request::new(finance_target::GetFinanceChartRecordRequest {
                    metadata: Some(metadata.clone()),
                    chart_id: plan.chart_id.clone(),
                });
            add_platform_metadata(&mut chart_request, access_token, principal_ref, session_id)?;
            let chart = client
                .get_chart(chart_request)
                .await
                .map_err(finance_rpc_error)?
                .into_inner()
                .chart
                .ok_or_else(|| {
                    "additional authorized Finance chart input is required".to_owned()
                })?;
            let mut period_request =
                tonic::Request::new(finance_target::GetFinancePeriodRecordRequest {
                    metadata: Some(metadata),
                    period_id: plan.period_id.clone(),
                });
            add_platform_metadata(&mut period_request, access_token, principal_ref, session_id)?;
            let period = client
                .get_period(period_request)
                .await
                .map_err(finance_rpc_error)?
                .into_inner()
                .period
                .ok_or_else(|| {
                    "additional authorized Finance period input is required".to_owned()
                })?;
            if chart.chart_id != plan.chart_id
                || period.period_id != plan.period_id
                || chart.source_version == 0
                || period.source_version == 0
                || !finance_target_record_company_matches(
                    chart.scope,
                    &scope.holding_id,
                    &plan.company_id,
                )
                || !finance_target_record_company_matches(
                    period.scope,
                    &scope.holding_id,
                    &plan.company_id,
                )
            {
                return Err("Finance journal reference facts escaped the requested scope".into());
            }
            Ok((chart.source_version, period.source_version))
        }
    };
}

define_finance_journal_reference_lookup!(
    cfg(target_arch = "wasm32"),
    tonic_web_wasm_client::Client
);
define_finance_journal_reference_lookup!(
    cfg(not(target_arch = "wasm32")),
    tonic::transport::Channel
);

fn finance_expected_version(value: &str, field: &str) -> Result<Option<u64>, String> {
    if value.trim().is_empty() {
        return Ok(None);
    }
    let version = value
        .trim()
        .parse::<u64>()
        .map_err(|_| format!("{field} must be a positive integer"))?;
    if version == 0 {
        return Err(format!("{field} must be a positive integer"));
    }
    Ok(Some(version))
}

