#[cfg(target_arch = "wasm32")]
async fn post_finance_journal(
    scope: FinanceScope,
    input: FinanceJournalTypedInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<FinanceJournalCommandReceipt, String> {
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    let mut commands =
        finance_target::finance_command_service_client::FinanceCommandServiceClient::new(
            channel.clone(),
        );
    let mut queries =
        finance_target::finance_query_service_client::FinanceQueryServiceClient::new(channel);
    let plan = finance_target_journal_plan(&scope, &input, &principal_ref, &session_id)?;
    let (chart_version, period_version) = finance_target_journal_reference_versions(
        &mut queries,
        &scope,
        &plan,
        &access_token,
        &principal_ref,
        &session_id,
    )
    .await?;
    let mut create = tonic::Request::new(plan.create);
    add_platform_metadata(&mut create, &access_token, &principal_ref, &session_id)?;
    let created = commands
        .create_journal(create)
        .await
        .map_err(finance_command_rpc_error)?
        .into_inner();
    let journal = created
        .journal
        .ok_or_else(|| "Finance journal create omitted its result".to_owned())?;
    let mut post = tonic::Request::new(finance_target::PostTypedFinanceJournalRequest {
        metadata: Some(finance_target_command_metadata(
            &scope,
            &principal_ref,
            &session_id,
            "finance_journal_post",
            Some(journal.source_version),
        )?),
        journal_id: journal.journal_id,
        expected_chart_version: chart_version,
        expected_period_version: period_version,
    });
    add_platform_metadata(&mut post, &access_token, &principal_ref, &session_id)?;
    finance_target_journal_receipt(
        commands
            .post_journal(post)
            .await
            .map_err(finance_command_rpc_error)?
            .into_inner(),
    )
}

