fn hr_read_error_state(category: &str) -> UiStateKind {
    match category {
        "authentication_required" | "authorization_denied" | "hr_scope_unavailable" => {
            UiStateKind::Denied
        }
        "offline" => UiStateKind::Offline,
        _ => UiStateKind::Error,
    }
}

fn hr_read_error_title(category: &str) -> &'static str {
    match category {
        "authentication_required" => "HR sign-in required",
        "authorization_denied" => "HR access denied",
        "hr_scope_unavailable" => "HR scope unavailable",
        "hr_route_unavailable" => "HR tenant route unavailable",
        "offline" => "HR service unavailable",
        _ => "HR employee read failed",
    }
}

fn hr_read_error_message(category: &str) -> &'static str {
    match category {
        "authentication_required" => localized_copy(
            "Sign in with an authenticated session before requesting an HR scope.",
            "เข้าสู่ระบบด้วยช่วงเวลานักศึกษาที่ได้รับการยืนยันก่อนขอขอบเขต HR.",
        ),
        "authorization_denied" => localized_copy(
            "The server denied the HR employee read for this principal and scope.",
            "เซิร์ฟเวอร์ปฏิเสธการอ่านพนักงาน HR สำหรับผู้ใหญ่และขอบเขตนี้",
        ),
        "hr_scope_unavailable" => {
            "The server rejected the HR tenant, holding, company, or branch scope; no employee rows are displayed."
        }
        "hr_route_unavailable" => "The tenant is not available on an active HR read route.",
        "offline" => "The HR service is unavailable; no cached employee rows are shown.",
        _ => "The authorized HR employee read returned a safe categorical error.",
    }
}

fn legal_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "legal_scope_unavailable".into()
        }
        tonic::Code::NotFound => "legal_route_unavailable".into(),
        _ => "legal_read_failed".into(),
    }
}

fn legal_read_error_state(category: &str) -> UiStateKind {
    match category {
        "authentication_required" | "authorization_denied" | "legal_scope_unavailable" => {
            UiStateKind::Denied
        }
        "offline" => UiStateKind::Offline,
        _ => UiStateKind::Error,
    }
}

fn legal_read_error_title(category: &str) -> &'static str {
    match category {
        "authentication_required" => "Legal sign-in required",
        "authorization_denied" => "Legal access denied",
        "legal_scope_unavailable" => "Legal scope unavailable",
        "legal_route_unavailable" => "Legal tenant route unavailable",
        "offline" => "Legal service unavailable",
        _ => "Legal contract read failed",
    }
}

fn legal_read_error_message(category: &str) -> &'static str {
    match category {
        "authentication_required" => localized_copy(
            "Sign in with an authenticated session before requesting a Legal scope.",
            "เข้าสู่ระบบด้วยช่วงเวลานักศึกษาที่ได้รับการยืนยันก่อนขอขอบเขตกฎหมาย.",
        ),
        "authorization_denied" => localized_copy(
            "The server denied the Legal contract read for this principal and scope.",
            "เซิร์ฟเวอร์ปฏิเสธการอ่านสัญญาทางกฎหมายสำหรับผู้ใหญ่และขอบเขตนี้",
        ),
        "legal_scope_unavailable" => {
            "The server rejected the Legal tenant, holding, company, or branch scope; no contract metadata is displayed."
        }
        "legal_route_unavailable" => "The tenant is not available on an active Legal read route.",
        "offline" => "The Legal service is unavailable; no cached contract metadata is shown.",
        _ => "The authorized Legal contract read returned a safe categorical error.",
    }
}

