fn legal_command_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "legal_command_rejected".into()
        }
        tonic::Code::NotFound => "legal_route_unavailable".into(),
        _ => "legal_command_failed".into(),
    }
}

fn product_aggregate_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "product_scope_unavailable".into()
        }
        tonic::Code::NotFound => "product_route_unavailable".into(),
        _ => "product_read_failed".into(),
    }
}

