async fn transition_hr_employee_cqrs(
    binding: HrEmployeeTransitionBinding,
) -> Result<HrEmployeeTransitionResult, String> {
    use erpx_ui_foundation::CommandGateway;

    let HrEmployeeTransitionBinding {
        scope,
        employee_id,
        transition,
        terminated_on,
        expected_version,
        access_token,
        principal_ref,
        session_id,
    } = binding;

    if expected_version == 0 {
        return Err("Enter a positive employee version.".to_owned());
    }
    let employee_id: erpx_people_payroll::EmployeeId = hr_cqrs_id(&employee_id, "employee")?;
    let transition = match transition.trim() {
        "active" | "activate" => erpx_people_payroll::EmployeeTransition::Activate,
        "on_leave" | "put_on_leave" => erpx_people_payroll::EmployeeTransition::PutOnLeave,
        "return_from_leave" => erpx_people_payroll::EmployeeTransition::ReturnFromLeave,
        "suspended" | "suspend" => erpx_people_payroll::EmployeeTransition::Suspend,
        "terminated" | "terminate" => erpx_people_payroll::EmployeeTransition::Terminate {
            terminated_on: hr_cqrs_date(&terminated_on, "Termination date")?,
        },
        _ => {
            return Err(
                "Choose activate, put_on_leave, return_from_leave, suspend, or terminate."
                    .to_owned(),
            );
        }
    };
    let action_key = match &transition {
        erpx_people_payroll::EmployeeTransition::Activate => "activate",
        erpx_people_payroll::EmployeeTransition::PutOnLeave => "put_on_leave",
        erpx_people_payroll::EmployeeTransition::ReturnFromLeave => "return_from_leave",
        erpx_people_payroll::EmployeeTransition::Suspend => "suspend",
        erpx_people_payroll::EmployeeTransition::Terminate { .. } => "terminate",
    };
    let envelope = hr_cqrs_command(
        &scope,
        &principal_ref,
        &session_id,
        format!(
            "people-payroll:employee:{}:{}:{}",
            employee_id.as_uuid(),
            expected_version,
            action_key
        ),
        Some(expected_version),
        erpx_people_payroll::PeoplePayrollCommand::TransitionEmployee(
            erpx_people_payroll::TransitionEmployee {
                employee_id,
                transition,
            },
        ),
    )?;
    let gateway = crate::features::people_payroll::PeoplePayrollGateway::new(
        hr_cqrs_transport(&scope, &access_token).await?,
    );
    let receipt = gateway
        .execute(envelope)
        .await
        .map_err(|error| error.message().to_owned())?;
    Ok(HrEmployeeTransitionResult {
        employee_id: receipt.aggregate.aggregate_id.to_string(),
        version: receipt.aggregate.version,
        replayed: receipt.replayed,
        correlation_id: receipt.correlation_id.to_string(),
    })
}

