fn legal_target_command_metadata(
    scope: &LegalContractScope,
    principal_ref: &str,
    session_id: &str,
    purpose: &str,
    idempotency_key: &str,
    expected_version: Option<u64>,
) -> Result<CommandRequestMetadata, String> {
    let session_id = Uuid::parse_str(session_id)
        .map_err(|_| "the authenticated Legal session must be a UUID".to_string())?;
    let correlation_id = Uuid::new_v4().to_string();
    Ok(CommandRequestMetadata {
        contract_version: u32::from(CONTRACT_VERSION),
        command_id: Uuid::new_v4().to_string(),
        idempotency_key: idempotency_key.to_owned(),
        correlation_id: correlation_id.clone(),
        causation_id: None,
        actor: Some(ActorAttribution {
            principal_ref: principal_ref.to_owned(),
            kind: ActorKind::PlatformUser as i32,
            session_id: session_id.to_string(),
            represented_principal_ref: String::new(),
            support_capability_id: String::new(),
        }),
        tenant_scope: Some(scope.tenant_scope()),
        audit: Some(AuditContext {
            purpose: purpose.to_owned(),
            customer_visible: false,
            module: "legal".into(),
            correlation_id,
        }),
        expected_aggregate_version: expected_version,
        subscription_id: None,
        mfa_code: None,
        tenant_route: Some(scope.tenant_route()),
    })
}

fn legal_content_hash(value: &str) -> Result<String, String> {
    let value = value.trim();
    if value.len() != 64 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err("Enter a 64-character SHA-256 content hash.".into());
    }
    Ok(value.to_ascii_lowercase())
}

fn legal_retention_until(value: &str) -> Result<chrono::DateTime<Utc>, String> {
    let value = value.trim();
    if let Ok(timestamp) = chrono::DateTime::parse_from_rfc3339(value) {
        return Ok(timestamp.with_timezone(&Utc));
    }
    chrono::NaiveDate::parse_from_str(value, "%Y-%m-%d")
        .ok()
        .and_then(|date| date.and_hms_opt(23, 59, 59))
        .map(|timestamp| timestamp.and_utc())
        .ok_or_else(|| "Choose a valid retention date.".to_string())
}

fn legal_uuid_or_new(value: &str, field: &str) -> Result<String, String> {
    if value.trim().is_empty() {
        Ok(Uuid::new_v4().to_string())
    } else {
        finance_command_uuid(value, field)
    }
}

fn legal_typed_receipt(
    receipt: Option<ProtoCommandReceipt>,
    idempotency_key: &str,
) -> Result<LegalCommandReceipt, String> {
    let receipt = receipt.ok_or_else(|| "Legal command omitted its receipt".to_string())?;
    let correlation_id = bounded_finance_value(
        &receipt.correlation_id,
        "Legal command correlation ID",
        false,
        128,
    )?;
    let aggregate = receipt
        .aggregate
        .ok_or_else(|| "Legal command omitted its aggregate version".to_string())?;
    let aggregate_type =
        finance_command_text(&aggregate.aggregate_type, "Legal aggregate type", 64)?;
    let aggregate_id = finance_command_uuid(&aggregate.aggregate_id, "Legal aggregate ID")?;
    if aggregate.version == 0 {
        return Err("Legal receipt version must be positive".into());
    }
    let event = receipt
        .committed_events
        .last()
        .ok_or_else(|| "Legal command omitted its committed event".to_string())?;
    let event_id = finance_command_uuid(&event.event_id, "Legal event ID")?;
    Ok(LegalCommandReceipt {
        aggregate_type,
        aggregate_id,
        version: aggregate.version,
        idempotency_key: finance_command_text(idempotency_key, "Legal idempotency key", 256)?,
        event_id,
        replayed: receipt.replayed,
        correlation_id,
    })
}

