async fn save_legal_contract(
    scope: LegalContractScope,
    input: LegalContractTypedInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<LegalCommandReceipt, String> {
    let contract_id = legal_uuid_or_new(&input.contract_id, "Legal contract ID")?;
    let reference = finance_command_text(&input.reference, "Legal contract reference", 128)?;
    let title = finance_command_text(&input.title, "Legal contract title", 255)?;
    let object_ref = finance_command_text(&input.object_ref, "Legal contract object", 1024)?;
    let content_sha256 = legal_content_hash(&input.content_sha256)?;
    let retention_until = legal_retention_until(&input.retention_until)?.to_rfc3339();
    let party_id = input.party_id.trim();
    let party_role = input.party_role.trim();
    if party_id.is_empty() != party_role.is_empty() {
        return Err("Enter both a party UUID and role, or leave both blank.".into());
    }
    let party = if party_id.is_empty() {
        None
    } else {
        Some(legal_target::LegalContractPartyRecord {
            party_id: finance_command_uuid(party_id, "Legal party ID")?,
            role: finance_command_text(party_role, "Legal party role", 128)?,
        })
    };
    let create_key = format!("console-legal-contract-{contract_id}");
    let channel = legal_grpc_channel().await?;
    let mut client =
        legal_target::legal_command_service_client::LegalCommandServiceClient::new(channel);
    let mut request = tonic::Request::new(legal_target::CreateLegalContractRequest {
        metadata: Some(legal_target_command_metadata(
            &scope,
            &principal_ref,
            &session_id,
            "legal_contract_create",
            &create_key,
            None,
        )?),
        contract_id: contract_id.clone(),
        target_scope: Some(scope.tenant_scope()),
        reference,
        title,
        object_ref,
        content_sha256,
        retention_until,
    });
    add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
    let created = client
        .create_contract(request)
        .await
        .map_err(legal_command_rpc_error)?
        .into_inner();
    let created_record = created
        .contract
        .as_ref()
        .ok_or_else(|| "Legal create command omitted its contract".to_string())?;
    if created_record.contract_id != contract_id || created_record.source_version == 0 {
        return Err("Legal create command returned mismatched contract evidence".into());
    }
    let mut receipt = legal_typed_receipt(created.receipt, &create_key)?;
    if let Some(party) = party {
        let party_key = format!(
            "console-legal-contract-party-{contract_id}-{}",
            party.party_id
        );
        let mut request = tonic::Request::new(legal_target::AddLegalContractPartyRequest {
            metadata: Some(legal_target_command_metadata(
                &scope,
                &principal_ref,
                &session_id,
                "legal_contract_party_add",
                &party_key,
                Some(created_record.source_version),
            )?),
            contract_id,
            party: Some(party),
        });
        add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
        let updated = client
            .add_contract_party(request)
            .await
            .map_err(legal_command_rpc_error)?
            .into_inner();
        receipt = legal_typed_receipt(updated.receipt, &party_key)?;
    }
    Ok(receipt)
}

async fn save_legal_document(
    scope: LegalContractScope,
    input: LegalDocumentTypedInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<LegalCommandReceipt, String> {
    let document_id = legal_uuid_or_new(&input.document_id, "Legal document ID")?;
    let title = finance_command_text(&input.title, "Legal document title", 255)?;
    let object_ref = finance_command_text(&input.object_ref, "Legal document object", 1024)?;
    let content_sha256 = legal_content_hash(&input.content_sha256)?;
    let create_key = format!("console-legal-document-{document_id}");
    let channel = legal_grpc_channel().await?;
    let mut client =
        legal_target::legal_command_service_client::LegalCommandServiceClient::new(channel);
    let mut request = tonic::Request::new(legal_target::CreateLegalDocumentRequest {
        metadata: Some(legal_target_command_metadata(
            &scope,
            &principal_ref,
            &session_id,
            "legal_document_create",
            &create_key,
            None,
        )?),
        document_id: document_id.clone(),
        target_scope: Some(scope.tenant_scope()),
        title,
    });
    add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
    let created = client
        .create_document(request)
        .await
        .map_err(legal_command_rpc_error)?
        .into_inner();
    let created_record = created
        .document
        .as_ref()
        .ok_or_else(|| "Legal create command omitted its document".to_string())?;
    if created_record.document_id != document_id || created_record.source_version == 0 {
        return Err("Legal create command returned mismatched document evidence".into());
    }
    let version_key = format!("console-legal-document-version-{document_id}-1");
    let mut request = tonic::Request::new(legal_target::AddLegalDocumentVersionRequest {
        metadata: Some(legal_target_command_metadata(
            &scope,
            &principal_ref,
            &session_id,
            "legal_document_version_add",
            &version_key,
            Some(created_record.source_version),
        )?),
        document_id,
        object_ref,
        content_sha256,
    });
    add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
    let updated = client
        .add_document_version(request)
        .await
        .map_err(legal_command_rpc_error)?
        .into_inner();
    legal_typed_receipt(updated.receipt, &version_key)
}

async fn record_legal_access(
    scope: LegalContractScope,
    input: LegalAccessTypedInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<LegalCommandReceipt, String> {
    let document_id = finance_command_uuid(&input.document_id, "Legal document ID")?;
    let document_version = input
        .version
        .trim()
        .parse::<u64>()
        .map_err(|_| "Enter a positive Legal document version.".to_string())?;
    if document_version == 0 {
        return Err("Enter a positive Legal document version.".into());
    }
    let access_entry_id = Uuid::new_v4().to_string();
    let idempotency_key = format!("console-legal-access-{access_entry_id}");
    let channel = legal_grpc_channel().await?;
    let mut client =
        legal_target::legal_command_service_client::LegalCommandServiceClient::new(channel);
    let mut request = tonic::Request::new(legal_target::RecordLegalDocumentAccessRequest {
        metadata: Some(legal_target_command_metadata(
            &scope,
            &principal_ref,
            &session_id,
            "legal_access_record",
            &idempotency_key,
            None,
        )?),
        access_entry_id,
        document_id,
        document_version,
        action: finance_command_text(&input.action, "Legal access action", 128)?,
        purpose: finance_command_text(&input.purpose, "Legal access purpose", 1024)?,
        observed_at: Utc::now().to_rfc3339(),
    });
    add_platform_metadata(&mut request, &access_token, &principal_ref, &session_id)?;
    let response = client
        .record_document_access(request)
        .await
        .map_err(legal_command_rpc_error)?
        .into_inner();
    legal_typed_receipt(response.receipt, &idempotency_key)
}

