fn pos_typed_scope(scope: &PosSaleScope) -> Result<erpx_kernel::TenantScope, String> {
    let holding_id = Uuid::parse_str(&scope.finance.holding_id)
        .map_err(|_| "The POS holding identifier is invalid.".to_owned())?;
    let company_id = Uuid::parse_str(&scope.company_id)
        .map_err(|_| "The POS company identifier is invalid.".to_owned())?;
    if scope.branch_id.is_empty() {
        Ok(erpx_kernel::TenantScope::Company {
            holding_id,
            company_id,
        })
    } else {
        Ok(erpx_kernel::TenantScope::Branch {
            holding_id,
            company_id,
            branch_id: Uuid::parse_str(&scope.branch_id)
                .map_err(|_| "The POS branch identifier is invalid.".to_owned())?,
        })
    }
}

fn pos_typed_actor(
    principal_ref: &str,
    session_id: &str,
) -> Result<erpx_kernel::ActorAttribution, String> {
    let session_id = Uuid::parse_str(session_id)
        .map_err(|_| "The authenticated POS session identifier is invalid.".to_owned())?;
    Ok(erpx_kernel::ActorAttribution {
        principal_ref: principal_ref.to_owned(),
        kind: erpx_kernel::ActorKind::TenantUser,
        session_id: Some(
            erpx_kernel::SessionId::try_from_uuid(session_id)
                .map_err(|_| "The authenticated POS session identifier is invalid.".to_owned())?,
        ),
        represented_principal_ref: None,
        support_capability_id: None,
    })
}

fn pos_typed_command<C>(
    scope: &PosSaleScope,
    principal_ref: &str,
    session_id: &str,
    idempotency_key: String,
    expected_aggregate_version: Option<u64>,
    command: C,
) -> Result<erpx_cqrs::CommandEnvelope<C>, String> {
    Ok(erpx_cqrs::CommandEnvelope {
        contract_version: erpx_cqrs::CONTRACT_VERSION,
        command_id: erpx_kernel::CommandId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a POS command identifier.".to_owned())?,
        idempotency_key: erpx_cqrs::IdempotencyKey::try_new(idempotency_key)
            .map_err(|_| "Unable to create the POS idempotency key.".to_owned())?,
        correlation_id: erpx_kernel::CorrelationId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a POS correlation identifier.".to_owned())?,
        causation_id: None,
        actor: pos_typed_actor(principal_ref, session_id)?,
        tenant_scope: pos_typed_scope(scope)?,
        audit: erpx_kernel::AuditContext {
            purpose: "pos_console_lifecycle".to_owned(),
            customer_visible: true,
            module: Some("pos".to_owned()),
        },
        expected_aggregate_version,
        command,
    })
}

fn pos_typed_query<Q>(
    scope: &PosSaleScope,
    principal_ref: &str,
    session_id: &str,
    query: Q,
) -> Result<erpx_cqrs::QueryEnvelope<Q>, String> {
    Ok(erpx_cqrs::QueryEnvelope {
        contract_version: erpx_cqrs::CONTRACT_VERSION,
        query_id: erpx_kernel::QueryId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a POS query identifier.".to_owned())?,
        correlation_id: erpx_kernel::CorrelationId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a POS correlation identifier.".to_owned())?,
        actor: pos_typed_actor(principal_ref, session_id)?,
        tenant_scope: pos_typed_scope(scope)?,
        audit: erpx_kernel::AuditContext {
            purpose: "pos_console_projection_read".to_owned(),
            customer_visible: false,
            module: Some("pos".to_owned()),
        },
        consistency: erpx_cqrs::QueryConsistency::Eventual,
        query,
    })
}

async fn pos_typed_transport(
    scope: &PosSaleScope,
    access_token: &str,
) -> Result<crate::transport::wave6_7::PosGrpcTransport, String> {
    #[cfg(target_arch = "wasm32")]
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    #[cfg(not(target_arch = "wasm32"))]
    let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
        .connect()
        .await
        .map_err(|_| "offline".to_owned())?;
    let route = crate::transport::wave6_7::Wave67Route::try_new(
        &scope.finance.tenant_id,
        scope.finance.holding_ref.clone(),
    )
    .map_err(|error| error.message().to_owned())?;
    crate::transport::wave6_7::PosGrpcTransport::try_new(channel, access_token, route)
        .map_err(|error| error.message().to_owned())
}

fn pos_uuid<T>(value: &str, field: &str) -> Result<T, String>
where
    T: TryFrom<Uuid>,
{
    let value =
        Uuid::parse_str(value.trim()).map_err(|_| format!("Enter a valid {field} UUID."))?;
    T::try_from(value).map_err(|_| format!("Enter a non-nil {field} UUID."))
}

fn pos_expected_version(value: &str, field: &str) -> Result<u64, String> {
    let version = value
        .trim()
        .parse::<u64>()
        .map_err(|_| format!("Enter a positive {field} version."))?;
    (version > 0)
        .then_some(version)
        .ok_or_else(|| format!("Enter a positive {field} version."))
}

fn pos_payment_method(value: &str) -> Result<erpx_pos::PaymentMethod, String> {
    match value {
        "cash" => Ok(erpx_pos::PaymentMethod::Cash),
        "card" => Ok(erpx_pos::PaymentMethod::Card),
        "bank_transfer" => Ok(erpx_pos::PaymentMethod::BankTransfer),
        "mobile_wallet" => Ok(erpx_pos::PaymentMethod::MobileWallet),
        "voucher" => Ok(erpx_pos::PaymentMethod::Voucher),
        "other" => Ok(erpx_pos::PaymentMethod::Other),
        _ => Err("Choose a supported POS payment method.".to_owned()),
    }
}

fn pos_typed_receipt<R>(receipt: erpx_cqrs::CommandReceipt<R>) -> PosSaleCommandReceipt {
    PosSaleCommandReceipt {
        aggregate_type: receipt.aggregate.aggregate_type,
        aggregate_id: receipt.aggregate.aggregate_id.to_string(),
        version: receipt.aggregate.version,
        idempotency_key: receipt.command_id.to_string(),
        replayed: receipt.replayed,
        correlation_id: receipt.correlation_id.to_string(),
    }
}

async fn create_pos_sale_typed(
    scope: PosSaleScope,
    input: PosSaleCommandInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<PosSaleCommandReceipt, String> {
    use erpx_ui_foundation::CommandGateway;

    let sale_id: erpx_pos::SaleId = pos_uuid(&input.sale_id, "sale")?;
    let register_id: erpx_pos::RegisterId = pos_uuid(&input.register_id, "register")?;
    let line_id: erpx_pos::SaleLineId = pos_uuid(&input.line_id, "sale line")?;
    let customer_id = (!input.customer_id.trim().is_empty())
        .then(|| pos_uuid::<erpx_pos::CustomerId>(&input.customer_id, "customer"))
        .transpose()?;
    let quantity = input
        .quantity
        .trim()
        .parse::<u64>()
        .map_err(|_| "POS quantity must be a positive integer.".to_owned())?;
    let unit_price_minor = input
        .unit_price_minor
        .trim()
        .parse::<i64>()
        .map_err(|_| "POS unit price must be an integer minor-unit amount.".to_owned())?;
    let tax_minor = input
        .tax_minor
        .trim()
        .parse::<i64>()
        .map_err(|_| "POS tax must be an integer minor-unit amount.".to_owned())?;
    let line = erpx_pos::SaleLine {
        line_id,
        item_reference: input.item_reference.trim().to_owned(),
        description: input.description.trim().to_owned(),
        quantity,
        unit_price_minor,
        tax_minor,
    };
    line.validate()
        .map_err(|error| format!("POS sale line is invalid: {error}"))?;
    let currency = input.currency.trim().to_ascii_uppercase();
    let command = erpx_pos::PosSaleCommand::Create(erpx_pos::CreateSale {
        sale_id,
        scope: pos_typed_scope(&scope)?,
        receipt_code: input.receipt_code.trim().to_owned(),
        register_id,
        customer_id,
        currency,
        lines: vec![line],
    });
    let envelope = pos_typed_command(
        &scope,
        &principal_ref,
        &session_id,
        format!("pos:create:{}", sale_id.as_uuid()),
        None,
        command,
    )?;
    let gateway =
        crate::features::pos::PosGateway::new(pos_typed_transport(&scope, &access_token).await?);
    gateway
        .execute(envelope)
        .await
        .map(pos_typed_receipt)
        .map_err(|error| error.message().to_owned())
}

async fn transition_pos_sale_typed(
    scope: PosSaleScope,
    input: PosSaleLifecycleInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<PosSaleCommandReceipt, String> {
    use erpx_ui_foundation::CommandGateway;

    let sale_id: erpx_pos::SaleId = pos_uuid(&input.sale_id, "sale")?;
    let version = pos_expected_version(&input.expected_version, "sale")?;
    let command = match input.action.as_str() {
        "open" => erpx_pos::PosSaleCommand::Open(erpx_pos::OpenSale { sale_id }),
        "hold" => erpx_pos::PosSaleCommand::Hold(erpx_pos::HoldSale { sale_id }),
        "resume" => erpx_pos::PosSaleCommand::Resume(erpx_pos::ResumeSale { sale_id }),
        "record_payment" => {
            let payment_id: erpx_pos::PaymentId = pos_uuid(&input.payment_id, "payment")?;
            let amount_minor = input
                .payment_amount_minor
                .trim()
                .parse::<i64>()
                .map_err(|_| "Enter a positive payment amount in minor units.".to_owned())?;
            let payment = erpx_pos::Payment {
                payment_id,
                amount_minor,
                method: pos_payment_method(&input.payment_method)?,
                received_at: Utc::now(),
            };
            payment
                .validate()
                .map_err(|error| format!("POS payment is invalid: {error}"))?;
            erpx_pos::PosSaleCommand::RecordPayment(erpx_pos::RecordPayment { sale_id, payment })
        }
        "complete" => erpx_pos::PosSaleCommand::Complete(erpx_pos::CompleteSale { sale_id }),
        "void" => erpx_pos::PosSaleCommand::Void(erpx_pos::VoidSale { sale_id }),
        _ => return Err("Choose a supported POS sale action.".to_owned()),
    };
    let key_suffix = if input.action == "record_payment" {
        input.payment_id.trim()
    } else {
        "transition"
    };
    let envelope = pos_typed_command(
        &scope,
        &principal_ref,
        &session_id,
        format!(
            "pos:{}:{}:{}:{}",
            input.action,
            sale_id.as_uuid(),
            version,
            key_suffix
        ),
        Some(version),
        command,
    )?;
    let gateway =
        crate::features::pos::PosGateway::new(pos_typed_transport(&scope, &access_token).await?);
    gateway
        .execute(envelope)
        .await
        .map(pos_typed_receipt)
        .map_err(|error| error.message().to_owned())
}

async fn transition_pos_refund_typed(
    scope: PosSaleScope,
    input: PosRefundLifecycleInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<PosSaleCommandReceipt, String> {
    use erpx_ui_foundation::CommandGateway;

    let refund_id: erpx_pos::RefundId = pos_uuid(&input.refund_id, "refund")?;
    let (command, expected_version) = match input.action.as_str() {
        "request" => {
            let sale_id: erpx_pos::SaleId = pos_uuid(&input.sale_id, "sale")?;
            let sale_line_id: erpx_pos::SaleLineId = pos_uuid(&input.sale_line_id, "sale line")?;
            let quantity = input
                .quantity
                .trim()
                .parse::<u64>()
                .map_err(|_| "Enter a positive refund quantity.".to_owned())?;
            let amount_minor = input
                .amount_minor
                .trim()
                .parse::<i64>()
                .map_err(|_| "Enter a positive refund amount in minor units.".to_owned())?;
            (
                erpx_pos::PosRefundCommand::Request(erpx_pos::RequestRefund {
                    refund_id,
                    sale_id,
                    lines: vec![erpx_pos::RefundLine {
                        sale_line_id,
                        quantity,
                        amount_minor,
                    }],
                    reason: input.reason.trim().to_owned(),
                }),
                None,
            )
        }
        action => {
            let version = pos_expected_version(&input.expected_version, "refund")?;
            let command = match action {
                "approve" => {
                    erpx_pos::PosRefundCommand::Approve(erpx_pos::ApproveRefund { refund_id })
                }
                "reject" => {
                    erpx_pos::PosRefundCommand::Reject(erpx_pos::RejectRefund { refund_id })
                }
                "post" => erpx_pos::PosRefundCommand::Post(erpx_pos::PostRefund { refund_id }),
                "cancel" => {
                    erpx_pos::PosRefundCommand::Cancel(erpx_pos::CancelRefund { refund_id })
                }
                _ => return Err("Choose a supported POS refund action.".to_owned()),
            };
            (command, Some(version))
        }
    };
    let envelope = pos_typed_command(
        &scope,
        &principal_ref,
        &session_id,
        format!(
            "pos:refund:{}:{}:{}",
            input.action,
            refund_id.as_uuid(),
            expected_version.unwrap_or_default()
        ),
        expected_version,
        command,
    )?;
    let gateway =
        crate::features::pos::PosGateway::new(pos_typed_transport(&scope, &access_token).await?);
    gateway
        .execute(envelope)
        .await
        .map(pos_typed_receipt)
        .map_err(|error| error.message().to_owned())
}

