fn pos_sale_status(value: erpx_pos::SaleStatus) -> &'static str {
    match value {
        erpx_pos::SaleStatus::Draft => "draft",
        erpx_pos::SaleStatus::Open => "open",
        erpx_pos::SaleStatus::Held => "held",
        erpx_pos::SaleStatus::Completed => "completed",
        erpx_pos::SaleStatus::Voided => "voided",
    }
}

fn pos_refund_status(value: erpx_pos::RefundStatus) -> &'static str {
    match value {
        erpx_pos::RefundStatus::Requested => "requested",
        erpx_pos::RefundStatus::Approved => "approved",
        erpx_pos::RefundStatus::Rejected => "rejected",
        erpx_pos::RefundStatus::Posted => "posted",
        erpx_pos::RefundStatus::Cancelled => "cancelled",
    }
}

fn pos_projected_at(metadata: &erpx_cqrs::QueryMetadata, fallback: DateTime<Utc>) -> String {
    metadata
        .projection
        .checkpoint
        .as_ref()
        .map(|checkpoint| checkpoint.updated_at)
        .unwrap_or(fallback)
        .to_rfc3339()
}

fn pos_sale_record_from_typed(
    scope: &PosSaleScope,
    value: erpx_pos::SaleView,
    metadata: &erpx_cqrs::QueryMetadata,
) -> Result<PosSaleRecord, String> {
    if value.scope != pos_typed_scope(scope)? {
        return Err("POS sale row escaped its requested typed scope.".to_owned());
    }
    let (company_id, branch_id) = match &value.scope {
        erpx_kernel::TenantScope::Company { company_id, .. } => {
            (company_id.to_string(), String::new())
        }
        erpx_kernel::TenantScope::Branch {
            company_id,
            branch_id,
            ..
        } => (company_id.to_string(), branch_id.to_string()),
        _ => return Err("POS sale row returned a non-exact scope.".to_owned()),
    };
    Ok(PosSaleRecord {
        sale_id: value.sale_id.as_uuid().to_string(),
        reference: value.receipt_code,
        company_id,
        branch_id,
        currency: value.currency,
        subtotal_minor: value.subtotal_minor,
        tax_minor: value.tax_minor,
        total_minor: value.total_minor,
        paid_minor: value.paid_minor,
        status: pos_sale_status(value.status).to_owned(),
        created_at: value.created_at.to_rfc3339(),
        line_count: value.lines.len(),
        payment_count: value.payments.len(),
        lines_truncated: false,
        payments_truncated: false,
        source_version: value.version,
        projected_at: pos_projected_at(metadata, value.updated_at),
    })
}

fn pos_refund_record_from_typed(
    scope: &PosSaleScope,
    value: erpx_pos::RefundView,
) -> Result<PosRefundRecord, String> {
    if value.scope != pos_typed_scope(scope)? {
        return Err("POS refund row escaped its requested typed scope.".to_owned());
    }
    Ok(PosRefundRecord {
        refund_id: value.refund_id.as_uuid().to_string(),
        sale_id: value.sale_id.as_uuid().to_string(),
        currency: value.currency,
        total_amount_minor: value.total_amount_minor,
        reason: value.reason,
        status: pos_refund_status(value.status).to_owned(),
        line_count: value.lines.len(),
        source_version: value.version,
        requester_principal_ref: value.requester_principal_ref,
        reviewer_principal_ref: value.reviewer_principal_ref,
        updated_at: value.updated_at.to_rfc3339(),
    })
}

async fn fetch_pos_sales_typed(
    scope: PosSaleScope,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<PosSaleReadModel, String> {
    use erpx_ui_foundation::QueryGateway;

    let gateway =
        crate::features::pos::PosGateway::new(pos_typed_transport(&scope, &access_token).await?);
    let sales = gateway
        .execute(pos_typed_query(
            &scope,
            &principal_ref,
            &session_id,
            erpx_pos::PosQuery::ListSales(erpx_pos::ListSales {
                filter: erpx_pos::SaleListFilter {
                    status: None,
                    register_id: None,
                    page_size: 25,
                    cursor: None,
                },
            }),
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    let refunds = gateway
        .execute(pos_typed_query(
            &scope,
            &principal_ref,
            &session_id,
            erpx_pos::PosQuery::ListRefunds(erpx_pos::ListRefunds {
                filter: erpx_pos::RefundListFilter {
                    status: None,
                    sale_id: None,
                    page_size: 25,
                    cursor: None,
                },
            }),
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    let sales_metadata = sales.metadata;
    let sales = match sales.value {
        erpx_pos::PosQueryResponse::Sales(value) => value,
        _ => {
            return Err(
                "POS typed list-sales query returned the wrong response family.".to_owned(),
            );
        }
    };
    let refunds = match refunds.value {
        erpx_pos::PosQueryResponse::Refunds(value) => value,
        _ => {
            return Err(
                "POS typed list-refunds query returned the wrong response family.".to_owned(),
            );
        }
    };
    let next_cursor = sales.next_cursor.clone().unwrap_or_default();
    let has_more = sales.next_cursor.is_some() || refunds.next_cursor.is_some();
    Ok(PosSaleReadModel {
        scope: scope.clone(),
        sales: sales
            .sales
            .into_iter()
            .map(|value| pos_sale_record_from_typed(&scope, value, &sales_metadata))
            .collect::<Result<Vec<_>, _>>()?,
        refunds: refunds
            .refunds
            .into_iter()
            .map(|value| pos_refund_record_from_typed(&scope, value))
            .collect::<Result<Vec<_>, _>>()?,
        has_more,
        next_cursor,
        correlation_id: sales_metadata.correlation_id.to_string(),
    })
}

