fn sales_cqrs_actor(
    principal_ref: &str,
    session_id: &str,
) -> Result<erpx_kernel::ActorAttribution, String> {
    let session_id = Uuid::parse_str(session_id)
        .map_err(|_| "The authenticated Sales session identifier is invalid".to_owned())?;
    Ok(erpx_kernel::ActorAttribution {
        principal_ref: principal_ref.to_owned(),
        kind: erpx_kernel::ActorKind::TenantUser,
        session_id: Some(
            erpx_kernel::SessionId::try_from_uuid(session_id)
                .map_err(|_| "The authenticated Sales session identifier is invalid".to_owned())?,
        ),
        represented_principal_ref: None,
        support_capability_id: None,
    })
}

fn sales_holding_scope(scope: &FinanceScope) -> Result<erpx_kernel::TenantScope, String> {
    Ok(erpx_kernel::TenantScope::Holding {
        holding_id: Uuid::parse_str(&scope.holding_id)
            .map_err(|_| "The Sales holding identifier is invalid".to_owned())?,
    })
}

fn sales_exact_scope(
    scope: &FinanceScope,
    company_id: &str,
    branch_id: &str,
) -> Result<erpx_kernel::TenantScope, String> {
    let holding_id = Uuid::parse_str(&scope.holding_id)
        .map_err(|_| "The Sales holding identifier is invalid".to_owned())?;
    let company_id = Uuid::parse_str(company_id.trim())
        .map_err(|_| "Enter a valid Sales company UUID".to_owned())?;
    if branch_id.trim().is_empty() {
        Ok(erpx_kernel::TenantScope::Company {
            holding_id,
            company_id,
        })
    } else {
        Ok(erpx_kernel::TenantScope::Branch {
            holding_id,
            company_id,
            branch_id: Uuid::parse_str(branch_id.trim())
                .map_err(|_| "Enter a valid Sales branch UUID".to_owned())?,
        })
    }
}

fn sales_cqrs_query(
    scope: erpx_kernel::TenantScope,
    principal_ref: &str,
    session_id: &str,
    query: erpx_sales::SalesQuery,
) -> Result<erpx_cqrs::QueryEnvelope<erpx_sales::SalesQuery>, String> {
    Ok(erpx_cqrs::QueryEnvelope {
        contract_version: erpx_cqrs::CONTRACT_VERSION,
        query_id: erpx_kernel::QueryId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a Sales query identifier".to_owned())?,
        correlation_id: erpx_kernel::CorrelationId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a Sales correlation identifier".to_owned())?,
        actor: sales_cqrs_actor(principal_ref, session_id)?,
        tenant_scope: scope,
        audit: erpx_kernel::AuditContext {
            purpose: "sales_console_projection_read".to_owned(),
            customer_visible: false,
            module: Some("sales".to_owned()),
        },
        consistency: erpx_cqrs::QueryConsistency::Eventual,
        query,
    })
}

fn sales_cqrs_command(
    scope: erpx_kernel::TenantScope,
    principal_ref: &str,
    session_id: &str,
    idempotency_key: String,
    expected_aggregate_version: Option<u64>,
    command: erpx_sales::SalesCommand,
) -> Result<erpx_cqrs::CommandEnvelope<erpx_sales::SalesCommand>, String> {
    Ok(erpx_cqrs::CommandEnvelope {
        contract_version: erpx_cqrs::CONTRACT_VERSION,
        command_id: erpx_kernel::CommandId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a Sales command identifier".to_owned())?,
        idempotency_key: erpx_cqrs::IdempotencyKey::try_new(idempotency_key)
            .map_err(|_| "Unable to create the Sales idempotency key".to_owned())?,
        correlation_id: erpx_kernel::CorrelationId::try_from_uuid(Uuid::new_v4())
            .map_err(|_| "Unable to create a Sales correlation identifier".to_owned())?,
        causation_id: None,
        actor: sales_cqrs_actor(principal_ref, session_id)?,
        tenant_scope: scope,
        audit: erpx_kernel::AuditContext {
            purpose: "sales_console_lifecycle".to_owned(),
            customer_visible: true,
            module: Some("sales".to_owned()),
        },
        expected_aggregate_version,
        command,
    })
}

async fn sales_cqrs_transport(
    scope: &FinanceScope,
    access_token: &str,
) -> Result<crate::transport::wave6_7::SalesGrpcTransport, String> {
    #[cfg(target_arch = "wasm32")]
    let channel = tonic_web_wasm_client::Client::new(grpc_endpoint());
    #[cfg(not(target_arch = "wasm32"))]
    let channel = tonic::transport::Endpoint::from_static(GRPC_ENDPOINT)
        .connect()
        .await
        .map_err(|_| "offline".to_owned())?;
    let route = crate::transport::wave6_7::Wave67Route::try_new(
        &scope.tenant_id,
        scope.holding_ref.clone(),
    )
    .map_err(|error| error.message().to_owned())?;
    crate::transport::wave6_7::SalesGrpcTransport::try_new(channel, access_token, route)
        .map_err(|error| error.message().to_owned())
}

async fn fetch_sales_read(
    scope: SalesScope,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<SalesReadModel, String> {
    use erpx_ui_foundation::QueryGateway;

    let query = match scope.aggregate_type.as_str() {
        "quote" => erpx_sales::SalesQuery::GetQuote(erpx_sales::GetQuote {
            quote_id: erpx_sales::QuoteId::try_from_uuid(
                Uuid::parse_str(&scope.aggregate_id)
                    .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
            )
            .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
        }),
        "sales_order" => erpx_sales::SalesQuery::GetSalesOrder(erpx_sales::GetSalesOrder {
            sales_order_id: erpx_sales::SalesOrderId::try_from_uuid(
                Uuid::parse_str(&scope.aggregate_id)
                    .map_err(|_| "The Sales order identifier is invalid".to_owned())?,
            )
            .map_err(|_| "The Sales order identifier is invalid".to_owned())?,
        }),
        _ => return Err("Choose a Sales-owned quote or sales_order record".to_owned()),
    };
    let gateway = crate::features::sales::SalesGateway::new(
        sales_cqrs_transport(&scope.finance, &access_token).await?,
    );
    let response = gateway
        .execute(sales_cqrs_query(
            sales_holding_scope(&scope.finance)?,
            &principal_ref,
            &session_id,
            query,
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    SalesReadModel::from_target(&scope, response)
}

