fn sales_quote_command(
    scope: &SalesScope,
    input: &SalesTypedCreateInput,
) -> Result<(erpx_kernel::TenantScope, erpx_sales::SalesCommand), String> {
    if scope.aggregate_type != "quote" {
        return Err(
            "Sales record creation is limited to quotes; leads and opportunities belong to CRM"
                .into(),
        );
    }
    let target_scope = sales_exact_scope(&scope.finance, &input.company_id, &input.branch_id)?;
    let quote_id = erpx_sales::QuoteId::try_from_uuid(
        Uuid::parse_str(&scope.aggregate_id)
            .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
    )
    .map_err(|_| "The Sales quote identifier is invalid".to_owned())?;
    let opportunity_id = erpx_integration_contracts::crm::OpportunityRef::try_from_uuid(
        Uuid::parse_str(input.upstream_id.trim())
            .map_err(|_| "Select an authorized CRM opportunity UUID".to_owned())?,
    )
    .map_err(|_| "Select an authorized CRM opportunity UUID".to_owned())?;
    let customer_id = erpx_integration_contracts::customer::CustomerRef::try_from_uuid(
        Uuid::parse_str(input.customer_id.trim())
            .map_err(|_| "Select an authorized Customer UUID".to_owned())?,
    )
    .map_err(|_| "Select an authorized Customer UUID".to_owned())?;
    let currency = finance_command_text(&input.currency, "quote currency", 3)?.to_ascii_uppercase();
    let currency_code = erpx_integration_contracts::CurrencyCode::try_new(&currency)
        .map_err(|_| "Quote currency must be a three-letter uppercase code".to_owned())?;
    let quantity = input
        .quantity
        .trim()
        .parse::<i64>()
        .map_err(|_| "Quote quantity must be a positive whole number".to_owned())?;
    let unit_price_minor = input
        .unit_price_minor
        .trim()
        .parse::<i64>()
        .map_err(|_| "Quote unit price must use integer minor units".to_owned())?;
    let tax_minor = input
        .tax_minor
        .trim()
        .parse::<i64>()
        .map_err(|_| "Quote tax must use integer minor units".to_owned())?;
    let line_value = quantity
        .checked_mul(unit_price_minor)
        .and_then(|value| value.checked_add(tax_minor))
        .ok_or_else(|| "Quote amount overflowed".to_owned())?;
    let line = erpx_sales::SalesOrderLine {
        line_id: erpx_sales::SalesOrderLineId::try_from_uuid(
            Uuid::parse_str(input.line_id.trim())
                .map_err(|_| "Enter a valid quote line UUID".to_owned())?,
        )
        .map_err(|_| "Enter a valid quote line UUID".to_owned())?,
        item_code: finance_command_text(&input.item_reference, "quote item code", 128)?,
        description: finance_command_text(&input.description, "quote description", 255)?,
        quantity,
        unit_price_minor,
        tax_minor,
        currency: currency.clone(),
    };
    line.validate()
        .map_err(|_| "Quote line does not satisfy the Sales contract".to_owned())?;
    let valid_until = chrono::DateTime::parse_from_rfc3339(input.valid_until.trim())
        .map_err(|_| "Quote validity must be an RFC3339 timestamp".to_owned())?
        .with_timezone(&Utc);
    Ok((
        target_scope.clone(),
        erpx_sales::SalesCommand::CreateQuote(erpx_sales::CreateQuote {
            quote_id,
            scope: target_scope,
            opportunity: erpx_integration_contracts::crm::OpportunityFact {
                opportunity: opportunity_id,
                customer: customer_id,
                stage: erpx_integration_contracts::crm::OpportunityStage::Proposal,
                expected_value: erpx_integration_contracts::MoneyAmount::new(
                    line_value,
                    currency_code,
                ),
            },
            quote_code: finance_command_text(&input.name, "quote code", 128)?,
            currency,
            lines: vec![line],
            valid_until,
        }),
    ))
}

fn sales_transition_command(
    scope: &SalesScope,
    transition: &str,
) -> Result<erpx_sales::SalesCommand, String> {
    match (scope.aggregate_type.as_str(), transition.trim()) {
        ("quote", "send" | "sent") => {
            Ok(erpx_sales::SalesCommand::SendQuote(erpx_sales::SendQuote {
                quote_id: erpx_sales::QuoteId::try_from_uuid(
                    Uuid::parse_str(&scope.aggregate_id)
                        .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
                )
                .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
            }))
        }
        ("quote", "accept" | "accepted") => Ok(erpx_sales::SalesCommand::AcceptQuote(
            erpx_sales::AcceptQuote {
                quote_id: erpx_sales::QuoteId::try_from_uuid(
                    Uuid::parse_str(&scope.aggregate_id)
                        .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
                )
                .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
            },
        )),
        ("quote", "reject" | "rejected") => Ok(erpx_sales::SalesCommand::RejectQuote(
            erpx_sales::RejectQuote {
                quote_id: erpx_sales::QuoteId::try_from_uuid(
                    Uuid::parse_str(&scope.aggregate_id)
                        .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
                )
                .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
            },
        )),
        ("quote", "expire" | "expired") => Ok(erpx_sales::SalesCommand::ExpireQuote(
            erpx_sales::ExpireQuote {
                quote_id: erpx_sales::QuoteId::try_from_uuid(
                    Uuid::parse_str(&scope.aggregate_id)
                        .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
                )
                .map_err(|_| "The Sales quote identifier is invalid".to_owned())?,
            },
        )),
        ("sales_order", "confirm" | "confirmed") => Ok(
            erpx_sales::SalesCommand::ConfirmSalesOrder(erpx_sales::ConfirmSalesOrder {
                sales_order_id: sales_order_id(&scope.aggregate_id)?,
            }),
        ),
        ("sales_order", "partially_fulfilled" | "mark_partially_fulfilled") => {
            Ok(erpx_sales::SalesCommand::MarkSalesOrderPartiallyFulfilled(
                erpx_sales::MarkSalesOrderPartiallyFulfilled {
                    sales_order_id: sales_order_id(&scope.aggregate_id)?,
                },
            ))
        }
        ("sales_order", "fulfill" | "fulfilled") => {
            Ok(erpx_sales::SalesCommand::MarkSalesOrderFulfilled(
                erpx_sales::MarkSalesOrderFulfilled {
                    sales_order_id: sales_order_id(&scope.aggregate_id)?,
                },
            ))
        }
        ("sales_order", "cancel" | "cancelled") => Ok(erpx_sales::SalesCommand::CancelSalesOrder(
            erpx_sales::CancelSalesOrder {
                sales_order_id: sales_order_id(&scope.aggregate_id)?,
            },
        )),
        _ => Err("Choose a lifecycle action supported by the selected Sales record".to_owned()),
    }
}

fn sales_order_id(value: &str) -> Result<erpx_sales::SalesOrderId, String> {
    erpx_sales::SalesOrderId::try_from_uuid(
        Uuid::parse_str(value).map_err(|_| "The Sales order identifier is invalid".to_owned())?,
    )
    .map_err(|_| "The Sales order identifier is invalid".to_owned())
}

async fn transition_sales_aggregate(
    scope: SalesScope,
    transition: String,
    expected_version: u64,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<SalesTransitionResult, String> {
    use erpx_ui_foundation::CommandGateway;

    if expected_version == 0 {
        return Err("A positive Sales source version is required".to_owned());
    }
    let command = sales_transition_command(&scope, &transition)?;
    let gateway = crate::features::sales::SalesGateway::new(
        sales_cqrs_transport(&scope.finance, &access_token).await?,
    );
    let response = gateway
        .execute(sales_cqrs_command(
            sales_holding_scope(&scope.finance)?,
            &principal_ref,
            &session_id,
            format!(
                "sales:{}:{}:{}:{}",
                scope.aggregate_type, scope.aggregate_id, expected_version, transition
            ),
            Some(expected_version),
            command,
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    SalesTransitionResult::from_target(&scope, response)
}

async fn create_sales_typed(
    scope: SalesScope,
    input: SalesTypedCreateInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<SalesCommandReceipt, String> {
    use erpx_ui_foundation::CommandGateway;

    let (target_scope, command) = sales_quote_command(&scope, &input)?;
    let gateway = crate::features::sales::SalesGateway::new(
        sales_cqrs_transport(&scope.finance, &access_token).await?,
    );
    let response = gateway
        .execute(sales_cqrs_command(
            target_scope,
            &principal_ref,
            &session_id,
            format!("sales:quote:create:{}", scope.aggregate_id),
            None,
            command,
        )?)
        .await
        .map_err(|error| error.message().to_owned())?;
    if response.aggregate.aggregate_type != "quote"
        || response.aggregate.aggregate_id.to_string() != scope.aggregate_id
        || response.aggregate.version == 0
    {
        return Err("Sales quote receipt identity was invalid".to_owned());
    }
    Ok(SalesCommandReceipt {
        aggregate_type: response.aggregate.aggregate_type,
        aggregate_id: response.aggregate.aggregate_id.to_string(),
        version: response.aggregate.version,
        replayed: response.replayed,
        correlation_id: response.correlation_id.to_string(),
    })
}

