async fn execute_quality_command_with_client<T>(
    client: &mut QualityCommandServiceClient<T>,
    scope: &QualityScope,
    input: QualityCommandInput,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<QualityCommandReceiptModel, String>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    match input {
        QualityCommandInput::Create(input) => {
            let inspection_id = quality_uuid(&input.inspection_id, "inspection ID")?;
            let product_id = quality_uuid(&input.product_id, "product ID")?;
            let kind = match input.kind.as_str() {
                "incoming" => QualityInspectionKind::Incoming as i32,
                "in_process" => QualityInspectionKind::InProcess as i32,
                "final" => QualityInspectionKind::Final as i32,
                _ => return Err("inspection kind is unsupported".into()),
            };
            let lot_reference = quality_note(&input.lot_reference, "lot reference")?;
            let quantity = quality_quantity(&input.quantity, "inspection quantity", false)?;
            let idempotency_key = format!("quality-create-{inspection_id}");
            let context = quality_command_context(
                principal_ref,
                session_id,
                scope,
                "quality_inspection_create",
                &idempotency_key,
                None,
            )?;
            let mut request = tonic::Request::new(CreateQualityInspectionRequest {
                metadata: Some(context),
                inspection_id,
                scope: Some(scope.tenant_scope()),
                kind,
                product_id,
                lot_reference: (!lot_reference.is_empty()).then_some(lot_reference),
                quantity,
            });
            add_platform_metadata(&mut request, access_token, principal_ref, session_id)?;
            let response = client
                .create(request)
                .await
                .map_err(quality_command_rpc_error)?
                .into_inner();
            quality_receipt_model(response.receipt, response.inspection)
        }
        QualityCommandInput::Transition(input) => {
            let inspection_id = quality_uuid(&input.inspection_id, "inspection ID")?;
            let expected_version =
                quality_quantity(&input.expected_version, "expected version", false)?;
            let action = match input.action.as_str() {
                "start" | "record_result" | "release" | "cancel" => input.action,
                _ => return Err("inspection action is unsupported".into()),
            };
            let (passed_quantity, failed_quantity, disposition_note) = if action == "record_result"
            {
                let passed = quality_quantity(&input.passed_quantity, "passed quantity", true)?;
                let failed = quality_quantity(&input.failed_quantity, "failed quantity", true)?;
                if passed.checked_add(failed).is_none_or(|total| total == 0) {
                    return Err("the recorded result must account for at least one item".into());
                }
                (
                    passed,
                    failed,
                    quality_note(&input.disposition_note, "disposition note")?,
                )
            } else {
                (0, 0, String::new())
            };
            let idempotency_key = format!("quality-{action}-{inspection_id}-v{expected_version}");
            let context = quality_command_context(
                principal_ref,
                session_id,
                scope,
                match action.as_str() {
                    "start" => "quality_inspection_start",
                    "record_result" => "quality_inspection_record_result",
                    "release" => "quality_inspection_release",
                    "cancel" => "quality_inspection_cancel",
                    _ => unreachable!("the action was validated above"),
                },
                &idempotency_key,
                Some(expected_version),
            )?;
            match action.as_str() {
                "start" => {
                    let mut request = tonic::Request::new(StartQualityInspectionRequest {
                        metadata: Some(context),
                        inspection_id,
                    });
                    add_platform_metadata(&mut request, access_token, principal_ref, session_id)?;
                    let response = client
                        .start(request)
                        .await
                        .map_err(quality_command_rpc_error)?
                        .into_inner();
                    quality_receipt_model(response.receipt, response.inspection)
                }
                "record_result" => {
                    let mut request = tonic::Request::new(RecordQualityInspectionResultRequest {
                        metadata: Some(context),
                        inspection_id,
                        passed_quantity,
                        failed_quantity,
                        disposition_note: (!disposition_note.is_empty())
                            .then_some(disposition_note),
                    });
                    add_platform_metadata(&mut request, access_token, principal_ref, session_id)?;
                    let response = client
                        .record_result(request)
                        .await
                        .map_err(quality_command_rpc_error)?
                        .into_inner();
                    quality_receipt_model(response.receipt, response.inspection)
                }
                "release" => {
                    let mut request = tonic::Request::new(ReleaseQualityInspectionRequest {
                        metadata: Some(context),
                        inspection_id,
                    });
                    add_platform_metadata(&mut request, access_token, principal_ref, session_id)?;
                    let response = client
                        .release(request)
                        .await
                        .map_err(quality_command_rpc_error)?
                        .into_inner();
                    quality_receipt_model(response.receipt, response.inspection)
                }
                "cancel" => {
                    let mut request = tonic::Request::new(CancelQualityInspectionRequest {
                        metadata: Some(context),
                        inspection_id,
                    });
                    add_platform_metadata(&mut request, access_token, principal_ref, session_id)?;
                    let response = client
                        .cancel(request)
                        .await
                        .map_err(quality_command_rpc_error)?
                        .into_inner();
                    quality_receipt_model(response.receipt, response.inspection)
                }
                _ => unreachable!("the action was validated above"),
            }
        }
    }
}

fn quality_command_rpc_error(status: tonic::Status) -> String {
    match status.code() {
        tonic::Code::Unauthenticated => "authentication_required".into(),
        tonic::Code::PermissionDenied => "authorization_denied".into(),
        tonic::Code::Unavailable | tonic::Code::DeadlineExceeded => "offline".into(),
        tonic::Code::Aborted | tonic::Code::AlreadyExists => "conflict".into(),
        tonic::Code::NotFound => "quality_inspection_not_found".into(),
        tonic::Code::InvalidArgument | tonic::Code::FailedPrecondition => {
            "quality_command_rejected".into()
        }
        _ => "quality_command_failed".into(),
    }
}

fn quality_command_error_message(code: &str) -> &'static str {
    match code {
        "authentication_required" => "Your secure session expired. Sign in and retry.",
        "authorization_denied" => {
            "The server denied this Quality command for the current actor and scope."
        }
        "offline" => "Quality is temporarily offline. Your form values are still available.",
        "conflict" => {
            "This inspection changed on the server. Refresh the list and retry from its latest version."
        }
        "quality_inspection_not_found" => {
            "The inspection no longer exists in this authorized scope."
        }
        "quality_command_rejected" => {
            "The command does not match the inspection's current lifecycle or validation rules."
        }
        _ => "Quality could not accept the command. Retry after refreshing the authorized read.",
    }
}

