async fn fetch_scm_read_with_channel<T>(
    channel: T,
    scope: ProductAggregateScope,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<ProductAggregateReadModel, String>
where
    T: tonic::client::GrpcService<tonic::body::Body> + Clone,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let metadata = finance_target_query_metadata(
        &scope.finance,
        &principal_ref,
        &session_id,
        "scm_record_read",
    )?;
    match scope.aggregate_type.as_str() {
        "purchase_order" => {
            let mut client = procurement_target::procurement_query_service_client::ProcurementQueryServiceClient::new(channel);
            let response = client
                .get(authenticated_rpc_request(
                    procurement_target::GetPurchaseOrderRequest {
                        metadata: Some(metadata),
                        purchase_order_id: scope.aggregate_id.clone(),
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
                .map_err(product_aggregate_rpc_error)?
                .into_inner();
            let correlation_id = ScmListReadModel::correlation_id(response.metadata)?;
            let source_version = response
                .order
                .as_ref()
                .map_or(0, |order| order.source_version);
            if let Some(order) = response.order.as_ref()
                && (order.purchase_order_id != scope.aggregate_id
                    || order.source_version == 0
                    || !target_scope_within_holding(
                        &scope.finance.holding_id,
                        order.scope.as_ref(),
                    ))
            {
                return Err("Procurement record identity or scope was invalid".to_owned());
            }
            Ok(ProductAggregateReadModel {
                scope,
                present: response.order.is_some(),
                source_version,
                correlation_id,
            })
        }
        "stock_item" => {
            let mut client =
                inventory_target::inventory_query_service_client::InventoryQueryServiceClient::new(
                    channel,
                );
            let response = client
                .get(authenticated_rpc_request(
                    inventory_target::GetStockItemRequest {
                        metadata: Some(metadata),
                        stock_item_id: scope.aggregate_id.clone(),
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
                .map_err(product_aggregate_rpc_error)?
                .into_inner();
            let correlation_id = ScmListReadModel::correlation_id(response.metadata)?;
            let source_version = response.item.as_ref().map_or(0, |item| item.source_version);
            if let Some(item) = response.item.as_ref()
                && (item.stock_item_id != scope.aggregate_id
                    || item.source_version == 0
                    || !target_scope_within_holding(&scope.finance.holding_id, item.scope.as_ref()))
            {
                return Err("Inventory record identity or scope was invalid".to_owned());
            }
            Ok(ProductAggregateReadModel {
                scope,
                present: response.item.is_some(),
                source_version,
                correlation_id,
            })
        }
        _ => Err("Select purchase_order for Procurement or stock_item for Inventory.".to_owned()),
    }
}

fn target_scope_within_holding(holding_id: &str, scope: Option<&TenantScope>) -> bool {
    match scope.and_then(|scope| scope.scope.as_ref()) {
        Some(tenant_scope::Scope::Holding(scope)) => scope.holding_id == holding_id,
        Some(tenant_scope::Scope::Company(scope)) => scope.holding_id == holding_id,
        Some(tenant_scope::Scope::Branch(scope)) => scope.holding_id == holding_id,
        _ => false,
    }
}

