fn scm_target_scope(scope: &ScmListScope) -> TenantScope {
    let scope = if scope.branch_id.is_empty() {
        tenant_scope::Scope::Company(CompanyScope {
            holding_id: scope.finance.holding_id.clone(),
            company_id: scope.company_id.clone(),
        })
    } else {
        tenant_scope::Scope::Branch(BranchScope {
            holding_id: scope.finance.holding_id.clone(),
            company_id: scope.company_id.clone(),
            branch_id: scope.branch_id.clone(),
        })
    };
    TenantScope { scope: Some(scope) }
}

async fn fetch_scm_list_read_with_channel<T>(
    channel: T,
    scope: ScmListScope,
    access_token: String,
    principal_ref: String,
    session_id: String,
    before_cursor: Option<String>,
) -> Result<ScmListReadModel, String>
where
    T: tonic::client::GrpcService<tonic::body::Body> + Clone,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let mut metadata = finance_target_query_metadata(
        &scope.finance,
        &principal_ref,
        &session_id,
        "scm_record_list",
    )?;
    metadata.tenant_scope = Some(scm_target_scope(&scope));
    match scope.context {
        ProductContext::Procurement => {
            let mut client = procurement_target::procurement_query_service_client::ProcurementQueryServiceClient::new(channel);
            let response = client
                .list(authenticated_rpc_request(
                    procurement_target::ListPurchaseOrdersRequest {
                        metadata: Some(metadata),
                        status: None,
                        supplier_id: None,
                        page_size: 25,
                        cursor: before_cursor,
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
                .map_err(product_aggregate_rpc_error)?
                .into_inner();
            ScmListReadModel::from_procurement(&scope, response)
        }
        ProductContext::Inventory => {
            let mut client =
                inventory_target::inventory_query_service_client::InventoryQueryServiceClient::new(
                    channel,
                );
            let response = client
                .list(authenticated_rpc_request(
                    inventory_target::ListStockItemsRequest {
                        metadata: Some(metadata),
                        warehouse_id: None,
                        item_code: None,
                        page_size: 25,
                        cursor: before_cursor,
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
                .map_err(product_aggregate_rpc_error)?
                .into_inner();
            ScmListReadModel::from_inventory(&scope, response)
        }
        _ => Err("SCM list context was invalid".to_owned()),
    }
}

fn scm_command_scope(
    scope: &ProductAggregateScope,
    input: &ScmTypedCreateInput,
) -> Result<TenantScope, String> {
    let company_id = finance_command_uuid(&input.company_id, "SCM company ID")?;
    let scope_value = if input.branch_id.trim().is_empty() {
        tenant_scope::Scope::Company(CompanyScope {
            holding_id: scope.finance.holding_id.clone(),
            company_id,
        })
    } else {
        tenant_scope::Scope::Branch(BranchScope {
            holding_id: scope.finance.holding_id.clone(),
            company_id,
            branch_id: finance_command_uuid(&input.branch_id, "SCM branch ID")?,
        })
    };
    Ok(TenantScope {
        scope: Some(scope_value),
    })
}

fn scm_target_command_metadata(
    scope: &ProductAggregateScope,
    input: &ScmTypedCreateInput,
    principal_ref: &str,
    session_id: &str,
    purpose: &str,
    expected_version: Option<u64>,
) -> Result<CommandRequestMetadata, String> {
    let mut metadata = finance_target_command_metadata(
        &scope.finance,
        principal_ref,
        session_id,
        purpose,
        expected_version,
    )?;
    metadata.tenant_scope = Some(scm_command_scope(scope, input)?);
    Ok(metadata)
}

fn target_scm_command_receipt(
    aggregate_type: &str,
    aggregate_id: &str,
    receipt: Option<ProtoCommandReceipt>,
) -> Result<ScmCommandReceipt, String> {
    let receipt = receipt.ok_or_else(|| "SCM command omitted its receipt".to_owned())?;
    let aggregate = receipt
        .aggregate
        .ok_or_else(|| "SCM command omitted aggregate identity".to_owned())?;
    if aggregate.aggregate_type != aggregate_type
        || aggregate.aggregate_id != aggregate_id
        || aggregate.version == 0
    {
        return Err("SCM command receipt identity was invalid".to_owned());
    }
    Uuid::parse_str(&receipt.correlation_id)
        .map_err(|_| "SCM command correlation ID was invalid".to_owned())?;
    Ok(ScmCommandReceipt {
        aggregate_type: aggregate.aggregate_type,
        aggregate_id: aggregate.aggregate_id,
        version: aggregate.version,
        replayed: receipt.replayed,
        correlation_id: receipt.correlation_id,
    })
}
