async fn transition_scm_aggregate_with_channel<T>(
    channel: T,
    scope: ProductAggregateScope,
    transition: String,
    expected_version: u64,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<ScmTransitionResult, String>
where
    T: tonic::client::GrpcService<tonic::body::Body> + Clone,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    if scope.aggregate_type != "purchase_order" {
        return Err(
            "Inventory stock adjustments use Receive, Issue, Reserve, or Release actions; there is no generic lifecycle transition."
                .to_owned(),
        );
    }
    let metadata = finance_target_command_metadata(
        &scope.finance,
        &principal_ref,
        &session_id,
        "purchase_order_lifecycle",
        Some(expected_version),
    )?;
    let mut client = procurement_target::procurement_command_service_client::ProcurementCommandServiceClient::new(channel);
    let transition = transition.trim().to_ascii_lowercase();
    let receipt = match transition.as_str() {
        "release" | "released" => {
            client
                .release(authenticated_rpc_request(
                    procurement_target::ReleasePurchaseOrderRequest {
                        metadata: Some(metadata),
                        purchase_order_id: scope.aggregate_id.clone(),
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
        }
        "cancel" | "cancelled" => {
            client
                .cancel(authenticated_rpc_request(
                    procurement_target::CancelPurchaseOrderRequest {
                        metadata: Some(metadata),
                        purchase_order_id: scope.aggregate_id.clone(),
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
        }
        _ => return Err("Purchase order transition must be release or cancel.".to_owned()),
    }
    .map_err(product_aggregate_rpc_error)?
    .into_inner()
    .receipt
    .ok_or_else(|| "SCM transition response omitted its receipt".to_owned())?;
    ScmTransitionResult::from_target(&scope, receipt)
}

