async fn create_scm_typed_with_channel<T>(
    channel: T,
    scope: ProductAggregateScope,
    input: ScmTypedCreateInput,
    access_token: String,
    principal_ref: String,
    session_id: String,
) -> Result<ScmCommandReceipt, String>
where
    T: tonic::client::GrpcService<tonic::body::Body> + Clone,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody: tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error: Into<tonic::codegen::StdError> + Send,
{
    let target_scope = scm_command_scope(&scope, &input)?;
    let metadata = scm_target_command_metadata(
        &scope,
        &input,
        &principal_ref,
        &session_id,
        "scm_record_create",
        None,
    )?;
    match scope.aggregate_type.as_str() {
        "purchase_order" => {
            let supplier_id = finance_command_uuid(&input.supplier_id, "supplier ID")?;
            let line_id = finance_command_uuid(&input.line_id, "purchase order line ID")?;
            let quantity = input
                .quantity
                .trim()
                .parse::<i64>()
                .map_err(|_| "Purchase order quantity must be an integer.".to_owned())?;
            let unit_price_minor = input
                .unit_cost_minor
                .trim()
                .parse::<i64>()
                .map_err(|_| "Purchase order price must use integer minor units.".to_owned())?;
            if quantity <= 0 || unit_price_minor < 0 {
                return Err(
                    "Purchase order quantity must be positive and price non-negative.".to_owned(),
                );
            }
            let order_code = finance_command_text(&input.order_code, "order code", 128)?;
            let item_code = finance_command_text(&input.item_code, "item code", 128)?;
            let currency =
                finance_command_text(&input.currency, "currency", 3)?.to_ascii_uppercase();
            let destination_code =
                finance_command_text(&input.destination_code, "destination code", 128)?;
            let mut client = procurement_target::procurement_command_service_client::ProcurementCommandServiceClient::new(channel);
            let response = client
                .create(authenticated_rpc_request(
                    procurement_target::CreatePurchaseOrderRequest {
                        metadata: Some(metadata),
                        purchase_order_id: scope.aggregate_id.clone(),
                        scope: Some(target_scope),
                        order_code,
                        supplier_id,
                        currency: currency.clone(),
                        lines: vec![procurement_target::PurchaseOrderLineRecord {
                            line_id,
                            item_code,
                            ordered_quantity: quantity,
                            unit_price_minor,
                            currency,
                            destination_code,
                        }],
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
                .map_err(product_aggregate_rpc_error)?
                .into_inner();
            let order = response.order.ok_or_else(|| {
                "Procurement create response omitted the purchase order.".to_owned()
            })?;
            if order.purchase_order_id != scope.aggregate_id {
                return Err("Procurement create response identity was invalid.".to_owned());
            }
            target_scm_command_receipt("purchase_order", &scope.aggregate_id, response.receipt)
        }
        "stock_item" => {
            let warehouse_id = finance_command_uuid(&input.warehouse_id, "warehouse ID")?;
            let item_code = finance_command_text(&input.item_code, "item code", 128)?;
            let mut client = inventory_target::inventory_command_service_client::InventoryCommandServiceClient::new(channel);
            let response = client
                .register(authenticated_rpc_request(
                    inventory_target::RegisterStockItemRequest {
                        metadata: Some(metadata),
                        stock_item_id: scope.aggregate_id.clone(),
                        scope: Some(target_scope),
                        warehouse_id,
                        item_code,
                    },
                    &access_token,
                    &principal_ref,
                    &session_id,
                )?)
                .await
                .map_err(product_aggregate_rpc_error)?
                .into_inner();
            let item = response
                .item
                .ok_or_else(|| "Inventory register response omitted the stock item.".to_owned())?;
            if item.stock_item_id != scope.aggregate_id {
                return Err("Inventory register response identity was invalid.".to_owned());
            }
            target_scm_command_receipt("stock_item", &scope.aggregate_id, response.receipt)
        }
        _ => Err("Select purchase_order for Procurement or stock_item for Inventory.".to_owned()),
    }
}

fn add_platform_metadata<T>(
    request: &mut tonic::Request<T>,
    access_token: &str,
    principal_ref: &str,
    session_id: &str,
) -> Result<(), String> {
    request.metadata_mut().insert(
        "x-erpx-access-token",
        MetadataValue::try_from(access_token)
            .map_err(|_| "access token is not valid transport metadata".to_string())?,
    );
    request.metadata_mut().insert(
        "x-erpx-actor",
        MetadataValue::try_from(principal_ref)
            .map_err(|_| "principal reference is not valid transport metadata".to_string())?,
    );
    request.metadata_mut().insert(
        "x-erpx-session",
        MetadataValue::try_from(session_id)
            .map_err(|_| "session reference is not valid transport metadata".to_string())?,
    );
    Ok(())
}

