fn tone(value: &str) -> &'static str {
    match value {
        "healthy" | "active" => "good",
        "degraded" | "past_due" | "grace" => "warn",
        "down" | "read_only" | "canceled" => "bad",
        _ => "muted",
    }
}

fn route_customer_id(route: &PlatformRoute) -> Option<&str> {
    match route {
        PlatformRoute::Customer { customer_id, .. } => Some(customer_id.as_str()),
        PlatformRoute::PlatformHome | PlatformRoute::CustomerList => None,
    }
}

/// A credential-free, allow-listed destination for the console's initial deep link.
///
/// The shell has several independent route signals because each surface owns a different
/// transport/read model. Keeping the dispatch result typed prevents a path for one surface from
/// accidentally being interpreted as another surface, while the existing RouteStateBoundary
/// still gates every destination on the authenticated session.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ConsoleDeepLink {
    Home(EnterpriseHomeRoute),
    Auth(AuthRoute),
    Tenant(TenantRoute),
    Customer(PlatformRoute),
    Directory,
    Billing(BillingRoute),
    PlatformOperations(PlatformOperationsRoute),
    Support(SupportRoute),
    Marketing(RouteId),
    ProductContext(ProductContext),
    Workspace(RegisteredWorkspaceRoute),
}

