#[derive(Debug, Clone, PartialEq, Eq)]
enum PublicMarketingRoute {
    Form { form_id: String },
    Preview { preview_id: String },
}

impl PublicMarketingRoute {
    fn parse(path: &str) -> Option<Self> {
        let path = path.split('?').next().unwrap_or(path);
        let parse_id = |value: &str| {
            Uuid::parse_str(value)
                .ok()
                .filter(|id| !id.is_nil())
                .map(|id| id.to_string())
        };
        if let Some(value) = path.strip_prefix("/public/marketing/forms/") {
            let value = value.strip_suffix("/submissions").unwrap_or(value);
            return parse_id(value).map(|form_id| Self::Form { form_id });
        }
        path.strip_prefix("/public/marketing/previews/")
            .and_then(parse_id)
            .map(|preview_id| Self::Preview { preview_id })
    }
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct PublicMarketingSubmissionReceipt {
    accepted: bool,
    submission_id: String,
    replayed: bool,
    correlation_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
