fn platform_operations_not_connected_copy() -> (&'static str, &'static str) {
    (
        "Platform Operations not yet connected",
        "No Platform Operations data adapter is connected. This route is a read-only surface until server-authorized data and commands are available.",
    )
}

fn platform_operations_connection_copy(connected: bool) -> (&'static str, &'static str) {
    if connected {
        (
            "Platform Operations connected",
            "This route is rendering the authorized, bounded Platform Operations read model. Mutations remain server-owned and audited.",
        )
    } else {
        platform_operations_not_connected_copy()
    }
}

fn platform_operations_connection_state_copy(
    connected: bool,
    loading: bool,
    error: Option<&str>,
) -> (&'static str, &'static str) {
    if connected {
        return platform_operations_connection_copy(true);
    }
    if loading {
        return (
            "Platform Operations loading",
            "The connected adapter is requesting the authorized Platform Operations read model.",
        );
    }
    if error == Some("authentication_required") {
        return (
            "Session refresh required",
            "The Platform Operations adapter is connected, but this protected session must be refreshed before the authorized read can continue.",
        );
    }
    if error.is_some() {
        return (
            "Platform Operations read unavailable",
            "The connected adapter could not complete this authorized read. No backend details or fabricated data are exposed.",
        );
    }
    platform_operations_not_connected_copy()
}

fn platform_operations_state_copy(state: UiStateKind) -> (&'static str, &'static str) {
    match state {
        UiStateKind::Loading => (
            "Loading",
            "A connected adapter will show loading while an authorized read is in flight.",
        ),
        UiStateKind::Error => (
            "Unavailable",
            "The Platform Operations adapter is unavailable; no backend details are exposed.",
        ),
        UiStateKind::Denied => (
            "Access denied",
            "The server may deny this read for the current session or scope; no data is fabricated.",
        ),
        UiStateKind::Stale => (
            "Data may be stale",
            "A connected projection will be marked stale when its freshness budget is exceeded.",
        ),
        UiStateKind::ReadOnly => (
            "Read-only",
            "This console exposes no Platform Operations mutations until authoritative commands exist.",
        ),
        _ => unreachable!("only Platform Operations non-ready states are rendered"),
    }
}

fn platform_operations_area_for_route(route: PlatformOperationsRouteId) -> PlatformOperationsArea {
    match route {
        PlatformOperationsRouteId::Tenants
        | PlatformOperationsRouteId::Tenant
        | PlatformOperationsRouteId::TenantWorkspace => PlatformOperationsArea::Tenants,
        PlatformOperationsRouteId::Projections => PlatformOperationsArea::Projections,
        PlatformOperationsRouteId::Backups => PlatformOperationsArea::Backups,
        PlatformOperationsRouteId::Providers => PlatformOperationsArea::Providers,
        PlatformOperationsRouteId::Integrations => PlatformOperationsArea::Integrations,
        PlatformOperationsRouteId::Audit => PlatformOperationsArea::Audit,
        PlatformOperationsRouteId::Settings => PlatformOperationsArea::Settings,
        PlatformOperationsRouteId::RoleReview => PlatformOperationsArea::RoleReview,
    }
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
#[cfg(any(feature = "web", feature = "server"))]
struct WebBootstrap {
    initial_path: String,
    locale: String,
    authenticated: bool,
    principal_ref: Option<String>,
    account_count: u8,
}

#[cfg(any(feature = "web", feature = "server"))]
async fn load_web_bootstrap() -> Result<WebBootstrap, std::io::Error> {
    #[cfg(feature = "server")]
    {
        let context = dioxus::fullstack::FullstackContext::current()
            .ok_or_else(|| std::io::Error::other("request context unavailable"))?;
        let (initial_path, locale) = {
            let parts = context.parts_mut();
            let initial_path = parts
                .uri
                .path_and_query()
                .map(|value| value.as_str())
                .unwrap_or("/")
                .to_owned();
            let cookie_locale = parts.headers.get("cookie").and_then(|value| {
                value.to_str().ok()?.split(';').find_map(|part| {
                    let (name, value) = part.trim().split_once('=')?;
                    (name == "erpx_locale").then_some(value)
                })
            });
            let accepted_locale = parts
                .headers
                .get("accept-language")
                .and_then(|value| value.to_str().ok())
                .and_then(|value| value.split(',').next());
            let locale = cookie_locale
                .and_then(Locale::from_stored_tag)
                .or_else(|| accepted_locale.and_then(Locale::from_language_tag))
                .unwrap_or_default();
            (initial_path, locale)
        };
        let session = context
            .extension::<crate::bff::BffSessionContext>()
            .map(|context| context.snapshot)
            .unwrap_or_else(erpx_web_session::SafeWebSessionSnapshot::signed_out);
        return Ok(WebBootstrap {
            initial_path,
            locale: locale.language_tag().to_owned(),
            authenticated: session.authenticated,
            principal_ref: session.principal_ref,
            account_count: session.account_count,
        });
    }

    #[cfg(all(feature = "web", not(feature = "server"), target_arch = "wasm32"))]
    {
        let initial_path = crate::platform::preferences::web_location_path()
            .ok_or_else(|| std::io::Error::other("browser location unavailable"))?;
        return Ok(WebBootstrap {
            initial_path,
            locale: Locale::En.language_tag().to_owned(),
            authenticated: false,
            principal_ref: None,
            account_count: 0,
        });
    }

    #[cfg(all(feature = "web", not(feature = "server"), not(target_arch = "wasm32")))]
    return Ok(WebBootstrap {
        initial_path: "/".to_owned(),
        locale: Locale::En.language_tag().to_owned(),
        authenticated: false,
        principal_ref: None,
        account_count: 0,
    });

    #[allow(unreachable_code)]
    Err(std::io::Error::other("web bootstrap unavailable"))
}

#[component]
#[cfg(any(feature = "web", feature = "server"))]
pub(crate) fn App() -> Element {
    let bootstrap = use_loader(load_web_bootstrap)?;
    let bootstrap = bootstrap.read().clone();
    let locale = Locale::from_stored_tag(&bootstrap.locale).unwrap_or_default();
    provide_locale(locale);
    provide_theme(ThemeMode::System);
    provide_corporate_identity(
        erpx_domain::corporate_identity::ResolvedCorporateIdentity::neutral_erpx(),
    );
    let platform = crate::platform::ConsolePlatform::with_history(dioxus::history::history());
    use_context_provider(|| platform);
    use_context_provider(|| bootstrap.clone());
    rsx! { KitProvider { LocaleBootstrap { initial_path: bootstrap.initial_path } } }
}

#[component]
#[cfg(not(any(feature = "web", feature = "server")))]
pub(crate) fn App() -> Element {
    let platform = crate::platform::ConsolePlatform::with_history(dioxus::history::history());
    let locale = platform
        .preferences
        .load(crate::platform::PreferenceKey::Locale)
        .as_deref()
        .and_then(Locale::from_stored_tag)
        .or_else(|| {
            platform
                .external_actions
                .system_locale()
                .as_deref()
                .and_then(Locale::from_language_tag)
        })
        .unwrap_or(Locale::En);
    provide_locale(locale);
    provide_theme(ThemeMode::System);
    provide_corporate_identity(
        erpx_domain::corporate_identity::ResolvedCorporateIdentity::neutral_erpx(),
    );
    use_context_provider(|| platform);
    rsx! { KitProvider { LocaleBootstrap {} } }
}

#[component]
#[cfg(not(any(feature = "web", feature = "server")))]
fn LocaleBootstrap() -> Element {
    let locale = use_locale();
    let platform = use_context::<crate::platform::ConsolePlatform>();
    let preferences = platform.preferences.clone();

    use_effect(move || {
        let current = locale.current();
        preferences.store(
            crate::platform::PreferenceKey::Locale,
            current.language_tag(),
        );
    });

    let initial_path = platform.navigation.current_path();

    if let Some(route) = PublicMarketingRoute::parse(&initial_path) {
        return rsx! { PublicMarketingSurface { route } };
    }

    rsx! { ConsoleApp { initial_path } }
}

#[component]
#[cfg(any(feature = "web", feature = "server"))]
fn LocaleBootstrap(initial_path: String) -> Element {
    let locale = use_locale();
    let bootstrap = use_context::<WebBootstrap>();
    let preferences = use_context::<crate::platform::ConsolePlatform>()
        .preferences
        .clone();
    use_effect(move || {
        let current = locale.current();
        preferences.store(
            crate::platform::PreferenceKey::Locale,
            current.language_tag(),
        );
        #[cfg(target_arch = "wasm32")]
        let _ = crate::platform::preferences::apply_web_locale(current.language_tag());
    });

    if let Some(route) = PublicMarketingRoute::parse(&initial_path) {
        let error_path = initial_path.clone();
        return rsx! {
            ErrorBoundary {
                handle_error: move |errors: ErrorContext| {
                    let retry_errors = errors.clone();
                    rsx! { WorkspaceErrorSurface {
                        canonical_path: error_path.clone(),
                        on_retry: move |_| retry_errors.clear_errors(),
                    } }
                },
                PublicMarketingSurface { route }
            }
        };
    }

    if initial_path.split(['?', '#']).next() == Some(LOGIN_PATH) && !bootstrap.authenticated {
        return rsx! { BaseSignInSurface { initial_path } };
    }

    let error_path = initial_path.clone();
    rsx! {
        ErrorBoundary {
            handle_error: move |errors: ErrorContext| {
                let retry_errors = errors.clone();
                rsx! { WorkspaceErrorSurface {
                    canonical_path: error_path.clone(),
                    on_retry: move |_| retry_errors.clear_errors(),
                } }
            },
            ConsoleApp { initial_path }
        }
    }
}

#[component]
fn PublicMarketingSurface(route: PublicMarketingRoute) -> Element {
    let locale_context = use_locale();
    let locale = locale_context.current();
    let theme = use_theme();
    let theme_token = theme.current().css_token();
    let corporate_identity = use_corporate_identity();
    let mut identity_started = use_signal(|| false);
    use_effect(move || {
        if *identity_started.read() {
            return;
        }
        identity_started.set(true);
        spawn(async move {
            if let Ok(identity) = fetch_public_corporate_identity().await {
                corporate_identity.set(identity);
            }
        });
    });
    let identity = corporate_identity.current();
    let identity_style = erpx_ui_core::corporate_identity_style(&identity);
    let brand_name = SafeUiText::new(if identity.display_name.is_empty() {
        "ERPX"
    } else {
        &identity.display_name
    })
    .as_str()
    .to_owned();
    let brand_mark = identity.short_name.chars().take(2).collect::<String>();
    let mut public_brand_asset_failed = use_signal(|| false);
    let mut tenant_id = use_signal(String::new);
    let mut name = use_signal(String::new);
    let mut email = use_signal(String::new);
    let mut message = use_signal(String::new);
    let mut consent = use_signal(|| false);
    let mut preview_token = use_signal(String::new);
    let mut preview = use_signal(|| None::<PublicMarketingPreviewModel>);
    let mut receipt = use_signal(|| None::<PublicMarketingSubmissionReceipt>);
    let mut state = use_signal(|| UiStateKind::Empty);
    let mut error = use_signal(|| None::<String>);

    let title = match route {
        PublicMarketingRoute::Form { .. } => localized_copy("Contact our team", "ติดต่อทีมของเรา"),
        PublicMarketingRoute::Preview { .. } => localized_copy("Content preview", "ตัวอย่างเนื้อหา"),
    };
    let description = match route {
        PublicMarketingRoute::Form { .. } => localized_copy(
            "Send a consented enquiry through this published form.",
            "ส่งคำถามที่ได้รับความยินยอมผ่านแบบฟอร์มที่เผยแพร่นี้",
        ),
        PublicMarketingRoute::Preview { .. } => localized_copy(
            "Use the temporary access code supplied by the content owner.",
            "ใช้รหัสเข้าถึงชั่วคราวที่เจ้าของเนื้อหามอบให้",
        ),
    };
    let page_title = format!("{title} · ERPX");
    let busy = matches!(
        *state.read(),
        UiStateKind::Loading | UiStateKind::Submitting
    );

    let submit_form = {
        let route = route.clone();
        move |event: FormEvent| {
            event.prevent_default();
            let PublicMarketingRoute::Form { form_id } = route.clone() else {
                return;
            };
            state.set(UiStateKind::Submitting);
            error.set(None);
            receipt.set(None);
            let tenant_id_value = tenant_id.read().clone();
            let name_value = name.read().clone();
            let email_value = email.read().clone();
            let message_value = message.read().clone();
            let consent_value = *consent.read();
            spawn(async move {
                match submit_public_marketing_form(
                    form_id,
                    tenant_id_value,
                    name_value,
                    email_value,
                    message_value,
                    consent_value,
                )
                .await
                {
                    Ok(value) => {
                        receipt.set(Some(value));
                        state.set(UiStateKind::Success);
                        name.set(String::new());
                        email.set(String::new());
                        message.set(String::new());
                        consent.set(false);
                    }
                    Err(category) => {
                        let error_state = public_marketing_error_state(&category);
                        error.set(Some(category));
                        state.set(error_state);
                    }
                }
            });
        }
    };

    let load_preview = {
        let route = route.clone();
        move |event: FormEvent| {
            event.prevent_default();
            let PublicMarketingRoute::Preview { preview_id } = route.clone() else {
                return;
            };
            let access_code = preview_token.read().clone();
            preview_token.set(String::new());
            preview.set(None);
            error.set(None);
            state.set(UiStateKind::Loading);
            let tenant_id_value = tenant_id.read().clone();
            spawn(async move {
                match fetch_public_marketing_preview(
                    preview_id,
                    tenant_id_value,
                    access_code,
                    locale,
                )
                .await
                {
                    Ok(value) => {
                        preview.set(Some(value));
                        state.set(UiStateKind::Success);
                    }
                    Err(category) => {
                        let error_state = public_marketing_error_state(&category);
                        error.set(Some(category));
                        state.set(error_state);
                    }
                }
            });
        }
    };

    rsx! {
        document::Title { "{page_title}" }
        ConsoleStylesheets {}
        main {
            class: "public-marketing-shell ui-shell ui-theme-{theme_token}",
            style: "{identity_style}",
            "data-route-family": "public-shell",
            header { class: "public-marketing-header",
                div { class: "brand",
                    span { class: "brand-mark", aria_hidden: "true",
                        if *public_brand_asset_failed.read() {
                            "{brand_mark}"
                        } else {
                            img {
                                src: "/api/v2/public/branding/assets/logo_mark",
                                alt: "",
                                onerror: move |_| public_brand_asset_failed.set(true),
                            }
                        }
                    }
                    div { h1 { "{brand_name}" } p { {localized_copy("Published experience", "ประสบการณ์ที่เผยแพร่")} } }
                }
                div { class: "public-marketing-controls",
                    LocaleToggle {}
                    KitButton { size: ButtonSize::Default,
                        variant: ButtonVariant::Secondary,
                        r#type: "button",
                        aria_label: localized_copy("Change color mode", "เปลี่ยนโหมดสี"),
                        onclick: move |_| theme.toggle(),
                        {match theme.current() {
                            ThemeMode::Light => localized_copy("Light", "สว่าง"),
                            ThemeMode::Dark => localized_copy("Dark", "มืด"),
                            ThemeMode::System => localized_copy("System", "ตามระบบ"),
                        }}
                    }
                }
            }
            aside { class: "public-marketing-story", aria_label: localized_copy("About this experience", "เกี่ยวกับประสบการณ์นี้"),
                div { class: "public-story-orbit", aria_hidden: "true", span {} span {} span {} }
                div { class: "eyebrow", {localized_copy("TRUSTED BUSINESS EXPERIENCE", "ประสบการณ์ธุรกิจที่เชื่อถือได้")} }
                h2 { {localized_copy("A focused path from interest to action.", "เส้นทางที่ชัดเจนจากความสนใจสู่การลงมือทำ")} }
                p { {localized_copy("Your information is handled through a consent-aware, tenant-branded ERPX workflow.", "ข้อมูลของคุณได้รับการดูแลผ่านเวิร์กโฟลว์ ERPX ที่คำนึงถึงความยินยอมและแบรนด์ขององค์กร")} }
                ul {
                    li { {localized_copy("Purpose-limited processing", "ประมวลผลตามวัตถุประสงค์ที่กำหนด")} }
                    li { {localized_copy("No account session created", "ไม่สร้างเซสชันบัญชี")} }
                    li { {localized_copy("Secure published context", "บริบทที่เผยแพร่อย่างปลอดภัย")} }
                }
            }
            section { class: "public-marketing-card", aria_labelledby: "public-marketing-title",
                div { class: "eyebrow", {localized_copy("PUBLIC · CONSENT-AWARE", "สาธารณะ · คำนึงถึงความยินยอม")} }
                h2 { id: "public-marketing-title", "{title}" }
                p { class: "public-marketing-description", "{description}" }
                label { class: "auth-field", r#for: "public-site-reference",
                    span { {localized_copy("Published site reference", "ข้อมูลอ้างอิงไซต์ที่เผยแพร่")} }
                    KitInput {
                        id: "public-site-reference",
                        value: "{tenant_id}",
                        maxlength: "128",
                        autocomplete: "organization",
                        disabled: busy,
                        aria_required: "true",
                        oninput: move |event: FormEvent| tenant_id.set(event.value()),
                    }
                }

                match route {
                    PublicMarketingRoute::Form { .. } => rsx! {
                        form { class: "public-marketing-form", onsubmit: submit_form,
                            label { r#for: "public-name", {localized_copy("Name", "ชื่อ")} }
                            KitInput { id: "public-name", value: "{name}", maxlength: "255", autocomplete: "name", disabled: busy, required: true, oninput: move |event: FormEvent| name.set(event.value()) }
                            label { r#for: "public-email", {localized_copy("Email", "อีเมล")} }
                            KitInput { id: "public-email", r#type: "email", value: "{email}", maxlength: "320", autocomplete: "email", disabled: busy, required: true, oninput: move |event: FormEvent| email.set(event.value()) }
                            label { r#for: "public-message", {localized_copy("Message", "ข้อความ")} }
                            KitTextarea { id: "public-message", value: "{message}", maxlength: "4096", rows: "7", disabled: busy, required: true, oninput: move |event: FormEvent| message.set(event.value()) }
                            label { class: "public-consent", r#for: "public-consent",
                                KitInput { id: "public-consent", r#type: "checkbox", checked: *consent.read(), disabled: busy, required: true, onchange: move |event: FormEvent| consent.set(event.checked()) }
                                span { {localized_copy("I consent to this enquiry being processed and recorded for follow-up.", "ฉันยินยอมให้ประมวลผลและบันทึกคำถามนี้เพื่อติดตามผล")} }
                            }
                            KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "submit", disabled: busy, if busy { {localized_copy("Sending…", "กำลังส่ง…")} } else { {localized_copy("Send enquiry", "ส่งคำถาม")} } }
                        }
                    },
                    PublicMarketingRoute::Preview { .. } => rsx! {
                        form { class: "public-marketing-form", onsubmit: load_preview,
                            label { r#for: "public-preview-code", {localized_copy("Temporary access code", "รหัสเข้าถึงชั่วคราว")} }
                            KitInput { id: "public-preview-code", r#type: "password", value: "{preview_token}", maxlength: "4096", autocomplete: "off", disabled: busy, required: true, oninput: move |event: FormEvent| preview_token.set(event.value()) }
                            p { class: "security-note", {localized_copy("The access code is sent only in a request header and is cleared immediately after use.", "รหัสเข้าถึงจะส่งเฉพาะในส่วนหัวคำขอและถูกล้างทันทีหลังใช้งาน")} }
                            KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "submit", disabled: busy, if busy { {localized_copy("Loading…", "กำลังโหลด…")} } else { {localized_copy("Open preview", "เปิดตัวอย่าง")} } }
                        }
                    },
                }

                if matches!(*state.read(), UiStateKind::Loading | UiStateKind::Submitting) {
                    StatePanel { state: *state.read(), title: localized_copy("Request in progress", "กำลังดำเนินการคำขอ").to_owned(), message: localized_copy("The public service is validating this request.", "บริการสาธารณะกำลังตรวจสอบคำขอนี้").to_owned(), action_label: None, on_action: None }
                }
                if let Some(category) = error.read().as_deref() {
                    StatePanel { state: *state.read(), title: localized_copy("Request not completed", "คำขอยังไม่เสร็จสมบูรณ์").to_owned(), message: localized_public_marketing_error(category, locale).to_owned(), action_label: None, on_action: None }
                }
                if let Some(value) = receipt.read().as_ref() {
                    StatePanel { state: UiStateKind::Success, title: localized_copy("Enquiry received", "ได้รับคำถามแล้ว").to_owned(), message: match locale { Locale::En => format!("Receipt {}. You can safely close this page.", SafeUiText::new(&value.submission_id).as_str()), Locale::Th => format!("ใบรับคำขอ {} คุณสามารถปิดหน้านี้ได้อย่างปลอดภัย", SafeUiText::new(&value.submission_id).as_str()) }, action_label: None, on_action: None }
                }
                if let Some(value) = preview.read().as_ref() {
                    article { class: "public-preview", "data-no-index": value.no_index.to_string(),
                        div { class: "eyebrow", {match locale { Locale::En => format!("PREVIEW · VERSION {}", value.version), Locale::Th => format!("ตัวอย่าง · เวอร์ชัน {}", value.version) }} }
                        h2 { "{value.title.as_str()}" }
                        p { class: "public-preview-body", "{value.body.as_str()}" }
                        dl { class: "detail-grid",
                            dt { {localized_copy("SEO title", "ชื่อ SEO")} } dd { "{value.seo_title.as_str()}" }
                            dt { {localized_copy("SEO description", "คำอธิบาย SEO")} } dd { "{value.seo_description.as_str()}" }
                        }
                    }
                }
            }
            footer { class: "public-marketing-footer", {localized_copy("No account session is created on this public route.", "ไม่มีการสร้างเซสชันบัญชีในเส้นทางสาธารณะนี้")} }
        }
    }
}

#[component]
fn BaseSignInSurface(initial_path: String) -> Element {
    let locale = use_locale().current();
    let identity = use_corporate_identity().current();
    let identity_style = erpx_ui_core::corporate_identity_style(&identity);
    let principal =
        initial_login_principal(cfg!(debug_assertions), DEVELOPMENT_PERSONA_BUILD_ENABLED);
    let message = password_form_error_message(&initial_path, locale);
    let title = console_text(
        locale,
        "Sign in · ERPX Platform",
        "เข้าสู่ระบบ · ERPX Platform",
    );

    rsx! {
        document::Title { "{title}" }
        ConsoleStylesheets {}
        main { class: "sign-in-surface", style: "{identity_style}", "data-wasm-entry": "base-login",
            section { class: "sign-in-brand", aria_label: console_text(locale, "ERPX Platform identity", "อัตลักษณ์แพลตฟอร์ม ERPX"),
                div { class: "sign-in-brand-content",
                    span { class: "sign-in-mark", aria_hidden: "true", "{identity.short_name}" }
                    div { class: "eyebrow", "{identity.display_name}" }
                    h1 { {console_text(locale, "One secure operating system for every business unit.", "ระบบปฏิบัติการที่ปลอดภัยหนึ่งเดียวสำหรับทุกหน่วยธุรกิจ")} }
                    p { {console_text(locale, "Sign-in and protected session restore stay in the trusted Console bootstrap.", "การเข้าสู่ระบบและการกู้คืนเซสชันที่ได้รับการปกป้องอยู่ใน bootstrap ที่เชื่อถือได้ของคอนโซล")} }
                }
            }
            section { class: "sign-in-form-region",
                div { class: "sign-in-locale-control", LocaleToggle {} span { "{locale.native_name()}" } }
                div { class: "sign-in-form-shell",
                    header {
                        div { class: "eyebrow", {console_text(locale, "SECURE CONSOLE", "คอนโซลที่ปลอดภัย")} }
                        h2 { {console_text(locale, "Sign in to your workspace", "เข้าสู่ระบบพื้นที่ทำงานของคุณ")} }
                        p { {console_text(locale, "The ERPX workspace is delivered as a single optimized WebAssembly module.", "พื้นที่ทำงาน ERPX ส่งมอบเป็นโมดูล WebAssembly ที่ปรับประสิทธิภาพแล้วหนึ่งไฟล์")} }
                    }
                    form { class: "auth-form", method: "post", action: "/api/v2/auth/password/form",
                        KitInput { r#type: "hidden", name: "device_label", value: "erpx-console" }
                        div { class: "auth-field",
                            label { r#for: "auth-principal", {console_text(locale, "Principal", "ผู้ใช้หลัก")} }
                            KitInput {
                                id: "auth-principal",
                                name: "principal_ref",
                                autocomplete: "username webauthn",
                                required: true,
                                value: principal,
                            }
                        }
                        div { class: "auth-field",
                            label { r#for: "auth-password", {console_text(locale, "Password", "รหัสผ่าน")} }
                            KitInput {
                                id: "auth-password",
                                name: "password",
                                r#type: "password",
                                autocomplete: "current-password",
                                required: true,
                            }
                        }
                        KitButton {
                            variant: ButtonVariant::Secondary,
                            size: ButtonSize::Default,
                            class: "button auth-submit",
                            r#type: "submit",
                            {console_text(locale, "Sign in", "เข้าสู่ระบบ")}
                        }
                    }
                    if let Some(message) = message {
                        p { class: "status-banner warn", role: "alert", "{message}" }
                    }
                    footer { {console_text(locale, "Credentials are sent only to the same-origin ERPX BFF and are never placed in browser URLs.", "ข้อมูลรับรองจะส่งไปยัง ERPX BFF ต้นทางเดียวกันเท่านั้นและจะไม่อยู่ใน URL ของเบราว์เซอร์")} }
                }
            }
        }
    }
}

#[component]
fn WorkspaceErrorSurface(canonical_path: String, on_retry: EventHandler<()>) -> Element {
    let locale = use_locale().current();
    rsx! {
        main { class: "session-restore-surface workspace-render-error", "data-route-path": canonical_path,
            div { class: "session-restore-card", role: "alert",
                h1 { {console_text(locale, "Workspace unavailable", "พื้นที่ทำงานไม่พร้อมใช้งาน")} }
                p { {console_text(locale, "The workspace could not be rendered. The route and protected session were preserved.", "ไม่สามารถแสดงพื้นที่ทำงานได้ โดยยังคงเส้นทางและเซสชันที่ได้รับการปกป้องไว้")} }
                div { class: "auth-alternative-actions",
                    KitButton { variant: ButtonVariant::Secondary, size: ButtonSize::Default, r#type: "button", onclick: move |_| on_retry.call(()),
                        {console_text(locale, "Retry", "ลองอีกครั้ง")}
                    }
                    KitButton { variant: ButtonVariant::Primary, size: ButtonSize::Default, r#type: "button", onclick: move |_| {
                        restart_console();
                    },
                        {console_text(locale, "Reload page", "โหลดหน้าใหม่")}
                    }
                }
            }
        }
    }
}

fn work_domain_copy(locale: Locale, domain: WorkDomain) -> &'static str {
    match domain {
        WorkDomain::Operations => console_text(locale, "Operations", "ปฏิบัติการ"),
        WorkDomain::Support => console_text(locale, "Support", "บริการลูกค้า"),
        WorkDomain::Finance => console_text(locale, "Finance", "การเงิน"),
        WorkDomain::People => console_text(locale, "People", "บุคลากร"),
        WorkDomain::Maintenance => console_text(locale, "Maintenance", "ซ่อมบำรุง"),
        WorkDomain::Procurement => console_text(locale, "Procurement", "จัดซื้อ"),
    }
}

fn work_kind_copy(locale: Locale, kind: WorkItemKind) -> &'static str {
    match kind {
        WorkItemKind::Approval => console_text(locale, "Approval", "อนุมัติ"),
        WorkItemKind::Exception => console_text(locale, "Exception", "ข้อยกเว้น"),
        WorkItemKind::Incident => console_text(locale, "Incident", "เหตุขัดข้อง"),
        WorkItemKind::Task => console_text(locale, "Task", "งาน"),
    }
}

fn work_severity_copy(locale: Locale, severity: WorkItemSeverity) -> &'static str {
    match severity {
        WorkItemSeverity::Critical => console_text(locale, "Critical", "วิกฤต"),
        WorkItemSeverity::High => console_text(locale, "High", "สูง"),
        WorkItemSeverity::Medium => console_text(locale, "Medium", "ปานกลาง"),
        WorkItemSeverity::Low => console_text(locale, "Low", "ต่ำ"),
        WorkItemSeverity::Informational => console_text(locale, "Info", "ข้อมูล"),
    }
}

fn work_sla_copy(locale: Locale, sla: WorkSlaState) -> &'static str {
    match sla {
        WorkSlaState::Overdue => console_text(locale, "Overdue", "เกิน SLA"),
        WorkSlaState::DueToday => console_text(locale, "Due today", "ครบกำหนดวันนี้"),
        WorkSlaState::Healthy => console_text(locale, "On track", "ตามกำหนด"),
        WorkSlaState::NoDueDate => console_text(locale, "No due date", "ไม่มีกำหนด"),
    }
}

fn work_severity_tone(severity: WorkItemSeverity) -> StatusTone {
    match severity {
        WorkItemSeverity::Critical => StatusTone::Danger,
        WorkItemSeverity::High => StatusTone::Warning,
        WorkItemSeverity::Medium => StatusTone::Info,
        WorkItemSeverity::Low | WorkItemSeverity::Informational => StatusTone::Neutral,
    }
}

fn work_availability_copy(locale: Locale, availability: ReadModelAvailability) -> &'static str {
    match availability {
        ReadModelAvailability::Available => console_text(locale, "Available", "พร้อมใช้"),
        ReadModelAvailability::Partial => console_text(locale, "Partial", "บางส่วน"),
        ReadModelAvailability::Empty => console_text(locale, "No active work", "ไม่มีงานค้าง"),
        ReadModelAvailability::Unavailable => console_text(locale, "Unavailable", "ไม่พร้อมใช้"),
    }
}

#[component]
fn MyWorkSurface(
    model: Option<WorkQueueReadModel>,
    loading: bool,
    error: Option<String>,
    view: WorkQueueView,
    domain: Option<WorkDomain>,
    severity: Option<WorkItemSeverity>,
    on_view: EventHandler<WorkQueueView>,
    on_domain: EventHandler<Option<WorkDomain>>,
    on_severity: EventHandler<Option<WorkItemSeverity>>,
    on_retry: EventHandler<()>,
    on_next: EventHandler<String>,
    on_navigate: EventHandler<String>,
) -> Element {
    let locale = use_locale().current();
    let mut selected = use_signal(|| None::<WorkItemReadModel>);
    let mut compact = use_signal(|| false);
    let counters = model
        .as_ref()
        .map(|model| model.counters)
        .unwrap_or_default();
    let items = model
        .as_ref()
        .map(|model| model.items.clone())
        .unwrap_or_default();
    let contributions = model
        .as_ref()
        .map(|model| model.contributions.clone())
        .unwrap_or_default();
    let next_cursor = model.as_ref().and_then(|model| model.next_cursor.clone());
    let partial = model.as_ref().is_some_and(|model| {
        matches!(
            model.meta.availability,
            ReadModelAvailability::Partial | ReadModelAvailability::Unavailable
        )
    });
    let selected_item = selected.read().clone();

    rsx! {
        section { class: if *compact.read() { "work-os compact" } else { "work-os" }, "data-page-family": "collection",
            header { class: "work-os-heading",
                div {
                    p { class: "work-os-eyebrow", {console_text(locale, "MY WORK", "งานของฉัน")} }
                    h1 { {console_text(locale, "What needs attention today", "สิ่งที่ต้องจัดการวันนี้")} }
                    p { {console_text(locale, "One prioritized queue across the domains available to your active role.", "คิวงานเดียวที่จัดลำดับจากทุกโดเมนที่บทบาทปัจจุบันเข้าถึงได้")} }
                }
                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", onclick: move |_| on_retry.call(()),
                    {console_text(locale, "Refresh", "รีเฟรช")}
                }
            }

            div { class: "work-summary", aria_label: console_text(locale, "Work summary", "สรุปงาน"),
                article { "data-tone": "danger", span { {console_text(locale, "Overdue", "เกิน SLA")} } strong { "{counters.overdue}" } }
                article { "data-tone": "warning", span { {console_text(locale, "Due today", "ครบกำหนดวันนี้")} } strong { "{counters.due_today}" } }
                article { span { {console_text(locale, "Approvals", "ต้องอนุมัติ")} } strong { "{counters.approvals}" } }
                article { span { {console_text(locale, "Exceptions", "ข้อยกเว้น")} } strong { "{counters.exceptions}" } }
                article { span { {console_text(locale, "Waiting", "รอผู้อื่น")} } strong { "{counters.waiting}" } }
            }

            nav { class: "work-saved-views", aria_label: console_text(locale, "Saved views", "มุมมองที่บันทึก"),
                for (next_view, en, th) in [
                    (WorkQueueView::All, "All work", "ทั้งหมด"),
                    (WorkQueueView::Mine, "Mine", "ของฉัน"),
                    (WorkQueueView::Team, "Team", "ทีม"),
                    (WorkQueueView::Overdue, "Overdue", "เกิน SLA"),
                    (WorkQueueView::Approvals, "Approvals", "ต้องอนุมัติ"),
                ] {
                    KitButton { size: ButtonSize::Default,
                        variant: ButtonVariant::Ghost,
                        r#type: "button",
                        class: if view == next_view { "active" } else { "" },
                        aria_pressed: (view == next_view).to_string(),
                        onclick: move |_| { selected.set(None); on_view.call(next_view); },
                        {console_text(locale, en, th)}
                    }
                }
            }

            div { class: "work-toolbar", role: "toolbar", aria_label: console_text(locale, "Work filters", "ตัวกรองงาน"),
                label {
                    span { {console_text(locale, "Domain", "โดเมน")} }
                    KitSelect {
                        value: domain.map(WorkDomain::as_str).unwrap_or("all"),
                        onchange: move |event: FormEvent| on_domain.call(match event.value().as_str() {
                            "operations" => Some(WorkDomain::Operations),
                            "support" => Some(WorkDomain::Support),
                            "finance" => Some(WorkDomain::Finance),
                            "people" => Some(WorkDomain::People),
                            "maintenance" => Some(WorkDomain::Maintenance),
                            "procurement" => Some(WorkDomain::Procurement),
                            _ => None,
                        }),
                        option { value: "all", {console_text(locale, "All domains", "ทุกโดเมน")} }
                        for value in [WorkDomain::Operations, WorkDomain::Support, WorkDomain::Finance, WorkDomain::People, WorkDomain::Maintenance, WorkDomain::Procurement] {
                            option { value: value.as_str(), {work_domain_copy(locale, value)} }
                        }
                    }
                }
                label {
                    span { {console_text(locale, "Severity", "ความสำคัญ")} }
                    KitSelect {
                        value: severity.map(work_severity_query_value).unwrap_or("all"),
                        onchange: move |event: FormEvent| on_severity.call(match event.value().as_str() {
                            "critical" => Some(WorkItemSeverity::Critical),
                            "high" => Some(WorkItemSeverity::High),
                            "medium" => Some(WorkItemSeverity::Medium),
                            "low" => Some(WorkItemSeverity::Low),
                            "informational" => Some(WorkItemSeverity::Informational),
                            _ => None,
                        }),
                        option { value: "all", {console_text(locale, "All severity", "ทุกระดับ")} }
                        for value in [WorkItemSeverity::Critical, WorkItemSeverity::High, WorkItemSeverity::Medium, WorkItemSeverity::Low, WorkItemSeverity::Informational] {
                            option { value: work_severity_query_value(value), {work_severity_copy(locale, value)} }
                        }
                    }
                }
                KitButton { variant: ButtonVariant::Secondary, size: ButtonSize::Default, class: "work-density", r#type: "button", aria_pressed: compact.read().to_string(), onclick: move |_| { let next = !*compact.read(); compact.set(next); },
                    {if *compact.read() { console_text(locale, "Comfortable", "แบบสบายตา") } else { console_text(locale, "Compact", "แบบกระชับ") }}
                }
                span { class: "work-total", {match locale { Locale::En => format!("{} active", counters.total), Locale::Th => format!("{} งานที่เปิดอยู่", counters.total) }} }
            }

            if partial {
                div { class: "work-source-banner", role: "status",
                    StatusBadge { label: console_text(locale, "Partial data", "ข้อมูลบางส่วน").to_owned(), tone: StatusTone::Warning }
                    span { {console_text(locale, "Available sources are shown below. Unavailable domains are not counted as zero.", "แสดงเฉพาะแหล่งข้อมูลที่พร้อมใช้ โดเมนที่ไม่พร้อมจะไม่ถูกนับเป็นศูนย์")} }
                }
            }

            div { class: "work-list", role: "list", aria_label: console_text(locale, "Prioritized work queue", "คิวงานตามลำดับความสำคัญ"),
                if loading {
                    for _ in 0..6 { article { class: "work-row work-row-loading", Skeleton { lines: 2 } } }
                } else if error.is_some() {
                    EmptyState {
                        title: console_text(locale, "Work queue unavailable", "คิวงานไม่พร้อมใช้งาน").to_owned(),
                        message: console_text(locale, "Your shell remains available. Retry when the authorized work sources recover.", "คุณยังใช้ส่วนหลักของระบบได้ โปรดลองอีกครั้งเมื่อแหล่งข้อมูลงานกลับมาพร้อมใช้").to_owned(),
                        action: Some(rsx! { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", onclick: move |_| on_retry.call(()), {console_text(locale, "Retry", "ลองอีกครั้ง")} } }),
                    }
                } else if items.is_empty() {
                    EmptyState {
                        title: console_text(locale, "No work in this view", "ไม่มีงานในมุมมองนี้").to_owned(),
                        message: console_text(locale, "No authoritative active items matched these filters.", "ไม่มีงานที่เปิดอยู่จากแหล่งข้อมูลที่เชื่อถือได้ตรงกับตัวกรองนี้").to_owned(),
                    }
                } else {
                    for item in items {
                        {
                            let detail = item.clone();
                            let path = item.target.route.path().to_owned();
                            let due = item.due_at.clone().unwrap_or_else(|| work_sla_copy(locale, item.sla).to_owned());
                            let updated = item.updated_at.clone().unwrap_or_else(|| console_text(locale, "Freshness unavailable", "ไม่ทราบเวลาอัปเดต").to_owned());
                            rsx! {
                                article { class: "work-row", role: "listitem", "data-severity": work_severity_query_value(item.severity),
                                    div { class: "work-row-kind",
                                        span { class: "work-domain", {work_domain_copy(locale, item.domain)} }
                                        StatusBadge { label: work_kind_copy(locale, item.kind).to_owned(), tone: work_severity_tone(item.severity) }
                                    }
                                    KitButton { variant: ButtonVariant::Secondary, size: ButtonSize::Default, class: "work-row-main", r#type: "button", onclick: move |_| selected.set(Some(detail.clone())),
                                        strong { "{item.title}" }
                                        span { "{item.summary}" }
                                    }
                                    div { class: "work-row-owner",
                                        small { {console_text(locale, "Owner", "ผู้รับผิดชอบ")} }
                                        span { {item.assignee.clone().unwrap_or_else(|| console_text(locale, "Unassigned", "ยังไม่มอบหมาย").to_owned())} }
                                    }
                                    div { class: "work-row-time",
                                        StatusBadge { label: work_sla_copy(locale, item.sla).to_owned(), tone: if item.sla == WorkSlaState::Overdue { StatusTone::Danger } else if item.sla == WorkSlaState::DueToday { StatusTone::Warning } else { StatusTone::Neutral } }
                                        time { title: updated, "{due}" }
                                    }
                                    KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button work-row-action", r#type: "button", onclick: move |_| on_navigate.call(path.clone()),
                                        {console_text(locale, "Open", "เปิด")}
                                    }
                                }
                            }
                        }
                    }
                }
            }

            if let Some(cursor) = next_cursor {
                div { class: "work-pagination",
                    KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", onclick: move |_| on_next.call(cursor.clone()), {console_text(locale, "Next page", "หน้าถัดไป")} }
                }
            }

            if !contributions.is_empty() {
                KitDisclosure { class: "work-source-details",
                    summary { {console_text(locale, "Data source status", "สถานะแหล่งข้อมูล")} }
                    div { class: "work-source-grid",
                        for source in contributions {
                            article {
                                strong { {work_domain_copy(locale, source.domain)} }
                                StatusBadge {
                                    label: work_availability_copy(locale, source.availability).to_owned(),
                                    tone: if source.availability == ReadModelAvailability::Unavailable { StatusTone::Warning } else { StatusTone::Neutral },
                                }
                                span { "{source.label}" }
                                small { "{source.message}" }
                            }
                        }
                    }
                }
            }

            if let Some(item) = selected_item {
                {
                    let target = item.target.route.path().to_owned();
                    rsx! {
                        Drawer { open: true, title: item.title.clone(), on_close: move |_| selected.set(None),
                            div { class: "work-drawer-summary",
                                div { class: "work-drawer-badges",
                                    StatusBadge { label: work_domain_copy(locale, item.domain).to_owned(), tone: StatusTone::Neutral }
                                    StatusBadge { label: work_severity_copy(locale, item.severity).to_owned(), tone: work_severity_tone(item.severity) }
                                    StatusBadge { label: work_sla_copy(locale, item.sla).to_owned(), tone: if item.sla == WorkSlaState::Overdue { StatusTone::Danger } else { StatusTone::Neutral } }
                                }
                                p { "{item.summary}" }
                                dl {
                                    dt { {console_text(locale, "Status", "สถานะ")} } dd { "{item.status_label}" }
                                    dt { {console_text(locale, "Owner", "ผู้รับผิดชอบ")} } dd { {item.assignee.clone().unwrap_or_else(|| console_text(locale, "Unassigned", "ยังไม่มอบหมาย").to_owned())} }
                                    dt { {console_text(locale, "Due / SLA", "กำหนด / SLA")} } dd { {item.due_at.clone().unwrap_or_else(|| work_sla_copy(locale, item.sla).to_owned())} }
                                }
                            }
                            section { class: "work-drawer-section",
                                h3 { {console_text(locale, "Business context", "บริบททางธุรกิจ")} }
                                p { {console_text(locale, "This item comes from an authoritative domain read model for the active role and scope.", "รายการนี้มาจากแบบจำลองการอ่านของโดเมนที่เชื่อถือได้สำหรับบทบาทและขอบเขตปัจจุบัน")} }
                            }
                            section { class: "work-drawer-section",
                                h3 { {console_text(locale, "Activity", "กิจกรรม")} }
                                ol { class: "work-audit-timeline",
                                    li { strong { {console_text(locale, "Latest source update", "อัปเดตล่าสุดจากแหล่งข้อมูล")} } time { {item.updated_at.clone().unwrap_or_else(|| console_text(locale, "Time unavailable", "ไม่ทราบเวลา").to_owned())} } }
                                    li { strong { {console_text(locale, "Added to prioritized queue", "เพิ่มในคิวตามลำดับความสำคัญ")} } span { {work_sla_copy(locale, item.sla)} } }
                                }
                            }
                            section { class: "work-drawer-section",
                                h3 { {console_text(locale, "Related record", "ระเบียนที่เกี่ยวข้อง")} }
                                p { {console_text(locale, "Open the authorized workspace to review the full record and available commands.", "เปิดพื้นที่ทำงานที่ได้รับอนุญาตเพื่อตรวจระเบียนฉบับเต็มและคำสั่งที่ใช้ได้")} }
                            }
                            KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button work-drawer-primary", r#type: "button", onclick: move |_| on_navigate.call(target.clone()), {console_text(locale, "Open authorized record", "เปิดระเบียนที่ได้รับอนุญาต")} }
                        }
                    }
                }
            }
        }
    }
}

