    let mut customer_note_busy = use_signal(|| false);
    let mut customer_note_message = use_signal(|| None::<String>);
    let on_add_customer_note = move |(customer_id, title, content_object_ref, content_sha256): (
        String,
        String,
        String,
        String,
    )| {
        let (access_token, principal_ref, session_id, scope_key) = {
            let controller = auth.read();
            (
                controller
                    .request_credential()
                    .map(|token| token.as_str().to_owned()),
                controller
                    .metadata()
                    .and_then(|metadata| metadata.principal_label.clone()),
                controller
                    .session_id()
                    .map(|session| session.as_str().to_owned()),
                controller
                    .metadata()
                    .and_then(|metadata| metadata.scope_label.clone()),
            )
        };
        let (Some(access_token), Some(principal_ref), Some(session_id), Some(scope_key)) =
            (access_token, principal_ref, session_id, scope_key)
        else {
            customer_note_message.set(Some(
                "Select an exact Company or Branch role before adding a customer note.".into(),
            ));
            return;
        };
        customer_note_busy.set(true);
        customer_note_message.set(None);
        let mut busy_for_task = customer_note_busy;
        let mut message_for_task = customer_note_message;
        let mut detail_for_task = customer_360_detail;
        let mut cursor_for_task = customer_notes_cursor;
        spawn(async move {
            let result = execute_customer_note_command(CustomerNoteCommandInput {
                customer_id,
                title,
                content_object_ref,
                content_sha256,
                scope_key,
                access_token,
                principal_ref,
                session_id,
            })
            .await;
            busy_for_task.set(false);
            message_for_task.set(Some(match result {
                    Ok(receipt) => {
                        cursor_for_task.set(None);
                        detail_for_task.restart();
                        let replay = if receipt.replayed {
                            console_text(locale, " (idempotent replay)", " (ส่งซ้ำโดยไม่สร้างรายการเพิ่ม)")
                        } else {
                            ""
                        };
                        match locale {
                            Locale::En => format!(
                                "Customer note {} committed at version {}{} · event {} · correlation {}.",
                                receipt.aggregate_id,
                                receipt.aggregate_version,
                                replay,
                                receipt.event_id,
                                receipt.correlation_id,
                            ),
                            Locale::Th => format!(
                                "บันทึกลูกค้า {} ถูกบันทึกที่เวอร์ชัน {}{} · เหตุการณ์ {} · สหสัมพันธ์ {}",
                                receipt.aggregate_id,
                                receipt.aggregate_version,
                                replay,
                                receipt.event_id,
                                receipt.correlation_id,
                            ),
                        }
                    }
                    Err(error) => customer_note_error_message(&error).to_string(),
                }));
        });
    };

