#[component]
fn PlatformSettingsView(
    settings: Option<PlatformSettingsRecord>,
    loading: bool,
    error: Option<String>,
    brand: Option<PlatformBrandEditorRecord>,
    brand_loading: bool,
    brand_error: Option<String>,
    brand_busy: bool,
    brand_message: Option<String>,
    on_brand_action: EventHandler<CorporateIdentityEditorAction>,
) -> Element {
    let locale = use_locale().current();
    let architecture = if loading {
        rsx! {
            StatePanel {
                state: UiStateKind::Loading,
                title: console_text(locale, "Loading platform settings", "กำลังโหลดการตั้งค่าแพลตฟอร์ม").to_string(),
                message: console_text(locale, "Fetching the safe ERPX architecture settings projection.", "กำลังดึงข้อมูลการตั้งค่าสถาปัตยกรรม ERPX ที่ปลอดภัย").to_string(),
                action_label: None,
                on_action: None,
            }
        }
    } else if let Some(error) = error {
        rsx! {
            StatePanel {
                state: if error == "authentication_required" { UiStateKind::Denied } else { UiStateKind::Error },
                title: console_text(locale, "Platform settings unavailable", "การตั้งค่าแพลตฟอร์มไม่พร้อมใช้งาน").to_string(),
                message: console_text(locale, "The server did not provide a safe settings read model.", "เซิร์ฟเวอร์ไม่ได้ส่งแบบจำลองการอ่านการตั้งค่าที่ปลอดภัย").to_string(),
                action_label: None,
                on_action: None,
            }
        }
    } else if let Some(settings) = settings {
        rsx! {
            section { class: "projection-detail", aria_label: console_text(locale, "Platform settings", "การตั้งค่าแพลตฟอร์ม"),
                div { class: "projection-meta", {console_text(locale, "Authoritative architecture settings · read-only", "การตั้งค่าสถาปัตยกรรมที่เป็นข้อยุติ · อ่านอย่างเดียว")} }
                dl { class: "detail-grid",
                    dt { {console_text(locale, "Contract version", "เวอร์ชันสัญญา")} } dd { "{settings.contract_version}" }
                    dt { {console_text(locale, "Transport", "การขนส่งข้อมูล")} } dd { "{settings.transport}" }
                    dt { {console_text(locale, "Tenant isolation", "การแยกผู้เช่า")} } dd { "{settings.tenant_isolation}" }
                    dt { {console_text(locale, "Aggregate authority", "อำนาจของแอกกริเกต")} } dd { "{settings.aggregate_authority}" }
                    dt { {console_text(locale, "Billing authority", "อำนาจการเรียกเก็บเงิน")} } dd { "{settings.billing_authority}" }
                    dt { {console_text(locale, "Storage authority", "อำนาจการจัดเก็บ")} } dd { "{settings.storage_authority}" }
                    dt { {console_text(locale, "Command owner", "เจ้าของคำสั่ง")} } dd { "{settings.command_owner}" }
                }
                div { class: "audit-banner", {console_text(locale, "This is a read-only architecture projection. It does not expose environment values, secrets, credentials, mutable feature flags, or operational commands.", "นี่คือภาพฉายสถาปัตยกรรมแบบอ่านอย่างเดียว ซึ่งไม่เปิดเผยค่าสภาพแวดล้อม ข้อมูลลับ ข้อมูลประจำตัว แฟล็กคุณลักษณะที่แก้ไขได้ หรือคำสั่งปฏิบัติการ")} }
                if brand_loading {
                    div { class: "status-banner muted", {console_text(locale, "Loading governed platform identity…", "กำลังโหลดอัตลักษณ์แพลตฟอร์มที่มีการกำกับดูแล…")} }
                } else if let Some(error) = brand_error {
                    div { class: "status-banner bad", role: "alert", {console_text(locale, "Corporate identity unavailable", "อัตลักษณ์องค์กรไม่พร้อมใช้งาน")} " · {error}" }
                } else if let Some(brand) = brand {
                    CorporateIdentityEditor {
                        scope_label: console_text(locale, "Layer 1 · ERPX Platform", "ระดับ 1 · แพลตฟอร์ม ERPX").to_owned(),
                        profile: brand.identity,
                        parent_locked_categories: Vec::new(),
                        editable: !brand_busy,
                        on_action: Some(on_brand_action),
                    }
                }
                if let Some(message) = brand_message {
                    div { class: "audit-banner", role: "status", "{message}" }
                }
            }
        }
    } else {
        rsx! {
            StatePanel {
                state: UiStateKind::Empty,
                title: console_text(locale, "Platform settings not loaded", "ยังไม่ได้โหลดการตั้งค่าแพลตฟอร์ม").to_string(),
                message: console_text(locale, "Open this route with an authenticated Platform session.", "เปิดเส้นทางนี้ด้วยเซสชันแพลตฟอร์มที่ยืนยันตัวตนแล้ว").to_string(),
                action_label: None,
                on_action: None,
            }
        }
    };

    rsx! {
        div { class: "platform-settings-stack",
            DeviceLanguagePreference {}
            {architecture}
        }
    }
}

#[component]
fn PlatformBackupJobList(
    jobs: Option<Vec<PlatformBackupJobRecord>>,
    loading: bool,
    error: Option<String>,
) -> Element {
    if loading {
        return rsx! {
            StatePanel {
                state: UiStateKind::Loading,
                title: localized_copy("Loading backup history", "การโหลดประวัติสำรองข้อมูล").to_string(),
                message: localized_copy("Fetching the audited control-plane backup history.", "การดึงประวัติสำรองcontrol-plane หลังจากการตรวจสอบ").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    }
    if let Some(error) = error {
        return rsx! {
            StatePanel {
                state: if error == "authentication_required" { UiStateKind::Denied } else { UiStateKind::Error },
                title: localized_copy("Backup history unavailable", "ประวัติการสำรองไม่มีให้บริการ").to_string(),
                message: localized_copy("The server did not provide a safe backup-history read model.", "เซิร์ฟเวอร์ไม่ให้โมเดลการอ่านประวัติสำรองปลอดภัย").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    }
    let Some(jobs) = jobs else {
        return rsx! {
            StatePanel {
                state: UiStateKind::Empty,
                title: localized_copy("Backup history not loaded", "ประวัติการสำรองไม่ได้โหลด").to_string(),
                message: localized_copy("Open this route with an authenticated Platform session.", "เปิดเส้นทางนี้ด้วยการเข้าสู่ระบบแพลตฟอร์ม").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    };
    if jobs.is_empty() {
        return rsx! {
            StatePanel {
                state: UiStateKind::Empty,
                title: localized_copy("No backup jobs", "ไม่มีงานสำรอง").to_string(),
                message: localized_copy("The authorized control-plane read model returned no backup history rows.", "โมเดลอ่านของระนาบควบคุมที่ได้รับสิทธิ์ไม่คืนแถวประวัติการสำรองข้อมูล").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    }
    rsx! {
        section { class: "projection-detail", aria_label: localized_copy("Platform backup history", "ประวัติสำรองข้อมูลของแพลตฟอร์ม"),
            div { class: "projection-meta", {match active_console_locale() { Locale::En => format!("Authorized backup history · {arg0} rows · read-only", arg0 = jobs.len()), Locale::Th => format!("ประวัติการสำรองข้อมูลที่ได้รับสิทธิ์ · {arg0} แถว · อ่านอย่างเดียว", arg0 = jobs.len()) }} }
            div { class: "table-wrap",
                KitTable { class: "data-table",
                    thead {
                        tr {
                            th { {localized_copy("Tenant", "ลูกค้า")} }
                            th { {localized_copy("Job", "งาน")} }
                            th { {localized_copy("Kind", "ประเภท")} }
                            th { {localized_copy("State", "สถานะ")} }
                            th { { {localized_copy("Available", "พร้อมใช้งาน")} } }
                            th { {localized_copy("Attempts", "การพยายาม")} }
                            th { {localized_copy("Verified", "ได้รับการยืนยัน")} }
                            th { { {localized_copy("Error", "ข้อผิดพลาด")} } }
                            th { {localized_copy("Updated", "อัปเดต")} }
                        }
                    }
                    tbody {
                        for job in jobs {
                            tr {
                                td { "{job.tenant_id}" }
                                td { "{job.job_id}" }
                                td { "{job.kind}" }
                                td { "{display_status(&job.state)}" }
                                td { "{display_timestamp(&job.available_at)}" }
                                td { "{job.attempts}/{job.max_attempts}" }
                                td { if job.verified { {localized_copy("yes", "ใช่")} } else { {localized_copy("no", "ไม่")} } }
                                td { if job.error_present { {localized_copy("present", "พบข้อผิดพลาด")} } else { {localized_copy("none", "ไม่มี")} } }
                                td { "{display_timestamp(&job.updated_at)}" }
                            }
                        }
                    }
                }
            }
            div { class: "audit-banner", {localized_copy("Only bounded job state is rendered. Backup object references, restore targets, database keys, credentials, and raw error text remain outside this client contract.", "แสดงเฉพาะสถานะงานที่จำกัดเท่านั้น การอ้างอิงวัตถุสำรองข้อมูล เป้าหมายการกู้คืน คีย์ฐานข้อมูล ข้อมูลรับรอง และข้อความข้อผิดพลาดดิบยังคงอยู่นอกขอบเขตสัญญาไคลเอนต์นี้")} }
        }
    }
}

#[component]
fn PlatformTenantList(
    tenants: Option<Vec<PlatformTenantRecord>>,
    loading: bool,
    error: Option<String>,
    on_navigate: EventHandler<PlatformOperationsRoute>,
    on_retry: EventHandler<MouseEvent>,
) -> Element {
    if loading {
        return rsx! {
            StatePanel {
                state: UiStateKind::Loading,
                title: localized_copy("Loading tenants", "การโหลดที่อยู่อาศัย").to_string(),
                message: localized_copy("Fetching the audited Platform Operations tenant projection.", "การดึงโพรเจกชันtenant Operations Platform หลังจากการตรวจสอบ").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    }
    if let Some(error) = error {
        let state = tenant_admin_error_state(&error);
        let denied = state == UiStateKind::Denied;
        return rsx! {
            StatePanel {
                state,
                title: if denied {
                    localized_copy("Select a Platform persona", "เลือกบทบาทแพลตฟอร์ม").to_string()
                } else {
                    localized_copy("Tenant projection unavailable", "ภาพรวมของลูกค้าไม่มีให้ใช้งาน").to_string()
                },
                message: if denied {
                    localized_copy("Select an active role with Platform tenant read access, then retry.", "เลือกบทบาทที่ใช้งานซึ่งมีสิทธิ์อ่าน tenant ของแพลตฟอร์ม แล้วลองอีกครั้ง").to_string()
                } else {
                    localized_copy("The server did not provide a safe tenant operations projection.", "เซิร์ฟเวอร์ไม่ให้ภาพรวมการดำเนินงานของผู้เช่าที่ปลอดภัย").to_string()
                },
                action_label: Some(localized_copy("Retry tenant read", "ลองอ่านข้อมูลผู้เช่าอีกครั้ง").to_string()),
                on_action: Some(on_retry),
            }
        };
    }
    let Some(tenants) = tenants else {
        return rsx! {
            StatePanel {
                state: UiStateKind::Empty,
                title: localized_copy("Tenant projection not loaded", "ภาพรวมของลูกค้าไม่ได้โหลด").to_string(),
                message: localized_copy("Open the Tenants route with an authenticated Platform session.", "เปิดเส้นทางผู้ใช้ด้วยการเข้าสู่ระบบแพลตฟอร์ม").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    };
    if tenants.is_empty() {
        return rsx! {
            StatePanel {
                state: UiStateKind::Empty,
                title: localized_copy("No tenants", "ไม่มีผู้เช่า").to_string(),
                message: localized_copy("The authorized control-plane registry returned no tenant records.", "ทะเบียนระนาบควบคุมที่ได้รับสิทธิ์ไม่คืนบันทึกผู้เช่า").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    }
    rsx! {
        section { class: "projection-detail", aria_label: localized_copy("Platform tenant list", "รายการผู้เช่าของแพลตฟอร์ม"),
            div { class: "projection-meta", {match active_console_locale() { Locale::En => format!("Authorized tenant registry · {arg0} records · read-only", arg0 = tenants.len()), Locale::Th => format!("ทะเบียนผู้เช่าที่ได้รับอนุญาต · {arg0} รายการ · อ่านเฉพาะ", arg0 = tenants.len()) }} }
            div { class: "table-wrap tenant-registry-table-wrap",
                KitTable { class: "data-table tenant-registry-table", aria_label: localized_copy("Authorized tenant registry", "ทะเบียนผู้เช่าที่ได้รับอนุญาต"),
                    thead {
                        tr {
                            th { {localized_copy("Tenant", "ลูกค้า")} }
                            th { { {localized_copy("Configuration", "การกำหนดค่า")} } }
                            th { {localized_copy("Subscription", "การสมัครใช้งาน")} }
                            th { { {localized_copy("Plan & modules", "แผนและโมดูล")} } }
                            th { { {localized_copy("Capacity", "ความจุ")} } }
                            th { { {localized_copy("Renewal", "การต่ออายุ")} } }
                            th { { {localized_copy("Operational health", "สถานะการดำเนินงาน")} } }
                        }
                    }
                    tbody {
                        for tenant in tenants {
                            {
                                let tenant_id = tenant.tenant_id.clone();
                                let enabled_modules = tenant.enabled_modules.join(", ");
                                let module_count = tenant.enabled_modules.len();
                                let module_summary = match active_console_locale() {
                                    Locale::En => format!("{module_count} modules"),
                                    Locale::Th => format!("{module_count} โมดูล"),
                                };
                                rsx! {
                                    tr {
                                        td { class: "tenant-registry-identity",
                                            KitButton { size: ButtonSize::Sm,
                                                variant: ButtonVariant::Link,
                                                r#type: "button",
                                                onclick: move |_| {
                                                    if let Ok(tenant_id) = PlatformTenantId::new(tenant_id.clone()) {
                                                        on_navigate.call(PlatformOperationsRoute::Tenant { tenant_id });
                                                    }
                                                },
                                                "{tenant.tenant_id}"
                                            }
                                            span { class: "tenant-registry-secondary",
                                                if tenant.customer_name.is_empty() { {localized_copy("Unbound", "ยังไม่ผูกลูกค้า")} } else { "{tenant.customer_name}" }
                                            }
                                        }
                                        td { class: "tenant-registry-stack",
                                            strong { "{display_status(&tenant.state)}" }
                                            span { "{tenant.configuration_state}" }
                                        }
                                        td { class: "tenant-registry-nowrap", "{tenant.subscription_state}" }
                                        td { class: "tenant-registry-plan",
                                            strong { if tenant.plan_key.is_empty() { "—" } else { "{tenant.plan_key}" } }
                                            KitDisclosure { class: "tenant-registry-details",
                                                summary { "{module_summary}" }
                                                div { class: "tenant-registry-detail-copy",
                                                    if enabled_modules.is_empty() { {localized_copy("No modules enabled", "ยังไม่ได้เปิดโมดูล")} } else { "{enabled_modules}" }
                                                }
                                            }
                                        }
                                        td { class: "tenant-registry-capacity",
                                            span { strong { {localized_copy("Seats", "ที่นั่ง")} } " {tenant.used_seats}/{tenant.purchased_seats}" }
                                            span { strong { {localized_copy("Companies / branches", "บริษัท / สาขา")} } " {tenant.company_count}/{tenant.branch_count}" }
                                        }
                                        td { class: "tenant-registry-renewal", if tenant.renewal_at.is_empty() { "—" } else { "{display_timestamp(&tenant.renewal_at)}" } }
                                        td { class: "tenant-registry-health",
                                            span { class: "status-pill {tone(&tenant.health)}", "{display_status(&tenant.health)}" }
                                            KitDisclosure { class: "tenant-registry-details",
                                                summary { {localized_copy("View 4 signals", "ดู 4 สัญญาณ")} }
                                                dl { class: "tenant-registry-signals",
                                                    div { dt { {localized_copy("Projection", "โพรเจกชัน")} } dd { "{tenant.projection}" } }
                                                    div { dt { {localized_copy("Backup", "สำรองข้อมูล")} } dd { "{tenant.backup_pitr}" } }
                                                    div { dt { {localized_copy("Storage", "พื้นที่จัดเก็บ")} } dd { "{tenant.storage}" } }
                                                    div { dt { {localized_copy("Integrations", "การเชื่อมต่อ")} } dd { "{tenant.integration_health}" } }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            div { class: "audit-banner", {localized_copy("This page is backed by one rebuildable control-plane projection. It never opens tenant databases or combines tenant business records. Configuration-required tenants remain visible but cannot be entered or billed.", "หน้านี้สนับสนุนโดยการโปรเจกชันควบคุมระดับผู้เช่าที่สามารถสร้างใหม่ได้ มันไม่มีวันเปิดฐานข้อมูลของผู้เช่าหรือรวมบันทึกธุรกิจของผู้เช่า ผู้เช่าที่ต้องการกำหนดค่าจะปรากฏอยู่แต่ไม่สามารถเข้าถึงหรือเรียกเก็บเงินได้")} }
        }
    }
}

#[component]
fn PlatformTenantIdentityPanel(
    tenant_id: String,
    root_holding_id: String,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    administrative_context: Option<TenantAdminContextModel>,
) -> Element {
    let resource_access_token = access_token.clone();
    let resource_principal_ref = principal_ref.clone();
    let resource_session_id = session_id.clone();
    let resource_holding_id = root_holding_id.clone();
    let mut directory = use_resource(move || {
        let access_token = resource_access_token.clone();
        let principal_ref = resource_principal_ref.clone();
        let session_id = resource_session_id.clone();
        let holding_id = resource_holding_id.clone();
        async move {
            Uuid::parse_str(&holding_id)
                .map_err(|_| "tenant_configuration_incomplete".to_owned())?;
            let (Some(access_token), Some(principal_ref), Some(session_id)) =
                (access_token, principal_ref, session_id)
            else {
                return Err("authentication_required".to_owned());
            };
            fetch_directory_administration(access_token, principal_ref, session_id, holding_id)
                .await
        }
    });
    let identity_scope = TenantGovernanceScope::validate(&tenant_id, &root_holding_id);
    let identity_resource_scope = identity_scope.clone();
    let identity_resource_access_token = access_token.clone();
    let identity_resource_principal_ref = principal_ref.clone();
    let identity_resource_session_id = session_id.clone();
    let mut identity_workspace = use_resource(move || {
        let scope = identity_resource_scope.clone();
        let access_token = identity_resource_access_token.clone();
        let principal_ref = identity_resource_principal_ref.clone();
        let session_id = identity_resource_session_id.clone();
        async move {
            let scope = scope?;
            let (Some(access_token), Some(principal_ref), Some(session_id)) =
                (access_token, principal_ref, session_id)
            else {
                return Err("authentication_required".to_owned());
            };
            fetch_identity_access_workspace(scope, access_token, principal_ref, session_id).await
        }
    });
    let mut identity_busy = use_signal(|| false);
    let mut identity_message = use_signal(|| None::<Result<String, String>>);
    let identity_action_scope = identity_scope.clone();
    let identity_action_access_token = access_token.clone();
    let identity_action_principal_ref = principal_ref.clone();
    let identity_action_session_id = session_id.clone();
    let on_identity_action = EventHandler::new(move |action: IdentityAccessConsoleAction| {
        let (Ok(scope), Some(access_token), Some(principal_ref), Some(session_id)) = (
            identity_action_scope.clone(),
            identity_action_access_token.clone(),
            identity_action_principal_ref.clone(),
            identity_action_session_id.clone(),
        ) else {
            identity_message.set(Some(Err("authentication_required".to_owned())));
            return;
        };
        identity_busy.set(true);
        identity_message.set(None);
        let mut identity_busy = identity_busy;
        let mut identity_message = identity_message;
        let mut identity_workspace = identity_workspace;
        spawn(async move {
            let result = submit_identity_access_action(
                scope,
                access_token,
                principal_ref,
                session_id,
                action,
            )
            .await;
            identity_busy.set(false);
            identity_message.set(Some(result));
            identity_workspace.restart();
        });
    });
    let mut busy = use_signal(|| false);
    let mut message = use_signal(|| None::<String>);
    let command_access_token = access_token.clone();
    let command_principal_ref = principal_ref.clone();
    let command_session_id = session_id.clone();
    let command_holding_id = root_holding_id.clone();
    let context_active = administrative_context.as_ref().is_some_and(|context| {
        context.active
            && context.tenant_id == tenant_id
            && context.root_holding_id == root_holding_id
    });
    let administrative_context_id = administrative_context
        .as_ref()
        .filter(|context| context_active && context.active)
        .map(|context| context.administrative_context_id.clone());
    let on_command = EventHandler::new(move |command: DirectoryAdministrationCommand| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            command_access_token.clone(),
            command_principal_ref.clone(),
            command_session_id.clone(),
        ) else {
            message.set(Some("authentication_required".into()));
            return;
        };
        if !context_active {
            message.set(Some("tenant_context_required".into()));
            return;
        }
        busy.set(true);
        message.set(None);
        let holding_id = command_holding_id.clone();
        let administrative_context_id = administrative_context_id.clone();
        let mut busy_for_task = busy;
        let mut message_for_task = message;
        let mut directory_for_task = directory;
        spawn(async move {
            let result = execute_directory_administration_command(
                command,
                access_token,
                principal_ref,
                session_id,
                holding_id,
                administrative_context_id,
            )
            .await;
            busy_for_task.set(false);
            message_for_task.set(Some(match result {
                Ok(message) => {
                    directory_for_task.restart();
                    message
                }
                Err(error) => format!("Directory command failed: {error}."),
            }));
        });
    });
    let identity_panel = rsx! {
        IdentityAccessAdminPanel {
            workspace: identity_workspace.read().clone(),
            busy: *identity_busy.read(),
            message: identity_message.read().clone(),
            on_refresh: move |_| identity_workspace.restart(),
            on_action: on_identity_action,
        }
    };
    let snapshot = directory.read().clone();
    match snapshot {
        None => rsx! {
            {identity_panel}
            StatePanel { state: UiStateKind::Loading, title: localized_copy("Loading tenant directory", "กำลังโหลด directory ของ tenant").to_owned(), message: localized_copy("Reading connector, reconciliation, role mapping, and identity-link state.", "กำลังอ่านสถานะ connector, reconciliation, role mapping และ identity link").to_owned(), action_label: None, on_action: None }
        },
        Some(Err(error)) => {
            let state = directory_error_state(&error);
            let denied = state == UiStateKind::Denied;
            rsx! {
                {identity_panel}
                StatePanel {
                    state,
                    title: if denied { localized_copy("Directory access denied", "ปฏิเสธการเข้าถึง directory").to_owned() } else { localized_copy("Tenant directory unavailable", "directory ของ tenant ไม่พร้อมใช้งาน").to_owned() },
                    message: localized_copy("The holding-scoped DirectoryService read model could not be loaded.", "ไม่สามารถโหลด read model ของ DirectoryService ที่ scoped ตาม holding ได้").to_owned(),
                    action_label: Some(localized_copy("Retry directory", "ลองโหลด directory อีกครั้ง").to_owned()),
                    on_action: Some(EventHandler::new(move |_| directory.restart())),
                }
            }
        }
        Some(Ok(model)) => rsx! {
            {identity_panel}
            DirectoryAdministrationSurface { model }
            if context_active {
                DirectoryAdministrationCommandPanel {
                    busy: *busy.read(),
                    message: message.read().clone(),
                    on_command,
                }
            } else {
                StatePanel { state: UiStateKind::Denied, title: localized_copy("Administrative context required for changes", "ต้องมีบริบทการดูแลสำหรับการแก้ไข").to_owned(), message: localized_copy("Directory reads remain available. Begin an MFA-gated tenant context from Overview before saving or activating a connector.", "ยังอ่าน directory ได้ แต่ต้องเริ่มบริบท tenant ที่ผ่าน MFA จาก Overview ก่อนบันทึกหรือ activate connector").to_owned(), action_label: None, on_action: None }
            }
        },
    }
}

#[component]
fn PlatformTenantCorporateIdentityPanel(
    tenant_id: String,
    root_holding_id: String,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    administrative_context: Option<TenantAdminContextModel>,
) -> Element {
    let scope = TenantGovernanceScope::validate(&tenant_id, &root_holding_id);
    let resource_scope = scope.clone();
    let resource_access_token = access_token.clone();
    let resource_principal_ref = principal_ref.clone();
    let resource_session_id = session_id.clone();
    let mut brand = use_resource(move || {
        let scope = resource_scope.clone();
        let access_token = resource_access_token.clone();
        let principal_ref = resource_principal_ref.clone();
        let session_id = resource_session_id.clone();
        async move {
            let scope = scope?;
            let (Some(access_token), Some(principal_ref), Some(session_id)) =
                (access_token, principal_ref, session_id)
            else {
                return Err("authentication_required".to_owned());
            };
            fetch_tenant_brand_editor(scope, access_token, principal_ref, session_id).await
        }
    });
    let mut busy = use_signal(|| false);
    let mut message = use_signal(|| None::<Result<String, String>>);
    let snapshot = brand.read().clone();
    let action_record = snapshot
        .as_ref()
        .and_then(|result| result.as_ref().ok())
        .cloned();
    let action_scope = scope.clone();
    let action_access_token = access_token.clone();
    let action_principal_ref = principal_ref.clone();
    let action_session_id = session_id.clone();
    let administrative_context_id = administrative_context.as_ref().and_then(|context| {
        (context.active
            && context.tenant_id == tenant_id
            && context.root_holding_id == root_holding_id)
            .then(|| context.administrative_context_id.clone())
    });
    let action_administrative_context_id = administrative_context_id.clone();
    let on_action = EventHandler::new(move |action: CorporateIdentityEditorAction| {
        let (
            Ok(scope),
            Some(record),
            Some(access_token),
            Some(principal_ref),
            Some(session_id),
            Some(administrative_context_id),
        ) = (
            action_scope.clone(),
            action_record.clone(),
            action_access_token.clone(),
            action_principal_ref.clone(),
            action_session_id.clone(),
            action_administrative_context_id.clone(),
        )
        else {
            message.set(Some(Err("authorization_denied".to_owned())));
            return;
        };
        busy.set(true);
        message.set(None);
        let mut busy_for_task = busy;
        let mut message_for_task = message;
        let mut brand_for_task = brand;
        spawn(async move {
            let result = mutate_tenant_brand(
                scope,
                Some(administrative_context_id),
                access_token,
                principal_ref,
                session_id,
                record,
                action,
            )
            .await;
            busy_for_task.set(false);
            message_for_task.set(Some(result));
            brand_for_task.restart();
        });
    });

    match snapshot {
        None => rsx! {
            StatePanel { state: UiStateKind::Loading, title: localized_copy("Loading corporate identity", "กำลังโหลดอัตลักษณ์องค์กร").to_owned(), message: localized_copy("Reading the resolved identity and server-owned draft.", "กำลังอ่านอัตลักษณ์ที่ resolve แล้วและ draft ที่เซิร์ฟเวอร์เป็นเจ้าของ").to_owned(), action_label: None, on_action: None }
        },
        Some(Err(error)) => {
            let state = tenant_admin_error_state(&error);
            let denied = state == UiStateKind::Denied;
            rsx! {
                StatePanel {
                    state,
                    title: if denied { localized_copy("Corporate identity access denied", "ปฏิเสธการเข้าถึงอัตลักษณ์องค์กร").to_owned() } else { localized_copy("Corporate identity unavailable", "อัตลักษณ์องค์กรไม่พร้อมใช้งาน").to_owned() },
                    message: localized_copy("The resolved identity and draft could not be loaded for this tenant.", "ไม่สามารถโหลดอัตลักษณ์ที่ resolve แล้วและ draft ของ tenant นี้ได้").to_owned(),
                    action_label: Some(localized_copy("Retry identity", "ลองโหลดอัตลักษณ์อีกครั้ง").to_owned()),
                    on_action: Some(EventHandler::new(move |_| brand.restart())),
                }
            }
        }
        Some(Ok(record)) => {
            let parent_locked_categories = record
                .identity
                .locked_categories
                .iter()
                .copied()
                .collect::<Vec<_>>();
            rsx! {
                if *busy.read() {
                    div { class: "status-banner muted", {localized_copy("Saving corporate identity…", "กำลังบันทึกอัตลักษณ์องค์กร…")} }
                }
                if let Some(result) = message.read().as_ref() {
                    div { class: if result.is_ok() { "status-banner good" } else { "status-banner bad" },
                        {match result { Ok(value) => value.clone(), Err(error) => tenant_admin_error_message(error).to_owned() }}
                    }
                }
                CorporateIdentityEditor {
                    scope_label: format!("Layer 2 · {tenant_id}"),
                    profile: record.identity,
                    parent_locked_categories,
                    editable: !*busy.read() && administrative_context_id.is_some(),
                    on_action: Some(on_action),
                }
            }
        }
    }
}

#[component]
fn TenantControlHistoryPanel(
    tenant_id: String,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
) -> Element {
    let mut cursor = use_signal(|| None::<(String, String)>);
    let mut history = use_resource(move || {
        let cursor = cursor.read().clone();
        let tenant_id = tenant_id.clone();
        let access_token = access_token.clone();
        let principal_ref = principal_ref.clone();
        let session_id = session_id.clone();
        async move {
            let (Some(access_token), Some(principal_ref), Some(session_id)) =
                (access_token, principal_ref, session_id)
            else {
                return Err("authentication_required".to_owned());
            };
            fetch_tenant_control_history(tenant_id, cursor, access_token, principal_ref, session_id)
                .await
        }
    });
    let snapshot = history.read().clone();
    match snapshot {
        None => rsx! {
            StatePanel {
                state: UiStateKind::Loading,
                title: localized_copy("Loading tenant control history", "กำลังโหลดประวัติการควบคุม tenant").to_owned(),
                message: localized_copy("Reading allow-listed audit and outbox evidence.", "กำลังอ่านหลักฐาน audit และ outbox ที่อยู่ในรายการอนุญาต").to_owned(),
                action_label: None,
                on_action: None,
            }
        },
        Some(Err(error)) => {
            let state = tenant_admin_error_state(&error);
            let denied = state == UiStateKind::Denied;
            rsx! {
                StatePanel {
                    state,
                    title: if denied { localized_copy("History access denied", "ปฏิเสธการเข้าถึงประวัติ").to_owned() } else { localized_copy("Tenant history unavailable", "ประวัติ tenant ไม่พร้อมใช้งาน").to_owned() },
                    message: if denied { localized_copy("The active role cannot read tenant control history.", "บทบาทที่ใช้งานไม่มีสิทธิ์อ่านประวัติการควบคุม tenant").to_owned() } else { localized_copy("The safe history projection could not be loaded.", "ไม่สามารถโหลดภาพรวมประวัติที่ปลอดภัยได้").to_owned() },
                    action_label: Some(localized_copy("Retry history", "ลองโหลดประวัติอีกครั้ง").to_owned()),
                    on_action: Some(EventHandler::new(move |_| history.restart())),
                }
            }
        }
        Some(Ok(page)) if page.entries.is_empty() => rsx! {
            StatePanel {
                state: UiStateKind::Empty,
                title: localized_copy("No tenant control history", "ยังไม่มีประวัติการควบคุม tenant").to_owned(),
                message: localized_copy("No allow-listed control events exist for this page.", "ไม่มีเหตุการณ์ควบคุมที่อยู่ในรายการอนุญาตสำหรับหน้านี้").to_owned(),
                action_label: None,
                on_action: None,
            }
        },
        Some(Ok(page)) => {
            let next_cursor = page.next_cursor.clone();
            rsx! {
                section { class: "tenant-config-surface", aria_label: localized_copy("Tenant control history", "ประวัติการควบคุม tenant"),
                    div { class: "eyebrow", {localized_copy("SAFE IMMUTABLE EVIDENCE", "หลักฐานถาวรที่ปลอดภัย")} }
                    h3 { {localized_copy("Tenant control events", "เหตุการณ์ควบคุม tenant")} }
                    KitTable { class: "data-table",
                        thead { tr {
                            th { {localized_copy("Time", "เวลา")} }
                            th { {localized_copy("Category", "หมวดหมู่")} }
                            th { {localized_copy("Action", "การดำเนินการ")} }
                            th { {localized_copy("Version", "เวอร์ชัน")} }
                            th { {localized_copy("Actor", "ผู้ดำเนินการ")} }
                            th { {localized_copy("Correlation", "สหสัมพันธ์")} }
                        } }
                        tbody {
                            for entry in page.entries {
                                tr {
                                    td { "{display_timestamp(&entry.occurred_at)}" }
                                    td { "{entry.event_category}" }
                                    td { "{entry.safe_action}" }
                                    td { if entry.aggregate_version == 0 { "—" } else { "{entry.aggregate_version}" } }
                                    td { "{entry.actor_ref}" }
                                    td { "{entry.correlation_id}" }
                                }
                            }
                        }
                    }
                    if page.has_more {
                        KitButton { size: ButtonSize::Default,
                            variant: ButtonVariant::Secondary, class: "button",
                            r#type: "button",
                            disabled: next_cursor.is_none(),
                            onclick: move |_| cursor.set(next_cursor.clone()),
                            {localized_copy("Next history page", "หน้าประวัติถัดไป")}
                        }
                    }
                    div { class: "audit-banner", {localized_copy("This view never receives raw event payloads, secret references, database keys, or internal error text.", "มุมมองนี้จะไม่ได้รับ payload เหตุการณ์ดิบ การอ้างอิงข้อมูลลับ คีย์ฐานข้อมูล หรือข้อความผิดพลาดภายใน")} }
                }
            }
        }
    }
}

#[component]
fn PlatformTenantDetail(
    tenant: Option<PlatformTenantRecord>,
    loading: bool,
    error: Option<String>,
    infrastructure: Option<TenantInfrastructureRecord>,
    infrastructure_loading: bool,
    infrastructure_error: Option<String>,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    administrative_context: Signal<Option<TenantAdminContextModel>>,
    on_navigate: EventHandler<PlatformOperationsRoute>,
    on_retry: EventHandler<MouseEvent>,
    on_session_refresh: EventHandler<()>,
    on_infrastructure_changed: EventHandler<()>,
) -> Element {
    let locale = active_console_locale();
    let mut active_tab = use_signal(|| PlatformTenantAdministrationTab::Overview);
    let mut show_setup = use_signal(|| false);
    let organization_page = use_signal(|| None::<TenantOrganizationPageModel>);
    let mut tenant_admin_busy = use_signal(|| false);
    let mut tenant_admin_message = use_signal(|| None::<String>);
    let mut tenant_admin_reason = use_signal(String::new);
    let mut tenant_admin_mfa = use_signal(String::new);
    let mut tenant_admin_end_reason = use_signal(move || {
        console_text(
            locale,
            "operator completed tenant administration",
            "ผู้ปฏิบัติงานดำเนินการดูแลผู้เช่าเสร็จแล้ว",
        )
        .to_string()
    });
    if loading {
        return rsx! {
            StatePanel {
                state: UiStateKind::Loading,
                title: localized_copy("Loading tenant detail", "การโหลดรายละเอียดที่อยู่อาศัย").to_string(),
                message: localized_copy("Fetching the audited tenant readiness projection.", "การดึงโพรเจกชันความพร้อมของtenant หลังจากการตรวจสอบ").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    }
    if let Some(error) = error {
        let authentication_required = error == "authentication_required";
        return rsx! {
            StatePanel {
                state: tenant_admin_error_state(&error),
                title: if authentication_required { localized_copy("Session refresh required", "ต้องรีเฟรชเซสชัน").to_string() } else { localized_copy("Tenant detail unavailable", "รายละเอียดผู้เช่าไม่พร้อมใช้งาน").to_string() },
                message: if authentication_required { localized_copy("Your access token expired. Refresh the protected session to request this tenant detail again.", "โทเค็นการเข้าถึงหมดอายุ โปรดรีเฟรชเซสชันที่ได้รับการปกป้องเพื่อขอรายละเอียดผู้เช่าอีกครั้ง").to_string() } else { localized_copy("The server did not provide a safe tenant detail projection. Retry the authorized read.", "เซิร์ฟเวอร์ไม่ส่งโพรเจกชันรายละเอียดผู้เช่าที่ปลอดภัย โปรดลองอ่านข้อมูลที่ได้รับอนุญาตอีกครั้ง").to_string() },
                action_label: Some(if authentication_required { localized_copy("Refresh session", "รีเฟรชเซสชัน").to_string() } else { localized_copy("Retry tenant detail", "ลองโหลดรายละเอียดผู้เช่าอีกครั้ง").to_string() }),
                on_action: Some(if authentication_required { EventHandler::new(move |_| on_session_refresh.call(())) } else { on_retry }),
            }
        };
    }
    let Some(tenant) = tenant else {
        return rsx! {
            StatePanel {
                state: UiStateKind::Empty,
                title: localized_copy("Tenant detail not loaded", "รายละเอียดของลูกค้าไม่ได้โหลด").to_string(),
                message: localized_copy("Open this route with an authenticated Platform session.", "เปิดเส้นทางนี้ด้วยการเข้าสู่ระบบแพลตฟอร์ม").to_string(),
                action_label: None,
                on_action: None,
            }
        };
    };
    let tenant_id_for_action = tenant.tenant_id.clone();
    let tenant_admin_access_token = access_token.clone();
    let tenant_admin_principal_ref = principal_ref.clone();
    let tenant_admin_session_id = session_id.clone();
    let on_tenant_admin_action = EventHandler::new(move |action: TenantAdminAction| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            tenant_admin_access_token.clone(),
            tenant_admin_principal_ref.clone(),
            tenant_admin_session_id.clone(),
        ) else {
            tenant_admin_message.set(Some(
                console_text(
                    locale,
                    "An authenticated platform session is required for tenant administration.",
                    "ต้องมีเซสชันแพลตฟอร์มที่ยืนยันตัวตนแล้วเพื่อดูแลผู้เช่า",
                )
                .into(),
            ));
            return;
        };
        tenant_admin_busy.set(true);
        tenant_admin_message.set(None);
        let tenant_id = tenant_id_for_action.clone();
        let current_context = administrative_context.read().clone();
        let mut context_for_task = administrative_context;
        let mut organization_for_task = organization_page;
        let mut busy_for_task = tenant_admin_busy;
        let mut message_for_task = tenant_admin_message;
        let mut mfa_for_task = tenant_admin_mfa;
        spawn(async move {
            let result = execute_tenant_admin_action(
                tenant_id,
                current_context,
                action,
                access_token,
                principal_ref,
                session_id,
                locale,
            )
            .await;
            busy_for_task.set(false);
            mfa_for_task.set(String::new());
            match result {
                Ok(result) => {
                    if let Some(organization) = result.organization {
                        organization_for_task.set(Some(organization));
                    }
                    if result.context.is_none() {
                        organization_for_task.set(None);
                    }
                    context_for_task.set(result.context);
                    message_for_task.set(Some(result.message));
                }
                Err(error) => {
                    if matches!(
                        error.as_str(),
                        "tenant_context_not_found" | "authorization_denied"
                    ) {
                        context_for_task.set(None);
                        organization_for_task.set(None);
                    }
                    message_for_task.set(Some(tenant_admin_error_message(&error).into()));
                }
            }
        });
    });
    let enabled_modules = tenant.enabled_modules.join(", ");
    let workspace_modules = tenant
        .enabled_modules
        .iter()
        .filter_map(|module| TenantWorkspaceModule::parse(module).ok())
        .collect::<Vec<_>>();
    let selected_tab = *active_tab.read();
    let contextual_tabs = [
        (
            PlatformTenantAdministrationTab::Overview,
            localized_copy("Overview", "ภาพรวม"),
        ),
        (
            PlatformTenantAdministrationTab::Infrastructure,
            localized_copy("Infrastructure", "โครงสร้างพื้นฐาน"),
        ),
        (
            PlatformTenantAdministrationTab::Identity,
            localized_copy("Identity & Access", "ผู้ใช้และสิทธิ์"),
        ),
        (
            PlatformTenantAdministrationTab::CorporateIdentity,
            localized_copy("Corporate Identity", "อัตลักษณ์องค์กร"),
        ),
        (
            PlatformTenantAdministrationTab::BusinessUnits,
            localized_copy("Business Units", "หน่วยธุรกิจ"),
        ),
        (
            PlatformTenantAdministrationTab::RootAccess,
            localized_copy("Root Access", "การเข้าถึง Root"),
        ),
        (
            PlatformTenantAdministrationTab::Organization,
            localized_copy("Organization", "องค์กร"),
        ),
        (
            PlatformTenantAdministrationTab::ConfigurationHistory,
            localized_copy("History", "ประวัติ"),
        ),
    ];
    rsx! {
        section { class: "projection-detail", aria_label: localized_copy("Platform tenant detail", "รายละเอียดผู้เช่าของแพลตฟอร์ม"),
            div { class: "tenant-infrastructure-heading",
                div {
                    div { class: "eyebrow", {localized_copy("TENANT CONTROL PLANE", "ระนาบควบคุมผู้เช่า")} }
                    h3 { "{localized_copy(\"Tenant\", \"ผู้เช่า\")}: {tenant.tenant_id}" }
                    p { if tenant.customer_name.is_empty() { { {localized_copy("Customer binding requires configuration", "การผูกพันลูกค้าต้องการการกำหนดค่า")} } } else { "{tenant.customer_name}" } }
                }
                if let Some(infrastructure) = infrastructure.as_ref() {
                    div { class: "tenant-infrastructure-summary",
                        span { class: "status-pill", if infrastructure.is_customer_hosted() { { {localized_copy("Customer data plane", "ช่องทางข้อมูลลูกค้า")} } } else { { {localized_copy("ERPX managed", "จัดการโดย ERPX")} } } }
                        span { class: if infrastructure.agent_available() || !infrastructure.is_customer_hosted() { "status-pill good" } else { "status-pill bad" },
                            if infrastructure.is_customer_hosted() { "{localized_copy(\"Agent\", \"เอเจนต์\")}: {display_status(&infrastructure.agent_state)}" } else { { {localized_copy("Managed runtime", "รันไทม์ที่มีการจัดการ")} } }
                        }
                        span { class: if infrastructure.configuration_drifted { "status-pill warn" } else { "status-pill good" },
                            "{localized_copy(\"Config\", \"การกำหนดค่า\")} v{infrastructure.desired_version}"
                        }
                    }
                }
            }
            nav { class: "customer-route-tabs", aria_label: localized_copy("Tenant administration tabs", "แท็บการจัดการของลูกค้า"),
                for (tab, label) in contextual_tabs {
                    KitButton { variant: ButtonVariant::Secondary, size: ButtonSize::Default,
                        class: if selected_tab == tab { "route-tab active" } else { "route-tab" },
                        r#type: "button",
                        aria_current: if selected_tab == tab { "page" } else { "false" },
                        onclick: move |_| active_tab.set(tab),
                        "{label}"
                    }
                }
            }
            if infrastructure_loading {
                div { class: "status-banner muted", {localized_copy("Loading redacted infrastructure state…", "กำลังโหลดสถานะโครงสร้างพื้นฐานที่ปกปิดข้อมูล…")} }
            }
            if infrastructure_error.is_some() {
                StatePanel {
                    state: UiStateKind::Denied,
                    title: localized_copy("Infrastructure visibility unavailable", "การมองเห็นโครงสร้างพื้นฐานไม่พร้อมใช้งาน").to_string(),
                    message: localized_copy("The current role cannot read this tenant's redacted infrastructure state, or the control plane is unavailable.", "บทบาทปัจจุบันไม่สามารถอ่านสถานะโครงสร้างพื้นฐานที่ถูกลบของบริษัทหรือการควบคุมระดับผู้อนุญาตไม่มีอยู่").to_string(),
                    action_label: None,
                    on_action: None,
                }
            }
            if let Some(infrastructure) = infrastructure.as_ref() {
                div { class: "tenant-security-banners", aria_live: "polite",
                    if infrastructure.is_customer_hosted() && !infrastructure.agent_available() {
                        div { class: "status-banner bad", strong { { {localized_copy("Customer data plane unavailable", "ระนาบข้อมูลลูกค้าไม่พร้อมใช้งาน")} } } {localized_copy(" · New Root sessions and business requests fail closed.", " · เซสชัน Root ใหม่และคำขอทางธุรกิจจะถูกปฏิเสธเพื่อความปลอดภัย")} }
                    }
                    if infrastructure.configuration_drifted {
                        div { class: "status-banner warn", strong { { {localized_copy("Configuration drift", "การกำหนดค่าคลาดเคลื่อน")} } } "{localized_copy(\" · Desired\", \" · ค่าที่ต้องการ\")} v{infrastructure.desired_version} {localized_copy(\"differs from observed\", \"ต่างจากค่าที่ตรวจพบ\")} v{infrastructure.observed_version}." }
                    }
                    if infrastructure.root_access_active {
                        div { class: "status-banner warn", strong { {localized_copy("Root session active", "เซสชัน Root ใช้งานอยู่")} } {localized_copy(" · Customer-visible, scoped, expiring, and revocable from Root Access.", " · ลูกค้ามองเห็น มีขอบเขต มีวันหมดอายุ และเพิกถอนได้จากการเข้าถึง Root")} }
                    }
                    if infrastructure.is_customer_hosted() && !infrastructure.directory_ready {
                        div { class: "status-banner bad", strong { { {localized_copy("Directory stale", "ข้อมูลไดเรกทอรีล้าสมัย")} } } {localized_copy(" · Directory authorization fails closed until a fresh Active observation arrives.", " · การอนุญาตผ่านไดเรกทอรีจะถูกปฏิเสธจนกว่าจะได้รับสถานะใช้งานล่าสุด")} }
                    }
                    if infrastructure.is_customer_hosted() && !infrastructure.backup_verified {
                        div { class: "status-banner warn", strong { { {localized_copy("Backup verification required", "ต้องตรวจสอบข้อมูลสำรอง")} } } {localized_copy(" · Recovery readiness is degraded.", " · ความพร้อมในการกู้คืนอยู่ในระดับลดลง")} }
                    }
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::Overview {
                dl { class: "detail-grid",
                    dt { { {localized_copy("Opaque tenant", "ผู้ใช้ไม่เปิดเผย")} } }
                    dd { "{tenant.tenant_id}" }
                    dt { { {localized_copy("Customer", "ลูกค้า")} } }
                    dd { if tenant.customer_name.is_empty() { { {localized_copy("Configuration required", "จำเป็นต้องกำหนดค่า")} } } else { "{tenant.customer_name}" } }
                    dt { { {localized_copy("Configuration", "การกำหนดค่า")} } }
                    dd { "{tenant.configuration_state}" }
                    dt { {localized_copy("State", "สถานะ")} }
                    dd { "{display_status(&tenant.state)}" }
                    dt { {localized_copy("Subscription", "การสมัครใช้งาน")} }
                    dd { "{tenant.subscription_state}" }
                    dt { { {localized_copy("Plan", "แผน")} } }
                    dd { if tenant.plan_key.is_empty() { { {localized_copy("Not configured", "ไม่ได้กำหนด")} } } else { "{tenant.plan_key}" } }
                    dt { { {localized_copy("Modules", "โมดูล")} } }
                    dd { "{enabled_modules}" }
                    dt { { {localized_copy("Seats", "ที่นั่ง")} } }
                    dd { "{active_console_locale().formatter().format_integer(tenant.used_seats as i64)} {localized_copy(\"used\", \"ใช้งาน\")} / {active_console_locale().formatter().format_integer(tenant.purchased_seats as i64)} {localized_copy(\"purchased\", \"ซื้อแล้ว\")}" }
                    dt { { {localized_copy("Organization", "องค์กร")} } }
                    dd { "{active_console_locale().formatter().format_integer(tenant.company_count as i64)} {localized_copy(\"companies\", \"บริษัท\")} · {active_console_locale().formatter().format_integer(tenant.branch_count as i64)} {localized_copy(\"branches\", \"สาขา\")}" }
                    dt { { {localized_copy("Renewal", "การต่ออายุ")} } }
                    dd { if tenant.renewal_at.is_empty() { { {localized_copy("Not configured", "ไม่ได้กำหนด")} } } else { "{display_timestamp(&tenant.renewal_at)}" } }
                    dt { { {localized_copy("Projection", "การคาดการณ์")} } }
                    dd { "{tenant.projection}" }
                    dt { { {localized_copy("Backup / PITR", "สำรอง / PITR")} } }
                    dd { "{tenant.backup_pitr}" }
                    dt { {localized_copy("Storage", "การเก็บรักษา")} }
                    dd { "{tenant.storage}" }
                    dt { { {localized_copy("Overall health", "สภาพการทำงานรวมทั้งหมด")} } }
                    dd { "{display_status(&tenant.health)}" }
                }
                PlatformTenantLifecycleControls {
                    tenant: tenant.clone(),
                    access_token: access_token.clone(),
                    principal_ref: principal_ref.clone(),
                    session_id: session_id.clone(),
                    administrative_context: administrative_context.read().clone(),
                    on_changed: on_infrastructure_changed,
                }
                if tenant.enterable {
                    section { class: "projection-card tenant-admin-context", "data-authority": "platform-tenant-admin-context",
                        div { class: "section-caption", {localized_copy("SHORT-LIVED TENANT ADMINISTRATION", "การดูแลผู้เช่าระยะสั้น")} }
                        p { {localized_copy("Entry requires platform.tenant.enter, a stated reason, and fresh MFA. The server binds the 30-minute context to this principal, device, session, tenant, and root holding.", "การเข้าต้องมีสิทธิ์ platform.tenant.enter ระบุเหตุผล และ MFA ใหม่ เซิร์ฟเวอร์จะผูกบริบท 30 นาทีกับผู้ใช้ อุปกรณ์ เซสชัน ผู้เช่า และโฮลดิ้งหลักนี้")} }
                        if let Some(context) = administrative_context.read().clone() {
                            div { class: if context.active { "status-banner good" } else { "status-banner bad" },
                                strong { if context.active { {localized_copy("Administrative context active", "บริบทการดูแลใช้งานอยู่")} } else { {localized_copy("Administrative context inactive", "บริบทการดูแลไม่ทำงาน")} } }
                                span { " · {localized_copy(\"expires\", \"หมดอายุ\")} {context.expires_at}" }
                            }
                            dl { class: "detail-grid",
                                dt { {localized_copy("Customer", "ลูกค้า")} } dd { "{context.customer_id}" }
                                dt { {localized_copy("Root holding", "โฮลดิ้งหลัก")} } dd { "{context.root_holding_id}" }
                                dt { {localized_copy("Issued", "ออกเมื่อ")} } dd { "{context.issued_at}" }
                                dt { {localized_copy("Correlation", "สหสัมพันธ์")} } dd { "{context.correlation_id}" }
                            }
                            div { class: "command-grid",
                                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: *tenant_admin_busy.read(), onclick: move |_| on_tenant_admin_action.call(TenantAdminAction::Refresh), {localized_copy("Refresh server context", "รีเฟรชบริบทเซิร์ฟเวอร์")} }
                                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", disabled: *tenant_admin_busy.read() || !context.active, onclick: move |_| on_tenant_admin_action.call(TenantAdminAction::Discover { after_cursor: String::new() }), {localized_copy("Discover organization units", "ค้นหาหน่วยองค์กร")} }
                            }
                            if context.active {
                                div { class: "section-caption", {localized_copy("ENTER AUTHORIZED MODULE", "เข้าสู่โมดูลที่ได้รับอนุญาต")} }
                                if workspace_modules.is_empty() {
                                    StatePanel { state: UiStateKind::Unavailable, title: localized_copy("No entitled tenant modules", "ไม่มีโมดูลผู้เช่าที่ได้รับสิทธิ์").to_owned(), message: localized_copy("The tenant registry did not return an entitled business module for this administrative context.", "ทะเบียนผู้เช่าไม่ส่งคืนโมดูลธุรกิจที่ได้รับสิทธิ์สำหรับบริบทการดูแลนี้").to_owned(), action_label: None, on_action: None }
                                } else {
                                    div { class: "tenant-workspace-module-grid",
                                        for module in workspace_modules.iter().copied() {
                                            {
                                                let tenant_id = PlatformTenantId::new(tenant.tenant_id.clone()).ok();
                                                rsx! { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: tenant_id.is_none(), onclick: move |_| {
                                                    if let Some(tenant_id) = tenant_id.clone() {
                                                        on_navigate.call(PlatformOperationsRoute::TenantWorkspace { tenant_id, module });
                                                    }
                                                }, "{module.as_str()}" } }
                                            }
                                        }
                                    }
                                }
                            }
                            label { r#for: "tenant-admin-end-reason", {localized_copy("End reason", "เหตุผลที่สิ้นสุด")} }
                            KitInput { id: "tenant-admin-end-reason", value: "{tenant_admin_end_reason}", maxlength: "512", disabled: *tenant_admin_busy.read(), oninput: move |event: FormEvent| tenant_admin_end_reason.set(event.value()) }
                            KitButton { size: ButtonSize::Default, variant: ButtonVariant::Destructive, class: "button", r#type: "button", disabled: *tenant_admin_busy.read(), onclick: move |_| on_tenant_admin_action.call(TenantAdminAction::End { reason: tenant_admin_end_reason.read().clone() }), {localized_copy("End administrative context", "สิ้นสุดบริบทการดูแล")} }
                        } else {
                            label { r#for: "tenant-admin-reason", {localized_copy("Audited entry reason", "เหตุผลการเข้าที่ตรวจสอบย้อนหลังได้")} }
                            KitTextarea { id: "tenant-admin-reason", value: "{tenant_admin_reason}", maxlength: "512", disabled: *tenant_admin_busy.read(), oninput: move |event: FormEvent| tenant_admin_reason.set(event.value()) }
                            label { r#for: "tenant-admin-mfa", {localized_copy("Fresh MFA code", "รหัส MFA ใหม่")} }
                            KitInput { id: "tenant-admin-mfa", r#type: "password", autocomplete: "one-time-code", value: "{tenant_admin_mfa}", disabled: *tenant_admin_busy.read(), oninput: move |event: FormEvent| tenant_admin_mfa.set(event.value()) }
                            KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", disabled: *tenant_admin_busy.read(), onclick: move |_| on_tenant_admin_action.call(TenantAdminAction::Begin { reason: tenant_admin_reason.read().clone(), mfa_code: tenant_admin_mfa.read().clone() }), if *tenant_admin_busy.read() { {localized_copy("Entering…", "กำลังเข้า…")} } else { {localized_copy("Begin administrative context", "เริ่มบริบทการดูแล")} } }
                        }
                        if let Some(message) = tenant_admin_message.read().clone() { p { class: "status-banner", role: "status", "{message}" } }
                        if let Some(page) = organization_page.read().clone() {
                            div { class: "section-caption", {localized_copy("AUTHORIZED ORGANIZATION UNITS", "หน่วยองค์กรที่ได้รับอนุญาต")} }
                            if page.units.is_empty() {
                                StatePanel { state: UiStateKind::Empty, title: localized_copy("No organization units", "ไม่มีหน่วยองค์กร").to_string(), message: localized_copy("The tenant read route returned no organization units.", "เส้นทางอ่านผู้เช่าไม่ส่งคืนหน่วยองค์กร").to_string(), action_label: None, on_action: None }
                            } else {
                                div { class: "table-wrap", KitTable { class: "data-table",
                                    thead { tr { th { {localized_copy("Kind", "ประเภท")} } th { {localized_copy("Code / name", "รหัส / ชื่อ")} } th { {localized_copy("Holding", "โฮลดิ้ง")} } th { {localized_copy("Company / branch", "บริษัท / สาขา")} } } }
                                    tbody { for unit in page.units.iter() { tr {
                                        td { "{unit.kind}" }
                                        td { strong { "{unit.code}" } small { "{unit.name}" } }
                                        td { "{unit.holding_id}" }
                                        td { if unit.company_id.is_empty() { "—" } else { "{unit.company_id}" } if !unit.branch_id.is_empty() { small { "{unit.branch_id}" } } }
                                    } } }
                                } }
                            }
                            p { class: "muted", "{localized_copy(\"Correlation\", \"สหสัมพันธ์\")}: {page.correlation_id}" }
                            if page.has_more {
                                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: *tenant_admin_busy.read(), onclick: {
                                    let next_cursor = page.next_cursor.clone();
                                    move |_| on_tenant_admin_action.call(TenantAdminAction::Discover { after_cursor: next_cursor.clone() })
                                }, {localized_copy("Next organization page", "หน้าหน่วยองค์กรถัดไป")} }
                            }
                        }
                    }
                } else {
                    StatePanel {
                        state: UiStateKind::Denied,
                        title: localized_copy("Workspace entry unavailable", "ไม่สามารถเข้าสู่พื้นที่ทำงาน").to_string(),
                        message: localized_copy("This tenant is inactive or its customer/root-holding binding requires configuration.", "ผู้เช่านี้ไม่ได้ใช้งาน หรือยังต้องกำหนดค่าการเชื่อมโยงลูกค้ากับโฮลดิ้งหลัก").to_string(),
                        action_label: None,
                        on_action: None,
                    }
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::Infrastructure {
                if let Some(infrastructure) = infrastructure.as_ref() {
                    section { class: "tenant-config-surface", aria_label: localized_copy("Tenant infrastructure", "โครงสร้างพื้นฐานของลูกค้า"),
                        div { class: "surface-header",
                            div {
                                div { class: "eyebrow", {localized_copy("LAYER 2 · HOLDING INFRASTRUCTURE", "ชั้นที่ 2 · โครงสร้างพื้นฐานของโฮลดิ้ง")} }
                                h3 { if infrastructure.is_customer_hosted() { {localized_copy("Customer-hosted data plane", "ช่องทางข้อมูลของลูกค้า-จัดการเอง; ค่าไม่มีใน ERPX อย่างแน่นอน")} } else { { {localized_copy("ERPX-managed data plane", "พื้นที่ข้อมูลจัดการโดย ERPX")} } } }
                                p { { {localized_copy("Only secret references, fingerprints, versions, and redacted health cross this control-plane boundary.", "เฉพาะข้อมูลลับ อินพุตแฮช เวอร์ชัน และข้อมูลสุขภาพที่ถูกลบออก ที่จะผ่านพ้นขอบเขตควบคุมระบบ")} } }
                            }
                            div { class: "tenant-action-row",
                                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", onclick: move |_| { let next = !*show_setup.read(); show_setup.set(next); }, if *show_setup.read() { { {localized_copy("Close setup guide", "ปิดคู่มือการตั้งค่า")} } } else { { {localized_copy("Self-host setup", "ตั้งค่าการโฮสต์เอง")} } } }
                                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", onclick: move |_| active_tab.set(PlatformTenantAdministrationTab::RootAccess), {localized_copy("Request access", "ขอสิทธิ์เข้าถึง")} }
                            }
                        }
                        dl { class: "detail-grid infrastructure-grid",
                            dt { {localized_copy("Hosting", "การโฮสต์")} } dd { if infrastructure.is_customer_hosted() { { {localized_copy("Customer data plane", "ระนาบข้อมูลของลูกค้า")} } } else { { {localized_copy("ERPX managed", "จัดการโดย ERPX")} } } }
                            dt { { {localized_copy("Profile", "โพรไฟล์")} } } dd { "{localized_copy(\"Active\", \"ใช้งานอยู่\")} v{infrastructure.profile_version}" }
                            dt { {localized_copy("Agent", "ตัวแทน")} } dd { if infrastructure.agent_id.is_empty() { { {localized_copy("Not required", "ไม่มีความจำเป็น")} } } else { "{infrastructure.agent_state} · {infrastructure.agent_version}" } }
                            dt { {localized_copy("Last check-in", "การเช็คเข้าครั้งสุดท้าย")} } dd { if infrastructure.last_heartbeat_at.is_empty() { { {localized_copy("No observation", "ไม่มีข้อมูลการสังเกต")} } } else { "{display_timestamp(&infrastructure.last_heartbeat_at)}" } }
                            dt { {localized_copy("Write database", "ฐานข้อมูลเขียน")} } dd { if infrastructure.write_healthy { { {localized_copy("Healthy · secret owner redacted", "ปกติ · ปกปิดเจ้าของข้อมูลลับ")} } } else { { {localized_copy("Not verified", "ยังไม่ตรวจสอบ")} } } }
                            dt { { {localized_copy("Read database", "อ่านฐานข้อมูล")} } } dd { if infrastructure.read_healthy { { {localized_copy("Healthy", "อยู่ในสภาพดี")} } } else { { {localized_copy("Not verified", "ไม่ได้ตรวจสอบ")} } } }
                            dt { { {localized_copy("Object storage", "บริการเก็บข้อมูล")} } } dd { if infrastructure.storage_healthy { { {localized_copy("Healthy", "อยู่ในสภาพดี")} } } else { { {localized_copy("Not verified", "ไม่ได้ตรวจสอบ")} } } }
                            dt { {localized_copy("Directory", "ไดเรกทอรี")} } dd { if infrastructure.directory_ready { {localized_copy("Active", "ใช้งานอยู่")} } else { { {localized_copy("Not ready · fail-closed", "ยังไม่พร้อม · ปฏิเสธเพื่อความปลอดภัย")} } } }
                            dt { {localized_copy("Projections", "ภาพรวม")} } dd { if infrastructure.projections_healthy { { {localized_copy("Healthy", "อยู่ในสภาพดี")} } } else { {localized_copy("Verification required", "การยืนยันต้องการ")} } }
                            dt { { {localized_copy("Backup", "สำรอง")} } } dd { if infrastructure.backup_verified { {localized_copy("Verified", "ได้รับการยืนยัน")} } else { {localized_copy("Verification required", "การยืนยันต้องการ")} } }
                            dt { { {localized_copy("Secret ownership", "โฮลดิ้งลับ")} } } dd { if infrastructure.customer_managed_secrets { {localized_copy("Customer-managed; values never enter ERPX", "ที่แสดงให้ลูกค้าเห็น; การเข้าถึงและกิจกรรม")} } else { { {localized_copy("ERPX-managed registry references", "พนักงาน ERPXจัดการรายการใน registry")} } } }
                            dt { {localized_copy("Root access", "การเข้าถึงระดับราก")} } dd { if infrastructure.root_access_active { {localized_copy("Active approved session", "ช่วงเวลาอนุมัติที่มีผลบังคับใช้")} } else { {localized_copy("Inactive", "ไม่ใช้งาน")} } }
                        }
                        if *show_setup.read() {
                            SelfHostSetupGuide {}
                        }
                        TenantInfrastructureControls {
                            infrastructure: infrastructure.clone(),
                            access_token: access_token.clone(),
                            principal_ref: principal_ref.clone(),
                            session_id: session_id.clone(),
                            administrative_context: administrative_context.read().clone(),
                            on_changed: on_infrastructure_changed,
                        }
                    }
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::Identity {
                PlatformTenantIdentityPanel {
                    tenant_id: tenant.tenant_id.clone(),
                    root_holding_id: tenant.root_holding_id.clone(),
                    access_token: access_token.clone(),
                    principal_ref: principal_ref.clone(),
                    session_id: session_id.clone(),
                    administrative_context: administrative_context.read().clone(),
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::CorporateIdentity {
                PlatformTenantCorporateIdentityPanel {
                    tenant_id: tenant.tenant_id.clone(),
                    root_holding_id: tenant.root_holding_id.clone(),
                    access_token: access_token.clone(),
                    principal_ref: principal_ref.clone(),
                    session_id: session_id.clone(),
                    administrative_context: administrative_context.read().clone(),
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::BusinessUnits {
                BusinessUnitConfigurationCatalog {
                    tenant_id: tenant.tenant_id.clone(),
                    root_holding_id: tenant.root_holding_id.clone(),
                    access_token: access_token.clone(),
                    principal_ref: principal_ref.clone(),
                    session_id: session_id.clone(),
                    administrative_context: administrative_context.read().clone(),
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::RootAccess {
                RootAccessQueuePanel {
                    infrastructure: infrastructure.clone(),
                    access_token: access_token.clone(),
                    principal_ref: principal_ref.clone(),
                    session_id: session_id.clone(),
                    administrative_context: administrative_context.read().clone(),
                    on_changed: on_infrastructure_changed,
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::Organization {
                if let Some(context) = administrative_context.read().clone() {
                    if context.active && context.tenant_id == tenant.tenant_id {
                        PlatformTenantOrganizationPanel {
                            tenant_id: tenant.tenant_id.clone(),
                            root_holding_id: tenant.root_holding_id.clone(),
                            administrative_context: context.clone(),
                            access_token: access_token.clone(),
                            principal_ref: principal_ref.clone(),
                            session_id: session_id.clone(),
                        }
                        BranchProvisioningPanel {
                            tenant_id: tenant.tenant_id.clone(),
                            administrative_context: context,
                            access_token: access_token.clone(),
                            principal_ref: principal_ref.clone(),
                            session_id: session_id.clone(),
                            on_changed: on_infrastructure_changed,
                        }
                    } else {
                        StatePanel { state: UiStateKind::Denied, title: localized_copy("Active tenant context required", "ต้องมีบริบทผู้เช่าที่ใช้งานอยู่").to_owned(), message: localized_copy("Begin or refresh the short-lived administrative context from Overview before managing branch infrastructure.", "เริ่มหรือรีเฟรชบริบทการดูแลระยะสั้นจากภาพรวมก่อนจัดการโครงสร้างพื้นฐานสาขา").to_owned(), action_label: None, on_action: None }
                    }
                } else {
                    StatePanel { state: UiStateKind::Denied, title: localized_copy("Tenant context required", "ต้องมีบริบทผู้เช่า").to_owned(), message: localized_copy("Branch provisioning is available only inside an MFA-gated tenant administrative context.", "การจัดเตรียมสาขาพร้อมใช้เฉพาะในบริบทการดูแลผู้เช่าที่ใช้ MFA").to_owned(), action_label: None, on_action: None }
                }
            }
            if selected_tab == PlatformTenantAdministrationTab::ConfigurationHistory {
                section { class: "tenant-config-surface", aria_label: localized_copy("Configuration versions", "เวอร์ชันการกำหนดค่า"),
                    div { class: "eyebrow", {localized_copy("CURRENT VERSION SNAPSHOT", "ภาพรวมเวอร์ชันปัจจุบัน")} }
                    h3 { {localized_copy("Desired and observed versions", "เวอร์ชันที่ต้องการและที่สังเกต")} }
                    if let Some(infrastructure) = infrastructure.as_ref() {
                        dl { class: "detail-grid",
                            dt { { {localized_copy("Profile version", "เวอร์ชันของโปรไฟล์")} } } dd { "{infrastructure.profile_version}" }
                            dt { {localized_copy("Desired version", "เวอร์ชันที่ต้องการ")} } dd { "{infrastructure.desired_version}" }
                            dt { { {localized_copy("Observed version", "เวอร์ชันที่สังเกต")} } } dd { "{infrastructure.observed_version}" }
                            dt { {localized_copy("Last observation", "การตรวจพบล่าสุด")} } dd { if infrastructure.observed_at.is_empty() { { {localized_copy("No observation", "ไม่มีข้อมูลการตรวจพบ")} } } else { "{display_timestamp(&infrastructure.observed_at)}" } }
                            dt { { {localized_copy("Drift", "ความคลาดเคลื่อน")} } } dd { if infrastructure.configuration_drifted { {localized_copy("Detected", "ตรวจพบ")} } else { {localized_copy("None", "ไม่มี")} } }
                        }
                    }
                }
                TenantControlHistoryPanel {
                    tenant_id: tenant.tenant_id.clone(),
                    access_token: access_token.clone(),
                    principal_ref: principal_ref.clone(),
                    session_id: session_id.clone(),
                }
            }
        }
    }
}

#[component]
fn TenantProvisioningWizard(
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    on_changed: EventHandler<()>,
    on_navigate: EventHandler<PlatformOperationsRoute>,
) -> Element {
    let mut open = use_signal(|| false);
    let mut review = use_signal(|| false);
    let mut busy = use_signal(|| false);
    let mut outcome = use_signal(|| None::<Result<PlatformTenantLifecycleReceipt, String>>);
    let mut tenant_id = use_signal(String::new);
    let mut holding_ref = use_signal(String::new);
    let mut write_database_key = use_signal(String::new);
    let mut read_database_key = use_signal(String::new);
    let mut storage_namespace = use_signal(String::new);
    let mut credential_key_ref = use_signal(String::new);
    let mut backup_chain_ref = use_signal(String::new);
    let mut owner_principal_ref = use_signal(String::new);
    let mut owner_approver_ref = use_signal(String::new);
    let mut mfa_code = use_signal(String::new);

    let on_review = move |event: FormEvent| {
        event.prevent_default();
        let values = [
            (tenant_id.read().clone(), "Tenant ID"),
            (holding_ref.read().clone(), "Holding reference"),
            (write_database_key.read().clone(), "Write database key"),
            (read_database_key.read().clone(), "Read database key"),
            (storage_namespace.read().clone(), "Storage namespace"),
            (
                credential_key_ref.read().clone(),
                "Credential key reference",
            ),
            (backup_chain_ref.read().clone(), "Backup chain reference"),
            (
                owner_principal_ref.read().clone(),
                "Owner principal reference",
            ),
            (
                owner_approver_ref.read().clone(),
                "Independent approver reference",
            ),
        ];
        for (value, label) in values {
            if let Err(error) = validate_tenant_registration_reference(&value, label) {
                outcome.set(Some(Err(error)));
                return;
            }
        }
        if write_database_key.read().trim() == read_database_key.read().trim() {
            outcome.set(Some(Err(
                "Write and read database keys must differ.".to_owned()
            )));
            return;
        }
        outcome.set(None);
        review.set(true);
    };

    let tenant_id_for_submit = tenant_id;
    let on_submit = move |event: FormEvent| {
        event.prevent_default();
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            access_token.clone(),
            principal_ref.clone(),
            session_id.clone(),
        ) else {
            outcome.set(Some(Err("Authentication is required.".to_owned())));
            return;
        };
        let input = BeginTenantProvisioningInput {
            tenant_id: tenant_id_for_submit.read().clone(),
            holding_ref: holding_ref.read().clone(),
            write_database_key: write_database_key.read().clone(),
            read_database_key: read_database_key.read().clone(),
            storage_namespace: storage_namespace.read().clone(),
            credential_key_ref: credential_key_ref.read().clone(),
            backup_chain_ref: backup_chain_ref.read().clone(),
            owner_principal_ref: owner_principal_ref.read().clone(),
            owner_approver_ref: owner_approver_ref.read().clone(),
            mfa_code: mfa_code.read().clone(),
        };
        mfa_code.set(String::new());
        busy.set(true);
        outcome.set(None);
        let mut busy_for_task = busy;
        let mut outcome_for_task = outcome;
        let mut open_for_task = open;
        let mut review_for_task = review;
        let on_changed = on_changed;
        let on_navigate = on_navigate;
        spawn(async move {
            let result =
                begin_platform_tenant_provisioning(input, access_token, principal_ref, session_id)
                    .await;
            busy_for_task.set(false);
            if let Ok(receipt) = &result {
                let route_id = PlatformTenantId::new(receipt.tenant_id.clone()).ok();
                open_for_task.set(false);
                review_for_task.set(false);
                on_changed.call(());
                if let Some(tenant_id) = route_id {
                    on_navigate.call(PlatformOperationsRoute::Tenant { tenant_id });
                }
            }
            outcome_for_task.set(Some(result));
        });
    };

    rsx! {
        section { class: "tenant-config-surface tenant-provisioning-wizard", aria_label: localized_copy("Tenant provisioning wizard", "ตัวช่วยจัดเตรียมผู้เช่า"),
            div { class: "surface-header",
                div {
                    div { class: "eyebrow", {localized_copy("RESUMABLE TENANT PROVISIONING", "การจัดเตรียมผู้เช่าที่ดำเนินต่อได้")} }
                    h3 { {localized_copy("Register a tenant boundary", "ลงทะเบียนขอบเขตผู้เช่า")} }
                    p { {localized_copy("This first step records opaque routing keys and independent owner approval. Accepted registrations resume from the tenant detail lifecycle controls.", "ขั้นตอนแรกนี้บันทึกคีย์การกำหนดเส้นทางแบบทึบและการอนุมัติเจ้าของโดยอิสระ การลงทะเบียนที่ยอมรับแล้วจะดำเนินต่อจากการควบคุมวงจรชีวิตในรายละเอียดผู้เช่า")} }
                }
                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| { let next = !*open.read(); open.set(next); review.set(false); }, if *open.read() { {localized_copy("Close wizard", "ปิดตัวช่วย")} } else { {localized_copy("Provision tenant", "จัดเตรียมผู้เช่า")} } }
            }
            if *open.read() && !*review.read() {
                form { class: "typed-command-form", onsubmit: on_review,
                    div { class: "section-caption", {localized_copy("STEP 1 OF 2 · REGISTRATION", "ขั้นตอน 1 จาก 2 · การลงทะเบียน")} }
                    div { class: "form-grid",
                        label { {localized_copy("Opaque tenant ID", "ID ผู้เช่าแบบทึบ")} KitInput { value: "{tenant_id}", autocomplete: "off", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| tenant_id.set(event.value()) } }
                        label { {localized_copy("Root holding reference", "ข้อมูลอ้างอิงโฮลดิ้งหลัก")} KitInput { value: "{holding_ref}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| holding_ref.set(event.value()) } }
                        label { {localized_copy("Write database routing key", "คีย์กำหนดเส้นทางฐานข้อมูลเขียน")} KitInput { value: "{write_database_key}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| write_database_key.set(event.value()) } }
                        label { {localized_copy("Read database routing key", "คีย์กำหนดเส้นทางฐานข้อมูลอ่าน")} KitInput { value: "{read_database_key}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| read_database_key.set(event.value()) } }
                        label { {localized_copy("Storage namespace", "เนมสเปซพื้นที่จัดเก็บ")} KitInput { value: "{storage_namespace}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| storage_namespace.set(event.value()) } }
                        label { {localized_copy("Credential key reference", "ข้อมูลอ้างอิงคีย์ข้อมูลประจำตัว")} KitInput { value: "{credential_key_ref}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| credential_key_ref.set(event.value()) } }
                        label { {localized_copy("Backup chain reference", "ข้อมูลอ้างอิงสายข้อมูลสำรอง")} KitInput { value: "{backup_chain_ref}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| backup_chain_ref.set(event.value()) } }
                        label { {localized_copy("Initial Holding Owner principal", "ผู้ใช้หลักเจ้าของโฮลดิ้งเริ่มต้น")} KitInput { value: "{owner_principal_ref}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| owner_principal_ref.set(event.value()) } }
                        label { {localized_copy("Independent platform approver", "ผู้อนุมัติแพลตฟอร์มอิสระ")} KitInput { value: "{owner_approver_ref}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| owner_approver_ref.set(event.value()) } }
                    }
                    div { class: "audit-banner", {localized_copy("These are registry and secret-provider keys, never passwords, URLs, database connection strings, or credential values.", "ข้อมูลเหล่านี้เป็นคีย์ทะเบียนและผู้ให้บริการข้อมูลลับ ไม่ใช่รหัสผ่าน URL สตริงเชื่อมต่อฐานข้อมูล หรือค่าข้อมูลประจำตัว")} }
                    KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "submit", disabled: *busy.read(), {localized_copy("Review registration", "ตรวจสอบการลงทะเบียน")} }
                }
            }
            if *open.read() && *review.read() {
                form { class: "typed-command-form", onsubmit: on_submit,
                    div { class: "section-caption", {localized_copy("STEP 2 OF 2 · REVIEW AND MFA", "ขั้นตอน 2 จาก 2 · ตรวจสอบและ MFA")} }
                    dl { class: "detail-grid",
                        dt { {localized_copy("Tenant", "ผู้เช่า")} } dd { "{tenant_id}" }
                        dt { {localized_copy("Holding", "โฮลดิ้ง")} } dd { "{holding_ref}" }
                        dt { {localized_copy("Write / read keys", "คีย์เขียน / อ่าน")} } dd { "{write_database_key} · {read_database_key}" }
                        dt { {localized_copy("Storage / backup", "พื้นที่จัดเก็บ / สำรอง")} } dd { "{storage_namespace} · {backup_chain_ref}" }
                        dt { {localized_copy("Owner / independent approver", "เจ้าของ / ผู้อนุมัติอิสระ")} } dd { "{owner_principal_ref} · {owner_approver_ref}" }
                    }
                    label { {localized_copy("Fresh operator MFA code", "รหัส MFA ใหม่ของผู้ปฏิบัติงาน")} KitInput { r#type: "password", value: "{mfa_code}", autocomplete: "one-time-code", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| mfa_code.set(event.value()) } }
                    div { class: "tenant-action-row",
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Destructive, class: "button", r#type: "submit", disabled: *busy.read(), if *busy.read() { {localized_copy("Registering…", "กำลังลงทะเบียน…")} } else { {localized_copy("Confirm tenant registration", "ยืนยันการลงทะเบียนผู้เช่า")} } }
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| review.set(false), {localized_copy("Back to edit", "กลับไปแก้ไข")} }
                    }
                }
            }
            if let Some(result) = outcome.read().clone() {
                match result {
                    Ok(receipt) => rsx! { div { class: "status-banner good", role: "status", {localized_copy("Tenant registration accepted", "ยอมรับการลงทะเบียนผู้เช่าแล้ว")} " · {receipt.tenant_id} · {receipt.state}" } },
                    Err(message) => rsx! { div { class: "status-banner warn", role: "alert", "{message}" } },
                }
            }
        }
    }
}

#[component]
fn PlatformTenantLifecycleControls(
    tenant: PlatformTenantRecord,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    administrative_context: Option<TenantAdminContextModel>,
    on_changed: EventHandler<()>,
) -> Element {
    let mut pending_action = use_signal(|| None::<PlatformTenantLifecycleAction>);
    let mut confirmation = use_signal(String::new);
    let mut mfa_code = use_signal(String::new);
    let mut busy = use_signal(|| false);
    let mut outcome = use_signal(|| None::<Result<PlatformTenantLifecycleReceipt, String>>);
    let tenant_id = tenant.tenant_id.clone();
    let state = tenant.state.clone();
    let can_provision = state == "provisioning";
    let can_activate = matches!(state.as_str(), "provisioning" | "suspended" | "recovery");
    let can_suspend = state == "active";
    let has_action = can_provision || can_activate || can_suspend;
    let administrative_context_id = administrative_context.as_ref().and_then(|context| {
        (context.active
            && context.tenant_id == tenant.tenant_id
            && context.root_holding_id == tenant.root_holding_id)
            .then(|| context.administrative_context_id.clone())
    });

    let tenant_id_for_submit = tenant_id.clone();
    let on_submit = move |event: FormEvent| {
        event.prevent_default();
        let Some(action) = *pending_action.read() else {
            outcome.set(Some(Err(
                "Select a tenant lifecycle command before confirming.".to_owned(),
            )));
            return;
        };
        if !matches!(action, PlatformTenantLifecycleAction::ProvisionResources)
            && administrative_context_id.is_none()
        {
            outcome.set(Some(Err("tenant_context_required".to_owned())));
            return;
        }
        if confirmation.read().trim() != tenant_id_for_submit {
            outcome.set(Some(Err(
                "Type the exact tenant ID to confirm this command.".to_owned(),
            )));
            return;
        }
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            access_token.clone(),
            principal_ref.clone(),
            session_id.clone(),
        ) else {
            outcome.set(Some(Err("Authentication is required.".to_owned())));
            return;
        };
        let mfa = mfa_code.read().clone();
        mfa_code.set(String::new());
        busy.set(true);
        outcome.set(None);
        let tenant_id = tenant_id_for_submit.clone();
        let mut busy_for_task = busy;
        let mut outcome_for_task = outcome;
        let mut pending_for_task = pending_action;
        let mut confirmation_for_task = confirmation;
        let on_changed = on_changed;
        let administrative_context_id = administrative_context_id.clone();
        spawn(async move {
            let result = mutate_platform_tenant_lifecycle(
                tenant_id,
                action,
                mfa,
                administrative_context_id,
                access_token,
                principal_ref,
                session_id,
            )
            .await;
            busy_for_task.set(false);
            if result.is_ok() {
                pending_for_task.set(None);
                confirmation_for_task.set(String::new());
                on_changed.call(());
            }
            outcome_for_task.set(Some(result));
        });
    };

    rsx! {
        section { class: "tenant-config-surface tenant-lifecycle-controls", aria_label: localized_copy("Tenant lifecycle controls", "การควบคุมวงจรชีวิตผู้เช่า"),
            div { class: "surface-header",
                div {
                    div { class: "eyebrow", {localized_copy("AUTHORIZED TENANT LIFECYCLE", "วงจรชีวิตผู้เช่าที่ได้รับอนุญาต")} }
                    h3 { {localized_copy("Provision, activate, or suspend", "จัดเตรียม เปิดใช้งาน หรือระงับ")} }
                    p { {localized_copy("Each command is MFA-gated, independently reauthorized, idempotency-tagged, and confirmed against the exact tenant ID.", "แต่ละคำสั่งต้องใช้ MFA ได้รับอนุญาตใหม่อย่างอิสระ มีแท็ก idempotency และยืนยันด้วย ID ผู้เช่าที่ตรงกัน")} }
                }
                span { class: "status-pill {tone(&state)}", "{display_status(&state)}" }
            }
            if has_action {
                div { class: "tenant-action-row",
                    if can_provision { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| pending_action.set(Some(PlatformTenantLifecycleAction::ProvisionResources)), {localized_copy("Provision resources", "จัดเตรียมทรัพยากร")} } }
                    if can_activate { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| pending_action.set(Some(PlatformTenantLifecycleAction::Activate)), {localized_copy("Activate tenant", "เปิดใช้งานผู้เช่า")} } }
                    if can_suspend { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Destructive, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| pending_action.set(Some(PlatformTenantLifecycleAction::Suspend)), {localized_copy("Suspend tenant", "ระงับผู้เช่า")} } }
                }
            } else {
                StatePanel { state: UiStateKind::Unavailable, title: localized_copy("No lifecycle command available", "ไม่มีคำสั่งวงจรชีวิตที่พร้อมใช้").to_owned(), message: localized_copy("The current server state does not expose a safe transition from this route.", "สถานะเซิร์ฟเวอร์ปัจจุบันไม่มีการเปลี่ยนผ่านที่ปลอดภัยจากเส้นทางนี้").to_owned(), action_label: None, on_action: None }
            }
            if let Some(action) = *pending_action.read() {
                form { class: "typed-command-form destructive-confirmation", onsubmit: on_submit,
                    div { class: "status-banner warn", role: "alert", {match action {
                        PlatformTenantLifecycleAction::ProvisionResources => localized_copy("This creates tenant databases, storage, organization roots, and owner bootstrap state. Recovery material is never rendered here.", "การดำเนินการนี้สร้างฐานข้อมูลผู้เช่า พื้นที่จัดเก็บ รากองค์กร และสถานะเริ่มต้นเจ้าของ โดยจะไม่แสดงข้อมูลการกู้คืนที่นี่"),
                        PlatformTenantLifecycleAction::Activate => localized_copy("Activation opens authorized tenant routes only after server readiness checks pass.", "การเปิดใช้งานจะเปิดเส้นทางผู้เช่าที่ได้รับอนุญาตหลังจากผ่านการตรวจสอบความพร้อมของเซิร์ฟเวอร์เท่านั้น"),
                        PlatformTenantLifecycleAction::Suspend => localized_copy("Suspension closes tenant entry and business routing. Existing audit evidence remains retained.", "การระงับจะปิดการเข้าสู่ผู้เช่าและการกำหนดเส้นทางธุรกิจ โดยยังคงเก็บหลักฐานการตรวจสอบไว้"),
                    }} }
                    div { class: "form-grid",
                        label { {localized_copy("Type the exact tenant ID", "พิมพ์ ID ผู้เช่าที่ตรงกัน")} KitInput { value: "{confirmation}", autocomplete: "off", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| confirmation.set(event.value()) } }
                        label { {localized_copy("Fresh MFA code", "รหัส MFA ใหม่")} KitInput { r#type: "password", value: "{mfa_code}", autocomplete: "one-time-code", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| mfa_code.set(event.value()) } }
                    }
                    div { class: "tenant-action-row",
                        KitButton { variant: tenant_lifecycle_button_variant(action), size: ButtonSize::Default, class: "button", r#type: "submit", disabled: *busy.read(), if *busy.read() { {localized_copy("Submitting…", "กำลังส่ง…")} } else { {localized_copy("Confirm server command", "ยืนยันคำสั่งเซิร์ฟเวอร์")} } }
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| { pending_action.set(None); confirmation.set(String::new()); mfa_code.set(String::new()); }, {localized_copy("Cancel", "ยกเลิก")} }
                    }
                }
            }
            if let Some(result) = outcome.read().clone() {
                match result {
                    Ok(receipt) => rsx! { div { class: "status-banner good", role: "status",
                        strong { {localized_copy("Tenant command accepted", "ยอมรับคำสั่งผู้เช่าแล้ว")} }
                        " · {receipt.state} · " {localized_copy("correlation", "สหสัมพันธ์")} " {receipt.correlation_id}"
                        if let Some(version) = receipt.registry_version { {localized_copy(" · version", " · เวอร์ชัน")} " {version}" }
                        if let (Some(databases), Some(storage), Some(owner)) = (receipt.databases_ready, receipt.storage_ready, receipt.owner_seeded) {
                            small {
                                {localized_copy("Databases", "ฐานข้อมูล")} ": {databases} · "
                                {localized_copy("Storage", "พื้นที่จัดเก็บ")} ": {storage} · "
                                {localized_copy("Owner seeded", "ตั้งค่าเจ้าของแล้ว")} ": {owner}"
                            }
                        }
                    } },
                    Err(message) => rsx! { div { class: "status-banner warn", role: "alert", "{message}" } },
                }
            }
        }
    }
}

#[component]
fn TenantInfrastructureControls(
    infrastructure: TenantInfrastructureRecord,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    administrative_context: Option<TenantAdminContextModel>,
    on_changed: EventHandler<()>,
) -> Element {
    let locale = active_console_locale();
    let mut show_profile = use_signal(|| false);
    let mut show_desired = use_signal(|| false);
    let mut busy = use_signal(|| false);
    let mut outcome = use_signal(|| None::<(bool, String)>);
    let mut write_database_ref = use_signal(String::new);
    let mut read_database_ref = use_signal(String::new);
    let mut storage_ref = use_signal(String::new);
    let mut directory_credential_ref = use_signal(String::new);
    let mut backup_profile_ref = use_signal(String::new);
    let mut profile_reason = use_signal(move || {
        console_text(
            locale,
            "rotate managed infrastructure references",
            "หมุนเวียนข้อมูลอ้างอิงโครงสร้างพื้นฐานที่มีการจัดการ",
        )
        .to_owned()
    });
    let mut profile_mfa = use_signal(String::new);
    let mut desired_reason = use_signal(move || {
        console_text(
            locale,
            "reconcile tenant infrastructure requirements",
            "ปรับความต้องการโครงสร้างพื้นฐานของผู้เช่าให้สอดคล้องกัน",
        )
        .to_owned()
    });
    let mut require_directory = use_signal(|| true);
    let mut require_projections = use_signal(|| true);
    let mut require_backup = use_signal(|| true);
    let administrative_context_id = administrative_context.as_ref().and_then(|context| {
        (context.active
            && context.tenant_id == infrastructure.tenant_id
            && context.root_holding_id == infrastructure.root_holding_id)
            .then(|| context.administrative_context_id.clone())
    });

    let infrastructure_for_action = infrastructure.clone();
    let on_action = EventHandler::new(move |action: TenantInfrastructureAction| {
        let (
            Some(access_token),
            Some(principal_ref),
            Some(session_id),
            Some(administrative_context_id),
        ) = (
            access_token.clone(),
            principal_ref.clone(),
            session_id.clone(),
            administrative_context_id.clone(),
        )
        else {
            outcome.set(Some((
                false,
                console_text(
                    locale,
                    "An authenticated platform session is required.",
                    "ต้องมีเซสชันแพลตฟอร์มที่ยืนยันตัวตนแล้ว",
                )
                .to_owned(),
            )));
            return;
        };
        busy.set(true);
        outcome.set(None);
        let infrastructure = infrastructure_for_action.clone();
        let mut busy_for_task = busy;
        let mut outcome_for_task = outcome;
        let on_changed = on_changed;
        spawn(async move {
            let result = mutate_tenant_infrastructure(
                access_token,
                principal_ref,
                session_id,
                Some(administrative_context_id),
                infrastructure,
                action,
            )
            .await;
            busy_for_task.set(false);
            match result {
                Ok(message) => {
                    outcome_for_task.set(Some((true, message)));
                    on_changed.call(());
                }
                Err(message) => outcome_for_task.set(Some((false, message))),
            }
        });
    });

    rsx! {
        section { class: "tenant-config-surface infrastructure-command-panel", aria_label: localized_copy("Infrastructure controls", "การควบคุมโครงสร้างพื้นฐาน"),
            div { class: "surface-header",
                div {
                    div { class: "eyebrow", {localized_copy("TYPED CONTROL-PLANE COMMANDS", "คำสั่งระนาบควบคุมแบบระบุชนิด")} }
                    h4 { {localized_copy("Profile and desired state", "โปรไฟล์และสถานะที่ต้องการ")} }
                    p { {localized_copy("Opaque secret-manager references are accepted; passwords, connection strings, and raw JSON are rejected.", "ยอมรับเฉพาะข้อมูลอ้างอิงตัวจัดการข้อมูลลับแบบทึบ รหัสผ่าน สตริงเชื่อมต่อ และ JSON ดิบจะถูกปฏิเสธ")} }
                }
                div { class: "tenant-action-row",
                    if !infrastructure.is_customer_hosted() {
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| { let next = !*show_profile.read(); show_profile.set(next); }, if *show_profile.read() { {localized_copy("Close profile", "ปิดโปรไฟล์")} } else { {localized_copy("Update profile", "อัปเดตโปรไฟล์")} } }
                    }
                    KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", disabled: *busy.read(), onclick: move |_| { let next = !*show_desired.read(); show_desired.set(next); }, if *show_desired.read() { {localized_copy("Close proposal", "ปิดข้อเสนอ")} } else { {localized_copy("Propose desired state", "เสนอสถานะที่ต้องการ")} } }
                }
            }
            if infrastructure.is_customer_hosted() {
                div { class: "status-banner warn", {localized_copy("Platform Root can propose customer-hosted desired state, but profile application remains customer-scoped and approval-gated.", "Platform Root เสนอสถานะที่ต้องการสำหรับระบบที่ลูกค้าโฮสต์ได้ แต่การใช้โปรไฟล์ยังอยู่ในขอบเขตลูกค้าและต้องได้รับอนุมัติ")} }
            }
            if *show_profile.read() && !infrastructure.is_customer_hosted() {
                form { class: "typed-command-form", onsubmit: move |event| {
                    event.prevent_default();
                    let mfa_code = profile_mfa.read().clone();
                    profile_mfa.set(String::new());
                    on_action.call(TenantInfrastructureAction::SaveProfile(InfrastructureProfileInput {
                        write_database_ref: write_database_ref.read().clone(),
                        read_database_ref: read_database_ref.read().clone(),
                        storage_ref: storage_ref.read().clone(),
                        directory_credential_ref: directory_credential_ref.read().clone(),
                        backup_profile_ref: backup_profile_ref.read().clone(),
                        reason: profile_reason.read().clone(),
                        mfa_code,
                    }));
                },
                    h5 { {localized_copy("ERPX-managed profile v", "โปรไฟล์ที่ ERPX จัดการ v")} "{infrastructure.profile_version.saturating_add(1)}" }
                    div { class: "form-grid",
                        label { {localized_copy("Write database reference", "ข้อมูลอ้างอิงฐานข้อมูลเขียน")} KitInput { value: "{write_database_ref}", placeholder: localized_copy("erpx-managed:reference", "erpx-managed:ข้อมูลอ้างอิง"), autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| write_database_ref.set(event.value()) } }
                        label { {localized_copy("Read database reference", "ข้อมูลอ้างอิงฐานข้อมูลอ่าน")} KitInput { value: "{read_database_ref}", placeholder: localized_copy("erpx-managed:reference", "erpx-managed:ข้อมูลอ้างอิง"), autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| read_database_ref.set(event.value()) } }
                        label { {localized_copy("Object storage reference", "ข้อมูลอ้างอิงพื้นที่จัดเก็บออบเจ็กต์")} KitInput { value: "{storage_ref}", placeholder: localized_copy("erpx-managed:reference", "erpx-managed:ข้อมูลอ้างอิง"), autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| storage_ref.set(event.value()) } }
                        label { {localized_copy("Directory credential reference (optional)", "ข้อมูลอ้างอิงข้อมูลประจำตัวไดเรกทอรี (ไม่บังคับ)")} KitInput { value: "{directory_credential_ref}", placeholder: localized_copy("erpx-managed:reference", "erpx-managed:ข้อมูลอ้างอิง"), autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| directory_credential_ref.set(event.value()) } }
                        label { {localized_copy("Backup profile reference", "ข้อมูลอ้างอิงโปรไฟล์สำรอง")} KitInput { value: "{backup_profile_ref}", placeholder: localized_copy("erpx-managed:reference", "erpx-managed:ข้อมูลอ้างอิง"), autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| backup_profile_ref.set(event.value()) } }
                        label { {localized_copy("Audited reason", "เหตุผลที่ตรวจสอบย้อนหลังได้")} KitTextarea { value: "{profile_reason}", maxlength: "512", disabled: *busy.read(), oninput: move |event: FormEvent| profile_reason.set(event.value()) } }
                        label { {localized_copy("Fresh MFA code", "รหัส MFA ใหม่")} KitInput { r#type: "password", value: "{profile_mfa}", autocomplete: "one-time-code", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| profile_mfa.set(event.value()) } }
                    }
                    KitButton { size: ButtonSize::Default, variant: ButtonVariant::Destructive, class: "button", r#type: "submit", disabled: *busy.read(), if *busy.read() { {localized_copy("Saving…", "กำลังบันทึก…")} } else { {localized_copy("Confirm profile update", "ยืนยันการอัปเดตโปรไฟล์")} } }
                }
            }
            if *show_desired.read() {
                form { class: "typed-command-form", onsubmit: move |event| {
                    event.prevent_default();
                    on_action.call(TenantInfrastructureAction::ProposeConfiguration(DesiredConfigurationInput {
                        reason: desired_reason.read().clone(),
                        require_directory: *require_directory.read(),
                        require_projections: *require_projections.read(),
                        require_backup: *require_backup.read(),
                    }));
                },
                    h5 { {localized_copy("Tenant desired-state proposal", "ข้อเสนอสถานะที่ต้องการของผู้เช่า")} }
                    p { class: "section-caption", {localized_copy("The adapter creates a canonical, non-sensitive payload and binds it to the current observed version.", "อะแดปเตอร์สร้างเพย์โหลดมาตรฐานที่ไม่มีข้อมูลลับและผูกกับเวอร์ชันที่ตรวจพบปัจจุบัน")} }
                    div { class: "check-grid",
                        label { KitInput { r#type: "checkbox", checked: *require_directory.read(), disabled: *busy.read(), onchange: move |event: FormEvent| require_directory.set(event.checked()) } {localized_copy("Require directory readiness", "ต้องการความพร้อมของไดเรกทอรี")} }
                        label { KitInput { r#type: "checkbox", checked: *require_projections.read(), disabled: *busy.read(), onchange: move |event: FormEvent| require_projections.set(event.checked()) } {localized_copy("Require healthy projections", "ต้องการโพรเจกชันที่ปกติ")} }
                        label { KitInput { r#type: "checkbox", checked: *require_backup.read(), disabled: *busy.read(), onchange: move |event: FormEvent| require_backup.set(event.checked()) } {localized_copy("Require verified backup", "ต้องการข้อมูลสำรองที่ยืนยันแล้ว")} }
                    }
                    label { {localized_copy("Audited reason", "เหตุผลที่ตรวจสอบย้อนหลังได้")} KitTextarea { value: "{desired_reason}", maxlength: "512", disabled: *busy.read(), oninput: move |event: FormEvent| desired_reason.set(event.value()) } }
                    KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "submit", disabled: *busy.read(), if *busy.read() { {localized_copy("Submitting…", "กำลังส่ง…")} } else { {localized_copy("Submit versioned proposal", "ส่งข้อเสนอที่มีเวอร์ชัน")} } }
                }
            }
            if let Some((success, message)) = outcome.read().clone() {
                div { class: if success { "status-banner good" } else { "status-banner warn" }, role: if success { "status" } else { "alert" }, "{message}" }
            }
        }
    }
}

#[component]
fn RootAccessQueuePanel(
    infrastructure: Option<TenantInfrastructureRecord>,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    administrative_context: Option<TenantAdminContextModel>,
    on_changed: EventHandler<()>,
) -> Element {
    let locale = active_console_locale();
    let refresh = use_signal(|| 0_u64);
    let tenant_id = infrastructure.as_ref().map(|value| value.tenant_id.clone());
    let queue_access_token = access_token.clone();
    let queue_principal_ref = principal_ref.clone();
    let queue_session_id = session_id.clone();
    let queue = use_resource(move || {
        let _refresh = *refresh.read();
        let tenant_id = tenant_id.clone();
        let access_token = queue_access_token.clone();
        let principal_ref = queue_principal_ref.clone();
        let session_id = queue_session_id.clone();
        async move {
            match (tenant_id, access_token, principal_ref, session_id) {
                (Some(tenant_id), Some(access_token), Some(principal_ref), Some(session_id)) => {
                    fetch_root_access_queue(tenant_id, access_token, principal_ref, session_id)
                        .await
                }
                _ => Err("An authenticated tenant context is required.".to_owned()),
            }
        }
    });
    let mut busy = use_signal(|| false);
    let mut outcome = use_signal(|| None::<(bool, String)>);
    let mut device_ref = use_signal(String::new);
    let mut mode = use_signal(|| "health_diagnostic".to_owned());
    let mut business_unit = use_signal(String::new);
    let mut reason = use_signal(move || {
        console_text(
            locale,
            "diagnose tenant data-plane health",
            "วินิจฉัยสถานะระนาบข้อมูลของผู้เช่า",
        )
        .to_owned()
    });
    let mut ticket_reference = use_signal(String::new);
    let mut duration_hours = use_signal(|| "1".to_owned());
    let mut decision_request_id = use_signal(String::new);
    let mut decision_reason = use_signal(|| "tenant Root access decision".to_owned());
    let mut decision_mfa = use_signal(String::new);
    let context_active = administrative_context.as_ref().is_some_and(|context| {
        infrastructure.as_ref().is_some_and(|value| {
            context.active
                && context.tenant_id == value.tenant_id
                && context.root_holding_id == value.root_holding_id
        })
    });
    let administrative_context_id = administrative_context
        .as_ref()
        .filter(|context| context_active && context.active)
        .map(|context| context.administrative_context_id.clone());

    let infrastructure_for_action = infrastructure.clone();
    let submit_access_token = access_token.clone();
    let submit_principal_ref = principal_ref.clone();
    let submit_session_id = session_id.clone();
    let submit_administrative_context_id = administrative_context_id.clone();
    let on_submit = move |event: FormEvent| {
        event.prevent_default();
        if !context_active {
            outcome.set(Some((false, "tenant_context_required".to_owned())));
            return;
        }
        let Some(infrastructure) = infrastructure_for_action.clone() else {
            outcome.set(Some((
                false,
                "Tenant infrastructure is not loaded.".to_owned(),
            )));
            return;
        };
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            submit_access_token.clone(),
            submit_principal_ref.clone(),
            submit_session_id.clone(),
        ) else {
            outcome.set(Some((false, "Authentication is required.".to_owned())));
            return;
        };
        let action = TenantInfrastructureAction::RequestRootAccess(RootAccessInput {
            device_ref: device_ref.read().clone(),
            mode: mode.read().clone(),
            business_unit: business_unit.read().clone(),
            reason: reason.read().clone(),
            ticket_reference: ticket_reference.read().clone(),
            duration_hours: duration_hours.read().parse().unwrap_or_default(),
        });
        device_ref.set(String::new());
        busy.set(true);
        outcome.set(None);
        let mut busy_for_task = busy;
        let mut outcome_for_task = outcome;
        let mut refresh_for_task = refresh;
        let on_changed = on_changed;
        let administrative_context_id = submit_administrative_context_id.clone();
        spawn(async move {
            let result = mutate_tenant_infrastructure(
                access_token,
                principal_ref,
                session_id,
                administrative_context_id,
                infrastructure,
                action,
            )
            .await;
            busy_for_task.set(false);
            match result {
                Ok(message) => {
                    outcome_for_task.set(Some((true, message)));
                    let next_refresh = refresh_for_task.peek().saturating_add(1);
                    refresh_for_task.set(next_refresh);
                    on_changed.call(());
                }
                Err(message) => outcome_for_task.set(Some((false, message))),
            }
        });
    };

    let decision_infrastructure = infrastructure.clone();
    let decision_access_token = access_token.clone();
    let decision_principal_ref = principal_ref.clone();
    let decision_session_id = session_id.clone();
    let decision_administrative_context_id = administrative_context_id;
    let on_decision = EventHandler::new(move |action: &'static str| {
        let (Some(infrastructure), Some(access_token), Some(principal_ref), Some(session_id)) = (
            decision_infrastructure.clone(),
            decision_access_token.clone(),
            decision_principal_ref.clone(),
            decision_session_id.clone(),
        ) else {
            outcome.set(Some((false, "authentication_required".to_owned())));
            return;
        };
        if !context_active {
            outcome.set(Some((false, "tenant_context_required".to_owned())));
            return;
        }
        let scope = match TenantGovernanceScope::validate(
            &infrastructure.tenant_id,
            &infrastructure.root_holding_id,
        ) {
            Ok(scope) => scope,
            Err(error) => {
                outcome.set(Some((false, error)));
                return;
            }
        };
        let request_id = decision_request_id.read().clone();
        let reason = decision_reason.read().clone();
        let mfa_code = decision_mfa.read().clone();
        let command = match action {
            "approve" => TenantGovernanceAction::DecideRootAccess {
                request_id,
                approve: true,
                reason,
                mfa_code,
            },
            "reject" => TenantGovernanceAction::DecideRootAccess {
                request_id,
                approve: false,
                reason,
                mfa_code,
            },
            "revoke" => TenantGovernanceAction::RevokeRootAccess {
                request_id,
                reason,
                mfa_code,
            },
            _ => return,
        };
        busy.set(true);
        outcome.set(None);
        decision_mfa.set(String::new());
        let mut busy_for_task = busy;
        let mut outcome_for_task = outcome;
        let mut refresh_for_task = refresh;
        let on_changed = on_changed;
        let administrative_context_id = decision_administrative_context_id.clone();
        spawn(async move {
            let result = mutate_tenant_governance(
                scope,
                command,
                administrative_context_id,
                access_token,
                principal_ref,
                session_id,
            )
            .await;
            busy_for_task.set(false);
            match result {
                Ok(receipt) => {
                    outcome_for_task.set(Some((
                        true,
                        format!(
                            "{} · {} · {}",
                            receipt.subject_id, receipt.state, receipt.correlation_id
                        ),
                    )));
                    let next = refresh_for_task.peek().saturating_add(1);
                    refresh_for_task.set(next);
                    on_changed.call(());
                }
                Err(error) => outcome_for_task.set(Some((false, error))),
            }
        });
    });

    let queue_snapshot = queue.read().clone();
    rsx! {
        RootAccessRules { active: infrastructure.as_ref().is_some_and(|value| value.root_access_active) }
        section { class: "tenant-config-surface root-access-request-panel", aria_label: localized_copy("Root access request and queue", "คำขอและคิวสิทธิ์ Root"),
            div { class: "eyebrow", {localized_copy("PLATFORM REQUEST · CUSTOMER DECISION", "คำขอจากแพลตฟอร์ม · การตัดสินใจของลูกค้า")} }
            h3 { {localized_copy("Request a bounded capability", "ขอความสามารถที่มีขอบเขตจำกัด")} }
            p { {localized_copy("The customer holding must approve with a different principal and fresh MFA. Platform Root cannot approve its own request.", "โฮลดิ้งลูกค้าต้องอนุมัติด้วยผู้ใช้หลักคนอื่นและ MFA ใหม่ Platform Root ไม่สามารถอนุมัติคำขอของตนเองได้")} }
            if let Some(infrastructure) = infrastructure.as_ref() {
                if infrastructure.agent_id.is_empty() {
                    if infrastructure.is_customer_hosted() {
                        StatePanel { state: UiStateKind::Unavailable, title: localized_copy("Agent enrollment required", "ต้องลงทะเบียนเอเจนต์").to_owned(), message: localized_copy("Root access remains fail-closed until a tenant-bound customer agent is enrolled.", "สิทธิ์ Root จะยังปิดอย่างปลอดภัยจนกว่าจะลงทะเบียนเอเจนต์ลูกค้าที่ผูกกับ tenant").to_owned(), action_label: None, on_action: None }
                    } else {
                        StatePanel { state: UiStateKind::Unavailable, title: localized_copy("Not applicable to ERPX-managed tenants", "ไม่ใช้กับ tenant ที่ ERPX จัดการ").to_owned(), message: localized_copy("This tenant has no customer agent and the console will not fabricate one. Use managed infrastructure controls instead.", "tenant นี้ไม่มีเอเจนต์ลูกค้าและ console จะไม่สร้างเอเจนต์จำลอง ให้ใช้การควบคุมโครงสร้างพื้นฐานแบบ managed แทน").to_owned(), action_label: None, on_action: None }
                    }
                } else {
                    form { class: "typed-command-form", onsubmit: on_submit,
                        div { class: "form-grid",
                            label { {localized_copy("Active session device UUID", "UUID อุปกรณ์ของเซสชันที่ใช้งานอยู่")} KitInput { value: "{device_ref}", autocomplete: "off", maxlength: "36", disabled: *busy.read(), oninput: move |event: FormEvent| device_ref.set(event.value()) } }
                            label { {localized_copy("Access mode", "โหมดการเข้าถึง")} KitSelect { value: "{mode}", disabled: *busy.read(), onchange: move |event: FormEvent| mode.set(event.value()),
                                option { value: "health_diagnostic", {localized_copy("Health diagnostic · max 8h", "วินิจฉัยสุขภาพ · สูงสุด 8 ชม.")} }
                                option { value: "infrastructure_maintenance", {localized_copy("Infrastructure maintenance · max 2h", "บำรุงรักษาโครงสร้างพื้นฐาน · สูงสุด 2 ชม.")} }
                                option { value: "business_diagnostic", {localized_copy("Business diagnostic · max 8h", "วินิจฉัยธุรกิจ · สูงสุด 8 ชม.")} }
                                option { value: "business_mutation", {localized_copy("Business recovery mutation · max 2h", "เปลี่ยนแปลงเพื่อกู้คืนธุรกิจ · สูงสุด 2 ชม.")} }
                                option { value: "emergency_recovery", {localized_copy("Emergency recovery · max 1h", "กู้คืนฉุกเฉิน · สูงสุด 1 ชม.")} }
                            } }
                            label { {localized_copy("Business unit (required for business modes)", "หน่วยธุรกิจ (จำเป็นสำหรับโหมดธุรกิจ)")} KitSelect { value: "{business_unit}", disabled: *busy.read(), onchange: move |event: FormEvent| business_unit.set(event.value()), option { value: "", {localized_copy("Infrastructure only", "เฉพาะโครงสร้างพื้นฐาน")} } for unit in erpx_domain::data_plane::BusinessUnitId::ALL { option { value: unit.as_str(), "{unit.as_str()}" } } } }
                            label { {localized_copy("Duration hours", "ระยะเวลาเป็นชั่วโมง")} KitInput { r#type: "number", min: "1", max: "8", value: "{duration_hours}", disabled: *busy.read(), oninput: move |event: FormEvent| duration_hours.set(event.value()) } }
                            label { {localized_copy("Ticket reference", "ข้อมูลอ้างอิงทิกเก็ต")} KitInput { value: "{ticket_reference}", autocomplete: "off", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| ticket_reference.set(event.value()) } }
                            label { {localized_copy("Exact audited reason", "เหตุผลที่ตรวจสอบย้อนหลังได้อย่างชัดเจน")} KitTextarea { value: "{reason}", maxlength: "512", disabled: *busy.read(), oninput: move |event: FormEvent| reason.set(event.value()) } }
                        }
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Destructive, class: "button", r#type: "submit", disabled: *busy.read(), if *busy.read() { {localized_copy("Requesting…", "กำลังขอ…")} } else { {localized_copy("Submit approval request", "ส่งคำขออนุมัติ")} } }
                    }
                }
            }
            if let Some((success, message)) = outcome.read().clone() {
                div { class: if success { "status-banner good" } else { "status-banner warn" }, role: if success { "status" } else { "alert" }, "{message}" }
            }
            if context_active {
                fieldset { class: "typed-form-grid governance-decision-form", disabled: *busy.read(),
                    legend { {localized_copy("Approve, reject, or revoke", "อนุมัติ ปฏิเสธ หรือเพิกถอน")} }
                    label { {localized_copy("Request UUID", "UUID คำขอ")} KitInput { value: "{decision_request_id}", autocomplete: "off", oninput: move |event: FormEvent| decision_request_id.set(event.value()) } }
                    label { {localized_copy("Audited reason", "เหตุผลที่ตรวจสอบย้อนหลังได้")} KitTextarea { value: "{decision_reason}", maxlength: "512", oninput: move |event: FormEvent| decision_reason.set(event.value()) } }
                    label { {localized_copy("Fresh MFA evidence", "หลักฐาน MFA ล่าสุด")} KitInput { r#type: "password", autocomplete: "one-time-code", value: "{decision_mfa}", oninput: move |event: FormEvent| decision_mfa.set(event.value()) } }
                    if principal_ref.as_deref() == Some(DEVELOPMENT_CONTROLLER_PRINCIPAL) {
                        div { class: "status-banner warn", {localized_copy("Local development MFA/SoD exceptions apply only when the selected role, target policy, and environment gates match. Every use is audited.", "ข้อยกเว้น MFA/SoD สำหรับ local development ใช้ได้เฉพาะเมื่อบทบาท target policy และ environment gate ตรงกัน และทุกครั้งมี audit")} }
                    }
                    div { class: "button-row",
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", onclick: move |_| on_decision.call("approve"), {localized_copy("Approve request", "อนุมัติคำขอ")} }
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", onclick: move |_| on_decision.call("reject"), {localized_copy("Reject request", "ปฏิเสธคำขอ")} }
                        KitButton { size: ButtonSize::Default, variant: ButtonVariant::Destructive, class: "button", r#type: "button", onclick: move |_| on_decision.call("revoke"), {localized_copy("Revoke active access", "เพิกถอนสิทธิ์ที่ใช้งานอยู่")} }
                    }
                }
            } else {
                StatePanel { state: UiStateKind::Denied, title: localized_copy("Administrative context required for Root changes", "ต้องมีบริบทการดูแลสำหรับการเปลี่ยนแปลง Root").to_owned(), message: localized_copy("The queue remains readable. Begin an MFA-gated tenant context before requesting, approving, rejecting, or revoking access.", "ยังอ่านคิวได้ แต่ต้องเริ่มบริบท tenant ที่ผ่าน MFA ก่อนขอ อนุมัติ ปฏิเสธ หรือเพิกถอนสิทธิ์").to_owned(), action_label: None, on_action: None }
            }
            div { class: "section-caption", {localized_copy("REQUEST HISTORY · SERVER-AUTHORIZED", "ประวัติคำขอ · เซิร์ฟเวอร์อนุญาต")} }
            match queue_snapshot {
                None => rsx! { StatePanel { state: UiStateKind::Loading, title: localized_copy("Loading access queue", "กำลังโหลดคิวสิทธิ์").to_owned(), message: localized_copy("Reading customer-visible approval state.", "กำลังอ่านสถานะการอนุมัติที่ลูกค้ามองเห็น").to_owned(), action_label: None, on_action: None } },
                Some(Err(error)) => rsx! { StatePanel { state: tenant_admin_error_state(&error), title: localized_copy("Access queue unavailable", "คิวสิทธิ์ไม่พร้อมใช้งาน").to_owned(), message: localized_copy("The queue read was denied, unavailable, stale, or conflicted as indicated by this state. No capability material is shown.", "สถานะนี้ระบุว่าการอ่านคิวถูกปฏิเสธ ไม่พร้อมใช้งาน ล้าสมัย หรือขัดแย้ง และจะไม่แสดงข้อมูลความสามารถ").to_owned(), action_label: None, on_action: None } },
                Some(Ok(records)) if records.is_empty() => rsx! { StatePanel { state: UiStateKind::Empty, title: localized_copy("No access requests", "ไม่มีคำขอสิทธิ์").to_owned(), message: localized_copy("No open or closed Root requests exist for this tenant.", "ไม่มีคำขอ Root ที่เปิดหรือปิดสำหรับผู้เช่านี้").to_owned(), action_label: None, on_action: None } },
                Some(Ok(records)) => rsx! {
                    div { class: "table-wrap",
                        KitTable { class: "data-table",
                            thead { tr {
                                th { {localized_copy("Request", "คำขอ")} }
                                th { {localized_copy("Mode / scope", "โหมด / ขอบเขต")} }
                                th { {localized_copy("Reason", "เหตุผล")} }
                                th { {localized_copy("State / expiry", "สถานะ / หมดอายุ")} }
                            } }
                            tbody {
                                for record in records {
                                    {
                                        let scope_label = if record.business_units.is_empty() {
                                            localized_copy("Infrastructure", "โครงสร้างพื้นฐาน").to_owned()
                                        } else {
                                            record.business_units.join(", ")
                                        };
                                        let action_label = record.allowed_actions.join(", ");
                                        rsx! { tr {
                                            td { code { "{record.request_id}" } small { "{record.ticket_reference}" } KitButton { size: ButtonSize::Sm, variant: ButtonVariant::Link, r#type: "button", onclick: { let request_id = record.request_id.clone(); move |_| decision_request_id.set(request_id.clone()) }, {localized_copy("Review", "ตรวจสอบ")} } }
                                            td { "{record.mode}" small { "{scope_label}" } }
                                            td { "{record.reason}" small { "{action_label}" } }
                                            td { span { class: "badge muted", "{record.state}" } small { "{display_timestamp(&record.requested_until)}" } }
                                        } }
                                    }
                                }
                            }
                        }
                    }
                },
            }
        }
    }
}

#[component]
fn PlatformTenantOrganizationPanel(
    tenant_id: String,
    root_holding_id: String,
    administrative_context: TenantAdminContextModel,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
) -> Element {
    let mut cursor = use_signal(String::new);
    let refresh = use_signal(|| 0_u64);
    let read_tenant_id = tenant_id.clone();
    let read_holding_id = root_holding_id.clone();
    let read_context_id = administrative_context.administrative_context_id.clone();
    let read_access_token = access_token.clone();
    let read_principal_ref = principal_ref.clone();
    let read_session_id = session_id.clone();
    let mut nodes = use_resource(move || {
        let _refresh = *refresh.read();
        let after_cursor = cursor.read().clone();
        let scope = TenantGovernanceScope::validate(&read_tenant_id, &read_holding_id);
        let context_id = read_context_id.clone();
        let access_token = read_access_token.clone();
        let principal_ref = read_principal_ref.clone();
        let session_id = read_session_id.clone();
        async move {
            let scope = scope?;
            let (Some(access_token), Some(principal_ref), Some(session_id)) =
                (access_token, principal_ref, session_id)
            else {
                return Err("authentication_required".to_owned());
            };
            fetch_tenant_organization_nodes(
                scope,
                after_cursor,
                Some(context_id),
                access_token,
                principal_ref,
                session_id,
            )
            .await
        }
    });
    let mut kind = use_signal(|| "company".to_owned());
    let mut node_id = use_signal(|| Uuid::new_v4().to_string());
    let mut company_id = use_signal(String::new);
    let mut branch_id = use_signal(String::new);
    let mut department_id = use_signal(String::new);
    let mut code = use_signal(String::new);
    let mut name = use_signal(String::new);
    let mut busy = use_signal(|| false);
    let mut outcome = use_signal(|| None::<Result<TenantOrganizationWriteReceipt, String>>);
    let save_tenant_id = tenant_id.clone();
    let save_holding_id = root_holding_id.clone();
    let save_context_id = administrative_context.administrative_context_id.clone();
    let on_save = move |_| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            access_token.clone(),
            principal_ref.clone(),
            session_id.clone(),
        ) else {
            outcome.set(Some(Err("authentication_required".to_owned())));
            return;
        };
        let scope = match TenantGovernanceScope::validate(&save_tenant_id, &save_holding_id) {
            Ok(scope) => scope,
            Err(error) => {
                outcome.set(Some(Err(error)));
                return;
            }
        };
        let input = TenantOrganizationNodeInput {
            kind: kind.read().clone(),
            node_id: node_id.read().clone(),
            company_id: company_id.read().clone(),
            branch_id: branch_id.read().clone(),
            department_id: department_id.read().clone(),
            code: code.read().clone(),
            name: name.read().clone(),
        };
        busy.set(true);
        outcome.set(None);
        let context_id = save_context_id.clone();
        let mut busy_for_task = busy;
        let mut outcome_for_task = outcome;
        let mut nodes_for_task = nodes;
        let mut cursor_for_task = cursor;
        spawn(async move {
            let result = save_tenant_organization_node(
                scope,
                input,
                Some(context_id),
                access_token,
                principal_ref,
                session_id,
            )
            .await;
            busy_for_task.set(false);
            if result.is_ok() {
                cursor_for_task.set(String::new());
                nodes_for_task.restart();
            }
            outcome_for_task.set(Some(result));
        });
    };
    let snapshot = nodes.read().clone();
    rsx! {
        section { class: "tenant-config-surface organization-node-panel", aria_label: localized_copy("Tenant organization nodes", "หน่วยองค์กรของ tenant"),
            div { class: "eyebrow", {localized_copy("SERVER-OWNED ORGANIZATION TREE", "โครงสร้างองค์กรที่เซิร์ฟเวอร์เป็นเจ้าของ")} }
            h3 { {localized_copy("Create an organization node", "สร้างหน่วยองค์กร")} }
            p { {localized_copy("Creation uses the owner-context command and authoritative tenant/holding route. Existing nodes are changed through explicit rename, code, placement, and lifecycle actions.", "การสร้างใช้คำสั่งของบริบทเจ้าของและเส้นทาง tenant/holding ที่เป็นแหล่งจริง ส่วนหน่วยเดิมเปลี่ยนผ่านการดำเนินการเปลี่ยนชื่อ รหัส ตำแหน่ง และวงจรชีวิตอย่างชัดเจน")} }
            fieldset { class: "typed-form-grid", disabled: *busy.read(),
                label { {localized_copy("Node kind", "ประเภทหน่วย")} KitSelect { value: "{kind}", onchange: move |event: FormEvent| kind.set(event.value()), for value in ["holding", "company", "headquarters", "department", "team", "branch"] { option { value, "{value}" } } } }
                label { {localized_copy("Node UUID", "UUID หน่วย")} KitInput { value: "{node_id}", autocomplete: "off", oninput: move |event: FormEvent| node_id.set(event.value()) } }
                label { {localized_copy("Parent company UUID", "UUID บริษัทแม่")} KitInput { value: "{company_id}", autocomplete: "off", oninput: move |event: FormEvent| company_id.set(event.value()) } }
                label { {localized_copy("Parent branch UUID", "UUID สาขาแม่")} KitInput { value: "{branch_id}", autocomplete: "off", oninput: move |event: FormEvent| branch_id.set(event.value()) } }
                label { {localized_copy("Parent department UUID", "UUID แผนกแม่")} KitInput { value: "{department_id}", autocomplete: "off", oninput: move |event: FormEvent| department_id.set(event.value()) } }
                label { {localized_copy("Code", "รหัส")} KitInput { value: "{code}", maxlength: "64", oninput: move |event: FormEvent| code.set(event.value()) } }
                label { {localized_copy("Name", "ชื่อ")} KitInput { value: "{name}", maxlength: "160", oninput: move |event: FormEvent| name.set(event.value()) } }
                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "button", onclick: on_save, if *busy.read() { {localized_copy("Creating…", "กำลังสร้าง…")} } else { {localized_copy("Create organization node", "สร้างหน่วยองค์กร")} } }
            }
            if let Some(result) = outcome.read().as_ref() {
                div { class: if result.is_ok() { "status-banner good" } else { "status-banner warn" },
                    {match result { Ok(receipt) => format!("{} {} · v{} · {}", receipt.kind, receipt.node_id, receipt.aggregate_version, receipt.correlation_id), Err(error) => tenant_admin_error_message(error).to_owned() }}
                }
            }
            div { class: "section-caption", {localized_copy("AUTHORIZED ORGANIZATION PAGE", "หน้าองค์กรที่ได้รับอนุญาต")} }
            match snapshot {
                None => rsx! { StatePanel { state: UiStateKind::Loading, title: localized_copy("Loading organization", "กำลังโหลดองค์กร").to_owned(), message: localized_copy("Reading the tenant organization tree.", "กำลังอ่านโครงสร้างองค์กรของ tenant").to_owned(), action_label: None, on_action: None } },
                Some(Err(error)) => rsx! { StatePanel { state: tenant_admin_error_state(&error), title: localized_copy("Organization unavailable", "องค์กรไม่พร้อมใช้งาน").to_owned(), message: tenant_admin_error_message(&error).to_owned(), action_label: Some(localized_copy("Retry organization", "ลองโหลดองค์กรอีกครั้ง").to_owned()), on_action: Some(EventHandler::new(move |_| nodes.restart())) } },
                Some(Ok(page)) if page.nodes.is_empty() => rsx! { StatePanel { state: UiStateKind::Empty, title: localized_copy("No organization nodes", "ไม่มีหน่วยองค์กร").to_owned(), message: localized_copy("No nodes exist in this authorized holding page.", "ไม่มีหน่วยในหน้าโฮลดิ้งที่ได้รับอนุญาตนี้").to_owned(), action_label: None, on_action: None } },
                Some(Ok(page)) => rsx! {
                    div { class: "table-wrap", KitTable { class: "data-table",
                        thead { tr { th { {localized_copy("Kind", "ประเภท")} } th { {localized_copy("Code / name", "รหัส / ชื่อ")} } th { {localized_copy("Scope", "ขอบเขต")} } th { {localized_copy("State", "สถานะ")} } th { {localized_copy("Version", "เวอร์ชัน")} } } }
                        tbody { for node in page.nodes.iter() { tr { td { "{node.kind}" } td { strong { "{node.code}" } small { "{node.name}" } } td { code { "{node.node_id}" } small { "{node.company_id}" } } td { "{node.status}" } td { "{node.aggregate_version}" } } } }
                    } }
                    if page.has_more { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", onclick: { let next = page.next_cursor.clone(); move |_| cursor.set(next.clone()) }, {localized_copy("Next organization page", "หน้าองค์กรถัดไป")} } }
                },
            }
        }
    }
}

#[component]
fn BranchProvisioningPanel(
    tenant_id: String,
    administrative_context: TenantAdminContextModel,
    access_token: Option<String>,
    principal_ref: Option<String>,
    session_id: Option<String>,
    on_changed: EventHandler<()>,
) -> Element {
    let refresh = use_signal(|| 0_u64);
    let queue_tenant_id = tenant_id.clone();
    let queue_context_id = administrative_context.administrative_context_id.clone();
    let queue_access_token = access_token.clone();
    let queue_principal_ref = principal_ref.clone();
    let queue_session_id = session_id.clone();
    let queue = use_resource(move || {
        let _refresh = *refresh.read();
        let tenant_id = queue_tenant_id.clone();
        let context_id = queue_context_id.clone();
        let access_token = queue_access_token.clone();
        let principal_ref = queue_principal_ref.clone();
        let session_id = queue_session_id.clone();
        async move {
            match (access_token, principal_ref, session_id) {
                (Some(access_token), Some(principal_ref), Some(session_id)) => {
                    fetch_branch_provisionings(
                        tenant_id,
                        context_id,
                        access_token,
                        principal_ref,
                        session_id,
                    )
                    .await
                }
                _ => Err("Authentication is required.".to_owned()),
            }
        }
    });
    let mut busy = use_signal(|| false);
    let mut outcome = use_signal(|| None::<Result<String, String>>);
    let mut company_id = use_signal(String::new);
    let mut branch_id = use_signal(|| Uuid::new_v4().to_string());
    let mut branch_code = use_signal(String::new);
    let mut branch_name = use_signal(String::new);
    let mut registration_number = use_signal(String::new);
    let mut database_profile_key = use_signal(String::new);
    let mut enabled_business_units = use_signal(Vec::<String>::new);
    let mut provision_mfa = use_signal(String::new);
    let mut queue_mfa = use_signal(String::new);
    let mut suspend_confirmation = use_signal(String::new);

    let tenant_id_for_action = tenant_id.clone();
    let context_id_for_action = administrative_context.administrative_context_id.clone();
    let on_action = EventHandler::new(move |action: BranchInfrastructureAction| {
        let (Some(access_token), Some(principal_ref), Some(session_id)) = (
            access_token.clone(),
            principal_ref.clone(),
            session_id.clone(),
        ) else {
            outcome.set(Some(Err("Authentication is required.".to_owned())));
            return;
        };
        busy.set(true);
        outcome.set(None);
        let tenant_id = tenant_id_for_action.clone();
        let context_id = context_id_for_action.clone();
        let mut busy_for_task = busy;
        let mut outcome_for_task = outcome;
        let mut refresh_for_task = refresh;
        let on_changed = on_changed;
        spawn(async move {
            let result = mutate_branch_infrastructure(
                tenant_id,
                context_id,
                action,
                access_token,
                principal_ref,
                session_id,
            )
            .await;
            busy_for_task.set(false);
            if result.is_ok() {
                let next_refresh = refresh_for_task.peek().saturating_add(1);
                refresh_for_task.set(next_refresh);
                on_changed.call(());
            }
            outcome_for_task.set(Some(result));
        });
    });

    let queue_snapshot = queue.read().clone();
    rsx! {
        section { class: "tenant-config-surface branch-provisioning-panel", aria_label: localized_copy("Branch infrastructure provisioning", "การจัดเตรียมโครงสร้างพื้นฐานสาขา"),
            div { class: "eyebrow", {localized_copy("BRANCH ROUTE LIFECYCLE", "วงจรชีวิตเส้นทางสาขา")} }
            h3 { {localized_copy("Provision an isolated branch", "จัดเตรียมสาขาที่แยกจากกัน")} }
            p { {localized_copy("A branch request is capacity-checked, tenant-context bound, MFA-gated, and queued for bounded provisioning. Database credentials never cross this form.", "คำขอสาขาจะตรวจสอบความจุ ผูกกับบริบทผู้เช่า ใช้ MFA และเข้าคิวการจัดเตรียมแบบมีขอบเขต ข้อมูลประจำตัวฐานข้อมูลจะไม่ผ่านแบบฟอร์มนี้")} }
            form { class: "typed-command-form", onsubmit: move |event| {
                event.prevent_default();
                let mfa_code = provision_mfa.read().clone();
                provision_mfa.set(String::new());
                on_action.call(BranchInfrastructureAction::Provision(ProvisionBranchInput {
                    company_id: company_id.read().clone(),
                    branch_id: branch_id.read().clone(),
                    branch_code: branch_code.read().clone(),
                    branch_name: branch_name.read().clone(),
                    registration_number: registration_number.read().clone(),
                    database_profile_key: database_profile_key.read().clone(),
                    enabled_business_units: enabled_business_units.read().clone(),
                    mfa_code,
                }));
            },
                div { class: "form-grid",
                    label { {localized_copy("Company UUID", "UUID บริษัท")} KitInput { value: "{company_id}", autocomplete: "off", maxlength: "36", disabled: *busy.read(), oninput: move |event: FormEvent| company_id.set(event.value()) } }
                    label { {localized_copy("New branch UUID", "UUID สาขาใหม่")} KitInput { value: "{branch_id}", autocomplete: "off", maxlength: "36", disabled: *busy.read(), oninput: move |event: FormEvent| branch_id.set(event.value()) } }
                    label { {localized_copy("Branch code", "รหัสสาขา")} KitInput { value: "{branch_code}", autocomplete: "off", maxlength: "64", disabled: *busy.read(), oninput: move |event: FormEvent| branch_code.set(event.value()) } }
                    label { {localized_copy("Branch name", "ชื่อสาขา")} KitInput { value: "{branch_name}", autocomplete: "off", maxlength: "160", disabled: *busy.read(), oninput: move |event: FormEvent| branch_name.set(event.value()) } }
                    label { {localized_copy("Registration number", "หมายเลขทะเบียน")} KitInput { value: "{registration_number}", autocomplete: "off", maxlength: "96", disabled: *busy.read(), oninput: move |event: FormEvent| registration_number.set(event.value()) } }
                    label { {localized_copy("Database profile routing key", "คีย์กำหนดเส้นทางโปรไฟล์ฐานข้อมูล")} KitInput { value: "{database_profile_key}", autocomplete: "off", maxlength: "255", disabled: *busy.read(), oninput: move |event: FormEvent| database_profile_key.set(event.value()) } }
                    label { {localized_copy("Fresh MFA code", "รหัส MFA ใหม่")} KitInput { r#type: "password", value: "{provision_mfa}", autocomplete: "one-time-code", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| provision_mfa.set(event.value()) } }
                }
                fieldset { class: "business-unit-selector", disabled: *busy.read(), legend { {localized_copy("Enabled business units", "หน่วยธุรกิจที่เปิดใช้งาน")} }
                    div { class: "check-grid",
                        for unit in erpx_domain::data_plane::BusinessUnitId::ALL {
                            {
                                let unit_key = unit.as_str().to_owned();
                                let checked = enabled_business_units.read().contains(&unit_key);
                                rsx! { label { KitInput { r#type: "checkbox", checked, onchange: {
                                    let unit_key = unit_key.clone();
                                    move |event: FormEvent| {
                                        let mut selected = enabled_business_units.write();
                                        if event.checked() {
                                            if !selected.contains(&unit_key) { selected.push(unit_key.clone()); }
                                        } else {
                                            selected.retain(|value| value != &unit_key);
                                        }
                                    }
                                } } "{unit_key}" } }
                            }
                        }
                    }
                }
                KitButton { size: ButtonSize::Default, variant: ButtonVariant::Primary, class: "button", r#type: "submit", disabled: *busy.read(), if *busy.read() { {localized_copy("Queueing…", "กำลังเข้าคิว…")} } else { {localized_copy("Queue branch provisioning", "เข้าคิวการจัดเตรียมสาขา")} } }
            }
            if let Some(result) = outcome.read().clone() {
                match result {
                    Ok(message) => rsx! { div { class: "status-banner good", role: "status", "{message}" } },
                    Err(message) => rsx! { div { class: "status-banner warn", role: "alert", "{message}" } },
                }
            }
            div { class: "section-caption", {localized_copy("PROVISIONING STATUS AND BOUNDED RECOVERY", "สถานะการจัดเตรียมและการกู้คืนแบบมีขอบเขต")} }
            div { class: "form-grid branch-queue-confirmation",
                label { {localized_copy("Fresh MFA for retry or suspension", "MFA ใหม่สำหรับลองอีกครั้งหรือระงับ")} KitInput { r#type: "password", value: "{queue_mfa}", autocomplete: "one-time-code", maxlength: "128", disabled: *busy.read(), oninput: move |event: FormEvent| queue_mfa.set(event.value()) } }
                label { {localized_copy("Type branch UUID to confirm suspension", "พิมพ์ UUID สาขาเพื่อยืนยันการระงับ")} KitInput { value: "{suspend_confirmation}", autocomplete: "off", maxlength: "36", disabled: *busy.read(), oninput: move |event: FormEvent| suspend_confirmation.set(event.value()) } }
            }
            match queue_snapshot {
                None => rsx! { StatePanel { state: UiStateKind::Loading, title: localized_copy("Loading branch jobs", "กำลังโหลดงานสาขา").to_owned(), message: localized_copy("Reading the authorized provisioning queue.", "กำลังอ่านคิวการจัดเตรียมที่ได้รับอนุญาต").to_owned(), action_label: None, on_action: None } },
                Some(Err(error)) => rsx! { StatePanel { state: tenant_admin_error_state(&error), title: localized_copy("Branch queue unavailable", "คิวสาขาไม่พร้อมใช้งาน").to_owned(), message: localized_copy("The state distinguishes a denied, unavailable, stale, conflicting, or invalid branch read. Refresh the administrative context before retrying.", "สถานะจะแยกการอ่านสาขาที่ถูกปฏิเสธ ไม่พร้อมใช้งาน ล้าสมัย ขัดแย้ง หรือไม่ถูกต้อง ให้รีเฟรชบริบทการดูแลก่อนลองอีกครั้ง").to_owned(), action_label: None, on_action: None } },
                Some(Ok(records)) if records.is_empty() => rsx! { StatePanel { state: UiStateKind::Empty, title: localized_copy("No branch jobs", "ไม่มีงานสาขา").to_owned(), message: localized_copy("No branch provisioning has been requested for this tenant.", "ยังไม่มีการขอจัดเตรียมสาขาสำหรับผู้เช่านี้").to_owned(), action_label: None, on_action: None } },
                Some(Ok(records)) => rsx! { div { class: "table-wrap", KitTable { class: "data-table",
                    thead { tr { th { {localized_copy("Branch", "สาขา")} } th { {localized_copy("Units", "หน่วย")} } th { {localized_copy("State", "สถานะ")} } th { {localized_copy("Evidence", "หลักฐาน")} } th { {localized_copy("Actions", "การดำเนินการ")} } } }
                    tbody { for record in records { tr {
                        td { strong { "{record.branch_code}" } small { "{record.branch_name}" } small { "{record.branch_id}" } }
                        td { "{record.enabled_business_units.len()}" }
                        td { span { class: "badge muted", "{record.state}" } small { {localized_copy("attempt", "ครั้งที่")} " {record.attempt_count}" } }
                        td { if record.failure_category.is_empty() { {localized_copy("No failure evidence", "ไม่มีหลักฐานความล้มเหลว")} } else { "{record.failure_category}" } small { "{display_timestamp(&record.updated_at)}" } small { "{record.correlation_id}" } }
                        td { div { class: "tenant-action-row",
                            if record.retryable() { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Secondary, class: "button", r#type: "button", disabled: *busy.read(), onclick: { let job_id = record.job_id.clone(); move |_| { let mfa_code = queue_mfa.read().clone(); queue_mfa.set(String::new()); on_action.call(BranchInfrastructureAction::Retry { job_id: job_id.clone(), mfa_code }); } }, {localized_copy("Retry", "ลองอีกครั้ง")} } }
                            if record.active() { KitButton { size: ButtonSize::Default, variant: ButtonVariant::Destructive, class: "button", r#type: "button", disabled: *busy.read() || suspend_confirmation.read().trim() != record.branch_id, onclick: { let branch_id = record.branch_id.clone(); move |_| { let mfa_code = queue_mfa.read().clone(); queue_mfa.set(String::new()); suspend_confirmation.set(String::new()); on_action.call(BranchInfrastructureAction::Suspend { branch_id: branch_id.clone(), mfa_code }); } }, {localized_copy("Suspend route", "ระงับเส้นทาง")} } }
                        } }
                    } } }
                } } },
            }
        }
    }
}

