    #[test]
    fn navigation_context_uses_the_exact_canonical_active_role_scope() {
        let holding_id = Uuid::parse_str("11111111-1111-4111-8111-111111111111").unwrap();
        let company_id = Uuid::parse_str("22222222-2222-4222-8222-222222222222").unwrap();
        let branch_id = Uuid::parse_str("33333333-3333-4333-8333-333333333333").unwrap();
        let cases = [
            "platform".to_owned(),
            format!("holding:{holding_id}"),
            format!("company:{holding_id}:{company_id}"),
            format!("branch:{holding_id}:{company_id}:{branch_id}"),
            format!("subtree:{holding_id}:companies={company_id}:branches={branch_id}"),
        ];

        for scope_key in cases {
            let context = navigation_query_context("principal", "session", &scope_key)
                .expect("canonical scope");
            let scope = context
                .tenant_scope
                .and_then(|scope| scope.scope)
                .expect("typed tenant scope");
            match (scope_key.as_str(), scope) {
                ("platform", tenant_scope::Scope::Platform(_)) => {}
                (key, tenant_scope::Scope::Holding(_)) if key.starts_with("holding:") => {}
                (key, tenant_scope::Scope::Company(_)) if key.starts_with("company:") => {}
                (key, tenant_scope::Scope::Branch(_)) if key.starts_with("branch:") => {}
                (key, tenant_scope::Scope::Subtree(_)) if key.starts_with("subtree:") => {}
                _ => panic!("scope kind did not follow active role: {scope_key}"),
            }
        }

        for malformed in [
            "",
            "holding",
            "holding:not-a-uuid",
            "company:11111111-1111-4111-8111-111111111111",
            "branch:11111111-1111-4111-8111-111111111111:22222222-2222-4222-8222-222222222222",
            "subtree:11111111-1111-4111-8111-111111111111:companies=bad:branches=",
        ] {
            assert!(navigation_query_context("principal", "session", malformed).is_err());
        }
    }

