    #[test]
    fn registered_web_routes_are_assigned_to_the_unified_page_families() {
        for definition in RouteRegistry::platform()
            .definitions()
            .iter()
            .chain(RouteRegistry::marketing_crm().definitions())
        {
            assert!(matches!(
                console_page_family(definition.template),
                "dashboard" | "collection" | "record" | "workflow" | "settings" | "operations"
            ));
        }
        for path in [
            "/auth/security",
            "/platform/directories",
            "/platform/incidents",
            "/support/tickets",
            "/finance/close",
            "/platform/customers/customer-001",
        ] {
            assert!(matches!(
                console_page_family(path),
                "dashboard" | "collection" | "record" | "workflow" | "settings" | "operations"
            ));
        }
        assert_eq!(console_page_family("/platform"), "dashboard");
        assert_eq!(console_page_family("/work"), "collection");
        assert_eq!(console_page_family("/processes"), "workflow");
        assert_eq!(console_page_family("/insights"), "dashboard");
        assert_eq!(console_page_family("/auth/security"), "settings");
        assert_eq!(console_page_family("/platform/incidents"), "operations");
    }

    #[test]
    fn web_styles_are_loaded_as_compiled_assets_and_public_routes_use_public_shell() {
        let source = include_str!("composition.rs");
        let styles = include_str!("../assets/console-surfaces.css");
        let legacy_shared_style = ["SHARED", "_STYLES"].join("");
        assert!(!source.contains(&legacy_shared_style));
        assert!(source.contains("/assets/console-surfaces.css"));
        assert!(source.contains("ConsoleStylesheets"));
        assert!(source.contains("AI_COLLABORATION_STYLES"));
        let authenticated_boundary = source
            .find("if !show_authenticated_shell")
            .expect("authenticated shell boundary");
        let launcher_mount = source
            .find("            FloatingAiLauncher {")
            .expect("AI launcher mount");
        assert!(authenticated_boundary < launcher_mount);
        assert!(source.contains("data-route-family\": \"public-shell"));
        assert!(source.contains("data-page-family\": route_family"));

        let role_groups = styles
            .split_once(".work-role-groups {")
            .and_then(|(_, rest)| rest.split_once('}'))
            .map(|(rule, _)| rule)
            .expect("work role group styles");
        assert!(role_groups.contains("overflow-y: auto"));
        assert!(role_groups.contains("overscroll-behavior: contain"));
        assert!(styles.contains(".work-role-card.selected"));
        assert!(styles.contains(".role-selection-actions"));
    }

    #[test]
    fn console_buttons_use_explicit_governed_variants_and_sizes() {
        let source = include_str!("composition.rs");
        for (index, segment) in source.split("KitButton {").skip(1).enumerate() {
            let head = segment.get(..segment.len().min(1_600)).unwrap_or(segment);
            assert!(
                head.contains("variant:"),
                "KitButton #{index} has no explicit variant"
            );
            assert!(
                head.contains("size:"),
                "KitButton #{index} has no explicit size"
            );
        }
        let forbidden_classes = [
            ["class: \"button ", "primary"].concat(),
            ["class: \"button ", "secondary"].concat(),
            ["class: \"button ", "danger"].concat(),
            ["class: \"link", "-button"].concat(),
        ];
        for forbidden in forbidden_classes {
            assert!(!source.contains(&forbidden), "retains {forbidden}");
        }
    }

    #[test]
    fn authentication_routes_and_browser_transports_keep_credentials_out_of_route_state() {
        for (path, route) in [
            ("/login", AuthRoute::SignIn),
            ("/auth/accounts", AuthRoute::Accounts),
            ("/auth/security", AuthRoute::Security),
            ("/auth/devices", AuthRoute::Devices),
            ("/auth/recovery", AuthRoute::Recovery),
        ] {
            assert_eq!(console_deep_link(path), Some(ConsoleDeepLink::Auth(route)));
            assert_eq!(route.path(), path);
        }
        assert_eq!(console_deep_link("/auth"), None);
        assert_eq!(console_deep_link("/auth/sign-in"), None);
        assert!(is_legacy_login_path("/auth"));
        assert!(is_legacy_login_path("/auth/sign-in"));
        assert_eq!(
            login_return_path_from_url("/login?return_to=/platform/tenants"),
            Some("/platform/tenants".to_owned())
        );
        assert_eq!(
            login_redirect_location("/platform/tenants?secret=discarded"),
            "/login?return_to=/platform/tenants"
        );
        assert_eq!(
            password_form_error_from_url("/login?auth_error=invalid_request"),
            Some("invalid_request")
        );
        assert_eq!(
            password_form_error_from_url(
                "/login?return_to=/platform/tenants&auth_error=authentication_rejected"
            ),
            Some("authentication_rejected")
        );
        assert_eq!(
            password_form_error_message("/login?auth_error=authentication_unavailable", Locale::Th),
            Some("บริการยืนยันตัวตนไม่พร้อมใช้งานชั่วคราว".to_owned())
        );
        for unsafe_error in [
            "/login?auth_error=unknown",
            "/login?auth_error=invalid_request&auth_error=authentication_rejected",
            "/billing?auth_error=invalid_request",
        ] {
            assert_eq!(password_form_error_from_url(unsafe_error), None);
        }
        for unsafe_target in [
            "/login",
            "//attacker.example/path",
            "https://attacker.example/path",
            "/login?return_to=%2Fplatform%2Ftenants",
            "/login?return_to=/platform/tenants&return_to=/billing",
        ] {
            assert_eq!(login_return_path_from_url(unsafe_target), None);
        }
        assert_eq!(console_deep_link("/auth/passkeys/opaque"), None);
        assert_eq!(console_deep_link("/auth/security?token=secret"), None);
    }

