    #[test]
    fn initial_deep_link_dispatch_covers_each_console_surface() {
        assert_eq!(
            console_deep_link("/work"),
            Some(ConsoleDeepLink::Home(EnterpriseHomeRoute::Work))
        );
        assert_eq!(
            console_deep_link("/processes"),
            Some(ConsoleDeepLink::Home(EnterpriseHomeRoute::Processes))
        );
        assert_eq!(
            console_deep_link("/insights"),
            Some(ConsoleDeepLink::Home(EnterpriseHomeRoute::Insights))
        );
        assert_eq!(
            console_deep_link("/modules"),
            Some(ConsoleDeepLink::Home(EnterpriseHomeRoute::Modules))
        );
        assert_eq!(
            console_deep_link("/ai"),
            Some(ConsoleDeepLink::Workspace(RegisteredWorkspaceRoute {
                workspace: Some(WorkspaceId::AiCollaboration),
                feature_id: "ai-collaboration",
                route_root: "/ai",
                navigation_route_id: "ai",
                canonical_path: "/ai".to_owned(),
            }))
        );
        for workspace in WORKSPACES {
            assert!(
                console_deep_link(workspace.route).is_some(),
                "typed workspace route {} is not registered",
                workspace.route
            );
        }
        for feature in erpx_ui_kit::CurrentFeatureKind::ALL {
            for family in feature.record_families() {
                let collection = family.collection_path();
                assert!(
                    console_deep_link(&collection).is_some(),
                    "current workspace collection route {collection} is not registered",
                );
            }
        }
        assert_eq!(
            console_deep_link("/platform/directories?tab=connectors"),
            Some(ConsoleDeepLink::Directory)
        );
        assert_eq!(
            console_deep_link("/platform/billing#entitlements"),
            Some(ConsoleDeepLink::Billing(BillingRoute::Overview))
        );
        assert_eq!(
            console_deep_link("/billing/checkout/success?session_id=ignored"),
            Some(ConsoleDeepLink::Billing(BillingRoute::CheckoutSuccess))
        );
        assert_eq!(
            console_deep_link("/platform/projections"),
            Some(ConsoleDeepLink::PlatformOperations(
                PlatformOperationsRoute::Projections
            ))
        );
        assert_eq!(
            console_deep_link("/platform/incidents"),
            Some(ConsoleDeepLink::Support(SupportRoute::PlatformIncidents))
        );
        assert_eq!(
            console_deep_link("/marketing/leads"),
            Some(ConsoleDeepLink::Marketing(RouteId::MarketingLeads))
        );
        assert_eq!(
            console_deep_link("/marketing/lead"),
            Some(ConsoleDeepLink::Marketing(RouteId::CrmLeads))
        );
        assert_eq!(
            console_deep_link("/finance?view=close"),
            Some(ConsoleDeepLink::ProductContext(ProductContext::Finance))
        );
        assert_eq!(
            console_deep_link("/asset"),
            Some(ConsoleDeepLink::ProductContext(ProductContext::Assets))
        );
        assert_eq!(
            console_deep_link("/assets"),
            None,
            "the static asset namespace must never be registered as an application route",
        );
        assert!(matches!(
            console_deep_link("/platform/customers/customer-001/health"),
            Some(ConsoleDeepLink::Customer(PlatformRoute::Customer { .. }))
        ));
    }

    #[test]
    fn module_hub_explains_required_roles_and_only_offers_assigned_switches() {
        let required = vec!["finance_viewer".to_owned(), "finance_operator".to_owned()];
        let assigned = ["finance_viewer".to_owned()]
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>();
        let unrelated = ["sales_viewer".to_owned()]
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>();

        assert!(assigned_role_can_open_module(&required, &assigned));
        assert!(!assigned_role_can_open_module(&required, &unrelated));
        assert!(module_requirement_copy(Locale::En, &required).contains("Finance Viewer"));
        assert!(module_requirement_copy(Locale::Th, &required).contains("บทบาทการทำงาน"));

        let finance = erpx_ui_core::NavItem::new("Finance", "/finance", "finance")
            .with_manifest_metadata("finance", "nav.business_unit.finance")
            .with_access(erpx_ui_core::NavAccess::locked(["finance_viewer"]));
        assert!(module_matches_query(&finance, "Finance"));
        assert!(module_matches_query(&finance, "การเงิน"));
        assert!(module_matches_query(&finance, "ผู้ดูข้อมูล การเงิน"));
        assert!(!module_matches_query(&finance, "Sales"));
    }

    fn role_option(
        selection_id: &str,
        role_key: &str,
        scope_key: &str,
    ) -> super::ActiveRoleOptionModel {
        super::ActiveRoleOptionModel {
            selection_id: selection_id.to_owned(),
            source: "local".into(),
            role_key: role_key.to_owned(),
            scope_key: scope_key.to_owned(),
            expires_at: None,
            requires_mfa: false,
        }
    }

