    #[test]
    fn authorized_navigation_manifest_gates_registered_document_routes() {
        let finance = erpx_ui_core::NavItem::new("Finance", "/finance", "module")
            .with_manifest_metadata("finance", "nav.business_unit.finance");
        let sales = erpx_ui_core::NavItem::new("Sales", "/sales", "module")
            .with_manifest_metadata("sales", "nav.business_unit.sales")
            .with_access(erpx_ui_core::NavAccess::locked(["sales_viewer"]));
        let groups = vec![erpx_ui_core::NavGroup::new(
            "Business Modules",
            vec![finance, sales],
        )];
        assert!(super::navigation_authorizes_console_path("/work", &groups));
        assert!(super::navigation_authorizes_console_path(
            "/finance", &groups
        ));
        assert!(!super::navigation_authorizes_console_path(
            "/sales", &groups
        ));
        assert!(!super::navigation_authorizes_console_path(
            "/platform/settings/access-simulation",
            &groups
        ));
        let duplicate_support_groups = vec![
            erpx_ui_core::NavGroup::new(
                "Customer Operations",
                vec![
                    erpx_ui_core::NavItem::new("Support", "/platform/support", "support")
                        .with_manifest_metadata("support", "nav.route.support")
                        .with_access(erpx_ui_core::NavAccess::locked(["platform_support_agent"])),
                ],
            ),
            erpx_ui_core::NavGroup::new(
                "Tenant Administration",
                vec![
                    erpx_ui_core::NavItem::new("Support", "/support", "support")
                        .with_manifest_metadata("support", "nav.route.support"),
                ],
            ),
        ];
        assert!(!super::navigation_authorizes_console_path(
            "/platform/support/new",
            &duplicate_support_groups
        ));
        assert!(super::navigation_authorizes_console_path(
            "/support/new",
            &duplicate_support_groups
        ));

        let canonical_group = erpx_ui_core::canonical_workspace_navigation(Locale::En);
        let retired_workspace_prefix = ["/", "workspaces"].concat();
        for item in &canonical_group.items {
            assert!(
                !item.path.starts_with(&retired_workspace_prefix),
                "canonical navigation emitted a retired workspace path"
            );
        }
        let all_groups = vec![canonical_group];
        for context in PRODUCT_CONTEXTS {
            assert!(
                super::navigation_authorizes_console_path(context.path(), &all_groups),
                "manifest rejected {}",
                context.path()
            );
        }
        for feature in erpx_ui_kit::CurrentFeatureKind::ALL {
            if WORKSPACES
                .iter()
                .any(|workspace| workspace.route == feature.root())
            {
                for family in feature.record_families() {
                    let collection = family.collection_path();
                    assert!(
                        super::navigation_authorizes_console_path(&collection, &all_groups),
                        "manifest rejected registered collection {collection}",
                    );
                }
            }
        }
        assert!(super::navigation_authorizes_console_path(
            "/marketing/content",
            &all_groups
        ));
        assert!(super::navigation_authorizes_console_path(
            "/crm/opportunity",
            &all_groups
        ));
    }

    #[test]
    fn navigation_manifest_access_state_is_backward_compatible_and_fail_closed() {
        fn manifest_item(
            access_state: platform_admin_target::NavigationAccessState,
            required_role_keys: Vec<String>,
        ) -> platform_admin_target::NavigationManifestItem {
            platform_admin_target::NavigationManifestItem {
                route_id: "finance".into(),
                label: "Finance".into(),
                path: "/finance".into(),
                icon: "finance".into(),
                badge_count: 0,
                action_capabilities: Vec::new(),
                label_key: "nav.business_unit.finance".into(),
                access_state: access_state as i32,
                required_role_keys,
            }
        }

        let legacy = super::decode_navigation_manifest(vec![
            platform_admin_target::NavigationManifestGroup {
                group_id: "business_modules".into(),
                label: "Business Modules".into(),
                items: vec![manifest_item(
                    platform_admin_target::NavigationAccessState::Unspecified,
                    Vec::new(),
                )],
                label_key: "nav.group.business_modules".into(),
            },
        ])
        .expect("legacy manifest");
        assert!(legacy[0].items[0].is_authorized());

        let locked = super::decode_navigation_manifest(vec![
            platform_admin_target::NavigationManifestGroup {
                group_id: "business_modules".into(),
                label: "Business Modules".into(),
                items: vec![manifest_item(
                    platform_admin_target::NavigationAccessState::Locked,
                    vec!["finance_viewer".into(), "access_token".into()],
                )],
                label_key: "nav.group.business_modules".into(),
            },
        ])
        .expect("locked manifest");
        assert!(!locked[0].items[0].is_authorized());
        assert_eq!(locked[0].items[0].required_role_keys(), ["finance_viewer"]);

        let invalid = platform_admin_target::NavigationManifestGroup {
            group_id: "business_modules".into(),
            label: "Business Modules".into(),
            items: vec![platform_admin_target::NavigationManifestItem {
                access_state: 99,
                ..manifest_item(
                    platform_admin_target::NavigationAccessState::Unspecified,
                    Vec::new(),
                )
            }],
            label_key: "nav.group.business_modules".into(),
        };
        assert!(super::decode_navigation_manifest(vec![invalid]).is_err());
    }

