    #[test]
    fn every_registered_human_route_family_resolves_in_the_console_shell() {
        for service in RPC_WORKFLOW_SERVICES {
            if !matches!(
                service.classification,
                RpcClassification::HumanInteractive | RpcClassification::PublicHuman
            ) {
                continue;
            }
            for route in service.routes {
                if route.starts_with("/public/marketing/") {
                    continue;
                }
                assert!(
                    console_deep_link(route).is_some(),
                    "{} human route is not mounted: {route}",
                    service.service
                );
            }
        }
    }

