    #[test]
    fn directory_rpc_auth_categories_render_as_denied_without_backend_details() {
        let cases = [
            (
                tonic::Status::unauthenticated("access token=secret"),
                "authentication_required",
                UiStateKind::Denied,
            ),
            (
                tonic::Status::permission_denied("directory password=secret"),
                "authorization_denied",
                UiStateKind::Denied,
            ),
            (
                tonic::Status::unavailable("ldap://secret"),
                "offline",
                UiStateKind::Offline,
            ),
        ];
        for (status, category, state) in cases {
            assert_eq!(directory_rpc_error(status), category);
            assert_eq!(directory_error_state(category), state);
            assert!(!directory_error_title(category).is_empty());
            assert!(!directory_error_message(category).contains("secret"));
            assert!(!directory_error_message(category).contains("ldap://"));
        }
        assert_eq!(
            directory_error_state("directory_read_failed"),
            UiStateKind::Error
        );
    }

