    #[test]
    fn operations_surface_markers_cover_scope_states_without_fabricating_evidence() {
        assert_eq!(
            operations_route_surface_state(false, false, None, false, ProjectionFreshness::Unknown,),
            UiStateKind::Empty
        );
        assert_eq!(
            operations_route_surface_state(true, true, None, false, ProjectionFreshness::Unknown,),
            UiStateKind::Loading
        );
        for (category, expected) in [
            ("authentication_required", UiStateKind::Denied),
            ("authorization_denied", UiStateKind::Denied),
            ("offline", UiStateKind::Offline),
            ("operations_read_failed", UiStateKind::Error),
        ] {
            assert_eq!(
                operations_route_surface_state(
                    true,
                    false,
                    Some(category),
                    false,
                    ProjectionFreshness::Unknown,
                ),
                expected
            );
        }
        assert_eq!(
            operations_route_surface_state(true, false, None, true, ProjectionFreshness::Fresh,),
            UiStateKind::ReadOnly
        );
        assert_eq!(
            operations_route_surface_state(true, false, None, true, ProjectionFreshness::Stale,),
            UiStateKind::Stale
        );
        assert_eq!(
            operations_route_surface_state(true, false, None, true, ProjectionFreshness::Unknown,),
            UiStateKind::ReadOnly
        );
        assert_eq!(operations_reconciliation_marker(true), "not-reported");
        assert_eq!(operations_reconciliation_marker(false), "unavailable");
        assert_eq!(
            operations_authentication_marker(UiStateKind::ReadOnly),
            "server-authorized"
        );
        assert_eq!(
            operations_authentication_marker(UiStateKind::Stale),
            "server-authorized"
        );
        assert_eq!(
            operations_authentication_marker(UiStateKind::Denied),
            "denied"
        );
        assert_eq!(
            operations_authentication_marker(UiStateKind::Loading),
            "pending"
        );
        assert_eq!(
            operations_authentication_marker(UiStateKind::Empty),
            "required"
        );
        assert_eq!(
            operations_authentication_marker(UiStateKind::Offline),
            "unknown"
        );
        assert_eq!(
            operations_authentication_marker(UiStateKind::Error),
            "unknown"
        );
        assert!(UiStateKind::Stale.accessibility().cached_payload_allowed);
        assert!(!UiStateKind::Denied.accessibility().cached_payload_allowed);
    }

    #[test]
    fn operations_freshness_marker_only_accepts_authoritative_status_labels() {
        let scope = OperationsScope::new("tenant-001", "00000000-0000-0000-0000-000000000001")
            .expect("valid Operations scope");
        let stale = Ok(vec![PlatformProjectionStatusRecord {
            tenant_id: "tenant-001".into(),
            holding_ref: "holding-001".into(),
            projection_name: "operations".into(),
            kind: "incremental".into(),
            state: "retryable".into(),
            attempts: 1,
            max_attempts: 3,
            freshness: "stale".into(),
            published_at: "2026-07-29T00:00:00Z".into(),
            updated_at: "2026-07-29T00:05:00Z".into(),
        }]);
        assert_eq!(
            operations_projection_freshness(Some(&stale), false, Some(&scope)),
            ProjectionFreshness::Stale
        );
        let other_scope =
            OperationsScope::new("tenant-002", "00000000-0000-0000-0000-000000000001")
                .expect("valid alternate Operations scope");
        assert_eq!(
            operations_projection_freshness(Some(&stale), false, Some(&other_scope)),
            ProjectionFreshness::Unknown
        );

        let unknown = Ok(vec![PlatformProjectionStatusRecord {
            projection_name: "operations".into(),
            freshness: "pending".into(),
            ..stale.as_ref().expect("stale status fixture")[0].clone()
        }]);
        assert_eq!(
            operations_projection_freshness(Some(&unknown), false, Some(&scope)),
            ProjectionFreshness::Unknown
        );
        assert_eq!(
            operations_projection_freshness(Some(&stale), true, Some(&scope)),
            ProjectionFreshness::Unknown
        );
        assert_eq!(
            operations_projection_freshness(None, false, Some(&scope)),
            ProjectionFreshness::Unknown
        );
    }

