    #[test]
    fn platform_operations_tenant_route_is_normalized_and_redacted() {
        let registry = PlatformOperationsRouteRegistry::new();
        let route = registry
            .resolve("/#/platform//tenants/opaque-tenant-001/?view=health#details")
            .expect("normalized tenant deep link");
        assert_eq!(route.path(), "/platform/tenants/opaque-tenant-001");

        let rejected = registry
            .resolve("/platform/tenants/opaque-tenant-001?access_token=secret-value")
            .expect_err("credential-bearing deep links must be discarded");
        assert_eq!(rejected.normalized_path, "/");
        assert!(!rejected.normalized_path.contains("secret-value"));
        assert!(registry.resolve("/platform/tenants/tenant/child").is_err());
    }

