    #[test]
    fn every_customer_360_path_resolves_to_a_visible_context() {
        let paths = [
            "/platform/customers",
            "/platform/customers/customer-001",
            "/platform/customers/customer-001/organization",
            "/platform/customers/customer-001/contacts",
            "/platform/customers/customer-001/commercial",
            "/platform/customers/customer-001/entitlements",
            "/platform/customers/customer-001/onboarding",
            "/platform/customers/customer-001/health",
            "/platform/customers/customer-001/support",
            "/platform/customers/customer-001/access-audit",
            "/platform/customers/customer-001/notes",
        ];

        for path in paths {
            let route = PlatformRoute::parse(path).expect("required Customer 360 route");
            let (title, description) = route_context(&route);
            let (thai_title, thai_description) = route_context_for(Locale::Th, &route);
            assert!(!title.is_empty());
            assert!(!description.is_empty());
            assert_ne!(title, thai_title);
            assert_ne!(description, thai_description);
            assert!(
                thai_title
                    .chars()
                    .any(|character| ('ก'..='๛').contains(&character))
            );
            assert!(
                thai_description
                    .chars()
                    .any(|character| ('ก'..='๛').contains(&character))
            );
            assert_eq!(route.path(), path);
        }
    }

