    #[test]
    fn customer_360_detail_display_discards_raw_projection_payload() {
        let section_states = [
            ("account", "present"),
            ("organization", "present"),
            ("contacts", "absent"),
            ("commercial", "unsupported"),
            ("entitlements", "present"),
            ("onboarding", "present"),
            ("health", "present"),
            ("support", "present"),
            ("access_audit", "absent"),
            ("notes", "present"),
        ]
        .into_iter()
        .map(
            |(section, state)| erpx_proto::erpx::customer_360::v2::Customer360SectionState {
                section: section.into(),
                state: state.into(),
            },
        )
        .collect();
        let record = Customer360DetailRecord::from_response(GetCustomer360DetailResponse {
            customer_id: "customer-001".into(),
            freshness: "fresh".into(),
            supported: true,
            present: true,
            section_states,
            section_facts: vec![erpx_proto::erpx::customer_360::v2::Customer360SectionFact {
                section: "health".into(),
                key: "state".into(),
                value: "healthy".into(),
            }],
            payload_json: br#"{"entitlements":{"secret":"must-not-render"}}"#.to_vec(),
            ..Default::default()
        })
        .expect("safe section summary");
        assert_eq!(
            record.sections.len(),
            CUSTOMER_360_DETAIL_SECTION_NAMES.len()
        );
        assert_eq!(record.sections[0].state, "present");
        assert_eq!(record.sections[2].state, "absent");
        assert_eq!(record.sections[3].state, "unsupported");
        assert!(!format!("{record:?}").contains("must-not-render"));
        assert!(!format!("{record:?}").contains("account_code"));

        let malformed = GetCustomer360DetailResponse {
            customer_id: "customer-001".into(),
            freshness: "fresh".into(),
            supported: true,
            present: true,
            section_states: vec![
                erpx_proto::erpx::customer_360::v2::Customer360SectionState {
                    section: "account".into(),
                    state: "present".into(),
                },
            ],
            ..Default::default()
        };
        let error = Customer360DetailRecord::from_response(malformed)
            .expect_err("incomplete section payload");
        assert!(error.contains("section state count"));
    }

    #[test]
    fn customer_360_detail_fact_boundary_rejects_unknown_or_duplicate_fields() {
        let base = GetCustomer360DetailResponse {
            customer_id: "customer-001".into(),
            freshness: "fresh".into(),
            ..Default::default()
        };
        let mut unknown = base.clone();
        unknown.section_facts = vec![erpx_proto::erpx::customer_360::v2::Customer360SectionFact {
            section: "health".into(),
            key: "database_url".into(),
            value: "must-not-render".into(),
        }];
        let error = Customer360DetailRecord::from_response(unknown)
            .expect_err("unknown Customer 360 fact must fail closed");
        assert!(error.contains("not allow-listed"));

        let mut duplicate = base;
        duplicate.section_facts = vec![
            erpx_proto::erpx::customer_360::v2::Customer360SectionFact {
                section: "health".into(),
                key: "state".into(),
                value: "healthy".into(),
            },
            erpx_proto::erpx::customer_360::v2::Customer360SectionFact {
                section: "health".into(),
                key: "state".into(),
                value: "degraded".into(),
            },
        ];
        let error = Customer360DetailRecord::from_response(duplicate)
            .expect_err("duplicate Customer 360 fact must fail closed");
        assert!(error.contains("repeated"));
    }

