    #[test]
    fn development_controller_reaches_the_server_owned_persona_picker() {
        assert_eq!(
            super::initial_login_principal(true, true),
            super::DEVELOPMENT_CONTROLLER_PRINCIPAL
        );
        assert!(super::initial_login_principal(true, false).is_empty());
        assert!(super::initial_login_principal(false, true).is_empty());
        assert_eq!(
            super::development_key_label("platform_tenant-administrator"),
            "Platform Tenant Administrator"
        );
        let platform = super::DevelopmentPersonaRecord {
            persona_key: "platform-role".into(),
            principal_ref: "dev:platform:role".into(),
            tenant_id: None,
            organization_scope: "platform".into(),
            role_key: "platform_role".into(),
            feature: "platform".into(),
            entitled: true,
            directory_enabled: true,
        };
        let mut tenant = platform.clone();
        tenant.tenant_id = Some("tenant-a".into());
        assert!(super::development_target_matches(
            &platform,
            super::DEVELOPMENT_PLATFORM_TARGET
        ));
        assert!(!super::development_target_matches(&platform, "tenant-a"));
        assert!(super::development_target_matches(&tenant, "tenant-a"));
        assert!(!super::development_target_matches(
            &tenant,
            super::DEVELOPMENT_PLATFORM_TARGET
        ));
        tenant.persona_key = "tenant-a:finance_operator".into();
        tenant.role_key = "finance_operator".into();
        assert!(super::is_managed_work_role_preset(&tenant));
        for scenario in ["limited", "multi-role", "collision", "deny-wins"] {
            tenant.persona_key = format!("tenant-a:{scenario}");
            assert!(!super::is_managed_work_role_preset(&tenant));
        }
        assert_eq!(
            super::password_login_path(super::DEVELOPMENT_CONTROLLER_PRINCIPAL),
            "/dev-access/login"
        );
        assert_eq!(
            super::password_login_path("local:platform-root"),
            "/auth/login"
        );
        assert!(super::active_role_selection_required(
            true,
            Some(super::DEVELOPMENT_CONTROLLER_PRINCIPAL),
        ));
        assert!(super::active_role_selection_required(
            true,
            Some("local:platform-root")
        ));
        assert!(!super::active_role_selection_required(
            false,
            Some("local:platform-root")
        ));
        assert_eq!(
            super::development_permission_summary(super::Locale::En, 3, true),
            "3 permissions · TOTP for high risk"
        );
        assert_eq!(
            super::development_permission_summary(super::Locale::En, 1, false),
            "1 permission"
        );
        assert_eq!(
            super::development_permission_summary(super::Locale::Th, 2, false),
            "2 สิทธิ์"
        );
        assert_eq!(
            super::development_access_state_summary(super::Locale::En, false, true),
            "subscription denied · TOTP for high risk"
        );
        let expired = super::AuthHttpResponse {
            status: 401,
            body: r#"{"error":"session_inactive"}"#.into(),
        };
        assert_eq!(
            super::development_access_error_message(&expired, super::Locale::En),
            "The controller session expired. Sign in again and retry the persona switch."
        );
    }

