    #[test]
    fn incident_read_boundary_is_bounded_and_exposes_only_safe_rows() {
        let response = support_target::ListSupportIncidentRecordsResponse {
            incidents: vec![support_target::SupportIncidentRecord {
                incident_id: "00000000-0000-0000-0000-000000000101".into(),
                source_version: 4,
                status: support_target::SupportIncidentStatus::Investigating as i32,
                commander_ref: "commander-001".into(),
                affected_services: vec!["checkout".into()],
                affected_customer_accounts: vec!["customer-001".into()],
                ..Default::default()
            }],
            next_cursor: None,
            metadata: Some(erpx_proto::common::v2::QueryMetadata {
                correlation_id: "correlation-001".into(),
                ..Default::default()
            }),
        };
        let page = IncidentReadPage::from_target_wire(response).expect("safe incident page");
        assert_eq!(page.model.items().len(), 1);
        assert!(!page.has_more);
        assert_eq!(page.correlation_id, "correlation-001");
        let debug = format!("{page:?}");
        assert!(!debug.contains("timeline"));
        assert!(!debug.contains("capability_secret"));

        let state = console_incident_surface_state(Some(page), false, None);
        assert!(matches!(
            state,
            SupportIncidentSurfaceState::IncidentList(IncidentListState::ReadOnly { .. })
        ));

        let invalid = support_target::ListSupportIncidentRecordsResponse {
            incidents: vec![support_target::SupportIncidentRecord {
                incident_id: String::new(),
                source_version: 1,
                status: support_target::SupportIncidentStatus::Investigating as i32,
                ..Default::default()
            }],
            metadata: Some(erpx_proto::common::v2::QueryMetadata {
                correlation_id: "correlation-001".into(),
                ..Default::default()
            }),
            next_cursor: None,
        };
        assert!(IncidentReadPage::from_target_wire(invalid).is_err());
    }

    #[test]
    fn support_ticket_read_boundary_keeps_bodies_out_and_requires_cursor_consistency() {
        let response = support_target::ListSupportInternalTicketRecordsResponse {
            tickets: vec![support_target::SupportInternalTicketRecord {
                ticket_id: "00000000-0000-0000-0000-000000000102".into(),
                source_version: 3,
                customer_id: "customer-001".into(),
                status: support_target::SupportTicketStatus::InProgress as i32,
                severity: "high".into(),
                description: "customer password=must-not-render".into(),
                ..Default::default()
            }],
            metadata: Some(erpx_proto::common::v2::QueryMetadata {
                correlation_id: "correlation-002".into(),
                ..Default::default()
            }),
            next_cursor: Some("cursor-002".into()),
        };
        let page = SupportTicketReadPage::from_target_wire(response).expect("safe ticket page");
        assert_eq!(page.model.items().len(), 1);
        assert!(page.has_more);
        assert_eq!(page.next_cursor, "cursor-002");
        assert!(!format!("{page:?}").contains("password=must-not-render"));

        let state = console_support_ticket_surface_state(Some(page), false, None);
        assert!(matches!(
            state,
            SupportIncidentSurfaceState::TicketList(SupportTicketListState::ReadOnly { .. })
        ));

        let inconsistent = support_target::ListSupportInternalTicketRecordsResponse {
            tickets: vec![],
            metadata: None,
            next_cursor: None,
        };
        assert!(SupportTicketReadPage::from_target_wire(inconsistent).is_err());
    }

