    #[test]
    fn marketing_delivery_read_boundary_is_scope_bound_and_payload_free() {
        let delivery_id = "00000000-0000-0000-0000-000000000201";
        let holding_id = "00000000-0000-0000-0000-000000000202";
        let scope = CrmReadScope::new(
            "tenant-001",
            "holding-ref-001",
            tenant_scope::Scope::Holding(HoldingScope {
                holding_id: holding_id.into(),
            }),
        )
        .expect("holding scope");
        let request = marketing_delivery_read_request(
            &scope,
            delivery_id,
            "principal-marketing-001",
            "session-marketing-001",
        )
        .expect("delivery read request")
        .into_inner();
        assert_eq!(request.delivery_id, delivery_id);
        assert!(matches!(
            request
                .context
                .and_then(|context| context.tenant_scope)
                .and_then(|scope| scope.scope),
            Some(tenant_scope::Scope::Holding(_))
        ));

        let read = decode_marketing_delivery_read(
            delivery_id,
            GetMarketingDeliveryReadResponse {
                delivery: Some(MarketingDeliveryRead {
                    delivery_id: delivery_id.into(),
                    holding_id: holding_id.into(),
                    state: "queued".into(),
                    attempt_count: 2,
                    next_attempt_at: "2026-07-28T12:00:00Z".into(),
                    expires_at: "2026-07-29T12:00:00Z".into(),
                    version: 4,
                    read_only: true,
                    present: true,
                }),
                correlation_id: "correlation-delivery-001".into(),
            },
        )
        .expect("safe delivery read");
        assert_eq!(read.state, "queued");
        assert_eq!(read.version, 4);
        assert!(read.read_only);
        assert!(!format!("{read:?}").contains("recipient"));

        assert!(
            decode_marketing_delivery_read(
                delivery_id,
                GetMarketingDeliveryReadResponse {
                    delivery: Some(MarketingDeliveryRead {
                        delivery_id: delivery_id.into(),
                        read_only: true,
                        present: true,
                        ..Default::default()
                    }),
                    ..Default::default()
                },
            )
            .is_err()
        );
        assert!(
            marketing_delivery_read_request(
                &scope,
                "not-a-uuid",
                "principal-marketing-001",
                "session-marketing-001",
            )
            .is_err()
        );
    }

