    #[test]
    fn crm_attribution_and_erasure_commands_are_scope_and_version_bound() {
        let scope = CrmReadScope::new(
            "00000000-0000-0000-0000-000000000001",
            "holding-ref-001",
            tenant_scope::Scope::Branch(erpx_proto::common::v2::BranchScope {
                holding_id: "00000000-0000-0000-0000-000000000002".into(),
                company_id: "00000000-0000-0000-0000-000000000003".into(),
                branch_id: "00000000-0000-0000-0000-000000000004".into(),
            }),
        )
        .expect("CRM branch scope");
        let principal = "principal-001";
        let session = "00000000-0000-0000-0000-000000000005";

        let attribution = crm_attribution_request(
            &scope,
            &CrmAttributionCommandInput {
                opportunity_id: "00000000-0000-0000-0000-000000000006".into(),
                model: "weighted".into(),
                expected_version: "8".into(),
            },
            principal,
            session,
        )
        .expect("CRM attribution request")
        .into_inner();
        assert_eq!(attribution.model, "weighted");
        assert_eq!(attribution.expected_opportunity_version, 8);
        assert_eq!(
            attribution
                .context
                .as_ref()
                .expect("attribution context")
                .expected_aggregate_version,
            8
        );

        let erasure = marketing_erasure_request(
            &scope,
            &MarketingErasureCommandInput {
                profile_id: "00000000-0000-0000-0000-000000000010".into(),
                reason: "customer privacy request".into(),
                erased_at: "2026-07-28T00:00:00Z".into(),
            },
            principal,
            session,
        )
        .expect("marketing erasure request")
        .into_inner();
        assert_eq!(erasure.profile_id, "00000000-0000-0000-0000-000000000010");
        assert_eq!(erasure.reason, "customer privacy request");
        assert_eq!(
            erasure
                .context
                .as_ref()
                .and_then(|context| context.audit.as_ref())
                .map(|audit| audit.module.as_str()),
            Some("marketing")
        );

        assert!(
            crm_attribution_request(
                &scope,
                &CrmAttributionCommandInput {
                    opportunity_id: "00000000-0000-0000-0000-000000000006".into(),
                    model: "unsupported".into(),
                    expected_version: "8".into(),
                },
                principal,
                session,
            )
            .is_err()
        );
        assert!(
            marketing_erasure_request(
                &scope,
                &MarketingErasureCommandInput {
                    profile_id: "not-a-uuid".into(),
                    reason: "privacy request".into(),
                    erased_at: String::new(),
                },
                principal,
                session,
            )
            .is_err()
        );
    }
