    #[test]
    fn crm_response_decodes_only_typed_allow_list_fields() {
        let response = ListCrmReadRowsResponse {
            rows: vec![CrmReadRow {
                aggregate_type: "marketing_crm_opportunity".into(),
                aggregate_id: "opportunity-001".into(),
                holding_id: "holding-001".into(),
                company_id: "company-001".into(),
                branch_id: String::new(),
                source_version: 3,
                payload_json:
                    br#"{"status":"Qualified","name":"Renewal","password":"do-not-render"}"#
                        .to_vec(),
            }],
            has_more: false,
            next_after_id: String::new(),
            correlation_id: "correlation-001".into(),
        };
        let decoded = decode_crm_rows(erpx_ui_crm::CrmSurface::Opportunities, response, None)
            .expect("typed CRM response");
        let debug = format!("{decoded:?}");
        assert!(matches!(decoded, CrmRows::Opportunities(_)));
        assert!(debug.contains("Renewal"));
        assert!(!debug.contains("do-not-render"));
        assert!(!debug.contains("password"));
    }

    #[test]
    fn crm_response_preserves_bounded_cursor_continuation() {
        let response = ListCrmReadRowsResponse {
            rows: vec![CrmReadRow {
                aggregate_type: "marketing_crm_opportunity".into(),
                aggregate_id: "00000000-0000-0000-0000-000000000002".into(),
                holding_id: "holding-001".into(),
                company_id: "company-001".into(),
                branch_id: String::new(),
                source_version: 4,
                payload_json: br#"{"status":"qualified","name":"Renewal"}"#.to_vec(),
            }],
            has_more: true,
            next_after_id: "00000000-0000-0000-0000-000000000003".into(),
            correlation_id: "correlation-004".into(),
        };
        let decoded = decode_crm_rows(
            erpx_ui_crm::CrmSurface::Opportunities,
            response,
            Some("00000000-0000-0000-0000-000000000001"),
        )
        .expect("bounded continuation");
        let CrmRows::Opportunities(page) = decoded else {
            panic!("expected opportunity page");
        };
        assert_eq!(
            page.metadata().after_cursor(),
            Some("00000000-0000-0000-0000-000000000001")
        );
        assert_eq!(
            page.metadata().next_cursor(),
            Some("00000000-0000-0000-0000-000000000003")
        );
        assert!(page.metadata().has_more());
    }

    #[test]
    fn crm_state_contract_is_explicit_and_bilingual() {
        let states = [
            UiStateKind::Loading,
            UiStateKind::Empty,
            UiStateKind::Denied,
            UiStateKind::Stale,
            UiStateKind::ReadOnly,
            UiStateKind::Offline,
            UiStateKind::Error,
        ];
        for state in states {
            let (en_title, en_message) = crm_state_copy(state, Locale::En);
            let (th_title, th_message) = crm_state_copy(state, Locale::Th);
            assert!(!en_title.is_empty());
            assert!(!en_message.is_empty());
            assert!(!th_title.is_empty());
            assert!(!th_message.is_empty());
            assert_ne!(en_title, th_title);
        }
        assert_eq!(
            crm_state_for_error(CrmReadError::Denied).kind(),
            Some(UiStateKind::Denied)
        );
        assert_eq!(
            crm_state_for_error(CrmReadError::Offline).kind(),
            Some(UiStateKind::Offline)
        );
        assert_eq!(
            crm_state_for_error(CrmReadError::ScopeUnavailable).kind(),
            Some(UiStateKind::Error)
        );
    }

