    #[test]
    fn finance_typed_adapters_build_chart_and_journal_commands() {
        let scope = FinanceScope::new(
            "tenant-001",
            "holding-ref-001",
            "00000000-0000-0000-0000-000000000001",
        )
        .expect("finance scope");
        let chart = finance_target_chart_request(
            &scope,
            &FinanceChartTypedInput {
                chart_id: "00000000-0000-0000-0000-000000000020".into(),
                company_id: "00000000-0000-0000-0000-000000000011".into(),
                code: "MAIN".into(),
                name: "Main chart".into(),
                currency: "THB".into(),
                account_id: "00000000-0000-0000-0000-000000000040".into(),
                account_code: "1000".into(),
                account_name: "Cash".into(),
                account_category: "asset".into(),
                expected_version: String::new(),
            },
            "principal-001",
            "00000000-0000-0000-0000-000000000099",
        )
        .expect("typed chart request");
        let FinanceTargetChartRequest::Create(chart) = chart else {
            panic!("blank version must create the chart");
        };
        assert_eq!(chart.code, "MAIN");
        assert_eq!(chart.currency, "THB");
        assert_eq!(
            chart.accounts[0].normal_balance,
            finance_target::FinanceNormalBalance::Debit as i32
        );

        let journal_input = FinanceJournalTypedInput {
            chart_id: "00000000-0000-0000-0000-000000000020".into(),
            chart_name: "Main chart".into(),
            currency: "thb".into(),
            period: FinancePeriodCommandInput {
                period_id: "00000000-0000-0000-0000-000000000010".into(),
                company_id: "00000000-0000-0000-0000-000000000011".into(),
                label: "2026-07".into(),
                starts_on: "2026-07-01".into(),
                ends_on: "2026-07-31".into(),
                expected_version: String::new(),
            },
            journal_id: "00000000-0000-0000-0000-000000000030".into(),
            journal_code: "JV-2026-0001".into(),
            source_reference: "manual-accrual-0001".into(),
            entry_date: "2026-07-15".into(),
            description: "Accrual adjustment".into(),
            debit_account_id: "00000000-0000-0000-0000-000000000040".into(),
            debit_account_code: "1000".into(),
            debit_account_name: "Cash".into(),
            debit_account_category: "asset".into(),
            credit_account_id: "00000000-0000-0000-0000-000000000041".into(),
            credit_account_code: "2000".into(),
            credit_account_name: "Accrued liabilities".into(),
            credit_account_category: "liability".into(),
            amount_minor: "10000".into(),
        };
        let journal = finance_target_journal_plan(
            &scope,
            &journal_input,
            "principal-001",
            "00000000-0000-0000-0000-000000000099",
        )
        .expect("typed journal request");
        assert_eq!(journal.create.currency, "THB");
        assert_eq!(journal.create.lines.len(), 2);
        assert_eq!(journal.create.lines[0].debit_minor, 10_000);
        assert_eq!(journal.create.lines[1].credit_minor, 10_000);
        let mut invalid_journal = journal_input;
        invalid_journal.amount_minor = "0".into();
        assert!(
            finance_target_journal_plan(
                &scope,
                &invalid_journal,
                "principal-001",
                "00000000-0000-0000-0000-000000000099",
            )
            .is_err()
        );
    }

