    #[test]
    fn infrastructure_reference_boundary_accepts_only_opaque_owned_locators() {
        assert!(
            validate_infrastructure_reference(
                "erpx-managed:tenant-001/write-primary",
                "erpx-managed:"
            )
            .is_ok()
        );
        assert!(
            validate_infrastructure_reference(
                "customer-secret:holding-001/write-primary",
                "customer-secret:"
            )
            .is_ok()
        );
        for unsafe_value in [
            "postgres://operator:password@database/erpx",
            "erpx-managed:user=operator",
            "erpx-managed:operator@example.test",
            "customer-secret:wrong-owner",
        ] {
            assert!(
                validate_infrastructure_reference(unsafe_value, "erpx-managed:").is_err(),
                "unsafe reference should fail: {unsafe_value}"
            );
        }
    }

    #[test]
    fn tenant_lifecycle_receipts_are_bounded_and_exclude_recovery_material() {
        let receipt = PlatformTenantLifecycleReceipt {
            tenant_id: "tenant-001".to_owned(),
            state: "provisioning".to_owned(),
            registry_version: None,
            databases_ready: Some(true),
            storage_ready: Some(true),
            owner_seeded: Some(true),
            correlation_id: Uuid::new_v4().to_string(),
        };
        assert!(receipt.validate().is_ok());
        assert_eq!(
            PlatformTenantLifecycleAction::ProvisionResources.purpose(),
            "platform_tenant_resource_provisioning"
        );
        assert_eq!(
            PlatformTenantLifecycleAction::Suspend.purpose(),
            "platform_tenant_suspension"
        );

        let source = include_str!("composition.rs");
        let forbidden_recovery_copy = ["response", "owner_recovery_code"].join(".");
        assert!(!source.contains(&forbidden_recovery_copy));
    }

